export const gpSentences: Sentence[] = [
  {"id":"s_work_gp_1_1","chapterId":"ch_work_gp_1","text":"《四库全書·家范》提要","sortOrder":1},
  {"id":"s_work_gp_1_2","chapterId":"ch_work_gp_1","text":"臣等謹按：《家范》十卷，宋司馬光撰。光所著《溫公易說》諸書已別著錄，是書見於《宋史·藝文志·文獻通考》者，卷目俱與此相合，猶當時原本。自顏之推作家訓以教子弟，其議論甚正，而詞旨泛濫，不能盡本諸經訓。至狄仁杰著有《家范》一卷，史志雖載其目，而書已不傳。光因取仁杰舊名，別加甄辑，以示後學准繩。首載《周易》家人卦辭、《大學》、《孝經》、《尧典》、《詩》思齊篇語則，即其全書之序也。其後，自治家至乳母，凡十九篇，皆雜采史傳事可為法則者。亦間有光所論說與朱子《小學》。義例差異而用意略同。其節目備具，切於日用，簡而不煩，實足為儒者治行之要。朱子嘗論《周禮》，師氏雲：至德以為道本，明道先生以之敏德，以為行本。司馬溫公以之觀於是編，其型方訓俗之規，尤可以概見矣。乾隆四十二年五月，恭校上。","sortOrder":2},
  {"id":"s_work_gp_1_3","chapterId":"ch_work_gp_1","text":"總纂官：臣紀昀臣陆錫熊臣孫士毅總校官：臣陆費墀","sortOrder":3},
  {"id":"s_work_gp_2_1","chapterId":"ch_work_gp_2","text":"前言","sortOrder":1},
  {"id":"s_work_gp_2_2","chapterId":"ch_work_gp_2","text":"司馬光（101—1086　年），字君實，陝州夏縣（山西夏縣）涑水人，世稱“涑水先生”。北宋大臣，歷經仁宗、英宗、神宗、哲宗四朝。著名史學家。","sortOrder":2},
  {"id":"s_work_gp_2_3","chapterId":"ch_work_gp_2","text":"司馬光自幼聰明穎悟，《宋史》載：“光生七歲，凛然如成人，聞講《左氏春秋》，愛之，退為家人講，即了其大指。自是手不釋書，至不知飢渴寒暑。”寶元元年中進士，時年二十歲。","sortOrder":3},
  {"id":"s_work_gp_2_4","chapterId":"ch_work_gp_2","text":"宋英宗時，司馬光常苦於歷代史籍浩繁，帝王不便閱覽，遂撰成《通志》八卷，英宗大喜，命置之秘閣，繼續撰寫。等到宋神宗即位後，更重视此書，正式賜書名為《資治通鑒》，併親自為此書做序，而且令司馬光為他每日進讀。也正因此，司馬光得以成為神宗的親近侍從。","sortOrder":4},
  {"id":"s_work_gp_2_5","chapterId":"ch_work_gp_2","text":"1084年，《資治通鑒》完稿，上呈朝廷。全書共294卷，上起戰國時期周威烈王二十三年（公元前403），下至五代後周顯德六年（公元959），是一部規模空前的編年體通史巨著，記述長達一千三百六十二年的歷史。全書完成歷時十九年。这部書是司馬光耗盡畢生精力所完成的一部巨著。為寫此書，司馬光及其助手遍閱舊史，工作非常勤奋。司馬光每三天必删改編定一卷，如果有事耽誤，日後必定補齊。因此，他的工作量非常大，每天工作到深夜，至五更初，仍要挑燈再幹。書成之日，他已是發白齒脱。","sortOrder":5},
  {"id":"s_work_gp_2_6","chapterId":"ch_work_gp_2","text":"《資治通鑒》“鑒前世之興衰，考當今之得失”，給統治者提供治國經验，為歷代帝王所看重，以致後世的君臣將相没有不讀《資治通鑒》的。該書在史學上也占有十分重要的地位，司馬光和司馬遷併稱兩司馬，史籍當中，只有《資治通鑒》能與《史記》相提併論。","sortOrder":6},
  {"id":"s_work_gp_2_7","chapterId":"ch_work_gp_2","text":"然而，一般人只知道司馬光有一部治國的書叫《資治通鑒》，却很少有人知道司馬光還有一部齊家的書叫《家范》。《家范》併不是仅仅講如何治家的問題，司馬光在《家范》卷首引用《大學》里的一段話，來闡明他寫《家范》的目的：“欲治其國者，先齊其家；欲齊其家者，先修其身。。。心正而後身修，身修而後家齊，家齊而後國治，國治而後天下平。”司馬光自己也說：“所謂治國必先齊其家者，其家不可教而能教人者，無之。”古人把齊家和治國看得同等重要，甚至認為齊家是本，治國是末，“本亂而末治”是不可能的。家都管不好，子弟都教育不好，怎么能出來教育別人呢？所以，司馬光是把齊家提到治國的高度，來寫《家范》的。所謂“聖人正家以正天下者也”。","sortOrder":7},
  {"id":"s_work_gp_2_8","chapterId":"ch_work_gp_2","text":"《四库全書》說：自顏之推作家訓以教子弟，其議論甚正，而詞旨泛濫，不能盡本諸經訓。至狄仁杰著有《家范》一卷，史志雖載其目，而書已不傳。司馬光就用狄仁杰的舊名，另外著述，以為後世提供治家的准繩。","sortOrder":8},
  {"id":"s_work_gp_2_9","chapterId":"ch_work_gp_2","text":"《家范》被歷代推崇為家教的范本，全書共十九篇，系統地闡述了封建家庭的倫理關系、治家原則，以及修身養性和為人處世之道。書中引用了許多儒家經典中的治家、修身格言，對我们頗有啟發。還收集了大量歷代治家有方的實例和典范，以為後人树立楷模。","sortOrder":9},
  {"id":"s_work_gp_2_10","chapterId":"ch_work_gp_2","text":"司馬光本人為人正直，為官清廉，居處得法，舉止有禮，忠信仁孝，治家有方，以身作則，為後人树立了做人和治家的榜樣。所以，他的《家范》更有實际意義。","sortOrder":10},
  {"id":"s_work_gp_2_11","chapterId":"ch_work_gp_2","text":"《家范》確實是一部中國古人修身齊家的典范作品，我们今天學習它，應該從中吸取有益的精華，對於司馬光的歷史局限和《家范》中的糟粕應予以分析和剔除。","sortOrder":11},
  {"id":"s_work_gp_2_12","chapterId":"ch_work_gp_2","text":"此次整理，是以《四库全書》所收《家范》為底本進行整理的。本著保持原汁原味的原則，我们對《四库全書》所收《家范》原本照錄，没作任何改動。對明顯的错字和筆誤，隨手改正，不另出校勘記。為了讀者在閱讀原文時更加醒目，我们在原文意思相同的段落前都擬了標題，在此說明。為了便於讀者閱讀理解，譯文采用譯述的方法，旨在充分闡明其道理。由於學識水平有限，點校過程中，疏漏和错誤之處在所難免，恳請方家不吝賜教。","sortOrder":12},
  {"id":"s_work_gp_2_13","chapterId":"ch_work_gp_2","text":"修遠1998　年11　月2　日","sortOrder":13},
  {"id":"s_work_gp_3_1","chapterId":"ch_work_gp_3","text":"家范卷一治家","sortOrder":1},
  {"id":"s_work_gp_3_2","chapterId":"ch_work_gp_3","text":"【原文】《周易》：離下巽上。家人：利女貞。","sortOrder":2},
  {"id":"s_work_gp_3_3","chapterId":"ch_work_gp_3","text":"彖曰：家人，女正位乎內，男正位乎外，男女正，天地之大義也。","sortOrder":3},
  {"id":"s_work_gp_3_4","chapterId":"ch_work_gp_3","text":"家人有嚴君焉，父母之謂也。父父，子子，兄兄，弟弟，夫夫，婦婦，而家道正。正家而天下定矣。","sortOrder":4},
  {"id":"s_work_gp_3_5","chapterId":"ch_work_gp_3","text":"象曰：風自火出，家人。君子以言有物而行有恒。","sortOrder":5},
  {"id":"s_work_gp_3_6","chapterId":"ch_work_gp_3","text":"初九：閒有家，悔亡。象曰：閒有家，志未变也。","sortOrder":6},
  {"id":"s_work_gp_3_7","chapterId":"ch_work_gp_3","text":"六二：無攸遂，在中饋，貞吉。象曰：六二之吉，順以巽也。","sortOrder":7},
  {"id":"s_work_gp_3_8","chapterId":"ch_work_gp_3","text":"九三：家人嗃嗃，悔，厲，吉。婦子嘻嘻，終吝。象曰：家人嗃嗃，未失也。婦子嘻嘻，失家節也。","sortOrder":8},
  {"id":"s_work_gp_3_9","chapterId":"ch_work_gp_3","text":"六四：富家，大吉。象曰：富家大吉，順在位也。","sortOrder":9},
  {"id":"s_work_gp_3_10","chapterId":"ch_work_gp_3","text":"九五：王假有家，勿恤，吉。象曰：王假有家，交相愛也。","sortOrder":10},
  {"id":"s_work_gp_3_11","chapterId":"ch_work_gp_3","text":"上九：有孚威如，終吉。象曰：威如之吉，反身之謂也。","sortOrder":11},
  {"id":"s_work_gp_3_12","chapterId":"ch_work_gp_3","text":"《大學》曰：“古之欲明明德於天下者，先治其國；欲治其國者，先齊其家；欲齊其家者，先修其身；欲修其身者，先正其心；欲正其心者，先誠其意；欲誠其意者，先致其知；致知在格物。物格而後知至，知至而後意誠，意誠而後心正，心正而後身修，身修而後家齊，家齊而後國治，國治而後天下平。自天子以至於庶人，一是皆以修身為本。其本亂而末治者否矣，其所厚者薄，而其所薄者厚，未之有也！”此謂知本，此謂知之至也。所謂治國必先齊其家者，其家不可教而能教人者，無之。故君子不出家而成教於國。孝者所以事君也，弟者所以事長也，慈愛者所以使眾也。《詩》雲：“桃之夭夭，其葉蓁蓁。之子於歸，宜其家人。”宜其家人，而後可以教國人。《詩》雲：“宜兄宜弟。”宜兄宜弟，而後可以教國人。《詩》雲：“其儀不忒，正是四國。”其為父子，兄弟足法，而後民法之也。此謂治國在齊其家。","sortOrder":12},
  {"id":"s_work_gp_3_13","chapterId":"ch_work_gp_3","text":"《孝經》曰：閨門之內具禮矣乎！嚴父，嚴兄。妻子臣妾，猶百姓徒役也。","sortOrder":13},
  {"id":"s_work_gp_3_14","chapterId":"ch_work_gp_3","text":"昔四嶽荐舜於尧，曰：“瞽子，父顽、母嚚、象傲。克諧以孝，烝烝乂，不格奸。”帝曰：“我其试哉！女於時，觀厥刑於二女。”厘降二女於妫汭，嫔於虞。帝曰：“钦哉！”","sortOrder":14},
  {"id":"s_work_gp_3_15","chapterId":"ch_work_gp_3","text":"《詩》稱文王之德曰：“刑於寡妻，至於兄弟，以御於家邦。”此皆聖人正家以正天下者也。降及後世，爰自卿士以至匹夫，亦有家行隆美可為人法者，今采集以為《家范》。","sortOrder":15},
  {"id":"s_work_gp_3_16","chapterId":"ch_work_gp_3","text":"【譯述】《周易》！離下巽上，家人卦：卜問婦女之事吉利。","sortOrder":16},
  {"id":"s_work_gp_3_17","chapterId":"ch_work_gp_3","text":"“彖詞”說：家人的爻象顯示，六二陰爻居於內卦的中位，像婦女在內，以正道守其位，九五陽爻居於外卦的中位，像男人在外，以正道守其位，則是天地間的大義。一个家庭有尊嚴的家長，即父親和母親。","sortOrder":17},
  {"id":"s_work_gp_3_18","chapterId":"ch_work_gp_3","text":"父親要像个父親，兒子要像个兒子，兄長要像个兄長，弟弟要像个弟弟，丈夫要像个丈夫，妻子要像个妻子，这樣家道就端正了。如果都能正其家，天下也就安定了。","sortOrder":18},
  {"id":"s_work_gp_3_19","chapterId":"ch_work_gp_3","text":"“象辭”說：家人卦外卦為巽，巽為風；內卦為離，離為火，內火外風，風助火势，火助風威，二者相辅相成，是家人的卦象。君子從这个卦象中悟到，言辭一定要有內容才不致於空洞，德行一定要持之以恒才能彰顯。","sortOrder":19},
  {"id":"s_work_gp_3_20","chapterId":"ch_work_gp_3","text":"初九：防范家庭出現意外事故，没有悔恨。“象辭”說：防范家庭出現意外事故就是防患於未然。","sortOrder":20},
  {"id":"s_work_gp_3_21","chapterId":"ch_work_gp_3","text":"六二：婦女在家里料理家務，安排膳食，没有失誤，这是吉利之象。","sortOrder":21},
  {"id":"s_work_gp_3_22","chapterId":"ch_work_gp_3","text":"“象辭”說：六二爻辭之所以稱吉利，是因為六二陰爻居九三陽爻之下，像婦人對男人順從而有謙恭。","sortOrder":22},
  {"id":"s_work_gp_3_23","chapterId":"ch_work_gp_3","text":"九三：貧困之家，眾人嗷嗷待哺，这是愁苦的事情，但是假如能够辛勤勞作，就可以脱貧致富。而那些富貴之家，驕奢淫逸，妻妾兒女只知道嘻戲作樂，家道終將败落。“象辭”說：貧困之家，而能辛勤勞作，没有失掉正派的家風。富貴人家，一味嘻戲作樂，就會有失勤俭之道。","sortOrder":23},
  {"id":"s_work_gp_3_24","chapterId":"ch_work_gp_3","text":"六四：富裕而幸福的家庭，大吉大利。“象辭”說：富裕而幸福的家庭大吉大利，因為六四陰爻居於九五陽爻之下，像家人和順而各守其職。","sortOrder":24},
  {"id":"s_work_gp_3_25","chapterId":"ch_work_gp_3","text":"九五：君王到家廟去祭祀祖先，不要忧慮，祖先福佑家人，凡事吉利。“象辭”說：君王到臣民之家，說明君臣相互愛護。","sortOrder":25},
  {"id":"s_work_gp_3_26","chapterId":"ch_work_gp_3","text":"上九：君王掌握殺罰之柄，威風凛凛，權柄不移，終歸吉利。“象辭”說：上九爻辭講殺罰立威，終歸吉利，因為君上能够反省己身，树立威望。","sortOrder":26},
  {"id":"s_work_gp_3_27","chapterId":"ch_work_gp_3","text":"《大學》說：“古代那些想在天下彰明德行的人，必須治理好他的國家；想要治理好國家，必須先要管理好家政；想管理好家政，必須先提高自己的修養；想要提高自己的修養，必須先端正自己的心；想要端正自己的心，必須先要有一个誠恳的態度；想要有誠恳的態度，必須先要有知識和才智；想獲得知識就必須去探求事物的理。通過探求事物的理獲得知識，有了知識就會產生誠恳的態度，有了誠恳的態度就會端正自己的心意，心意端正就能够提高自己的修養，提高了自己的修養就能够管理好自己的家，能够管理好自己的家就能够治理好國家，先治理好國家就能够平定整个天下。從天子到一般百姓，都要將提高自己的修養作為根本。本亂而未治是不可能的，想把本來應該厚實的東西用薄的來代替，而把本來應該薄的東西用厚的來代替，都是不可能的！”这才是抓住了事物的根本，这才是最高的知識和智慧。所謂想治理好國家必須先管理好自己的家，意思是說，連家都管理不好，而想去治理國家，这是不可能的。所以君子不出家門就教化了全國的人。这是因為在家里體現了子女要侍奉父母親，弟弟要侍奉兄長，長辈對晚辈既要慈愛又要指使他们。《詩經》說：“美麗的桃树啊，枝葉繁茂；妙令女子出嫁到丈夫家，使其家庭和順。”將家人治理的非常和諧，而後可以去教导國人。《詩經》說：“宜兄宜弟。”自己的兄弟之間非常和睦，而後就可以去教导國人了。《詩經》說：“其儀不忒，正是四國。”父親處理與子女之間的關系，也是兄弟之間處理關系的榜樣。推而廣之，成為全國民眾足以效法的榜樣。这就是治國先要能够齊家的道理。","sortOrder":27},
  {"id":"s_work_gp_3_28","chapterId":"ch_work_gp_3","text":"《孝經》說：家雖小，但治理天下的方法都在其中了！侍奉父親，侍奉兄長。對待妻子臣妾，就像對待百姓臣民一樣，必須御之以道。","sortOrder":28},
  {"id":"s_work_gp_3_29","chapterId":"ch_work_gp_3","text":"從前四方諸侯之長向尧推荐舜，說：“他是樂官瞽瞍的兒子。他父親心術不正，他的後母說話不誠實，弟弟象傲慢而不友好，但是舜能和他们和睦相處，他用孝行美德來感化他们，又加強自身修養，不流於邪惡。”尧帝說：“讓我试试他吧！我將兩个女兒嫁給舜，通過兩个女兒來觀察舜的德行。”於是尧帝命令兩个女兒下到妫水的轉弯處，嫁給舜。尧帝說：“嚴肅認真地處理政務吧！”","sortOrder":29},
  {"id":"s_work_gp_3_30","chapterId":"ch_work_gp_3","text":"《詩經》稱贊文王的德行說：“周文王能以身作則，用禮法感化妻子和兄弟，近而來教化全國百姓，治理國家。”这都是古代的聖人先治理好家，然後再治理國家的典范。到後世，上至卿士下至一般百姓，也有許多在家里遵守禮法，而且可以成為別人學習的榜樣的人和事，現在將这些典范事例收集起來，編成这本《家范》。","sortOrder":30},
  {"id":"s_work_gp_3_31","chapterId":"ch_work_gp_3","text":"治家治家必以禮為先","sortOrder":31},
  {"id":"s_work_gp_3_32","chapterId":"ch_work_gp_3","text":"【原文】衛石碏曰：“君義、臣行、父慈、子孝、兄愛、弟敬，所謂六順也。”","sortOrder":32},
  {"id":"s_work_gp_3_33","chapterId":"ch_work_gp_3","text":"齊晏婴曰：“君令臣共、父慈子孝、兄愛弟敬、夫和妻柔、姑慈婦聽，禮也。”君令而不违，臣共而不二，父慈而教，子孝而箴，兄愛而友，弟敬而順，夫和而義，妻柔而正，姑慈而從，婦聽而婉，禮之善物也。","sortOrder":33},
  {"id":"s_work_gp_3_34","chapterId":"ch_work_gp_3","text":"夫治家莫如禮。男女之別，禮之大節也，故治家者必以為先。《禮》：男女不雜坐，不同椸枷，不同巾櫛，不親授受；嫂叔不通問，諸母不漱裳；外言不入於阃，內言不出於阃；女子許嫁，纓。非有大故不入其門。姑姊妹、女子子，已嫁而反，兄弟弗與同席而坐，弗與同器而食。男女非有行媒不相知名，非受幣不交不親，故日月以告君，斋戒以告鬼神，為酒食以召乡党僚友，以厚其別也。","sortOrder":34},
  {"id":"s_work_gp_3_35","chapterId":"ch_work_gp_3","text":"又，男女非祭非丧，不相授器。其相授，則女受以篚。其無篚，則皆坐奠之，而後取之。外內不共井，不共湢浴，不通寢席，不通乞假。","sortOrder":35},
  {"id":"s_work_gp_3_36","chapterId":"ch_work_gp_3","text":"男子入內，不嘯不指；夜行以燭，無燭則止。女子出門，必擁蔽其面；夜行以燭，無燭則止。道路，男子由右，女子由左。","sortOrder":36},
  {"id":"s_work_gp_3_37","chapterId":"ch_work_gp_3","text":"又，子生七年，男女不同席，不共食。男子十年，出就外傅，居宿於外。女子十年不出。","sortOrder":37},
  {"id":"s_work_gp_3_38","chapterId":"ch_work_gp_3","text":"又婦人送迎不出門，見兄弟不逾閾。","sortOrder":38},
  {"id":"s_work_gp_3_39","chapterId":"ch_work_gp_3","text":"又，國君、夫人、父母在，則有歸寧。没，則使卿寧。","sortOrder":39},
  {"id":"s_work_gp_3_40","chapterId":"ch_work_gp_3","text":"【譯述】衛石碏說：“君王仁義、臣下有品行、父親慈祥、兒子孝順、兄長愛護、弟弟恭敬，这就是人们常說的六順。”齊國人晏婴說：“君主和善，臣子謙恭；父親慈祥，兒子孝順；兄長友愛，弟弟恭敬；丈夫溫和，妻子柔順；婆母慈善，媳婦聽話，这就叫禮。”君主和善而又不违禮法，臣下忠君而没有二心，父親對子女慈祥而且能够教育，子女對父母孝順且能規勸其過错，兄長對弟弟愛護而且友善，弟弟對兄長敬重而又順從，丈夫對妻子和氣，妻子對丈夫溫柔，婆母對媳婦慈祥，媳婦聽命而又溫婉，这一切是禮法中最規范的現象。治家最好的辦法莫過於講究禮法。","sortOrder":40},
  {"id":"s_work_gp_3_41","chapterId":"ch_work_gp_3","text":"男女有別，是禮之大節，所以治家者必須以禮為先。《禮記》規定：男女不能在一起，不能共用衣架，不能共用毛巾和梳子，不能親自傳遞和接受東西；嫂子與小叔不能互相往來問候；庶母不能洗非親生孩子的衣裳；閨房外的話不能傳入閨內，閨房內的話也不能傳到閨外；女子订婚後，必須佩帶香囊表示自己已有所歸屬。女子出嫁後，若不是家中發生大的事情，不能回娘家。姊妹、堂姊妹出嫁之後再回家，兄弟不能與她们同席而坐，也不能跟她们用同一个器皿吃飯。男女之間，不經媒人撮合，不能互通姓名而相好；没有接受彩禮不能成為姻親，舉行婚禮必須選擇良辰吉日，必須斋戒和祭祀鬼神，同時還要酒宴招待同乡朋友，來表示其隆重。","sortOrder":41},
  {"id":"s_work_gp_3_42","chapterId":"ch_work_gp_3","text":"另外，男女之間，如果不是遇到祭祀或舉行丧禮，不能相互傳遞用具。如果要相互傳遞，只能是男人把東西放進竹筐里遞給女人，女人從竹筐里取。實在没有竹筐，就需要男人先把東西放在地上，而後女人跪下去取。內室女眷不能和外邊的人取一口井里的水；不能使用同一个浴室；更不能在同一个炕上就寢；也不能相互借東西。男子如果要進入內室，不能嘯叫，不能用手指指點點；夜里出入，要掌蠟燭，没有蠟燭就要停止行動。女子出門，一定要用東西遮蔽住脸；夜里出入也要秉燭，没有蠟燭就要停止行動。在路上也有規矩：男子從右邊走，女子從左邊走。","sortOrder":42},
  {"id":"s_work_gp_3_43","chapterId":"ch_work_gp_3","text":"另外，孩子長到七歲的時候，男女之間就不能在同一个炕席上就寢了，也不能坐在一起吃飯了。这樣是為了顯示男女之間的區別。男孩子長到十歲的時候，就可以到外邊去拜師傅學習，居宿在外邊。女孩子即使到了十歲，也不能出去求學，永遠都居住在內室里。","sortOrder":43},
  {"id":"s_work_gp_3_44","chapterId":"ch_work_gp_3","text":"另外，婦人迎送客人也不能走出門外，即便是與自己的兄弟會面，也不能邁到門槛的外邊。另外，對於公主來說，如果父皇和母後在世，那么公主出嫁之後要經常回家去看望父皇和母後；如果父皇和母後去世了，也應該派晚辈回去看望一下。對於一般百姓家的女子來說，如果父母親在，則要時常回去看望父母；如果父母去世了，也要派晚辈回去看望娘家人。","sortOrder":44},
  {"id":"s_work_gp_3_45","chapterId":"ch_work_gp_3","text":"寢門之外，婦人莫問","sortOrder":45},
  {"id":"s_work_gp_3_46","chapterId":"ch_work_gp_3","text":"【原文】魯公父文伯之母如季氏，康子在其朝，與之言，弗應；從之及寢門，弗應而入。康子辭於朝而入見，曰：“肥也不得聞命，無乃罪乎？”曰：“寢門之內，婦人治其業焉，上下同之。夫外朝，子將業君之官職焉；內朝，子將庀季氏之政焉，皆非吾所敢言也，”","sortOrder":46},
  {"id":"s_work_gp_3_47","chapterId":"ch_work_gp_3","text":"公父文伯之母，季康子之從祖叔母也。康子往焉，　門而與之言，皆不逾閾。仲尼聞之，以為別於男女之禮矣。","sortOrder":47},
  {"id":"s_work_gp_3_48","chapterId":"ch_work_gp_3","text":"【譯述】魯公父文伯的母親是康子的從祖叔母，她到季氏那里造訪的時候，康子正在朝中。康子和她說話，她不答應。康子跟著她來到內室的門口，她仍然不和康子搭話，只顧自己進入里邊。康子覺得很奇怪，退朝後趕忙去拜見從祖叔母，說：“適才我没有聽到您的吩咐，莫非我有什么地方做错了吗？”從祖叔母回答道：“在內室里邊，是婦女们的事，上下都是这樣。在內，你要履行國君交給你的公務；在內，你又要處理季氏家里的事務。这些皆不是我所能够過問的。”","sortOrder":48},
  {"id":"s_work_gp_3_49","chapterId":"ch_work_gp_3","text":"公父文伯的母親是季康子的從祖叔母。康子去看望她，她總是打开門和康子說話，從不邁出門限一步。孔子聽說後，認為他们是認真遵守了男女有別的禮儀。","sortOrder":49},
  {"id":"s_work_gp_3_50","chapterId":"ch_work_gp_3","text":"謙恭治家，尊貴集門","sortOrder":50},
  {"id":"s_work_gp_3_51","chapterId":"ch_work_gp_3","text":"【原文】漢萬石君石奋，無文學，恭謹，舉無與比。奋長子建、次甲、次乙、次慶，皆以馴行孝謹，官至二千石。於是景帝曰：“石君及四子皆二千石，人臣尊寵乃舉集其門。”故號備為萬石君。孝景季年，萬石君以上大夫祿歸老於家，子孫為小吏，來歸謁，萬石君必朝服見之，不名。子孫有過失，不誚讓，為便坐，對案不食。然後諸子相责，因長老肉袒固謝罪，改之，乃許。子孫勝冠者在侧，雖燕必冠，申申如也。僮仆欣欣如也，唯謹。其執丧，哀戚甚。子孫遵教，亦如之。萬石君家以孝謹聞乎郡國，雖齊、魯諸儒质行，皆自以為不及也。建元二年，郎中令王臧以文學獲罪皇太後。太後以為儒者文多质少，今萬石君家不言而躬行，乃以長子建為郎中令，少子慶為內史。建老，白首，萬石君尚無恙。每五日洗沐歸謁親，入子舍，竊問侍者，取親中裙廁牏，身自浣洒，复與侍者，不敢令萬石君知之，以為常。萬石君徙居陵里。內史慶醉歸，入外門不下車。萬石君聞之，不食。慶恐，肉袒謝罪，不許。舉宗及兄建肉袒。萬石君讓曰：“內史貴人，入闾里，里中長老皆走匿，而內史坐車自如，固當！”乃謝罢慶。慶及諸子入里門，趨至家，萬石君元朔五年卒。建哭泣哀思，杖乃能行。歲餘，建亦死。諸子孫鹹孝，然建最甚。【譯述】漢朝的萬石君石奋没有文化，但是他為人謙恭、謹慎，周围很少有人能和他相比。石奋的大兒子石建、二兒子石甲、三兒子石乙、四兒子石慶，都因為溫順孝悌、為人謹慎而官至兩千石。於是漢景帝感叹道：“石奋和他的四个兒子都是兩千石，作為人臣的尊貴和榮寵竟然都集中在了他一个人門上。”所以將石奋稱為“萬石君”。孝景帝末年，萬石君以上大夫的俸祿告老還乡。他的子孫们當的都是小官，回家去拜見萬石君的時候，萬石君總要穿上朝服來會見他们，而且從不叫他们的名字。如果子孫们犯了错誤，萬石君從不责備他们，只是坐在侧面的座位上，吃飯的時候對著桌子不吃飯。这樣子孫就相互责備各自所犯的過失，然後求年歲大的人前去說情。子孫们跟在後邊袒胸露背以表謝罪，立誓要改正错誤。萬石君这才同意原谅他们。那些已經成年的子孫们經常在萬石君身邊侍立，即便是休閒時也要戴著帽子，表現出舒和的氣氛。家中的童子、仆人都是畢恭畢敬，欣然從命的樣子。","sortOrder":51},
  {"id":"s_work_gp_3_52","chapterId":"ch_work_gp_3","text":"萬石君操辦丧事的時候，非常地哀痛悲傷。他的子孫们也都聽從他的教导，也和他表現得一个樣。萬石君的家以孝順和謙恭聞名於郡國，就連齊、魯地區的一些儒者，也都自認為比不上。漢武帝建元二年，郎中令王臧因為寫文章得罪了皇太後，皇太後就認為讀書人知識雖然多，但是品质很差。而萬石君家却因為默默地躬行禮法，為皇太後所稱道，於是長子石建被提拔為郎中令，小兒子石慶被提拔為內史。石建已經老得頭發都白了，可萬石君却非常健康，没有一點病痛。石建非常孝順，他每隔五天就回家去看望父親。進入父親的房間，小聲向佣人打聽父親的身體情况，還親自為父親清洗內衣和便盆，洗幹净就悄悄交給佣人，不敢讓父親萬石君知道。石建这樣做已經成了習慣。","sortOrder":52},
  {"id":"s_work_gp_3_53","chapterId":"ch_work_gp_3","text":"後來萬石君遷徙到陵里居住。有一次，小兒子內史石慶喝醉了酒回來，已經進入了外門，還没有下車。萬石君知道了这件事後，就又不吃飯，石慶非常害怕，袒胸露背向父親請罪，萬石君仍不原谅他。全宗族的人以及石慶的哥哥石建，都袒露胸背前來求告，萬石君责備道：“內史是身份顯貴之人，進入里弄，連里中年歲大的人都要回避。可內史却一點禮法都不懂，坐在車上絲毫反應都没有。这當然要受到懲罰。”說完，他就讓石慶下去。從此之後，石慶和其他幾个哥哥一進入里門，就快步走進家。","sortOrder":53},
  {"id":"s_work_gp_3_54","chapterId":"ch_work_gp_3","text":"萬石君於元朔五年去世。他的大兒子石建悲痛欲絕，拄著拐杖才能行走。過了一年，石建也去世了。萬石君的子孫们一个个都很孝順，但是做得最好的要數石建。","sortOrder":54},
  {"id":"s_work_gp_3_55","chapterId":"ch_work_gp_3","text":"勤俭致富，仗義疏财","sortOrder":55},
  {"id":"s_work_gp_3_56","chapterId":"ch_work_gp_3","text":"【原文】樊重，字君雲。世善農稼，好货殖。重性溫厚，有法度，三世共财，子孫朝夕禮敬，常若公家。其營經產業，物無所弃；課役童隸，各得其宜。故能上下戮力，财利歲倍，乃至开廣田土三百餘頃。其所起庐舍，皆重堂高閣，陂渠灌註。又池魚牧畜，有求必給。嘗欲作器物，先种梓漆，時人嗤之。然積以歲月，皆得其用。向之笑者，鹹求假焉。赀至巨萬，而赈贍宗族，恩加乡闾。外孫何氏，兄弟爭财，重恥之，以田二頃解其忿訟。縣中稱美，推為三老。年八十餘終，其素所假貸人間數百萬，遺令焚削文契。债家聞者皆慚，爭往偿之。諸子從敕，竟不肯受。","sortOrder":56},
  {"id":"s_work_gp_3_57","chapterId":"ch_work_gp_3","text":"【譯述】樊重，字君雲。他家世世代代都很擅長耕种莊稼，併且喜歡做生意。","sortOrder":57},
  {"id":"s_work_gp_3_58","chapterId":"ch_work_gp_3","text":"樊重性情溫和厚道，做事情很講究法度。他们家三代没有分家，财物共有，但子孫都相互禮敬，家里常常像官府一樣講究禮儀。樊重經營家里的產業，非常得法，一點損失浪費都没有；他使用仆人、佣工，能够人盡其用。所以家里能够上下同心戮力，财產和利润每年都成倍增長。以至於後來擁有田地三百餘頃。樊重家所建造的房舍都是層樓高閣，四周有陂渠灌註。樊重家還養魚、養牲畜，乡里有窮困紧急的人向他家求助，樊重一般都滿足他们。樊重曾經想製作器物，他就先种植梓材和漆树。","sortOrder":58},
  {"id":"s_work_gp_3_59","chapterId":"ch_work_gp_3","text":"當時的人们都對他的做法嗤之以鼻。但是在幾年之後，梓树和漆树都派上了用場。過去那些恥笑他的人，現在返過來都向他借这些東西。樊重的錢财積累至成千上萬，他便經常周濟本家同族，施惠於乡里。樊重的外孫何氏，兄弟之間為一些财產而爭斗，樊重為他们的行為感到羞恥，索性送給他们兩頃田地，來解决他们兄弟之間相互憤恨，相互訴訟。本縣的人都稱道樊重的行為和品德，將他推為三老。","sortOrder":59},
  {"id":"s_work_gp_3_60","chapterId":"ch_work_gp_3","text":"樊重在八十多歲的時候去世，他平素所借給別人的錢财多達數百萬，他在遺嘱中安頓子女们將那些有關借貸的文書契約全部燒掉。向他借貸的那些人聽說後都感到很慚愧，爭先恐後地前去偿還。樊重的孩子们都謹遵父親的遺嘱，一概不接受。","sortOrder":60},
  {"id":"s_work_gp_3_61","chapterId":"ch_work_gp_3","text":"【原文】南陽冯良，志行高絜，遇妻子如君臣。","sortOrder":61},
  {"id":"s_work_gp_3_62","chapterId":"ch_work_gp_3","text":"宋侍中謝弘微從叔混以劉毅党見誅，混妻晉陽公主改造琅邪王練。","sortOrder":62},
  {"id":"s_work_gp_3_63","chapterId":"ch_work_gp_3","text":"公主雖執意不行，而詔與謝氏離絕。公主以混家委之弘微。混仍世宰相，一門兩封，田業十餘處，童役千人，唯有二女，年併數歲。弘微經紀生業，事若在公。一錢、尺帛，出入皆有文薄。宋武受命，晉陽公主降封東乡君，節義可嘉，聽還謝氏。自混亡至是九年，而室宇修整，仓廪充盈，門徒不異平日。田畴墾辟有加於舊。東乡叹曰：“仆射生平重此一子，可謂知人，仆射為不亡矣。”中外親姻、里党、故舊，見東乡之歸者，入門莫不叹息，或為流涕，感弘微之義也。弘微性嚴正，舉止必修禮度，婢仆之前不妄言笑，由是尊卑大小，敬之若神。及東乡君薨，遺财千萬，園宅十餘所，及會稽、吳興、琅邪諸處。太傅安、司空琰時事業，奴僮猶數百人。公私或謂：室內資财，宜歸二女；田宅僮仆應屬弘微。弘微一物不取，自以私祿營葬。混女夫殷睿素好摴蒱，聞弘微不取财物，乃濫奪其妻妹及伯母兩姑之分，以還戲责。內人皆化。弘微之讓，一無所爭。弘微舅子領軍將軍劉湛謂弘微曰：“天下事宜有裁衷，卿此不問，何以居官？”弘微笑而不答。或有譏以謝氏累世财產充殷，君一朝弃掷，譬弃物江海，以為廉耳？弘微曰：“親戚爭财，為鄙之甚。今內人尚能無言，豈可道之使爭！今分多共少不至有乏，身死之後，豈复見關！”","sortOrder":63},
  {"id":"s_work_gp_3_64","chapterId":"ch_work_gp_3","text":"【譯述】南陽的冯良，品行高絜，他把自己和妻子的關系處理的如同君臣關系一樣，十分講究禮儀和規矩。","sortOrder":64},
  {"id":"s_work_gp_3_65","chapterId":"ch_work_gp_3","text":"宋代侍中謝弘微的從叔謝混因為受劉毅一党的牵連，被處以死刑。","sortOrder":65},
  {"id":"s_work_gp_3_66","chapterId":"ch_work_gp_3","text":"謝混的妻子晉陽公主改嫁琅邪王練。公主雖然執意不肯離去，但皇上下詔要她離开謝家，併與謝家斷絕關系。公主只好將謝混家的事情委托給謝弘微。謝混是當世宰相，一門兩封，家里擁有田業十多處，童仆雜役上千人，惟獨有兩个女孩子，年紀都才幾歲。謝弘微經營謝混家的生意和產業如同給公家辦事一樣秉公執法，即使是一分錢、一尺帛，進出都有帳目。宋武帝登基後，晉陽公主被降封為東乡君，因為她頗守大節義理，受到人们的稱贊，因此朝廷允許她再重新回到謝家。","sortOrder":66},
  {"id":"s_work_gp_3_67","chapterId":"ch_work_gp_3","text":"從謝混死到現在已有九年，但謝家的房宇仍然修整一新，仓库里的糧食放得滿滿的，家里的佣人雜役仍像以前一樣多，而且耕种、开墾的田地比過去都多。東乡君感叹地說：“仆射平生很看重弘微，他可以稱得上了解人啊，仆射雖死，但香火不滅。”遠近親戚、鄰里、故交看到東乡君歸來後的情景，没有不叹息的，有的甚至被感動得痛哭流涕。大家都在感叹謝弘微的仁義。","sortOrder":67},
  {"id":"s_work_gp_3_68","chapterId":"ch_work_gp_3","text":"弘微的秉性非常嚴謹正直，舉止行動都十分講究禮法。他在奴婢仆人的面前不隨便說笑，因此家里從上到下都對他非常尊敬。東乡君去世之後，留下的财產成千上萬，另有莊園、宅第十餘所，遍布會稽、吳興、琅邪等地。到太傅安、司空琰的時候，謝混家經營產業的奴仆童役仍然有數百人之多。當時社會上有舆論認為，謝混家的财產，室內的錢财應歸謝混的兩个女兒所有，其餘的田宅童仆應當屬於弘微。然而，謝弘微連一件東西都没有拿，連給東乡君舉行葬禮的开銷都是用自己的俸祿支付的。謝混的一个女婿叫殷睿，平時愛好博戲（赌博），聽說謝弘微不動謝混家的财產，他便大肆侵奪屬於妻妹和伯母兩姑名下的那些财產，用來偿還博戲的欠债。家里的人都忍讓他，謝弘微更是一無所爭。弘微的妻弟領軍將軍劉湛對謝弘微說：“天下的任何事情都要有一个正確的裁决，你連这件不公平的家事都不去過問，又怎么可以去做官呢？”謝弘微却只笑不答。有的人諷刺謝弘微說，謝家祖祖辈辈傳下來的财產非常多，可是却在一時間就全部抛弃了，就好象扔到了大海里一樣，但謝弘微竟然還以為这樣做是廉絜呢，豈不是傻瓜！但謝弘微却說：“親戚之間爭奪财產，是最讓人瞧不起的，現在連家里的女人们都能够不說話，我怎么可以引导他们去爭斗呢？眼下财產或多或少，但還不至於匮乏，等到死了之後，又怎么能分得清财產是誰的呢？”","sortOrder":68},
  {"id":"s_work_gp_3_69","chapterId":"ch_work_gp_3","text":"累世同居，親密無間","sortOrder":69},
  {"id":"s_work_gp_3_70","chapterId":"ch_work_gp_3","text":"【原文】劉君良，瀛州樂寿人，累世同居，兄弟至四從，皆如同氣。尺布斗粟，相與共之。隋末，天下大飢，盜賊群起，君良妻欲其異居，乃密取庭树鳥雏交置巢中，於是群鳥大相與斗，舉家怪之。妻乃說君良，曰：“今天下大亂，爭斗之秋，群鳥尚不能聚居，而况人乎？”君良以為然，遂相與析居。月餘，君良乃知其謀，夜攬妻發，骂曰：“破家賊，乃汝耶！”悉召兄弟，哭而告之，立逐其妻，复聚居如初。乡里依之，以避盜賊，號曰義成堡。宅有六院，共一厨。子弟數十人，皆以禮法，貞觀六年，詔旌表其門。","sortOrder":70},
  {"id":"s_work_gp_3_71","chapterId":"ch_work_gp_3","text":"【譯述】劉君良，瀛州樂寿人。他们家好幾代都同在一个大家庭中居住，即使是四從的兄弟，也和同胞兄弟一樣親密和氣。哪怕是一尺布，一斗米，大家都是共同享有。隋朝末年，天下發生了大的飢荒，強盜賊寇非常多，劉君良的妻子想要自己分开居住，於是她想了一个辦法，將庭院里一棵树上的兩个小鳥調換鳥巢放置。这樣一來，兩窩鳥就打了起來。劉君良一家人都覺得很奇怪，劉君良的妻子於是對丈夫說：“現在天下大亂，到處都在爭斗，連鳥都不能在一起安居，更何况人呢？”劉君良認為妻子說的對，就與兄弟们分开來生活。過了一个多月，劉君良明白了妻子原先的計謀，便在晚上揪住妻子的頭發骂道：“破家賊就是你！”他把兄弟们都招呼來，哭泣著把分家的真實原因告訴了大家，立刻將他的妻子休回家，眾兄弟又向开始那樣聚居在一起。乡里的人都依靠他们，以防備盜賊。劉君良的大家庭被稱做“義成堡”。他们的住宅共有六个院落，但只有一个厨房。劉君良的子侄辈合起來有數十人之多，但都能以禮相待。貞觀六年，唐太宗頒布昭令，旌表劉家。","sortOrder":71},
  {"id":"s_work_gp_3_72","chapterId":"ch_work_gp_3","text":"家庭和睦之道：忍忍忍","sortOrder":72},
  {"id":"s_work_gp_3_73","chapterId":"ch_work_gp_3","text":"【原文】張公藝，鄆州寿張人，九世同居，北齊、隋、唐，皆旌表其門。麟德中，高宗封泰山，過寿張，幸其宅，召見公藝，問所以能睦族之道。","sortOrder":73},
  {"id":"s_work_gp_3_74","chapterId":"ch_work_gp_3","text":"公藝請紙筆以對，乃書“忍”字百餘以進。其意以為宗族所以不协，由尊長衣食，或者不均；卑幼禮節，或有不備。更相责望，遂成乖爭。苟能相與忍之，則常睦雍矣。","sortOrder":74},
  {"id":"s_work_gp_3_75","chapterId":"ch_work_gp_3","text":"【譯述】張公藝是唐代鄆州寿張人，他家九代聚居，北齊、隋朝、唐朝都表彰過他的家族。麟德年間，唐高宗到泰山封禪，經過寿張時，駕臨張公藝家。高宗召見張公藝，問他家能够和睦相處的方法。張公藝拿來紙筆，在紙上寫了一百多个“忍”字進呈給高宗皇帝。他的意思是說，有的家族之所以不能和睦协調地相處，或者是因為家長分派衣食不公平，或者是因為上下尊卑的禮節有疏漏，这樣，家庭內部互相责備，產生怨恨，便形成了矛盾和爭斗。倘若家人都能够互相忍讓，那么家族成員就能和睦相處了，整个家族也能長盛不衰。","sortOrder":75},
  {"id":"s_work_gp_3_76","chapterId":"ch_work_gp_3","text":"禮樂教子詩書傳家","sortOrder":76},
  {"id":"s_work_gp_3_77","chapterId":"ch_work_gp_3","text":"【原文】唐河東節度使柳公綽，在公卿間最名。有家法，中門東有小斋，自非朝謁之日，每平旦辄出，至小斋，諸子仲郢等皆束帶。晨省於中門之北。公綽决公私事，接賓客，與弟公權及群從弟再食，自旦至暮，不離小斋。燭至，則以次命子弟一人執經史立燭前，躬讀一過畢，乃講議居官治家之法。或論文，或聽琴，至人定鐘，然後歸寢，諸子复昏定於中門之北。凡二十餘年，未嘗一日变易。其遇飢歲，則諸子皆蔬食，曰：“昔吾兄弟侍先君為丹州刺史，以學業未成不聽食肉，吾不敢忘也。”","sortOrder":77},
  {"id":"s_work_gp_3_78","chapterId":"ch_work_gp_3","text":"姑姊妹侄有孤嫠者，雖疏遠，必為擇婿嫁之，皆用刻木妆奁，缬文絹為資裝。常言，必待資裝丰備，何如嫁不失時。及公綽卒，仲郢一遵其法。國朝公卿能守先法久而不衰者，唯故李相昉家。子孫數世二百餘口，猶同居共爨。田園邸舍所收及有官者俸祿，皆聚之一库，計口日給餅飯，婚姻丧葬所費皆有常數。分命子弟掌其事，其規模大抵出於翰林學士宗諤所製也。","sortOrder":78},
  {"id":"s_work_gp_3_79","chapterId":"ch_work_gp_3","text":"【譯述】唐朝河東節度使柳公綽在公卿士大夫間最為知名。他家家法很嚴。","sortOrder":79},
  {"id":"s_work_gp_3_80","chapterId":"ch_work_gp_3","text":"中門的東邊有个小書斋，只要不是朝見皇帝的日子，他每天清晨准時到小斋去，仲郢等子女都整裝束帶地站在中門之北向他問早安。柳公綽從早到晚不管是處理公事還是私事，以及接待賓客、和弟弟公權及堂弟们進食就餐，從早晨到晚上都不離开小書斋。掌燈以後，就依次叫子弟们捧著經史之書站在燈前，親自朗讀一遍，然後开始講解做官治家的方法。公綽或談論文章，或聆聽彈琴，直到深夜方才回到臥室睡覺，这時子女们又站在中門之北向他道晚安。这樣堅持了二十多年，從未改变過。如果遇到飢荒年月，子女们就以蔬菜為食，公綽對他们說：“先前我们兄弟侍奉父親丹州刺史，因為學業未成，不讓吃肉，我至今也不敢忘記。”堂姊妹中若有丧夫守寡的，即使是關系非常疏遠的，公綽也要為她们選擇夫婿，准備嫁妆，那些嫁妆都是木刻鏡匣以及染花的絲織品。公綽還常常說：與其一定要等待嫁妆丰厚完備，還不如及時出嫁。等到公綽去世後，兒子仲郢完全遵守家法，按父親的做法治家。","sortOrder":80},
  {"id":"s_work_gp_3_81","chapterId":"ch_work_gp_3","text":"在當朝的公卿之中，能够堅持遵守古代禮法的，只有太宗時的宰相李昉。他家好幾代的子孫約有二百多口，但仍然没有分家，還在一起吃飯。家里田園房產的所有收入，以及家里做官者的俸祿，都交回家里統一管理。平時按人口分配飯食，婚嫁丧葬的开支都有規定。選派家中子弟掌管这些事情。李家大家庭的規模大概已超過了翰林學士宗諤家的規模。","sortOrder":81},
  {"id":"s_work_gp_3_82","chapterId":"ch_work_gp_3","text":"单箭易折，眾箭難斷","sortOrder":82},
  {"id":"s_work_gp_3_83","chapterId":"ch_work_gp_3","text":"【原文】夫人爪之利，不及虎豹；膂力之強，不及熊羆；奔走之疾，不及麋鹿；飛颺之高，不及燕雀。苟非群聚以御外患，則反為異類食矣。是故聖人教之以禮，使之知父子兄弟之親。人知愛其父，則知愛其兄弟矣；愛其祖，則知愛其宗族矣。如枝葉之附於根幹，手足之系於身首，不可離也。豈徒使其粲然條理以為榮觀哉！乃實欲更相依庇，以捍外患也。","sortOrder":83},
  {"id":"s_work_gp_3_84","chapterId":"ch_work_gp_3","text":"吐穀浑阿豺有子二十人，病且死，謂曰：“汝等各奉吾一支箭，將玩之。”俄而命母弟慕利延曰：“汝取一支箭折之。”慕利延折之。又曰：“汝取十九支箭折之。”慕利延不能折。阿豺曰：“汝曹知否？单者易折，眾者難摧。戮力一心，然後社稷可固。”言終而死。彼戎狄也，猶知宗族相保以為強，况華夏乎？聖人知一族不足以獨立也，故又為之甥舅、婚媾、姻娅以辅之。猶懼其未也，故又愛養百姓以衛之。故愛親者，所以愛其身也；愛民者，所以愛其親也。如是則其身安若泰山，寿如箕翼，他人安得而侮之哉！故自古聖賢，未有不先親其九族，然後能施及他人者也。彼愚者則不然，弃其九族，遠其兄弟，欲以专利其身。殊不知身既孤，人斯戕之矣，於利何有哉？昔周厲王弃其九族，詩人刺之曰：“懷德惟寧，宗子惟城；毋俾城坏，毋獨斯畏；苟為獨居，斯可畏矣。”","sortOrder":84},
  {"id":"s_work_gp_3_85","chapterId":"ch_work_gp_3","text":"宋昭公將去群公子，樂豫曰：“不可。公族，公室之枝葉也。若去之則本根無所庇荫矣。葛藟猶能庇其根本，故君子以為比，况國君乎？","sortOrder":85},
  {"id":"s_work_gp_3_86","chapterId":"ch_work_gp_3","text":"此諺所謂庇焉，而縱尋斧焉者也，必不可君。其圖之，親之以德，皆股肱也。誰敢携貳！若之何去之？”昭公不聽，果及於亂。","sortOrder":86},
  {"id":"s_work_gp_3_87","chapterId":"ch_work_gp_3","text":"華亥欲代其兄合比為右師，谮於平公而逐之。左師曰：“汝亥也，必亡。汝丧而宗室，於人何有？人亦於汝何有？”既而，華亥果亡。","sortOrder":87},
  {"id":"s_work_gp_3_88","chapterId":"ch_work_gp_3","text":"【譯述】人的爪牙再鋒利，也比不上虎豹；力量再強大，也比不上熊羆；跑得再快，也比不上麋鹿；飛得再高，也不及燕雀。如果不是靠大家的力量來抵御外患，就會被其他動物吞食。因此賢德之人教給人们禮法，告訴人们父子兄弟應該相親相愛。一个人如果愛戴他的父親，就同樣會愛他的兄弟；熱愛他的祖宗，就同樣會愛他的宗族。人與自己家族的關系，就如同枝葉依附於根幹，手腳長在身體上，不可分離。哪里只是為了壮觀和秩序井然以達到表面上的榮耀呢？實在是希望互相保護，抵御外敵啊。吐穀浑阿豺有二十个兒子，他患病快死的時候對兒子们說：“你们各拿一支箭給我，我要玩个遊戲。”一會兒對弟弟慕利延說：“你拿一支箭來折斷它。”慕利延折斷了，阿豺又說：“你去拿十九支箭來，將其折斷。”慕利延却不能折斷。这時阿豺對兒子们說：“你们知道吗？","sortOrder":88},
  {"id":"s_work_gp_3_89","chapterId":"ch_work_gp_3","text":"一支箭很容易折斷，眾多的箭在一起，就難以折斷，只要你们戮力同心，國家就可以穩固。”說完就死了。阿豺是戎狄之人，尚且知道宗族互相保護才能够強大的道理，何况我们是中原內地的人呢？","sortOrder":89},
  {"id":"s_work_gp_3_90","chapterId":"ch_work_gp_3","text":"古代的賢德之人知道仅仅自己本宗族的人力量太单薄，所以又用甥舅關系、婚姻關系來做為辅助。即便如此，仍覺得不够，所以又愛護和撫育百姓，讓百姓來做為自己的護衛。由此看來，愛護自己的親戚，就等於是在愛護自己；愛護天下的民眾，就等於是在愛護自己的親戚。如果能这樣，那么自己就會安如泰山，永無危殆。別人怎么能够侵犯、侮辱你呢！所以，自古以來的聖賢之人，都是先和睦自己的本族遠親，然後再去保護天下的百姓。那些愚蠢的人就不一樣了，他们抛弃本族和親戚，與自己的兄弟们疏遠關系，一心想自己獨得利益。却不知道你一旦孤立無援，別人就會來戕害你，最終能得到什么利益呢？從前，周厲王抛弃九族，當時的人们寫詩來諷刺他：“君王廣施仁德國家才會安寧啊，宗族子弟是王室的堅強護衛。不要損坏自己的護衛啊，不要獨任其力。","sortOrder":90},
  {"id":"s_work_gp_3_91","chapterId":"ch_work_gp_3","text":"如果什么事都自己獨斷专行，这樣實在是太可怕了！”","sortOrder":91},
  {"id":"s_work_gp_3_92","chapterId":"ch_work_gp_3","text":"宋昭公將要去掉群公子，樂豫說：“不能这樣做，整个公族好比是公室的枝葉，如果去掉这些枝葉，那么公室这个树根就没有庇護了。連葛藟这种植物都懂得去庇護它的根，所以君子都用葛藟來比喻做人的道理，而况國君呢？这个諺語說的是國君要用本宗族做為辅弼，如同根要用枝葉來庇護它一樣。如果你用斧子砍掉这些枝葉，那么你一定不能當好國君。對待本家公族，應當用仁德來親近他们，这樣他们就都會成為你的強有力的辅佐。天下有誰敢對你有貳心呢？為什么要去掉他们呢？”昭公不聽樂豫的話，果然导致了國家的大亂。","sortOrder":92},
  {"id":"s_work_gp_3_93","chapterId":"ch_work_gp_3","text":"華亥想取代他的兄長合比成為右師，便到平公那里去說合比的坏話，讓平公把合比趕走。左師說：“你这个華亥呀，早晚必定要滅亡！你削弱你的同宗本族，對別人會怎么樣呢？別人又會對你怎么樣呢？”過了不久，華亥果然死了。","sortOrder":93},
  {"id":"s_work_gp_3_94","chapterId":"ch_work_gp_3","text":"不愛其親，焉能愛自己","sortOrder":94},
  {"id":"s_work_gp_3_95","chapterId":"ch_work_gp_3","text":"【原文】孔子曰：“不愛其親而愛他人者，謂之悖德；不敬其親而敬他人者，謂之悖禮。以順則逆，民無則焉，不在於善，而皆在於凶。德雖得之，君子不貴也。故欲愛其身而弃其宗族，乌在其能愛身也？”","sortOrder":95},
  {"id":"s_work_gp_3_96","chapterId":"ch_work_gp_3","text":"【譯述】孔子說：“不愛自己的親人却去愛別人，这就是违反道德；不敬重自己的親人而敬重別人，这就是违反禮法。君王教育百姓尊從父母，自己却违反道德禮法，这樣百姓就會無所適從。凡是不敬重自己的父母，一味地违背道德禮法的人，即使再講究德行，君子也不會去敬重他。一个人想愛護自己，却抛弃自己的宗族，那又怎么能够做到愛護自己呢？”怨之所生，生於自私【原文】孔子曰：“均無貧，和無寡，安無傾。”善為家者，盡其所有而均之，雖糲食不飽，敝衣不完，人無怨矣。夫怨之所生，生於自私及有厚薄也。","sortOrder":96},
  {"id":"s_work_gp_3_97","chapterId":"ch_work_gp_3","text":"【譯述】孔子說：“家里的财產分配均匀，就没有人貧窮；家里的人能够和睦相處，大家就會团結在一起；家人相安無事，家庭就不會有禍害。”","sortOrder":97},
  {"id":"s_work_gp_3_98","chapterId":"ch_work_gp_3","text":"善於治家的人，將所有财產都平均分配，即使是每天吃粗茶淡飯、穿破舊衣服，甚至吃不飽穿不暖，人们也不會有怨恨產生。怨恨之所以產生，是因為家長自私自利而且對待別人不公平。","sortOrder":98},
  {"id":"s_work_gp_3_99","chapterId":"ch_work_gp_3","text":"天下一尺布，大家共穿天下一斗粟，大家共食【原文】漢世諺曰：“一尺布尚可縫，一斗粟尚可舂。”言尺布可縫而共衣，斗粟可舂而共食。譏文帝以天下之富，不能容其弟也。","sortOrder":99},
  {"id":"s_work_gp_3_100","chapterId":"ch_work_gp_3","text":"【譯述】漢代有一句諺語說：“一尺布尚可縫，一斗粟尚可舂。”意思是說即使天下仅有一尺布，也還可以把它縫製成衣服，大家一起來穿；即使天下仅有一斗穀粟，也還可以做好了大家一起來吃。这句諺語是用來譏諷漢文帝擁有整个天下，却不能容納他的親兄弟。","sortOrder":100},
  {"id":"s_work_gp_3_101","chapterId":"ch_work_gp_3","text":"【原文】梁中書侍郎裴子野，家貧，妻子常苦飢寒。中表貧乏者，皆收養之。","sortOrder":101},
  {"id":"s_work_gp_3_102","chapterId":"ch_work_gp_3","text":"時逢水旱，以二石米為薄粥，仅得遍焉，躬自同之，曾無厭色。此得睦族之道者也。","sortOrder":102},
  {"id":"s_work_gp_3_103","chapterId":"ch_work_gp_3","text":"【譯述】梁代中書侍郎裴子野，家里很窮，妻子兒女經常被飢寒交迫所苦。","sortOrder":103},
  {"id":"s_work_gp_3_104","chapterId":"ch_work_gp_3","text":"裴子野却把没有飯吃的表弟表妹都收養在家。當時正碰上水旱灾害，裴子野家用二石米煮成很稀的粥，家里人多，一人只能吃一碗，裴子野和大家一樣只吃一碗，没有一點不堪忍受的表情。裴子野这种做法可以稱得上是懂得與家族和睦相處的道理了。","sortOrder":104},
  {"id":"s_work_gp_4_1","chapterId":"ch_work_gp_4","text":"家范卷二祖","sortOrder":1},
  {"id":"s_work_gp_4_2","chapterId":"ch_work_gp_4","text":"為兒孫積錢财，不如給後代留功德","sortOrder":2},
  {"id":"s_work_gp_4_3","chapterId":"ch_work_gp_4","text":"【原文】為人祖者，莫不思利其後世。然果能利之者，鮮矣。何以言之？今之為後世謀者，不過廣營生計以遺之。田畴連阡陌，邸肆跨坊曲，粟麥盈囷仓，金帛充箧笥，慊慊然求之猶未足，施施然自以為子子孫孫累世用之莫能盡也。然不知以義方訓其子，以禮法齊其家。自於數十年中勤身苦體以聚之，而子孫於時歲之間奢靡遊荡以散之，反笑其祖考之愚不知自娱，又怨其吝啬，無恩於我，而厲虐之也。始則欺绐攘竊，以充其欲；不足，則立券舉债於人，俟其死而偿之。觀其意，惟患其考之寿也。甚者至於有疾不療，陰行鳩毒，亦有之矣。然則向之所以利後世者，適足以長子孫之惡而為身禍也。頃嘗有士大夫，其先亦國朝名臣也，家甚富而尤吝啬，斗升之粟、尺寸之帛，必身自出納，鎖而封之。晝而佩鑰於身，夜則置鑰於枕下，病甚，困絕不知人，子孫竊其鑰，开藏室，發箧笥，取其财。其人後蘇，即扪枕下，求鑰不得，憤怒遂卒。其子孫不哭，相與爭匿其财，遂致斗訟。其處女蒙首執牒，自訐於府庭，以爭嫁資，為乡党笑。蓋由子孫自幼及長，惟知有利，不知有義故也。夫生生之資，固人所不能無，然勿求多餘，多餘希不為累矣。使其子孫果賢耶，豈蔬糲布褐不能自營，至死於道路乎？若其不賢耶，雖積金滿堂，奚益哉？多藏以遺子孫，吾見其愚之甚也。然則賢聖皆不顧子孫之匮乏邪？","sortOrder":3},
  {"id":"s_work_gp_4_4","chapterId":"ch_work_gp_4","text":"曰：何為其然也？昔者聖人遺子孫以德以禮，賢人遺子孫以廉以俭。舜自侧微積德至於為帝，子孫保之，享國百世而不絕。周自後稷、公劉、太王、王季、文王，積德累功，至於武王而有天下。其《詩》曰：“诒厥孫謀，以燕翼子。”言丰德泽，明禮法，以遺後世而安固之也。故能子孫承統八百餘年，其支庶猶為天下之顯，諸侯棋布於海內。其為利豈不大哉！","sortOrder":4},
  {"id":"s_work_gp_4_5","chapterId":"ch_work_gp_4","text":"【譯述】做為人的先祖，没有不希望能够造福於後代的。可是真能造福於後代的却很少。為什么这樣說呢？因為如今為後代謀利益的那些人，只懂得多積錢财留給後代兒孫。田地連阡陌，商鋪遍布街巷，糧食堆滿了仓库，财物塞滿了箱子，仍然覺得不够，還在苦心謀求。这樣他们心里就怡然自得，自以為子子孫孫世世代代都享用不盡了。但是这些祖辈们却不懂得更重要的是應該用做人的道理來教育子孫，也不懂得用禮法來管理家庭。他们自己幾十年辛勤勞作所積累起來的财富，却被那些没有教養的子孫们在短時間內就揮霍殆盡。子孫们反過來譏笑祖辈们愚蠢，不會享受，還埋怨祖辈吝啬小氣，曾經對自己不好，虐待了自己。那些家里廣有錢财但又没有得到良好教育的後代子孫，大都是一开始欺骗盜竊，以滿足自己的私欲，不够的時候，就向他人立券借债，打算等到祖父死後再來還债。仔細考察一下这些子孫们的心思，發現他们只是盼望祖父早死。更有甚者，祖父有病不但不給治療，反而在暗中投毒，以求早一些得到家里的财產。那些為後代謀利益的祖父们，不但助長了子孫的惡行，也給自己帶來了殺身之禍。過去有一位士大夫，他的祖先也是當朝名臣，他家里非常富裕但他却很小氣，連斗升之粟、尺寸之布，他都要親自管理。他還把金銀财寶鎖得嚴嚴實實，白天把鑰匙裝在身上，晚上睡覺時把鑰匙放在枕頭下邊。後來他得了重病，不懂人事，子孫们趁機把他的鑰匙偷走，打开密室，找到存放财寶的箱子，偷走了金銀财寶。","sortOrder":5},
  {"id":"s_work_gp_4_6","chapterId":"ch_work_gp_4","text":"他從昏迷中蘇醒過來後就尋找枕頭下面的鑰匙，可是鑰匙已没有了，他於是憤怒地死去了。他的子孫们不但没有為他的死而哭泣，反而因為相互爭奪、藏匿财產，打斗、訴訟。就連未嫁人的處女也蒙著頭拿著状紙，在公堂之上喊冤叫屈，為自己爭奪嫁妆。他们的卑鄙行為受到了乡里的譏笑，究其原因，大概就是因為这些子孫们從小長大，只懂得追逐利益，不知道講道義。生活中所用的錢财物資，本來是人所必需的，但是也不要去過分貪求。錢财一旦太多了，就會成為拖累。如果子孫们確實賢能，難道他们連粗食布衣都不能自己求得，難道會冻死饿死在路旁吗？倘若子孫们無能，即便是金銀堆滿屋，又有什么用呢？祖父们積累财富留給子孫後代，足見他们十分愚蠢。難道古代那些先賢都不關心他们的子孫後代的窮富吗？有人問：他们為什么不給後代留下很多财產呢？因為古代聖人懂得留給子孫後代高尚的品德與嚴格的禮法熏陶，賢人们傳給子孫的是廉絜的品质和俭朴的作風。舜出身卑賤却能够努力修養品德，終於當上了帝王。他的子孫们繼承他的高尚品德，統治國家歷經百代而不滅。周朝從後稷、公劉、太王、王季、文王开始修德積功，到了周武王的時候，終於推翻殷商，奪取了天下。《詩經》里說：“周文王謀及子孫，扶助子孫。”指的就是周文王積累恩德，申明禮法，而且將这筆财產傳給後代，使得國家安定、社稷穩固。因而他们的子孫後代能够統治國家八百年。他们的那些旁系親戚也成了天下的望族，被分封的諸侯遍及海內。周家祖先留給後代的利益難道不大吗？","sortOrder":6},
  {"id":"s_work_gp_4_7","chapterId":"ch_work_gp_4","text":"沃土易被人奪，薄田世代相傳","sortOrder":7},
  {"id":"s_work_gp_4_8","chapterId":"ch_work_gp_4","text":"【原文】孫叔敖為楚相，將死，戒其子曰：“王數封我矣，吾不受也。我死，王則封汝，必無受利地。楚越之間有寢邱者，此其地不利而名甚惡，可長有者唯此也。”孫叔敖死，王以美地封其子。其子辭，請寢邱，累世不失。","sortOrder":8},
  {"id":"s_work_gp_4_9","chapterId":"ch_work_gp_4","text":"漢相國萧何，買田宅必居窮僻處，為家不治垣屋，曰：“今後世賢，師吾俭；不賢，無為势家所奪。”","sortOrder":9},
  {"id":"s_work_gp_4_10","chapterId":"ch_work_gp_4","text":"【譯述】孫叔敖擔任楚國相，他快要死的時候告戒他的兒子說：“楚王多次要給我封地，我不接受。我死後，楚王就會賜封地給你们，你们千萬不要接受肥沃的土地。楚越兩地的中間有个地方叫寢邱，那里土地貧瘠而且地名也不好，但能够長期擁有的唯有这塊土地。”孫叔敖死後，楚王果然把一塊好地賜給他的兒子，他的兒子堅决不要，而向楚王請求寢邱这塊薄地。結果好幾代人都保有这塊封地，而未被人侵奪。","sortOrder":10},
  {"id":"s_work_gp_4_11","chapterId":"ch_work_gp_4","text":"漢代相國萧何，他家購買田產房屋一定要選擇荒涼偏僻的地方，家里也很少進行房屋的建筑。萧何解釋說：“如果我的後代賢能，他们就會學習我俭朴的作風；即便無能，田產也不會被有势力的大家族奪去。”祖上多留錢财，後代必然怠惰","sortOrder":11},
  {"id":"s_work_gp_4_12","chapterId":"ch_work_gp_4","text":"【原文】太子太傅疏廣乞骸骨歸乡里，天子賜金二十斤，太子赠以五十斤。","sortOrder":12},
  {"id":"s_work_gp_4_13","chapterId":"ch_work_gp_4","text":"廣日令家具設酒食，請族人、故舊、賓客，相與娱樂。數問其家金餘尚有幾何，趣賣以共具。居歲餘，廣子孫竊謂其崑弟、老人、廣所愛信者曰：“子孫冀及君時頗立產業基址，今日飲食費且盡，宜從大人所勸，說君買田宅。”老人即以閒暇時為廣言此計。廣曰：“吾豈老悖不念子孫哉！顧自有舊田庐，令子孫勤力其中，足以共衣食，與凡人齊。今复增益之，以為贏餘，但教子孫怠惰耳。賢而多财則損其志，愚而多财則益其過。且夫富者，眾之怨也。吾既亡，以教化子孫，不欲蓋其過而生怨。”","sortOrder":13},
  {"id":"s_work_gp_4_14","chapterId":"ch_work_gp_4","text":"【譯述】太子太傅疏廣向朝廷請求告老還乡，皇上賜給他黃金二十斤，太子又賜給他五十斤。疏廣每天命家里人摆酒設宴，款待本族人、朋友和賓客，與这些人吃酒娱樂。他好幾次向家里人詢問金子還剩下多少，讓家里人把金子都賣掉來治辦酒食。这樣過了一年多，子孫们悄悄對疏廣所敬重和信任的、疏廣的兄長說：“子孫们都希望老人在朝廷的時候多挣下些產業田宅，現在家里將皇帝和太子賞賜的一點金子快要吃喝光了，他能够聽從您的勸告，您應該勸說老人買一些田地房產，不要把錢都用於吃喝。”疏廣的哥哥找機會把兒孫们的意思告訴給了疏廣。疏廣說：“我難道老糊涂了吗？我難道不懂得為兒孫们打算吗？我是覺得家里本來就有一些田地和房舍，如果他们能够勤俭持家，足够他们的吃喝穿戴，而且生活水平也能和一般人站齊。現在再給他们增添一些家產，他们就會以為家里很有錢，这樣只能讓那些兒孫们學得懶惰，没有什么好處。","sortOrder":14},
  {"id":"s_work_gp_4_15","chapterId":"ch_work_gp_4","text":"即便是賢惠的人，财產多了也會使他们覺得有依賴而丧失奋發向上的志向；如果是愚蠢的人，财產多了更會因為放縱而增添他们的過失。而且，一般來講，有錢的人，容易招致別人的怨恨。我就要死了，應該教育他们懂得这些道理。我不願去增加他们的過失，也不願讓他们成為別人怨恨的對象。”","sortOrder":15},
  {"id":"s_work_gp_4_16","chapterId":"ch_work_gp_4","text":"留下清白給兒孫","sortOrder":16},
  {"id":"s_work_gp_4_17","chapterId":"ch_work_gp_4","text":"【原文】涿郡太守楊震，性公廉，子孫常蔬食步行。故舊長者，或欲令為开產業。震不肯，曰：“使後世稱為清白吏子孫，以此遺之，不亦厚乎！”","sortOrder":17},
  {"id":"s_work_gp_4_18","chapterId":"ch_work_gp_4","text":"【譯述】涿郡太守楊震，秉性公正廉絜，子孫經常粗食步行。楊震的親朋好友和同乡長者都勸楊震為兒孫们置辦些產業。楊震始終不肯，他說：“讓我的兒孫後代被世人稱為清廉官吏的子孫，將这樣的美名留給子孫，这不是很丰厚的遺產么？”","sortOrder":18},
  {"id":"s_work_gp_4_19","chapterId":"ch_work_gp_4","text":"兒孫自有兒孫福","sortOrder":19},
  {"id":"s_work_gp_4_20","chapterId":"ch_work_gp_4","text":"【原文】南唐德勝軍節度使兼中書令周本，好施。或勸之曰：“公春秋高，宜少留餘赀以遺子孫。”本曰：“吾系草，事吳武王，位至將相，誰遺之乎？”","sortOrder":20},
  {"id":"s_work_gp_4_21","chapterId":"ch_work_gp_4","text":"【譯述】南唐德勝軍節度使兼中書令周本樂善好施。有人勸他說：“您年紀已高，應留些财產給子孫後代。”周本說：“我當年穿著草鞋，跟隨吳武王，後來官至將相，有誰留下财產給我呢？”","sortOrder":21},
  {"id":"s_work_gp_4_22","chapterId":"ch_work_gp_4","text":"由俭入奢易，又奢入俭難","sortOrder":22},
  {"id":"s_work_gp_4_23","chapterId":"ch_work_gp_4","text":"【原文】近故張文節公為宰相，所居堂室，不蔽風雨；服用飲膳，與始為河陽書記時無異。其所親或規之曰：“公月入俸祿幾何，而自奉俭薄如此。外人不以公清俭為美，反以為有公孫布被之诈。”文節叹曰：“以吾今日之祿，雖侯服王食，何忧不足？然人情由俭入奢則易，由奢入俭則難。此祿安能常恃，一旦失之，家人既習於奢，不能頓俭，必至失所，曷若無失其常！吾雖违世，家人猶如今日乎！”聞者服其遠慮。此皆以德業遺子孫者也，所得顧不多乎？","sortOrder":23},
  {"id":"s_work_gp_4_24","chapterId":"ch_work_gp_4","text":"【譯述】新近去世的張文節公擔任宰相的時候，居住的房屋破舊到不能遮蔽風雨；衣服和膳食，也跟他擔任河陽書記時没有什么兩樣。他的親戚規勸他說：“你一个月的俸祿那么多，日常生活竟至如此俭朴。外人不但不把你的清廉俭朴看作美德，相反還以為你像公孫弘一樣在沽名釣譽呢！”文節感叹地說：“凭我現在的俸祿，要想穿王侯的衣服、吃美味佳肴，何愁没有錢？可是我知道人的性情一般都是由俭朴轉向奢侈容易接受，由奢侈轉為俭朴就很難適應。我現在的俸祿怎會永遠保有？一旦失去俸祿，家里的人已經習慣了奢侈的生活，不能馬上轉為俭朴，必然會出現問題。既然这樣，哪如就保持这樣的生活習慣呢！这樣，即便我離开人世，我的家人也還能像現在一樣愉快地生活下去。”聽者都佩服他的深謀遠慮。这些例子都是長辈们把德行和事業留給子孫後代的典范，他们所得到的難道說不多吗？","sortOrder":24},
  {"id":"s_work_gp_4_25","chapterId":"ch_work_gp_4","text":"福祿不要全占盡，留下一些給兒孫","sortOrder":25},
  {"id":"s_work_gp_4_26","chapterId":"ch_work_gp_4","text":"【原文】晉光祿大夫張澄，當葬父，郭璞為占墓地曰：“葬某處，年過百歲，位至三司，而子孫不蕃；某處，年幾减半，位裁乡校，而累世貴顯。”","sortOrder":26},
  {"id":"s_work_gp_4_27","chapterId":"ch_work_gp_4","text":"澄乃葬其劣處，位止光祿，年六十四而亡。其子孫昌炽，公侯將相，至梁陳不絕，雖未必因葬地而然，足見其愛子孫厚於身矣。先公既登侍從，常曰：“吾所得已多，當留以子孫。”處心如此，其顧念後世不亦深乎！","sortOrder":27},
  {"id":"s_work_gp_4_28","chapterId":"ch_work_gp_4","text":"【譯述】晉代光祿大夫張澄，安葬父親的時候，頗懂占卜之術的郭璞為他占卜墓地說：“你父親如果葬在甲地，你可以年過百歲，官至三司，但子孫後代却不興旺。若葬在乙地，你的寿命要减去一半，而且只能擔任乡學小官，可是你的子孫後代會顯貴。”張澄就將父親埋在不好的甲地，果然，他只做了光祿大夫，仅活了六十四歲就去世了。但是他的那些子孫後代都很興旺發達，官至公侯將相的，至梁、陳時代都代有其人。盡管这些不一定只是因為葬地的緣故，但是從中足以看出張澄疼愛兒孫勝過愛護自己。先父做了侍從之後，常常說：“我本人得到的已經够多的了，應該留一些福祿給子孫後代。”他考慮得如此長遠，顧念後世之情不也是很深的嘛！","sortOrder":28},
  {"id":"s_work_gp_5_1","chapterId":"ch_work_gp_5","text":"家范卷三父母/父/母","sortOrder":1},
  {"id":"s_work_gp_5_2","chapterId":"ch_work_gp_5","text":"父子之間有禮有節","sortOrder":2},
  {"id":"s_work_gp_5_3","chapterId":"ch_work_gp_5","text":"【原文】陳亢向於伯魚曰：“子亦有異聞乎？”對曰：“未也。嘗獨立，鯉趨而過庭。曰：‘學詩乎？’對曰：‘未也。’‘不學詩無以言。’鯉退而學詩。他日，又獨立，鯉趨而過庭。曰：‘學禮乎？’對曰：‘未也。’‘不學禮無以立。’鯉退而學禮。”聞斯二者，陳亢退而喜曰：“問一得三，聞詩，聞禮，又聞君子之遠其子也。”","sortOrder":3},
  {"id":"s_work_gp_5_4","chapterId":"ch_work_gp_5","text":"【譯述】陳亢問伯魚說：“孔夫子他老人家有没有什么奇聞逸事呢？”伯魚回答說：“他老人家没有什么奇聞逸事，只是有一次我獨自侍立，他的兒子鯉邁著小步快速經過廳堂，夫子問道：‘你學習《詩經》没有？’孔鯉回答說：‘没有。’夫子教导他說：‘不學《詩經》就没有說話的權利。’孔鯉便下去學習《詩經》。過了幾天，我又獨自侍立先生於侧，鯉又邁著小步快速經過廳堂，夫子問：‘你學習《禮》没有？’鯉回答說：‘没有。’夫子教导說：‘不學習《禮》就不能立身。’孔鯉便下去學習《禮》。”聽了这兩件事，陳亢出去後高興地說：“我問了一件事，却懂得了三个道理：懂得了學《詩經》的道理，懂得了學《禮》的道理，同時又懂得了君子與他的子女之間應該是有禮有節的，不能隨隨便便的道理。","sortOrder":4},
  {"id":"s_work_gp_5_5","chapterId":"ch_work_gp_5","text":"君子教子，遵之以道","sortOrder":5},
  {"id":"s_work_gp_5_6","chapterId":"ch_work_gp_5","text":"【原文】曾子曰：“君子之於子，愛之而勿面，使之而勿貌，遵之以道而勿強言；心雖愛之不形於外，常以嚴莊莅之，不以辭色悅之也。不遵之以道，是弃之也。然強之，或傷恩，故以日月漸摩之也。”","sortOrder":6},
  {"id":"s_work_gp_5_7","chapterId":"ch_work_gp_5","text":"【譯述】曾子說：“君子對於他的子女，喜愛他们却不表露在脸上，支使他们也不露聲色，讓他们按道理做事情，但又不勉強他们。心里雖然很喜愛他们却不表露在外邊，對待他们要嚴肅莊重，不能用和言悅色來讨他们喜歡。不教育子女按道理做事，就會把他们引上邪路。然而如果一味地強迫他们做，又會損傷父子之間的和氣。因此對待子女只能靠平時言傳身教去慢慢引导他们。”","sortOrder":7},
  {"id":"s_work_gp_5_8","chapterId":"ch_work_gp_5","text":"父子之間，不宜簡慢","sortOrder":8},
  {"id":"s_work_gp_5_9","chapterId":"ch_work_gp_5","text":"【原文】北齊黃門侍郎顏之推《家訓》曰：“父子之嚴，不可以狎；骨肉之愛，不可以簡。簡則慈孝不接，狎則怠慢生焉。由命士以上，父子異宮，此不狎之道也；抑搔痒痛，懸衾箧枕，此不簡之教也。”","sortOrder":9},
  {"id":"s_work_gp_5_10","chapterId":"ch_work_gp_5","text":"【譯述】北齊黃門侍郎顏之推在他寫的《家訓》中說：“父子之間應該嚴肅，不能隨隨便便，不能簡慢。如果簡慢隨便，就會因怠慢而形不成父慈子孝，古人規定做官的人家，父子應該分开居住，这是養成父子之間不隨隨便便的方法；兒子要為父母按摩病痛，收拾被褥枕頭等臥具，这是父子之間不生簡慢的道理所在。”","sortOrder":10},
  {"id":"s_work_gp_5_11","chapterId":"ch_work_gp_5","text":"人愛其子，當教子成人","sortOrder":11},
  {"id":"s_work_gp_5_12","chapterId":"ch_work_gp_5","text":"【原文】石碏諫衛莊公曰：“臣聞愛子教之以義方，弗納於邪。驕奢淫逸，所自邪也。四者之來，寵祿過也。”自古知愛子不知教，使至於危辱亂亡者，可勝數哉！夫愛之，當教之使成人。愛之而使陷於危辱亂亡，乌在其能愛子也？人之愛其子者多曰：“兒幼，未有知耳，俟其長而教之。”是猶養惡木之萌芽，曰俟其合抱而伐之，其用力顧不多哉？又如开籠放鳥而捕之，解韁放馬而逐之，曷若勿縱勿解之為易也！","sortOrder":12},
  {"id":"s_work_gp_5_13","chapterId":"ch_work_gp_5","text":"《曲禮》：“幼子常视毋誑。”","sortOrder":13},
  {"id":"s_work_gp_5_14","chapterId":"ch_work_gp_5","text":"“立必正方，不傾聽。”","sortOrder":14},
  {"id":"s_work_gp_5_15","chapterId":"ch_work_gp_5","text":"“長者與之提携，則兩手奉長者之手。負劍辟咡詔之，則掩口而對。”","sortOrder":15},
  {"id":"s_work_gp_5_16","chapterId":"ch_work_gp_5","text":"【譯述】石碏勸諫衛莊公說：“我聽說父親疼愛子女應該教給他们做人的正道，不使他们走上邪路。驕橫奢侈，荒淫放縱，就會走上邪路。驕奢淫逸四种習慣都有，这是過分寵愛他们所造成的。”自古以來許多父親都知道疼愛子女，却不懂得教育子女，以至於使他们危害他人，自取滅亡，这樣的事例還少吗？疼愛子女，就應當教育他们，培養他们成人。疼愛他们却讓他们走上邪路，又怎能算得上疼愛他们呢？疼愛子女的那些人常常說：“孩子小，不懂事，等他们長大後再來教育他们。”这就好比种了一棵不正的树苗，說等到树木長大後再來修剪它，那樣費力不更多吗？又像打开鳥籠把鳥放走之後再去捉鳥，解开韁繩把馬放走之後再去追它，與其这樣，哪如事先就不放开鳥和馬呢？","sortOrder":16},
  {"id":"s_work_gp_5_17","chapterId":"ch_work_gp_5","text":"《禮記·曲禮》說：“對於小孩子，要經常關註教导他，不要讓他學會說假話和誑骗。”","sortOrder":17},
  {"id":"s_work_gp_5_18","chapterId":"ch_work_gp_5","text":"又說：“孩子從小要養成好的習慣，站立的時候一定要中正，不要斜著身子去傾聽。”","sortOrder":18},
  {"id":"s_work_gp_5_19","chapterId":"ch_work_gp_5","text":"又說：“如果有長辈與你握手，你就要用兩只手奉長辈的手。如果長辈俯下身和你說話，你要將自己的嘴用手當住一點，然後再恭敬地說話。”","sortOrder":19},
  {"id":"s_work_gp_5_20","chapterId":"ch_work_gp_5","text":"【原文】《內則》：“子能食食，教以右手。能言，男唯女俞。男鞶革，女鞶絲。六年，教之數與方名；七年，男女不同席，不共食；八年，出入門戶及即席飲食，必後長者，始教之讓；九年，教之數日。十年，出就外傅，居宿於外，學書計。十有三年，學樂、誦詩、舞勺。成童，舞象、學射御。”","sortOrder":20},
  {"id":"s_work_gp_5_21","chapterId":"ch_work_gp_5","text":"【譯述】《禮記·內則》說：孩子會自己吃飯的時候，父母要教給他用右手拿筷子，會說話的時候，要教給他们應答，男孩答“唯”，女孩答“俞”。他们所用的佩囊，男的用皮革，女孩用絲繒，各代表武事和針黹之事。","sortOrder":21},
  {"id":"s_work_gp_5_22","chapterId":"ch_work_gp_5","text":"六歲的時候，教他们數數與記住東西南北这些方位的名稱；七歲的時候，教給他们男女不能同坐，不能在一起吃東西。八歲的時候，告訴他们謙讓之禮，出入門戶以及上炕進餐，都要在長者之後。九歲的時候，要告訴他们朔望與天幹地支的知識。十歲的時候，男孩子就要出去拜師求學，住宿在外邊，學習六書九數。十三歲的時候，要學習音樂、詩書和文舞。到了十五歲之後，就要學習武舞、射箭和駕御車馬。","sortOrder":22},
  {"id":"s_work_gp_5_23","chapterId":"ch_work_gp_5","text":"曾子殺猪教子","sortOrder":23},
  {"id":"s_work_gp_5_24","chapterId":"ch_work_gp_5","text":"【原文】曾子之妻出外，兒隨而啼。妻曰：“勿啼！吾歸，為爾殺豕。”妻歸，以語曾子。曾子即烹豕以食兒，曰：“毋教兒欺也。”","sortOrder":24},
  {"id":"s_work_gp_5_25","chapterId":"ch_work_gp_5","text":"【譯述】曾子的妻子到外邊去辦事，兒子跟著她邊走邊哭。妻子說：“別哭！","sortOrder":25},
  {"id":"s_work_gp_5_26","chapterId":"ch_work_gp_5","text":"等我回來給你殺猪吃猪肉。”妻子回來後，把这件事告訴了曾子。曾子就殺猪煮肉給孩子吃，他說：“我之所以真的給他殺猪吃，是為了教給他不要欺骗人。”","sortOrder":26},
  {"id":"s_work_gp_5_27","chapterId":"ch_work_gp_5","text":"近朱者赤，近墨者黑","sortOrder":27},
  {"id":"s_work_gp_5_28","chapterId":"ch_work_gp_5","text":"【原文】贾誼言：古之王者，太子始生，固舉以禮，使士負之，過闕則下，過廟則趨，孝子之道也。故自為赤子，而教固已行矣。提孩有識，三公三少，固明孝、仁、禮、義。以道習之，逐去邪人，不使見惡行。於是皆選天下之端士、孝弟、博聞、有道術者，以衛翼之。使與太子居處出入。故太子乃生而見正事，聞正言，行正道，左右前後皆正人也。夫習與正人居之，不能毋正。猶生長於齊，不能不齊言也；習與不正人居之，不能毋不正，猶生長於楚，不能不楚言也。","sortOrder":28},
  {"id":"s_work_gp_5_29","chapterId":"ch_work_gp_5","text":"【譯述】漢朝的贾誼說：古代的帝王教育太子，在太子一生下來的時候，就用符合禮法的行動來給他示范。讓人抱著他，經過宮闕的時候就要表示禮貌，經過廟堂的時候就要小步快走，这是培養孝子之道啊！所以，帝王對於後代，孩子還是婴兒的時候，就已經开始對他進行教育了。在孩子懂事的時候，就要請太師、太傅、太保三公和少保、少傅、少師三少來教育太子，讓他明白孝、仁、禮、義的道理。用道來教育太子，把那些心術不正的小人都趕走，不讓太子見到坏事惡行。於是都挑選天下品行端正的人、講究孝悌的人、學識淵博的人和有德行的人，來辅佐教育他。讓这些人一起與太子居住出入。这樣，太子從一生下來看到的就都是有德行的事，聽到的就都是符合道義的話，走的就是正道，因為在他的周围都是些正人君子。道理很簡单，每天和正人君子在一起，自己就自然會成為正人君子。这就好比你從小生長在齊地，就不可能不說齊地的方言；如果每天和那些邪惡的人在一起，你自己也就會成為邪惡的人，这就好比你從小生長在楚地，不能不講楚地的方言一樣。","sortOrder":29},
  {"id":"s_work_gp_5_30","chapterId":"ch_work_gp_5","text":"教婦初來，教子婴孩","sortOrder":30},
  {"id":"s_work_gp_5_31","chapterId":"ch_work_gp_5","text":"【原文】《顏氏家訓》曰：古者聖王，子生孩提，師保固明仁孝禮義，道習之矣。凡庶縱不能爾，當及婴稚，識人顏色，知人喜怒，便加教誨，使為則為，使止則止。比及數歲，可省笞罰，父母威嚴而有慈，則子女畏慎而生孝矣。吾見世間，無教而有愛，每不能然。飲食運為，恣其所欲，宜誡翻奖，應呵反笑，至有識知，謂法當爾。驕慢已習，方乃製之，捶撻至死而無威，忿怒日隆而增怨。逮於長成，終為败德。孔子雲：“少成若天性，習慣如自然”是也。諺雲：“教婦初來，教兒婴孩。”誠哉斯語！","sortOrder":31},
  {"id":"s_work_gp_5_32","chapterId":"ch_work_gp_5","text":"【譯述】《顏氏家訓》說：古代的帝王聖賢，孩子生下後，很小的時候，就有少師少保來負责教他孝仁禮義了。普通百姓雖然不能和皇家一樣，也當在孩子小的時候，他能識人顏色，知人喜怒的時候，就加以教誨，叫他做什么他就做什么，叫他什么不能做他就不去做。这樣幾年後，可以不用體罰，父母既威嚴又有慈愛，子女因畏慎而產生孝心。但我看世上有許多人，只知道愛而不懂得教育，做不到这些。孩子的飲食行為，都隨心所欲。做得不對應訓誡的時候反而夸奖他，應當诃责的時候反而嘻笑，等孩子長大懂事後，還以為理法就是这樣。驕慢的習慣已經養成，这時候大人才來管教他。就是打死他也不能建立尊長的威信，孩子的忿怒天天增長反而會增加他的怨恨。等孩子長大成人，終是德行不好。孔夫子說：“小時候形成的習慣就好像天性一樣，習慣會成為自然。”所講的就是这个道理。俗話說：“教育媳婦要從她初來時开始，教育孩子要從他小的時候开始。“这句話真是說得太正確了。","sortOrder":32},
  {"id":"s_work_gp_5_33","chapterId":"ch_work_gp_5","text":"糾正孩子缺點，如同有病用藥","sortOrder":33},
  {"id":"s_work_gp_5_34","chapterId":"ch_work_gp_5","text":"【原文】凡人不能教子女者，亦非欲陷其罪惡；但重於诃怒，傷其顏色，不忍楚撻惨其肌膚爾。當以疾病為喻，安得不用湯藥針艾救之哉？又宜思勤督訓者，豈願苛虐於骨肉乎？誠不得已也。","sortOrder":34},
  {"id":"s_work_gp_5_35","chapterId":"ch_work_gp_5","text":"王大司馬母衛夫人，性甚嚴正。王在湓城，為三千人將，年逾四十，少不如意，猶捶撻之，故能成其勋業。","sortOrder":35},
  {"id":"s_work_gp_5_36","chapterId":"ch_work_gp_5","text":"【譯述】《顏氏家訓》又說：那些不能好好教育子女的人，也不是存心要把子女陷入罪惡之中；只不過是不願讓子女因自己的责骂而感到脸上不好看，不忍心责打讓子女皮肉受苦罢了。拿人生了病來作个比喻，人有病難道能不用湯藥和針砭、艾熏來救治吗？我们反過來想一想那些勤於督促訓导孩子的人，難道他们真是願意讓孩子受虐待吗？實在是不得已才这樣做的啊。","sortOrder":36},
  {"id":"s_work_gp_5_37","chapterId":"ch_work_gp_5","text":"《顏氏家訓》還說：大司馬王僧辯的母親魏太夫人，品性很嚴正，王僧辯在湓城（九江）擔任軍職，地位已相當高，年紀也四十多了，但稍有做得不對的地方，魏太夫人還是要打他，所以最後王僧辯能建功立業。","sortOrder":37},
  {"id":"s_work_gp_5_38","chapterId":"ch_work_gp_5","text":"愛而不教，反害其子","sortOrder":38},
  {"id":"s_work_gp_5_39","chapterId":"ch_work_gp_5","text":"【原文】梁元帝時，有一學士，聰敏有才，少為父所寵，失於教義。一言之是，遍於行路，終年譽之；一行之非，掩藏文飾，冀其自改。年登婚宦，暴慢日滋，竟以語言不擇，為周逖抽腸衅鼓雲。然則愛而不教，適所以害之也。《傳》稱鳲鳩之養其子，朝從上下，暮從下上，平均如一。至於人，或不能然。《記》曰：父之於子也，親賢而下無能。使其所親果賢也，所下果無能也，則善矣。其溺於私愛者，往往親其無能，而下其賢，則禍亂由此而興矣。","sortOrder":39},
  {"id":"s_work_gp_5_40","chapterId":"ch_work_gp_5","text":"【譯述】《顏氏家訓》又說：“梁元帝時有一个士人，從小聰明有才能，很受父親寵愛，但家里没有很好地教育他。他只要有一句話說得有點理，他父親就不斷地夸奖他，一年到頭到處與人談論；一件事做错了，他父親就百般為他掩飾，替他找各种借口，希望他自己慢慢能改正。後來这人長大成人之後，不好的品质越發展越嚴重，待人粗暴傲慢，最後終於因為講話隨便，觸犯了有權势的周逖，而被周逖抽腸衅鼓，惨殺而死。”这樣看來，家長對子女如果一味溺愛而不懂得去教誨，恰恰是害了孩子。《左傳》說：鳲鳩鳥在喂養孩子的時候，早晨從上到下輪流，晚上從下到上輪流，始終能平等對待，没有偏向。人反倒不能这樣。《禮記》說：父親對於子女，一般都是偏親聰明有才幹的，而對於才能差一些的就不太喜歡。如果為父親的所偏親的果真有才有德，不喜歡的果真是品行才能很差的，那還算是不错的；然而，有些做父親的因溺於私愛，往往是偏親那些無品行無才能的，而疏遠品行端正有才能的。那么，家里的不和與禍亂就從此而生發了。","sortOrder":40},
  {"id":"s_work_gp_5_41","chapterId":"ch_work_gp_5","text":"父母對待子女，不宜偏親偏愛","sortOrder":41},
  {"id":"s_work_gp_5_42","chapterId":"ch_work_gp_5","text":"【原文】《顏氏家訓》曰：人之愛子，罕亦能均。自古及今，此弊多矣。賢俊者自可賞愛，顽魯者亦當矜怜。有偏寵者，雖欲以厚之，更所以禍之。共叔之死，母實為之；趙王之戮，父實使之。劉表之傾宗覆族，袁紹之地裂兵亡，可謂靈龟明鑒。此通論也。","sortOrder":42},
  {"id":"s_work_gp_5_43","chapterId":"ch_work_gp_5","text":"【譯述】人们愛自己的兒子，很少能做到没有偏愛。從古代到現在，这种偏愛的毛病非常多，聰明懂事的孩子自然讨人喜愛，顽皮愚魯的孩子也應當怜愛。偏愛雖然是喜歡他，盼他好，而事實上却是害了他。共叔的死，實际上是他母親的過错；趙王後來被殺，也是他父親偏寵偏愛造成的惡果；劉表和袁紹最終家破人亡，都可以作為偏愛子女的前車之鑒。","sortOrder":43},
  {"id":"s_work_gp_5_44","chapterId":"ch_work_gp_5","text":"曾子終身不娶後妻","sortOrder":44},
  {"id":"s_work_gp_5_45","chapterId":"ch_work_gp_5","text":"【原文】曾子出其妻，終身不取妻。其子元請焉，曾子告其子曰：“高宗以後妻殺孝己，尹吉甫以後妻放伯奇。吾上不及高宗，中不比吉甫，庸知其得免於非乎？”","sortOrder":45},
  {"id":"s_work_gp_5_46","chapterId":"ch_work_gp_5","text":"【譯述】曾子休掉了他的妻子，終身没有再娶。曾子的兒子曾經勸父親再娶後妻，曾子對兒子說：“殷高宗武丁因為後妻進讒言，害死了自己的兒子孝己；周宣王尹吉甫也因為娶了後妻的緣故，放逐了自己的兒子伯奇。我上比不上殷高宗，中比不上尹吉甫，怎么能保證娶了後妻而不發生禍亂呢？”","sortOrder":46},
  {"id":"s_work_gp_5_47","chapterId":"ch_work_gp_5","text":"續娶後妻，極易败家","sortOrder":47},
  {"id":"s_work_gp_5_48","chapterId":"ch_work_gp_5","text":"【原文】後漢尚書令朱暉，年五十失妻。崑弟欲為繼室。暉叹曰：“時俗希不以後妻败家者。”遂不娶。今之人年長而子孫具者，得不以先賢為鑒乎！","sortOrder":48},
  {"id":"s_work_gp_5_49","chapterId":"ch_work_gp_5","text":"【譯述】東漢尚書令朱暉，五十歲的時候死了妻子。兄長想為他續絃，他叹息道：“現在，因為續娶後妻败家的事例很多。”於是不再續娶。如今那些年事已高且子孫滿堂的人，難道能不以前代的賢人為榜樣吗？","sortOrder":49},
  {"id":"s_work_gp_5_50","chapterId":"ch_work_gp_5","text":"子不孝父不慈，其罪惡均等","sortOrder":50},
  {"id":"s_work_gp_5_51","chapterId":"ch_work_gp_5","text":"【原文】《內則》曰：“子婦未孝未敬，勿庸疾怨，姑教之。若不可教，而後怒之。不可怒，子放婦出而不表禮焉。”","sortOrder":51},
  {"id":"s_work_gp_5_52","chapterId":"ch_work_gp_5","text":"【譯述】《內則》說：“兒子和媳婦不孝順不恭敬，也不用怨恨，應該耐心地教育他们。如果不聽教育，然後再去指责他们。指责了也不改正，就將兒子和媳婦趕出家門但不去明說他们违背了孝道。”","sortOrder":52},
  {"id":"s_work_gp_5_53","chapterId":"ch_work_gp_5","text":"【原文】君子之所以治其子婦，盡於是而已矣。今世俗之人，其柔懦者，子婦之過尚小，則不能教而嘿藏之。及其稍著，又不能怒而心恨之。至於惡積罪大，不可禁遏，則喑呜鬱悒，至有成疾而終者。如此，有子不若無子之為愈也。其不仁者，則縱其情性，殘忍暴戾，或聽後妻之讒，或用嬖寵之計，捶扑過分，弃逐冻餒，必欲置之死地而後已。《康誥》稱：“子弗祗服厥父事，大傷厥考心；於父不能字厥子，乃疾厥子。”謂之元惡大憝，蓋言不孝不慈，其罪均也。","sortOrder":53},
  {"id":"s_work_gp_5_54","chapterId":"ch_work_gp_5","text":"【譯述】君子對待兒子和媳婦的辦法，就是这么个道理。如今世俗之人中的那些柔弱無能的父辈，在兒子、媳婦的過错還小的時候，不能及時教育，而是盡力去遮掩。等到他们的過失越來越大的時候，父母又不能發怒去责備他们。等到子女罪大惡極，不能遏製的時候，父母就忧愁苦悶，甚至有人積鬱成病，含恨而死。如果这樣，有子女還不如没子女好。另一方面，也有那些不仁不義的父親，放縱自己的情性，殘忍暴戾地對待子女，有的聽信後妻的讒言，有的用親信的計謀，對兒女過分捶打，或者把子女趕出家門，讓他们挨飢受饿，必欲置之死地才肯罢休。《康誥》說：“子女不能孝順父親，就會大大傷害父親的心；父親不能够養育他的子女，就是仇恨子女。”这樣的人可以稱之為大惡人，这段話大概是說子女不孝順和父親不慈祥，他们的罪惡一樣大。","sortOrder":54},
  {"id":"s_work_gp_5_55","chapterId":"ch_work_gp_5","text":"母慈母败子","sortOrder":55},
  {"id":"s_work_gp_5_56","chapterId":"ch_work_gp_5","text":"【原文】為人母者，不患不慈，患於知愛而不知教也。古人有言曰：“慈母败子。”愛而不教，使淪於不肖，陷於大惡，入於刑辟，歸於亂亡。非他人败之也，母败之也。自古及今，若是者多矣，不可悉數。","sortOrder":56},
  {"id":"s_work_gp_5_57","chapterId":"ch_work_gp_5","text":"【譯述】為人之母，不怕不慈祥，怕的是只知道疼愛子女而不懂得去教育子女。古人說：“慈母败子。”母親溺愛子女却不能教育子女，使子女淪為坏人，陷入惡跡劣行，最終受到懲罰，引出禍亂，自取滅亡。毀他的併非他人，恰恰是做母親的害了他。從古到今，这樣的例子太多了，不可勝數。","sortOrder":57},
  {"id":"s_work_gp_5_58","chapterId":"ch_work_gp_5","text":"古代聖賢重胎教","sortOrder":58},
  {"id":"s_work_gp_5_59","chapterId":"ch_work_gp_5","text":"【原文】周大任之娠文王也，目不视惡色，耳不聽淫聲，口不出敖言。文王生而明聖，卒為周宗。君子謂大任能胎教。古者婦人任子，寢不侧，坐不邊，立不跸，不食邪味，割不正不食，席不正不坐，目不视邪色，耳不聽淫聲。夜則令瞽誦詩，道正事。如此，則生子形容端正，才藝博通矣。彼其子尚未生也，固已教之，况已生乎！","sortOrder":59},
  {"id":"s_work_gp_5_60","chapterId":"ch_work_gp_5","text":"【譯述】周文王的母親懷周文王的時候，眼睛不看不好的顏色，耳朵不聽淫荡的聲音，嘴里不說戲虐調笑的語言。因此，文王生下來就明白賢聖，最終成為开創周代工業的一代聖主。有才德的人認為婦女在懷孕的時候可以胎教，古代的婦女在懷孕的時候，睡覺不侧臥，不在靠邊的地方坐，不一只腳站立，不吃亂七八糟的東西。食物切得不端正不吃，炕席鋪得不正不坐，眼睛不看不好的顏色，耳朵不聽淫荡的聲音。晚上讓盲人朗誦詩，談論正事。这樣，生下的孩子相貌體形端正，才能出眾。人家的孩子還没有出生，就已經开始教育了，而况出生之後呢？","sortOrder":60},
  {"id":"s_work_gp_5_61","chapterId":"ch_work_gp_5","text":"孟母三遷教子","sortOrder":61},
  {"id":"s_work_gp_5_62","chapterId":"ch_work_gp_5","text":"【原文】孟軻之母，其舍近墓，孟子之少也，嬉戲為墓間之事，踴躍筑埋。","sortOrder":62},
  {"id":"s_work_gp_5_63","chapterId":"ch_work_gp_5","text":"孟母曰：“此非所以居之也。”乃去。舍市傍，其嬉戲為衒賣之事。孟母又曰：“此非所以居之也。”乃徙。舍學宮之傍，其嬉戲乃設俎豆揖讓進退。孟母曰：“此真可以居子矣！”遂居之。孟子幼時問東家殺猪何為，母曰：“欲啖汝。”既而悔曰：“吾聞古有胎教，今適有知而欺之，是教之不信。”乃買猪肉食。既長就學，遂成大儒。彼其子尚幼也，固已慎其所習，况已長乎！","sortOrder":63},
  {"id":"s_work_gp_5_64","chapterId":"ch_work_gp_5","text":"【譯述】孟軻的母親家住在靠近墓地的地方，孟軻小時候就常玩些挖墓埋死人的遊戲，而且玩得非常起劲。母親就說：“此處不適合居住。”於是將家搬走，遷居到集市旁邊，於是孟軻又以學習商販吆喝叫賣為遊戲。","sortOrder":64},
  {"id":"s_work_gp_5_65","chapterId":"ch_work_gp_5","text":"孟母又說：“这里也不適合居住。”就又舉家遷徙，搬到學校旁邊的房舍里，这樣孟子就玩些祭祀、揖讓、進退的有關禮儀方面的遊戲。孟母高興地說：“这里才是居住的好地方。”於是就在这里安居。孟子小時候問母親鄰居為什么要殺猪，母親回答說：“給你吃肉。”說完又後悔了，心想：“我聽說古人就很註重胎教，現在孩子刚懂事，我就欺骗他，这是教他不講信用。”因此為了證明自己說話算數，孟母就買猪肉給孟子吃。孟子長大後讀書學習，終於成為博學多才的大學問家。孟母在孩子小的時候，就認真培養兒子的好習慣，何况在兒子長大之後呢？","sortOrder":65},
  {"id":"s_work_gp_5_66","chapterId":"ch_work_gp_5","text":"為子待客，其母斷發","sortOrder":66},
  {"id":"s_work_gp_5_67","chapterId":"ch_work_gp_5","text":"【原文】漢丞相翟方進繼母隨方進之長安，織履，以資方進遊學。","sortOrder":67},
  {"id":"s_work_gp_5_68","chapterId":"ch_work_gp_5","text":"晉太尉陶侃，早孤貧，為縣吏番陽，孝廉范逵嘗過侃，時仓卒無以待賓。其母乃截發，得双髲以易酒肴。逵荐侃於庐江太守，召為督郵，由此得仕進。","sortOrder":68},
  {"id":"s_work_gp_5_69","chapterId":"ch_work_gp_5","text":"【譯述】漢代的丞相翟方進求學的時候，他的繼母跟隨他到長安，靠編草鞋赚錢來資助方進拜師求學。","sortOrder":69},
  {"id":"s_work_gp_5_70","chapterId":"ch_work_gp_5","text":"晉代太尉陶侃，從小丧父，家里很窮，他擔任番陽縣吏之時，孝廉范逵來家探訪。一時間家里没有東西招待客人，他的母親就剪掉頭發，用頭發換來酒肴招待客人。後來，范逵向庐江太守推荐陶侃，太守就任命陶侃為督郵，陶侃從此進身仕途。","sortOrder":70},
  {"id":"s_work_gp_5_71","chapterId":"ch_work_gp_5","text":"兒子交友不善，母親拒絕吃飯","sortOrder":71},
  {"id":"s_work_gp_5_72","chapterId":"ch_work_gp_5","text":"【原文】後魏鉅鹿魏緝母房氏，緝生未十旬，父溥卒。母鞠育不嫁，訓导有母儀法度。緝所交遊，有名勝者，則身具酒饌。有不及己者，辄屏臥不餐，須其悔謝乃食。","sortOrder":72},
  {"id":"s_work_gp_5_73","chapterId":"ch_work_gp_5","text":"【譯述】後魏時候鉅鹿魏緝的母親房氏，魏緝刚生下來還不到十旬，他的父親魏溥就死了。魏緝的母親為了養育魏緝，不再改嫁，魏母教育孩子頗知禮儀法度。魏緝在外邊結交的人如果是有好名聲的，來家做客，魏母就親自准備酒食，款待客人。如果是品德修養差的人，她就睡在屏風後面，不出來吃飯，一定要在事後兒子表示悔恨，向她謝罪，她才肯吃飯。不以肥鮮所動，教子勤學讀書","sortOrder":73},
  {"id":"s_work_gp_5_74","chapterId":"ch_work_gp_5","text":"【原文】唐侍御史趙武孟，少好田獵，嘗獲肥鮮以遺母。母泣曰：“汝不讀書，而田獵如是，吾無望矣！”竟不食其膳。武孟感激勤學，遂博通經史，舉進士，至美官。","sortOrder":74},
  {"id":"s_work_gp_5_75","chapterId":"ch_work_gp_5","text":"【譯述】唐代侍御史趙武孟，少年的時候喜歡打獵。有一次捕獲了一些又肥又鮮的獵物，他將獵物獻給母親。母親不但没有高興，反而哭著說：“你不讀書，却去無休止地打獵，我没有指望了！”於是不吃飯。武孟為母親的教誨所感動，开始勤奋學習，終於博通經史，考中進士，當了大官。勸子苦讀，口含黃連","sortOrder":75},
  {"id":"s_work_gp_5_76","chapterId":"ch_work_gp_5","text":"【原文】天平節度使柳仲郢母韓氏，常粉苦參、黃連和以熊胆以授諸子，每夜讀書使噙之，以止睡。","sortOrder":76},
  {"id":"s_work_gp_5_77","chapterId":"ch_work_gp_5","text":"【譯述】天平節度使柳仲郢的母親韓氏，常常浸泡苦參、黃連和熊胆，交給幾个兒子，兒子们每天晚上讀書的時候，她就讓他们將这些東西含在嘴里，用这个辦法來製止他们打瞌睡。","sortOrder":77},
  {"id":"s_work_gp_5_78","chapterId":"ch_work_gp_5","text":"苟得錢财，不如正己立名","sortOrder":78},
  {"id":"s_work_gp_5_79","chapterId":"ch_work_gp_5","text":"【原文】太子少保李景讓母鄭氏，性嚴明，早寡家貧，親教諸子。久雨，宅後古牆頹陷，得錢滿缸。奴婢喜，走告鄭。鄭焚香祝之曰：“天蓋以先君餘慶，愍妾母子孤貧，賜以此錢。然妾所願者，諸子學業有成，他日受俸，此錢非所欲也。”亟命掩之。此唯患其子名不立也。","sortOrder":79},
  {"id":"s_work_gp_5_80","chapterId":"ch_work_gp_5","text":"【譯述】太子少保李景讓的母親鄭氏秉性嚴明，年輕時就守了寡，家里也很貧窮，她就親自教育子女。一次，因為下了很久的雨，房屋後面的古牆倒塌，露出滿滿一缸錢。奴婢發現後非常高興，連忙跑去告訴鄭氏。鄭氏燒香祈祷：“大概是因為孩子的父親生前積下陰德，上帝可怜我们母子孤寡貧窮，賜給我们这些錢。然而我所希望的只是孩子们學業有成，將來做官得到傣祿，这些錢併不是我想要的。”祈祷畢，她立刻命令奴婢將錢掩埋。鄭氏这樣做就是擔心子女將來不能立名。","sortOrder":80},
  {"id":"s_work_gp_5_81","chapterId":"ch_work_gp_5","text":"【原文】齊相田稷子受下吏金百镒，以遺其母。母曰：“夫為人臣不忠，是為人子不孝也。不義之财，非吾有也。不孝之子，非吾子也。子起矣。”稷子遂慚而出，反其金而自歸於宣王，請就誅。宣王悅其母之義，遂赦稷子之罪，复其位，而以公金賜母。","sortOrder":81},
  {"id":"s_work_gp_5_82","chapterId":"ch_work_gp_5","text":"【譯述】齊國丞相田稷子接受了部下送給他的一百镒金子，回家之後他把这些金子交給母親。母親說：“做為人的臣子而不忠誠，就等於是為人之子而不孝順。你这些不義之财，我不要。你这个不孝之子，也不是我的兒子，你走吧！”田稷子十分羞愧地離开家，將那一百镒金子還給部下，自己到齊宣王那里請求皇上殺頭治罪。宣王欣賞他母親的深明大義，於是就赦免了他的罪過，讓他仍任原職，而且還從國库里拿出一些金子賞賜給他的母親。","sortOrder":82},
  {"id":"s_work_gp_5_83","chapterId":"ch_work_gp_5","text":"雋母教子：為吏不可貪殘","sortOrder":83},
  {"id":"s_work_gp_5_84","chapterId":"ch_work_gp_5","text":"【原文】漢京兆尹雋不疑，每行縣錄囚徒，還，其母辄問不疑，有所平反，活幾何人耶？不疑多有所平反，母喜，笑為飲食，言語異於它時。或亡所出，母怒，為不食。故不疑為吏嚴而不殘。","sortOrder":84},
  {"id":"s_work_gp_5_85","chapterId":"ch_work_gp_5","text":"【譯述】漢代京兆尹雋不疑，每次下去验收登記囚徒返回來的時候，母親總要詢問雋不疑，这次有没有平反的囚徒，你救了幾个被冤枉的人？如果雋不疑平反得多，母親就高興，有說有笑地吃飯，說起話來也與平時不一樣。有時，雋不疑說没有囚徒得到平反，母親就不高興，拒絕用餐。","sortOrder":85},
  {"id":"s_work_gp_5_86","chapterId":"ch_work_gp_5","text":"正因為这樣，雋不疑做為官吏，雖然嚴厲，但併不殘酷。","sortOrder":86},
  {"id":"s_work_gp_5_87","chapterId":"ch_work_gp_5","text":"教子為官廉絜","sortOrder":87},
  {"id":"s_work_gp_5_88","chapterId":"ch_work_gp_5","text":"【原文】吳司空孟仁嘗為監魚池官，自結網捕魚作鮓寄母。母還之曰：“汝為魚官，以鮓寄母，非避嫌也！”","sortOrder":88},
  {"id":"s_work_gp_5_89","chapterId":"ch_work_gp_5","text":"【譯述】三國時東吳的司空孟仁曾經擔任監魚池官，他親自結網捕魚，將捕獲的魚製成腌魚，然後寄給母親。母親退還給他說：“你身為魚官，却把腌魚寄給你的母親，你没有做到當官應該避嫌疑！”","sortOrder":89},
  {"id":"s_work_gp_5_90","chapterId":"ch_work_gp_5","text":"【原文】晉陶侃為縣吏，嘗監魚池，以一坩鮓遺母。母封鮓责曰：“爾以官物遺我，不能益我，乃增吾忧耳。”","sortOrder":90},
  {"id":"s_work_gp_5_91","chapterId":"ch_work_gp_5","text":"【譯述】晉代陶侃擔任縣吏，曾經監管魚池，他將一些腌魚送給母親，母親不接受，還责備他說：“你將公家的東西送給我，不但對我没有好處，相反還會增加我的忧慮。”","sortOrder":91},
  {"id":"s_work_gp_5_92","chapterId":"ch_work_gp_5","text":"鄭母有節操，兒子為清官","sortOrder":92},
  {"id":"s_work_gp_5_93","chapterId":"ch_work_gp_5","text":"【原文】隋大理寺卿鄭善果母翟氏，夫鄭誠讨尉遲迥戰死。母年二十而寡，父欲奪其志。母抱善果曰：“鄭君雖死，幸有此兒。弃兒為不慈，背死夫為無禮。”遂不嫁。善果以父死王事，年數歲拜持節大將軍，袭爵开封縣公，年四十授沂州刺史，尋為魯郡太守。母性賢明，有節操，博涉書史，通晓政事。每善果出聽事，母辄坐胡床，於障後察之。聞其剖斷合理，歸則大悅，即賜之坐，相對談笑；若行事不允，或妄嗔怒，母乃還堂，蒙袂而泣，終日不食。善果伏於床前不敢起。母方起，謂之曰：“吾非怒汝，乃慚汝家耳。吾為汝家婦，獲奉洒扫，知汝先君忠勤之士也，守官清恪，未嘗問私，以身殉國。繼之以死，吾亦望汝副其此心。","sortOrder":93},
  {"id":"s_work_gp_5_94","chapterId":"ch_work_gp_5","text":"汝既年小而孤，吾寡耳，有慈愛無威，使汝不知禮訓，何可負荷忠臣之業乎？汝自童稚袭茅土，汝今位至方嶽，豈汝身致之邪？不思此事而妄加嗔怒心緣驕樂，墮於公政，內則墜爾家風，或失亡官爵；外則虧天子之法，以取辜戾。吾死日，何面目見汝先人於地下乎？”母恒自紡績，每至夜分而寢。善果曰：“兒封侯开國，位居三品，秩俸幸足，母何自勤如此？”答曰：“吁！汝年已長，吾謂汝知天下理，今聞此言，故猶未也。至於公事，何由濟乎？今此秩俸，乃天子報汝先人之殉命也，當散贍六姻，為先君之惠，奈何獨擅其利，以為富貴乎？又絲枲紡績，婦人之務，上自王後，下及大夫士妻，各有所製，若墮業者，是為驕逸。","sortOrder":94},
  {"id":"s_work_gp_5_95","chapterId":"ch_work_gp_5","text":"吾雖不知禮，其可自败名乎？”自初寡，便不御脂粉，常服大練，性又節俭，非祭祀、賓客之事，酒肉不妄陳其前；靜室端居，未嘗辄出門閣。內外姻戚有吉凶事，但厚加赠遺，皆不詣其門。非自手作，及莊園祿賜所得，雖親族禮遺，悉不許入門。善果歷任州郡，內自出饌，於衙中食之，公廨所供皆不許受，悉用修理公宇及分僚佐。善果亦由此克己，號為清吏，考為天下最。","sortOrder":95},
  {"id":"s_work_gp_5_96","chapterId":"ch_work_gp_5","text":"【譯述】隋代大理寺卿鄭善果的母親翟氏，丈夫鄭誠征讨尉遲迥時戰死。翟氏年方二十歲就守了寡，父親想讓她改嫁，翟氏抱著兒子善果說：“鄭君雖然已死，但是幸虧還有一个兒子。抛弃兒子就是不慈愛，背叛死去的丈夫就是無禮。”於是不再嫁人。善果因為父親為國而死，年仅幾歲就被封為持節大將軍，袭开封縣公的爵位，四十歲就擔任沂州刺史，不久又為魯郡太守。善果的母親秉性賢良，頗有節操，博覽書史，通晓政事。善果每次出去處理公事，母親就坐在胡床上，躲在屏障後暗中觀察。聽到兒子分析裁斷合理，回家就非常高興，讓兒子坐在身旁，母子俩說說笑笑。如果兒子辦事不公允，或者無端發怒，母親回到屋里，就蒙面而哭，整天不吃飯。善果跪在母親床前不敢起來。母親这才起來，對他說：“併不是我對你發怒，只是為你家感到羞愧。我是你家的媳婦，能在你家洒扫侍奉，知道你父親是个忠誠勤奋的人，為官清廉，未嘗營私，最終以身殉國，我也指望你繼承你先父的遺志。你年幼丧父，我丧夫守寡，有慈無威，使你不懂得禮訓，你又怎能勝任忠臣的事業？你自孩童之時就承袭封位，如今位至地方官，这難道是你自己努力所獲得的吗？","sortOrder":96},
  {"id":"s_work_gp_5_97","chapterId":"ch_work_gp_5","text":"不去想想这些事情，却妄加發怒，心里想著驕奢取樂，怠於公務。對於家里你是败坏家風，甚至會导致失去官位袭爵；在外則违背天子的王法，自取滅亡。我死後，你又有何脸面去見你的父親呢？”善果的母親經常紡紗織布，直至深夜方才睡覺。善果便問：“我封侯开國，位至三品，俸祿丰厚，母親為何還要如此勤勞？”母親回答說：“唉！你已長大，我以為你懂得道理了。如今聽你这話，才知道你還是不懂道理。你这个樣子，又怎么能幹好公事呢？你現在的俸祿，是皇帝對你父親為國捐軀的厚報，應當將这些好處散發給六親，以示你父親的恩惠，為何你只想著獨享其利，謀求个人的富貴呢？再說紡紗織布，是婦人的本職，上自王後，下至士大夫之妻，各有應該幹的事。如果停止紡紗織布，就是貪圖安逸。我雖然不懂得禮法，可是怎么能败坏鄭家的名聲呢？”翟氏從守寡开始，就不再涂脂抹粉，經常穿粗布衣服。她秉性節俭，除了祭祀或宴請賓客，吃飯一般不摆放酒肉。平時只靜靜地獨自呆在家里，未曾離开房門一步。內外親戚有什么吉凶事情，她都要赠送厚禮，但從不親自不登門。不是親手製作的東西，以及莊園出產或皇上賞賜給的東西，即便是親戚朋友赠送的禮品，她都一概不許拿進家門。善果擔任各地州郡長官，都由自己家提供飲食，他拿到衙門里去吃，官署所提供的，都不接受，都用作修理官舍，或者分給下邊的官員僚屬。善果也因此克己奉公，被稱為清廉的官吏，被考評為全國最好的官員。","sortOrder":97},
  {"id":"s_work_gp_5_98","chapterId":"ch_work_gp_5","text":"為官貪贓，與強盜無異","sortOrder":98},
  {"id":"s_work_gp_5_99","chapterId":"ch_work_gp_5","text":"【原文】唐中書令崔玄，初為库部員外郎，母盧氏嘗戒之曰：“吾嘗聞姨兄辛玄馭雲：‘兒子從官於外，有人來言其貧窭不能自存，此吉語也；言其富足，車馬輕肥，此惡語也。’吾嘗重其言。比見中表仕宦者，多以金帛獻遺其父母。父母但知忻悅，不問金帛所從來。若以非道得之，此乃為盜而未發者耳，安得不忧而更喜乎？汝今坐食俸祿，苟不能忠清，雖日殺三牲，吾猶食之不下咽也。”玄由是以廉謹著名。","sortOrder":99},
  {"id":"s_work_gp_5_100","chapterId":"ch_work_gp_5","text":"【譯述】唐代中書令崔玄，起初擔任库部員外郎，母親盧氏經常告誡他說：“我曾經聽姨兄辛玄馭對我說：‘兒子在外邊做官，如果有人來說他貧窮不能自存，这是好事兒；如果說他十分富裕，車輕馬肥，那就是坏話。’我很重视姨兄的这些話。常見那些做官的表兄表弟，多拿回金銀布帛送給他们的父母。父母只知道高興，却不問金銀布帛從何而來。若是他们通過不正當的途径得來，那就好比做了強盜未被發現一樣，这怎么能叫人不發愁反倒高興呢？你現在拿了國家的俸祿，如果不能忠誠、清廉，即便是每天給我殺猪宰羊，我也吃不下去啊！”玄在母親的教育下，以為官清廉、謹慎聞名於當時。","sortOrder":100},
  {"id":"s_work_gp_5_101","chapterId":"ch_work_gp_5","text":"母親高義，感動三軍","sortOrder":101},
  {"id":"s_work_gp_5_102","chapterId":"ch_work_gp_5","text":"【原文】李景讓，宦已達，發斑白，小有過，其母猶撻之。景讓事之，終日常兢兢。及為浙西觀察使，有左右都押牙忤景讓意，景讓杖之而毙。軍中憤怒，將為变。母聞之。景讓方视事，母出，坐廳事，立景讓於庭下而责之曰：“天子付汝以方面，國家刑法，豈得以為汝喜怒之資，妄殺無罪之人乎？萬一致一方不寧，豈惟上負朝廷，使垂老之母衔羞入地，何以見汝先人乎？”命左右禠其衣坐之，將撻其背。將佐皆至，為之請。不許。將佐拜且泣，久乃釋之。軍中由是遂安。此惟恐其子之入於不善也。","sortOrder":102},
  {"id":"s_work_gp_5_103","chapterId":"ch_work_gp_5","text":"【譯述】李景讓，在官場上已很顯赫了，而且頭發已花白，年紀也很大了，然而，只要稍有過错，母親仍舊要鞭撻他。景讓侍奉母親，整天戰戰兢兢。景讓擔任浙西觀察使時，有个部下违背了他的意願，他就將其杖责致死。軍士憤怒，眼看就要哗变。母親聽說了这件事後，景讓處理公務的時候，母親就走出來坐在廳堂之上，命景讓站在庭下，然後斥责說：“皇帝將一方的軍政事務交給你，國家刑法，怎么能作為你隨意發泄喜怒哀樂的資本而去枉殺無罪之人呢？萬一引起一方的動亂，何止是上負朝廷，而且使你垂老之母含羞入地，我又有何面目去見你的先人呢？”","sortOrder":103},
  {"id":"s_work_gp_5_104","chapterId":"ch_work_gp_5","text":"就命手下剝去他的衣服，摁翻在地，准備鞭打他。这時，軍中將領都來了，都為他求情，母親不答應。將領们一邊拜一邊哭泣哀求，過了很久母親方才同樣釋放李景讓。軍中因此才安定下來。李母这樣做是擔心兒子走上不仁不善的邪路。","sortOrder":104},
  {"id":"s_work_gp_5_105","chapterId":"ch_work_gp_5","text":"兒為正義死，慈母不落淚","sortOrder":105},
  {"id":"s_work_gp_5_106","chapterId":"ch_work_gp_5","text":"【原文】漢汝南功曹范滂坐党人被收，其母就與訣曰：“汝今得與李杜齊名，死亦何恨！既有令名，复求寿考，可兼得乎？”滂跪受教，再拜而辭。","sortOrder":106},
  {"id":"s_work_gp_5_107","chapterId":"ch_work_gp_5","text":"【譯述】漢代汝南功曹范滂受党人牵連被收執，他的母親於是與他訣別，說：“你為正義而死，得以與李杜齊名，死又有什么遺憾的呢？你既已獲得了名節，還怎么去追求長寿呢，这二者豈可都占全呢？”范滂跪地領受教誨，向母親拜了兩拜，辭別而去。","sortOrder":107},
  {"id":"s_work_gp_5_108","chapterId":"ch_work_gp_5","text":"【原文】魏高貴乡公將讨司馬文王，以告侍中王沈、尚書王經、散騎常侍王業。沈、業出走告文王，經獨不往。高貴乡公既薨，經被收。辭母，母顏色不变，笑而應曰：“人誰不死，但恐不得死所，以此併命，何恨之有？”","sortOrder":108},
  {"id":"s_work_gp_5_109","chapterId":"ch_work_gp_5","text":"【譯述】魏高貴乡公准備征讨司馬文王，他把这个打算告訴了侍中王沈、尚書王經、散騎常侍王業。王沈和王業出來後，就跑到司馬文王那兒告了密，惟獨王經没有去。後來，高貴乡公去世，王經於是被收執。王經去和母親告別，母親脸色不变，笑著說：“人哪有不死的，只怕死得不值得，你為正義而死，又有什么遺憾的呢？”","sortOrder":109},
  {"id":"s_work_gp_5_110","chapterId":"ch_work_gp_5","text":"為成子名，母不避禍","sortOrder":110},
  {"id":"s_work_gp_5_111","chapterId":"ch_work_gp_5","text":"【原文】唐相李義府专橫，侍御史王義方欲奏彈之，先白其母曰：“義方為御史，视奸臣不糾則不忠，糾之則身危而忧及於親，為不孝；二者不能自决，奈何？”母曰：“昔王陵之母殺身以成子之名，汝能盡忠以事君，吾死不恨。”此非不愛其子，惟恐其子為善之不終也。然則為人母者，非徒鞠育其身使不罹水火，又當養其德使不入於邪惡，乃可謂之慈矣！","sortOrder":111},
  {"id":"s_work_gp_5_112","chapterId":"ch_work_gp_5","text":"【譯述】唐朝宰相李義府专橫跋扈，侍御史王義方想彈劾他，先告訴母親說：“我身為御史，看見奸臣而不去彈劾是對皇上不忠；若彈劾他，那么自己危险又會使親人擔忧，这是對母親不孝。这兩者我無法作出决斷，怎么辦才好呢？”母親說：“昔日王陵的母親自殺以成全兒子的名聲，你能以忠誠事君報國，我死而無恨。”这併不是不喜愛兒子，是擔心兒子不能至始至終做好事。為人之母，她的责任併非只是撫養兒子長大，使他不遭水、火之灾，還應當培養他的品德，使他不走上邪路，这才稱得上是慈母。","sortOrder":112},
  {"id":"s_work_gp_5_113","chapterId":"ch_work_gp_5","text":"慈愛之道，義感人神","sortOrder":113},
  {"id":"s_work_gp_5_114","chapterId":"ch_work_gp_5","text":"【原文】漢明德馬皇後無子，贾貴人生肅宗。顯宗命後母養之，謂曰：“人未必當自生子，但患愛養不至耳。”後於是盡心撫育，勞瘁過於所生。","sortOrder":114},
  {"id":"s_work_gp_5_115","chapterId":"ch_work_gp_5","text":"肅宗亦孝性淳篤，恩性天至，母子慈愛，始終無纖介之間。古今稱之，以為美談。","sortOrder":115},
  {"id":"s_work_gp_5_116","chapterId":"ch_work_gp_5","text":"【譯述】漢明德馬皇後自己没生兒子，贾貴人生下了肅宗。顯宗命後母撫養肅宗，併且說：“人不一定只有自己生的孩子才感情好，只怕你愛護養育的恩情不够啊！”後母於是盡心竭力地撫養肅宗，其辛勞的程度超過了親生子。肅宗對待後母也非常誠恳孝順，自然就產生了養育之恩，他们母子慈愛，始終没有一點隔閡。这件事古今傳誦，成為美談。","sortOrder":116},
  {"id":"s_work_gp_5_117","chapterId":"ch_work_gp_5","text":"【原文】隋番州刺史陆讓母冯氏，性仁愛，有母儀。讓即其孽子也，坐贓當死。將就刑，冯氏蓬頭垢面詣朝堂，數讓罪，於是流涕呜咽，親持杯粥勸讓食，既而上表求哀，詞情甚切。上愍然為之改容，於是集京城士庶於朱雀門，遣舍人宣詔曰：“冯氏以嫡母之德，足為世范，慈愛之道，義感人神。特宜矜免，用奖風俗。讓可减死，除名。”复下詔褒美之，賜物五百段，集命婦與冯相識，以旌寵異。","sortOrder":117},
  {"id":"s_work_gp_5_118","chapterId":"ch_work_gp_5","text":"【譯述】隋朝刺史陆讓的母親冯氏，生性仁愛，有慈母的風范。陆讓是她的庶子，犯了貪贓枉法的罪，應當被處死，即將受刑的時候，冯氏蓬頭垢面來到朝堂，首先數落陆讓的罪行，流涕痛哭，親自捧著一碗粥勸陆讓吃，接著上書皇上哀求，言詞悲哀，情真意切。皇上怜悯而為之改变了態度，於是召集京城的士庶官員來到朱雀門，由舍人宣讀詔書：“冯氏以非親生母親的身份善待庶子的品德，足以成為世人的典范，她的慈愛之道，義感人神。應當嘉奖勉励，以净化風俗。陆讓可以免去死罪，予以除名。”又下詔褒奖冯氏，賞賜五百段布帛，還召集那些有身份的婦女與冯氏認識，以示對她的特殊恩寵。","sortOrder":118},
  {"id":"s_work_gp_5_119","chapterId":"ch_work_gp_5","text":"母親心存大義，以己子救人子","sortOrder":119},
  {"id":"s_work_gp_5_120","chapterId":"ch_work_gp_5","text":"【原文】齊宣王時，有人斗死於道，吏訊之。有兄弟二人，立其傍，吏問之。","sortOrder":120},
  {"id":"s_work_gp_5_121","chapterId":"ch_work_gp_5","text":"兄曰：“我殺之。”弟曰：“非兄也，乃我殺之。”期年，吏不能决，言之於相。相不能决，言之於王。王曰：“今皆舍之，是縱有罪也；皆殺之，是誅無辜也。寡人度其母能知善惡。试問其母，聽其所欲殺活。”相受命，召其母問曰：“母之子殺人，兄弟欲相代死。吏不能决，言之於王。王有仁惠，故問母何所欲殺活。”其母泣而對曰：“殺其少者。”相受其言，因而問之曰：“夫少子者，人之所愛，今欲殺之，何也？”","sortOrder":121},
  {"id":"s_work_gp_5_122","chapterId":"ch_work_gp_5","text":"其母曰：“少者，妾之子也；長者，前妻之子也。其父疾且死之時屬於妾曰：‘善養视之。’妾曰：‘诺！”今既受人之托，許人以诺，豈可忘人之托而不信其诺耶？且殺兄活弟，是以私愛废公義也。背言忘信，是欺死者也。失言忘約，已诺不信，何以居於世哉？予雖痛子，獨謂行何！”泣下沾襟。相入，言之於王。王美其義，高其行，皆赦。不殺其子，而尊其母，號曰“義母”。","sortOrder":122},
  {"id":"s_work_gp_5_123","chapterId":"ch_work_gp_5","text":"【譯述】齊宣王的時候，有人打架斗殴，死在路上，官吏前來調查。有兄弟二人站在旁邊，官吏詢問他们。哥哥說：“人是我殺死的。”弟弟說：“不是哥哥，是我殺的。”整整一年，官吏不能决斷，就把这事告知宰相，宰相也無法决斷，就禀報了齊宣王。宣王說：“如果放過他们，就是放縱犯罪的人；如果都殺掉，就會妄殺無辜之人。我估計他们的母親能知道誰好誰坏。問問他们的母親，聽聽她對誰死誰活的意見。”宰相受命，召見他们的母親，說：“你的兒子殺了人，兄弟兩人都想相互代替赴死，官吏不能决斷，告知宣王，宣王很仁義，讓我來問問你想殺誰活誰？”母親哭著說：“殺掉年紀小的。”宰相聽後，反問說：“小兒子是父母最疼愛的，而你却想殺掉他，这是為什么呢？”母親回答說：“年少的，是我親生的兒子，年長的是丈夫前妻的兒子，丈夫得病臨死之時將他托付給我說：‘好好地撫養他。’我答應說‘是’。既然受人之托，答應了人，又怎能忘人之托而失信於自己的诺言呢？再說殺兄活弟，是以个人私愛败坏公義道德；背言失信，是欺骗死去的丈夫。既然失言忘約，不守信用，又怎能在社會上立身處世呢？我雖然疼愛自己的兒子，却怎么能不顧道義德行呢？”說罢痛哭流涕。宰相入朝後把情形禀報了齊宣王。宣王贊叹这位母親的德行高義，於是赦免了她的兩个兒子。不但不殺她的兒子，還尊崇这位母親，稱这位母親為“父母”。","sortOrder":123},
  {"id":"s_work_gp_5_124","chapterId":"ch_work_gp_5","text":"後母賢惠，後子也孝順","sortOrder":124},
  {"id":"s_work_gp_5_125","chapterId":"ch_work_gp_5","text":"【原文】魏芒慈母者，孟楊氏之女，芒卯之後妻也，有三子。前妻之子有五人，皆不愛慈母。遇之甚異，猶不愛慈母。乃令其三子不得與前妻之子齊衣服、飲食。進退、起居甚相遠。前妻之子猶不愛。於是，前妻中子犯魏王令，當死。慈母忧戚悲哀，帶围减尺。朝夕勤勞，以救其罪。人有謂慈母曰：“子不愛母至甚矣，何為忧懼勤勞如此？”慈母曰：“如妾親子，雖不愛妾，妾猶救其禍而除其害。獨假子而不為，何以異於凡人？且其父為其孤也，使妾而繼母。繼母如母，為人母而不能愛其子，可謂慈乎？親其親而偏其假，可謂義乎？不慈且無義，何以立於世？彼雖不愛妾，妾可以忘義乎？”遂訟之。魏安厘王聞之，高其義，曰：“慈母如此，可不赦其子乎？”乃赦其子而复其家。自此之後，五子親慈母雍雍若一。慈母以禮義漸之，率导八子，鹹為魏大夫卿士。","sortOrder":125},
  {"id":"s_work_gp_5_126","chapterId":"ch_work_gp_5","text":"【譯述】魏時的芒慈母，是孟楊氏的女兒，芒卯的後妻。她與芒卯生了三个孩子。芒卯的前妻留下五个孩子，他们都不愛戴後母。盡管芒慈母對他们五人非常好，但他们仍然不愛戴她。於是，芒慈母讓自己的三个孩子不能與前妻的五子穿一樣的衣服，吃一樣的飯食，即便是起居、進退也對前妻的五子給予特殊的照顧。可是前妻的孩子仍然不能與她慈愛相處。正在这時，前妻的一个孩子违犯了魏王的命令，要被處死。芒慈母為此忧愁悲哀，消瘦了許多。她一天到晚奔波，想辦法拯救这个孩子。有人對芒慈母說：“兒子不愛他的母親已經到了这个地步，你為什么還这樣為他忧愁勤勞呢？”芒慈母說：“假如是我的親生子的話，他即使不愛我，我也肯定會救他與危難之中。单单對非親生子不能这樣，那與不懂禮數的一般人有什么區別呢？况且他们的父親因為他们失去了母親，才把他们托付給我。繼母就是母親，做為人的母親却不能愛自己的孩子，这能算得上是慈愛之舉吗？親自己的親生子，而偏废前妻的孩子，这能算是義舉吗？既失了慈又不講義，還怎么立身於世上呢？盡管他们不喜愛我，而我又怎么能不顧道義呢？”於是，她為前妻子訴訟辯罪。魏安厘王聽說了这件事後，贊叹芒慈母的德行義舉，併說：“後母有这樣的高義，怎么能不赦免她的孩子呢？”於是赦免了芒慈母的孩子，恢复他们完整的家庭。從此之後，这五个孩子都非常親善孝順後母，芒慈母即以禮義來教育引导他们。在芒慈母的訓导下，芒慈母家的八个孩子都成了魏國的大夫卿士。","sortOrder":126},
  {"id":"s_work_gp_5_127","chapterId":"ch_work_gp_5","text":"【原文】漢安眾令漢中程文矩妻李穆薑，有二男，而前妻四子以母非所生，憎毀日積。而穆薑慈愛溫仁，撫字益隆，衣食資供，皆兼倍所生。或謂母曰：“四子不孝甚矣，何不別居以遠之？”對曰：“吾方以義相导，使其自遷善也。”及前妻長子興疾困篤，母惻隱，親自為調藥膳，恩情篤密。興疾久乃瘳，於是呼三弟謂曰：“繼母慈仁，出自天愛，吾兄弟不識恩養，禽獸其心。雖母道益隆，我曹過惡亦已深矣！”遂將三弟詣南鄭獄，陳母之德，状己之過，乞就刑辟。縣言之於郡。郡守表異其母，蠲除家徭，遣散四子，許以修革。自後訓导愈明，併為良士。今之人，為人嫡母而疾其孽子，為人繼母而疾其前妻之子者，聞此四母之風，亦可以少愧矣？","sortOrder":127},
  {"id":"s_work_gp_5_128","chapterId":"ch_work_gp_5","text":"【譯述】漢代安眾令漢中程文矩的妻子李穆薑，有兩个兒子，而丈夫前妻的四个兒子認為李穆薑不是生身母親，便越來越憎惡她。可是穆薑慈愛溫和，撫養他们更加盡心盡力，給他们分配衣食的時候，總是比給她的親生兒子多。有人勸她說：“这四个孩子这么不孝順，你為何不遷居別處遠離他们呢？”穆薑說：“我正以仁義道德誘导他们，讓他们自己弃惡向善。”後來，丈夫前妻的長子興疾得了重病，境况十分困頓，穆薑很同情他，親自為他熬藥調膳，恩情甚深。这樣過了很久，興疾康复之後，他叫來三个弟弟，對他们說：“繼母慈祥仁愛，出自天性。我们兄弟不懂得她的恩養之情，心如禽獸，繼母的仁愛日漸加深，而我们的罪過也更加深重了！”於是他帶著三个弟弟來到南鄭監獄，陳述繼母的優良品德，供述自己的罪過，請求官府治罪。縣令將这件事禀報郡守，郡守没有治他们的罪，還表彰他们的後母，免除他们的徭役，令他们兄弟回家，允許他们改過自新。此後穆薑訓导兒子愈加嚴明，这兄弟幾个後來都成了為人们所稱道的良士。現在那些做為人的嫡母，却不善待非親生子；作為人的繼母而不善待前妻之子的，聽了以上四位母親的事跡，難道一點慚愧都没有吗？","sortOrder":128},
  {"id":"s_work_gp_5_129","chapterId":"ch_work_gp_5","text":"【原文】魯師春薑嫁其女，三往而三逐。春薑問其故。以輕侮其室人也。春薑召其女而笞之，曰：“夫婦人以順從為務。貞悫為首。今爾驕溢不遜以見逐，曾不悔前過。吾告汝數矣，而不吾用。爾非吾子也。”笞之百，而留之三年。乃复嫁之。女奉守節義，終知為人婦之道。令之為母者，女未嫁，不能誨也。既嫁，為之援，使挟己以凌其婿家。及見弃逐，則與婿家斗訟。終不自责其女之不令也。如師春薑者，豈非賢母乎？","sortOrder":129},
  {"id":"s_work_gp_5_130","chapterId":"ch_work_gp_5","text":"【譯述】魯師春薑嫁出去自己的女兒，三次送到婆家，三次都被趕回了娘家。","sortOrder":130},
  {"id":"s_work_gp_5_131","chapterId":"ch_work_gp_5","text":"春薑詢問婆家这是為什么，婆家的人回答說：“你的女兒經常輕慢、侮辱婆家的人。”於是春薑把女兒叫來，一邊鞭打，一邊教訓說：“作為人婦最大的美德就是要順從，而且首先要忠貞誠實，現在你因為傲慢無禮被驅逐回家，幾次都不能悔過。我已經和你講過好幾次了，你却不能聽我的話。既然这樣，你就不是我女兒了。”鞭打女兒上百下，併留女兒在家住了三年。三年後再次出嫁，女兒恪守禮義，終於知道為人婦的道理了。現在的做母親的却往往做不到这些，女兒在未出嫁之前就不能教誨；既出嫁之後，又做女兒的後台，讓女兒依仗娘家的势力去欺凌女婿家。等到女兒被婆家驅逐回娘家，則又興師動眾，與人家打斗或公堂爭訟。就是不去责怪自己的女兒不守婦道。这樣對比起來，師春薑難道不能被稱為賢母吗？","sortOrder":131},
  {"id":"s_work_gp_6_1","chapterId":"ch_work_gp_6","text":"家范卷四子上","sortOrder":1},
  {"id":"s_work_gp_6_2","chapterId":"ch_work_gp_6","text":"百善孝為先","sortOrder":2},
  {"id":"s_work_gp_6_3","chapterId":"ch_work_gp_6","text":"【原文】《孝經》曰：“夫孝，天之經也，地之義也，民之行也。天地之經，而民是則之。”又曰：“不愛其親而愛他人者，謂之悖德；不敬其親而敬他人者，謂之悖禮。以順則逆，民無則焉。不在於善，而皆在於凶德。雖得之，君子不貴也。”又曰：“五刑之屬三千，而罪莫大於不孝。”","sortOrder":3},
  {"id":"s_work_gp_6_4","chapterId":"ch_work_gp_6","text":"孟子曰：“不孝有五：惰其四支，不顧父母之養，一不孝也；博弈好飲酒，不顧父母之養，二不孝也；好货财，私妻子，不顧父母之養，三不孝也；從耳目之欲，以為父母戮，四不孝也；好勇斗狠以危父母，五不孝也。”夫為人子，而事親或虧，雖有他善累百，不能掩也，可不慎乎！","sortOrder":4},
  {"id":"s_work_gp_6_5","chapterId":"ch_work_gp_6","text":"【譯述】《孝經》說：“孝順，就像天上日月運行一樣是永恒的規律，也像地上萬物生長一樣是不变的法則，更是天下民眾的行為准則。天地間的規律，萬民都要遵循。”又說：“不喜愛自己的親人却去喜愛他人，这叫做违背道德；不敬重自己的父母却敬重別人，这是违反禮法。君王訓导萬民要尊敬愛戴父母，而有的人却违背道德和禮法，这种人即使能得志，君子也不以此為貴。”又說：“五种刑罰的罪状包括三千條，而其中罪惡最大的就是不孝。”孟子說：“不孝順有五种情状：好逸惡勞，不顧父母的養育之恩，这是第一种不孝；沉湎於赌博和酗酒，不顧父母的養育之恩，这是第二种不孝；貪圖錢财，只顧自己的妻子兒女，却不顧父母的養育之恩，这是第三种不孝；尋歡作樂，給父母帶來恥辱，这是第四种不孝；喜歡打架斗殴而危及父母，这是第五种不孝。”做為人子，在侍奉父母方面如果做得不够，即便其他的長處優點再多，也不能掩蓋他的罪過。所以為人子女能不小心謹慎吗？","sortOrder":5},
  {"id":"s_work_gp_6_6","chapterId":"ch_work_gp_6","text":"以父母之樂為樂，　以父母之忧為忧","sortOrder":6},
  {"id":"s_work_gp_6_7","chapterId":"ch_work_gp_6","text":"【原文】《經》曰：“君子之事親也，居則致其敬，養則致其樂，病則致其忧，丧則致其哀，祭則致其嚴。”","sortOrder":7},
  {"id":"s_work_gp_6_8","chapterId":"ch_work_gp_6","text":"【譯述】《孝經》說：“君子侍奉父母親，平日家居要盡量做到恭敬，贍養父母要讓父母得到歡樂，父母生病了就要忧慮，父母去世就要表現得十分哀痛，祭祀父母時要非常嚴肅。”","sortOrder":8},
  {"id":"s_work_gp_6_9","chapterId":"ch_work_gp_6","text":"養父母而不恭敬，何異於養犬馬","sortOrder":9},
  {"id":"s_work_gp_6_10","chapterId":"ch_work_gp_6","text":"【原文】孔子曰：“今之孝者，是謂能養。至於犬馬，皆能有養。不敬，何以別乎？”《禮》：子事父母，雞初鳴，鹹盥漱，盛容飾以適父母之所。父母之衣衾、簟席、枕幾不傳，杖、履祗敬之，勿敢近。敦牟、卮，非馂莫敢用。在父母之所，有命之，應唯敬對，進退周旋慎齊。升降、出入揖遜。不敢哕噫、嚏、咳、欠、伸、跛、倚、睇视，不敢唾洟。寒不敢袭，痒不敢搔。不有敬事，不敢袒褶。不涉不撅。為人子者，出必告，反必面。所遊必有常，所習必有業，恒言不稱老。","sortOrder":10},
  {"id":"s_work_gp_6_11","chapterId":"ch_work_gp_6","text":"又：“為人子者，居不主奧，坐不中席，行不中道，立不中門。食饗不為概，祭祀不為尸。聽於無聲，视於無形。不登高，不臨深，不苟訾，不苟笑。孝子不服闇，不登危，懼辱親也。”","sortOrder":11},
  {"id":"s_work_gp_6_12","chapterId":"ch_work_gp_6","text":"【譯述】孔子說：“如今的所謂孝子，仅仅稱得上是能够贍養父母。但是狗和馬，不也被養著吗？如果贍養父母不表現出恭敬來，那么这與養狗養馬又有什么區別呢？”《禮記》說：子女侍奉父母，在雞刚叫的時候就要起床洗漱，穿戴整齊去拜見父母。父母所用的衣被、炕席、枕頭等，不能去隨便移動，即便是對父母的拐杖和鞋子，也要恭恭敬敬，不能隨便靠近。父母使用的食器、酒具，在父母用完之後，才能使用。在父母的居所，如果父母有所吩咐，應答都要唯唯喏喏、恭恭敬敬。進退周旋要謹慎而莊重，舉止行動要有禮而謙遜，不能放肆地打呃、打喷嚏、咳嗽、打哈欠、伸懶腰、跛行、斜靠、斜眼看人看物，也不能隨便吐唾沫、擤鼻涕。即便是冷，也不能在衣服外邊再套衣服；即便是痒，也不能去搔。如果不是受父母之命，不敢隨便脱去外邊的衣服。自己身上的衣服要穿戴齊整，不要拖來拖去，或隨便撩起來。為人之子，出門必須向父母告辭，回家必須向父母問安。出遊必須有規矩，學習必須有所立業，說話不能摆資格。","sortOrder":12},
  {"id":"s_work_gp_6_13","chapterId":"ch_work_gp_6","text":"《禮記》里又說：“為人之子，住房不能占據西南角尊長的位置，坐的時候不能坐在正中間，走路也不能走中間，站立不能站在門的中間，吃飯不能挑三揀四，祭祀時不能充當受祭者而接受別人的禮拜。默默傾聽別人的意見，不要多插嘴；察顏觀色，善解人意。為人子，不能登高臨深，冒险行事，不能胡亂骂人，不能隨便說笑。孝子不在暗地里做事，不到危险的地方，怕的是因為自己的行為辱没了父母。”","sortOrder":13},
  {"id":"s_work_gp_6_14","chapterId":"ch_work_gp_6","text":"父母面前不顯尊貴","sortOrder":14},
  {"id":"s_work_gp_6_15","chapterId":"ch_work_gp_6","text":"【原文】宋武帝即大位，春秋已高，每旦朝繼母萧太後，未嘗失時刻。彼為帝王尚如是，况士民乎！","sortOrder":15},
  {"id":"s_work_gp_6_16","chapterId":"ch_work_gp_6","text":"【譯述】南朝宋武帝登基稱帝時，年事已高，但是他每天清晨都要朝拜繼母萧太後，而且從未错過時刻。他做了帝王，尚且能够这般孝順母親，更何况一般的士人百姓呢？","sortOrder":16},
  {"id":"s_work_gp_6_17","chapterId":"ch_work_gp_6","text":"【原文】梁臨川靜惠王宏，兄懿為齊中書令，為東昏侯所殺，諸弟皆被收。","sortOrder":17},
  {"id":"s_work_gp_6_18","chapterId":"ch_work_gp_6","text":"僧慧思藏宏，得免。宏避難潛伏，與太妃異處，每遣使恭問起居。或謂：“逃難須密，不宜往來。”宏衔淚答曰：“乃可無我，此事不容暫废。”彼在危難尚如是，况平時乎！","sortOrder":18},
  {"id":"s_work_gp_6_19","chapterId":"ch_work_gp_6","text":"為子者不敢自高貴，故在《禮》：“三賜不及車馬。”不敢以富貴加於父兄。","sortOrder":19},
  {"id":"s_work_gp_6_20","chapterId":"ch_work_gp_6","text":"【譯述】梁代臨川靜惠王萧宏的哥哥懿擔任齊朝中書令，被東昏侯所殺，幾个弟弟都被收斬。和尚慧思將萧宏藏匿起來，因此萧宏得以幸免。萧宏潛伏避難，與太妃異地而居，但是他還經常派人問候太妃的起居生活。","sortOrder":20},
  {"id":"s_work_gp_6_21","chapterId":"ch_work_gp_6","text":"有人對他說：“你正在逃難，必須保密，不應該和太妃來往。”萧宏流淚答道：“寧可讓我去死，也不能不行孝道。”他身處危難之中尚且能如此盡孝道，何况平時呢？","sortOrder":21},
  {"id":"s_work_gp_6_22","chapterId":"ch_work_gp_6","text":"做為人子，不能在父母面前顯示身份高貴，所以《禮記》中說：“三賜不及車馬。”不敢在父兄面前表現自己的富有和尊貴。","sortOrder":22},
  {"id":"s_work_gp_6_23","chapterId":"ch_work_gp_6","text":"【原文】國初，平章事王溥，父祚有賓客，溥常朝服侍立。客坐不安席。祚曰：“豚犬，不足為之起。”此可謂居則致其敬矣。","sortOrder":23},
  {"id":"s_work_gp_6_24","chapterId":"ch_work_gp_6","text":"【譯述】宋朝初年，平章事王溥的父親王祚每當在家招待客人的時候，王溥就穿著上朝的衣服侍立一旁。客人坐著頗覺不安。王祚就說：“他是我的兒子，不必因為他是平章事就起身。”这可以說是為子女的平日家居就要表示對父母的恭敬。","sortOrder":24},
  {"id":"s_work_gp_6_25","chapterId":"ch_work_gp_6","text":"待奉父母，要有耐心","sortOrder":25},
  {"id":"s_work_gp_6_26","chapterId":"ch_work_gp_6","text":"【原文】《禮》：“子事父母，雞初鳴而起，左右佩服以適父母之所。及所，下氣怡聲，問衣燠寒，疾痛苛痒，而敬抑搔之。出入則或先或後，而敬扶持之。進盥，少者奉槃，長者奉水，請沃盥，卒，授巾。問所欲而敬進之，柔色以溫之。。”父母之命勿逆勿怠。若飲之食之，雖不嗜，必嘗而待；加之衣服，雖不欲，必服而待。","sortOrder":26},
  {"id":"s_work_gp_6_27","chapterId":"ch_work_gp_6","text":"又，“子婦無私货，無私畜，無私器。不敢私假，不敢私與。”","sortOrder":27},
  {"id":"s_work_gp_6_28","chapterId":"ch_work_gp_6","text":"又，為人子之禮，冬溫而夏凊，昏定而晨省，在丑夷不爭。","sortOrder":28},
  {"id":"s_work_gp_6_29","chapterId":"ch_work_gp_6","text":"【譯述】《禮記》說：“子女侍奉父母，在雞刚叫的時候就要起床，穿戴整齊到父母的居室。到了父母的居所，要和顏悅色，向父母問寒問暖。父母如果有疾病痒痛，就要非常恭敬地去想辦法解除。如果是與父母一起出入，就或者在前邊引导，或者在後邊侍奉，非常恭敬地去攙扶。扶父母進了洗漱間，年紀小的趕快端來脸盆，年紀大的給倒上水，請父母洗脸。洗罢，將毛巾遞過去。然後再問父母需要什么，及時奉送上去，還要用柔和的態度來慰藉父母。。”對於父母的吩咐，不能违逆，也不能應付。如果是父母讓你吃喝，即使不對你的口味，你也必須吃一點，然後聽從父母的吩咐；如果是父母給你一件衣服，你即使不喜歡，也一定要先穿在身上，然後等父母讓你脱，你再脱去。","sortOrder":29},
  {"id":"s_work_gp_6_30","chapterId":"ch_work_gp_6","text":"《禮記》又說：“兒子和媳婦不能私自積蓄家產，也不能有自己的用具東西。不能私自和別人借東西，也不能私自將家里的東西送給別人。”《禮記》還說：作為人的子女，應該奉行这樣的禮數：冬天要為父母溫暖被褥，夏天要為父母扇涼臥席；晚上要為父母安頓好床鋪，早晨要向父母問安。而且不能和兄弟姐妹们有所爭執。","sortOrder":30},
  {"id":"s_work_gp_6_31","chapterId":"ch_work_gp_6","text":"自己有節操，方能孝父母","sortOrder":31},
  {"id":"s_work_gp_6_32","chapterId":"ch_work_gp_6","text":"【原文】孟子曰：“曾子養曾皙，必有酒肉；將彻，必請所與。問有餘，必曰：‘有。’曾皙死，曾元養曾子，必有酒肉。將彻，不請所與，問有餘，曰：‘亡矣。’將以复進也。此所謂養口體者也。若曾子，則可謂養志也。事親若曾子者，可也。”","sortOrder":32},
  {"id":"s_work_gp_6_33","chapterId":"ch_work_gp_6","text":"【譯述】孟子說：“先前曾子奉養他的父親曾皙，每頓飯一定有酒肉；往下撤的時候一定要問，剩下的給誰；曾皙若問還有剩飯吗？曾子一定回答，‘有。’曾皙死了，曾元養曾子，也一定有酒有肉。往下撤的時候，便不問剩下的給誰了；曾子若問還有剩飯吗？便說：“没有了。”意思是留下預備以後進用。这个叫做口體之養。至於曾子對父親，才可以叫做順從親意之養。侍奉父母做到像曾子那樣就可以了。","sortOrder":33},
  {"id":"s_work_gp_6_34","chapterId":"ch_work_gp_6","text":"可以委屈自己，但不能委屈双親","sortOrder":34},
  {"id":"s_work_gp_6_35","chapterId":"ch_work_gp_6","text":"【原文】老萊子孝奉二親，行年七十，作婴兒戲，身服五采斑斓之衣。嘗取水上堂，诈跌仆臥地，為小兒啼，弄雏於親侧，欲親之喜。","sortOrder":35},
  {"id":"s_work_gp_6_36","chapterId":"ch_work_gp_6","text":"【譯述】老萊子孝順地侍奉父母，年紀快七十了，還玩婴兒的遊戲。他身著五彩斑斓的衣服，把水端到堂上，裝作跌仆臥倒在地，又假裝小孩啼哭，在父母身邊摆弄小孩，目的是想讓父母高興。","sortOrder":36},
  {"id":"s_work_gp_6_37","chapterId":"ch_work_gp_6","text":"【原文】漢諫議大夫江革，少失父，獨與母居。遭天下亂，盜賊併起，革負母逃難，備經险阻，常采拾以為養，遂得俱全於難。革轉客下邳，貧窮裸跣行，佣以供母，便身之物，莫不畢給。建武末年，與母歸乡里，每至歲時，縣當案比，革以老母不欲搖動，自在轅中挽車，不用牛馬。由是乡里稱之曰“江巨孝”。","sortOrder":37},
  {"id":"s_work_gp_6_38","chapterId":"ch_work_gp_6","text":"【譯述】東漢諫議大夫江革，少年時丧父，與母親居住在一起。時逢天下大亂，盜賊併起，江革背著母親逃難，歷盡艱難险阻，常常靠采拾野菜來贍養母親，因此母子得以幸免於難。江革轉而客居下邳，因為貧窮，就赤著腳行走，他依靠給人打工來贍養母親。隨身所用之物，都給母親准備齊全。建武末年，他與母親一起回到故乡。每至歲時，縣里就清理戶口，江革因為老母害怕搖動顛簸，就自己駕轅拉車，不用牛馬。因此乡里稱他為“江巨孝”。","sortOrder":38},
  {"id":"s_work_gp_6_39","chapterId":"ch_work_gp_6","text":"【原文】晉西河人王延，事親色養，夏則扇枕席，冬則以身溫被，隆冬盛寒，體無全衣，而親極滋味。","sortOrder":39},
  {"id":"s_work_gp_6_40","chapterId":"ch_work_gp_6","text":"【譯述】晉代西河人王延，很孝順地侍奉父母，夏天就在父母枕邊扇涼風，冬天就以身為父母暖被。隆冬嚴寒，他自己體無全衣，而父母親却生活得很好。","sortOrder":40},
  {"id":"s_work_gp_6_41","chapterId":"ch_work_gp_6","text":"端碗先思父母飢飽","sortOrder":41},
  {"id":"s_work_gp_6_42","chapterId":"ch_work_gp_6","text":"【原文】宋會稽何子平，為扬州從事吏，月俸得白米，辄货市粟麥。人曰：“所利無幾，何足為煩？”子平曰：“尊老在東，不辦得米，何心獨饗白粲！”每有赠鮮肴者，若不可寄至家，則不肯受。後為海虞令，縣祿唯供養母一身，不以及妻子。人疑其俭薄。子平曰：“希祿本在養親，不在為己。”問者慚而退。","sortOrder":42},
  {"id":"s_work_gp_6_43","chapterId":"ch_work_gp_6","text":"【譯述】宋代會稽人何子平，擔任扬州從事吏，每月俸祿所得的白米，總要拿去賣掉買粟麥。有人說：“賣了米再買粟麥獲利併不多，何必要那么麻煩呢？”子平說：“我母親住在東邊，不能得到白米，我怎么能獨自享受白米呢？”每次有人送給他好吃的東西，如果不能寄到家里，他就不肯接受。後來他擔任海虞縣令，所得俸祿只供養母親一个人，完全不顧及妻子兒女。有人懷疑他過於節俭小氣。子平就說：“我之所以出來求官，原本就是為供養父母，而不是為了自己。”向他問話的人羞慚而退。","sortOrder":43},
  {"id":"s_work_gp_6_44","chapterId":"ch_work_gp_6","text":"【原文】同郡郭原平養親，必以己力，佣賃以給供養。性甚巧，每為人佣作，止取散夫价。主人没食，原平自以家貧，父母不辦有肴飯，唯餐鹽飯而已。若家或無食，則虛中竟日，義不獨飽，須日暮作畢，受直歸家，於里籴買，然後舉爨。","sortOrder":44},
  {"id":"s_work_gp_6_45","chapterId":"ch_work_gp_6","text":"【譯述】同郡郭原平侍養父母，一定要靠自己的勞動所得來供養。他秉姓靈巧，每次為人做工，只取散夫零工的价錢。主人供飯，郭原平認為家中貧窮，父母吃不上葷菜，自己也就只吃鹽飯。如果家中没有糧食，他也就整天不吃飯，等到天黑收工，拿了工錢回家的時候，再出去買些糧食，然後回家做飯。","sortOrder":45},
  {"id":"s_work_gp_6_46","chapterId":"ch_work_gp_6","text":"自己有忧愁，不必告父母","sortOrder":46},
  {"id":"s_work_gp_6_47","chapterId":"ch_work_gp_6","text":"【原文】唐曹成王皋為衡州刺史，遭誣在治，念太妃老，將驚而戚，出則囚服就辟，入則擁笏垂魚，坦坦施施，貶潮州刺史，以遷入贺。既而事得直，复還衡州，然後跪謝告實。此可謂養則致其樂矣。","sortOrder":47},
  {"id":"s_work_gp_6_48","chapterId":"ch_work_gp_6","text":"【譯述】唐代曹成王皋擔任衡州刺史時，受他人誣告將要被治罪。他想到太妃年老，將會為这件事驚慌、愁苦。於是出了家門他就穿著囚徒的衣服准備受刑，一回到家里就官服裝束，裝出一副坦然快樂的樣子。後來他被貶為潮州刺史，就假裝他要升遷調動，回家向太妃表示祝贺。不久，他的冤案得以平反，他又回到衡州，他才向太妃跪禀實情。这可以稱之為贍養父母就要想方設法讓他们享受歡樂。","sortOrder":48},
  {"id":"s_work_gp_6_49","chapterId":"ch_work_gp_6","text":"久病床前，亦有孝子","sortOrder":49},
  {"id":"s_work_gp_6_50","chapterId":"ch_work_gp_6","text":"【原文】《禮》：父母有疾，冠者不櫛，行不翔，言不惰，琴瑟不御。食肉不至变味，飲酒不至变貌，笑不至矧，怒不詈，疾止复故。","sortOrder":50},
  {"id":"s_work_gp_6_51","chapterId":"ch_work_gp_6","text":"【譯述】《禮記》說：父母有病的時候，成年子女不能梳頭打扮，走路也不能像平日那樣輕捷，不說閒話，不能鼓琴弄瑟。吃肉不能講究滋味，喝酒要少，笑不露齒，怒不能骂人，父母病愈後，子女方能恢复常態。","sortOrder":51},
  {"id":"s_work_gp_6_52","chapterId":"ch_work_gp_6","text":"【原文】文王之為世子，朝於王季，日三。雞初鳴而衣服，至於寢門外，問內竖之御者曰：“今日安否？何如？”內竖曰：“安。”文王乃喜。及日中，又至。亦如之。及莫又至，亦如之。其有不安節，則內竖以告文王。文王色忧，行不能正履。王季复膳，然後亦复初。武王帥而行之，不敢有加焉。文王有疾，武王不脱冠帶而養。文王一飯亦一飯，文王再飯亦再飯。旬有二日，乃間。","sortOrder":52},
  {"id":"s_work_gp_6_53","chapterId":"ch_work_gp_6","text":"【譯述】周文王為世子的時候，每天上朝問候君父季歷三次。雞刚叫的時候他就穿好衣服，來到父親的寢門外邊，問掌管內外事務的值班人員：“君父今天可好吗？他老人家怎么樣？”值班人員說：“很好。”周文王便喜形於色。到中午，周文王又來到父親的寢門外，又如早晨一般問候。","sortOrder":53},
  {"id":"s_work_gp_6_54","chapterId":"ch_work_gp_6","text":"到日暮的時候又來問候。如果父親有不舒服的地方，值班人員就告訴給文王，文王就表現得非常忧愁，連走路都是歪歪斜斜的。直到父親重新开始吃飯，文王才恢复如初。後來周武王完全遵循父親文王的做法行事，不敢有一點改動。文王有病的時候，武王則不脱衣服，不解冠帶地侍奉。如果文王吃一次飯，他也只吃一次飯；文王吃兩次飯，他也吃兩次飯。","sortOrder":54},
  {"id":"s_work_gp_6_55","chapterId":"ch_work_gp_6","text":"这樣整整一旬零兩天，父親的病才痊愈。","sortOrder":55},
  {"id":"s_work_gp_6_56","chapterId":"ch_work_gp_6","text":"【原文】漢文帝為代王時，薄太後常病。三年，文帝目不交睫，衣不解帶，湯藥非口所嘗弗進。","sortOrder":56},
  {"id":"s_work_gp_6_57","chapterId":"ch_work_gp_6","text":"【譯述】漢文帝任代王時，薄太後經常生病。三年之中，漢文帝没有好好睡過覺，也没有脱過衣服，盡心竭力侍候太後。凡是薄太後喝的藥，文帝都要親自嘗過後才進獻。","sortOrder":57},
  {"id":"s_work_gp_6_58","chapterId":"ch_work_gp_6","text":"【原文】晉范乔父粲，仕魏，為太宰中郎。齊王芳被废，粲遂稱疾阖門不出，陽狂不言，寢所乘車，足不履地。子孫常侍左右，候其顏色，以知其旨。如此三十六年，終於所寢之車。乔與二弟併弃學業，絕人事，侍疾家庭。至粲没，不出里邑。","sortOrder":58},
  {"id":"s_work_gp_6_59","chapterId":"ch_work_gp_6","text":"【譯述】晉代范乔的父親粲，曾在魏國做官，擔任太宰中郎。因為齊王芳被废黜，粲於是假裝有病，閉門不出。他裝作瘋狂而不說話，終日睡在車上，腳都不沾地。他的子孫们經常侍奉左右，看他的脸色來判斷他的欲求。这樣長達三十六年，直到他死在他睡的那个車子上。这期間，范乔和兩个弟弟都放下學業，謝絕人事，在家里侍候父親。直到父親去世，他们都没有離开所居乡里一步。","sortOrder":59},
  {"id":"s_work_gp_6_60","chapterId":"ch_work_gp_6","text":"【原文】南齊庾黔娄為孱陵令，到縣未旬，父易在家遘疾，黔娄忽心驚，舉身流汗。即日弃官歸家，家人悉驚。其忽至時，易病始二日。医雲：“欲知差剧，但嘗粪甜苦。”易泄利，黔娄辄取嘗之。味轉甜滑，心愈忧苦。至夕，每稽顙北辰，求以身代。俄聞空中有聲，曰：“徵君寿命盡，不可延，汝誠祷既至，改得至月末。”晦，而易亡。","sortOrder":60},
  {"id":"s_work_gp_6_61","chapterId":"ch_work_gp_6","text":"【譯述】南齊的庾黔娄擔任孱陵縣令，上任不到一旬的時間，他的父親在家里得了病。黔娄忽然感到心驚肉跳，全身大汗淋漓。他當下就弃官回到家里，家里的人都非常驚奇。他如此急地趕到家里的時候，父親患病仅兩天。医生說：“要想知道病的情况，只要能嘗一下他的粪便的甜苦就可以了。”於是，父親泄後，黔娄就取來品嘗。粪便的味道轉為甜滑，而黔娄的心却越來越变得忧愁苦悶。每當晚上，他就跪拜北辰，乞求用自己來替代父親。一會兒，聽到空中有說話的聲音：“你父親的寿命盡了，不能再延續，但因為你真誠的祷告起了作用，所以你父親的死期可以改至月末。月終，黔娄的父親易果真去世了。","sortOrder":61},
  {"id":"s_work_gp_6_62","chapterId":"ch_work_gp_6","text":"【原文】後魏孝文帝幼有至性，年四歲時，獻文患痈，帝親自吮脓。","sortOrder":62},
  {"id":"s_work_gp_6_63","chapterId":"ch_work_gp_6","text":"【譯述】後魏孝文帝從小就有超過一般人的孝性，他四歲的時候，父親獻文帝患了痈瘡，孝文帝親自為父親吮吸瘡脓。","sortOrder":63},
  {"id":"s_work_gp_6_64","chapterId":"ch_work_gp_6","text":"【原文】北齊孝昭帝，性至孝。太後不豫，出居南宮。帝行不正履，容色貶悴，衣不解帶，殆將旬。殿去南宮五百餘步，雞鳴而出，辰時方還；來去徒行，不乘舆輦。太後所苦小增，便即寢伏閣外，食飲藥物，盡皆躬親。太後惟常心痛，不自堪忍。帝立侍帷前，以爪掐手心，血流出袖。","sortOrder":64},
  {"id":"s_work_gp_6_65","chapterId":"ch_work_gp_6","text":"此可謂病則致其忧矣。","sortOrder":65},
  {"id":"s_work_gp_6_66","chapterId":"ch_work_gp_6","text":"【譯述】北齊孝昭帝，天性非常孝順。太後不舒服，住在南宮。孝昭帝十分愁苦，走路都走不正，面容憔悴，衣不解帶，將近十天。宮殿距離南宮五百多步，昭帝天亮雞叫時就去南宮問候太後，到了辰時方才返回宮；來去步行，從不乘車。太後的病痛稍微加剧，昭帝就睡在她的臥室門外，太後的飲食和藥物，昭帝都要親自服侍進獻。太後常常心痛，不堪忍受，昭帝就站在她的床前，以手指掐自己的手心，血從袖口流出來。这就是說父母生病了子女就要表示自己的忧愁。","sortOrder":66},
  {"id":"s_work_gp_6_67","chapterId":"ch_work_gp_6","text":"孝子居丧，泣血三年","sortOrder":67},
  {"id":"s_work_gp_6_68","chapterId":"ch_work_gp_6","text":"【原文】《經》曰：孝子之丧親也，哭不哀，禮無容，言不文，服美不安，聞樂不樂，食旨不甘，此哀戚之情也。三日而食，教民無以死傷生，毀不滅性，此聖人之政也。丧不過三年，示民有終也。為之棺椁衣衾而舉之，陳其簠簋而哀戚之。擗踴哭泣，哀以送之，卜其宅兆而安厝之，為之宗廟，以鬼享之。春秋祭祀，以時思之。生事愛敬，死事哀戚，生民之本盡矣，死生之義備矣，孝子之事親終矣。君子之於親丧固所以自盡也，不可不勉。丧禮備在方册，不可悉載。","sortOrder":68},
  {"id":"s_work_gp_6_69","chapterId":"ch_work_gp_6","text":"【譯述】《孝經》說：孝子死了父母，哭的時候聲嘶力竭，禮儀失去端莊，說話不講究文采，穿漂亮的衣服感到不安，聽到音樂也不會快樂，吃美味佳肴也不感到甘甜，这些都是哀傷悲痛的表現。父母死亡三天後就應當吃飯，是教百姓不要因為哀悼死者而損傷活人的身體。悲傷憔悴，但不能危及生命。这是聖人提倡的。居丧不得超過三年，这是向人们表明治丧應有一定的期限。子女要為死去的父母准備棺材、外棺和寿衣，舉行入殓之禮；要摆設各种祭器表示哀掉；送葬的時候，要捶胸頓足、嚎啕大哭；安放棺木，要占卜吉凶，選擇墓地；要建造宗廟祭祀亡靈。子女要歲時祭祀，寄托自己對死去的父母的思念。父母在活著的時候子女要敬重，父母死亡之後子女要哀悼，子女盡到了自己的责任，也完成了養老送終的義務。孝子也就完成了侍奉父母的大任。君子為父母治丧盡孝道原本就是要履行自己的责任，不能不努力做好。關於治丧所應遵循的禮節，典籍里的記載頗為詳細，在此不能細說。","sortOrder":69},
  {"id":"s_work_gp_6_70","chapterId":"ch_work_gp_6","text":"【原文】孔子曰：“少連、大連善居丧，三日不怠，三月不解，期悲哀，三年忧，東夷之子也。”高子皋執親之丧也，泣血三年，未嘗見齒，君子以為難。","sortOrder":70},
  {"id":"s_work_gp_6_71","chapterId":"ch_work_gp_6","text":"【譯述】孔子說：“少連和大連很會居丧，三日之內不惰怠，三个月之內不松懈，悲哀整整一年，而三年之內一直在忧愁。”少連和大連都是東夷之子。孔子的弟子子皋居丧，整整哀哭了三年，從未笑過，連那些很守禮法的君子都認為能够做到这樣很難。","sortOrder":71},
  {"id":"s_work_gp_6_72","chapterId":"ch_work_gp_6","text":"【原文】顏丁善居丧，始死，皇皇焉，如有求而弗得；及殯，望望焉，如有從而弗及；既葬，慨焉，如不及其反而息。","sortOrder":72},
  {"id":"s_work_gp_6_73","chapterId":"ch_work_gp_6","text":"【譯述】魯人顏丁很會居丧，人刚死的時候，他表現出一副皇皇然的樣子，就好象有什么東西想得到却没有得到；等到殯葬的時候，又望望然，就好象急切地想要跟誰走，而没有能够辦到；安葬之後，却表現的没有了聲息，就好象没能挽留住死者，自己彻底絕望了。","sortOrder":73},
  {"id":"s_work_gp_6_74","chapterId":"ch_work_gp_6","text":"【原文】唐太常少卿蘇颋遭父丧，睿宗起复為工部侍郎，颋固辭。上使李日知諭旨，日知終坐不言而還，奏曰：“臣見其哀毀，不忍發言，恐其殒絕。”上乃聽其終製。","sortOrder":74},
  {"id":"s_work_gp_6_75","chapterId":"ch_work_gp_6","text":"【譯述】唐代太常少卿蘇颋遭逢父丧，正巧唐睿宗打算要任命他為工部侍郎，他堅辭不受。皇上派遣李日知去宣喻聖旨，李日知到了蘇家，却坐在那里至始至終没有說話，他回去禀告皇上說：“我見他哀傷過度，面容憔悴，不忍心再去說这些事，怕他聽了會昏死過去。”於是皇上允許他守滿三年孝。","sortOrder":75},
  {"id":"s_work_gp_6_76","chapterId":"ch_work_gp_6","text":"【原文】左庶子李涵為河北宣慰使，會丁母忧，起复本官而行。每州縣郵驿公事之外，未嘗啟口。蔬飯飲水，席地而息。使還，請罢官，終丧製。","sortOrder":76},
  {"id":"s_work_gp_6_77","chapterId":"ch_work_gp_6","text":"代宗以其毀瘠，許之。自餘能盡哀竭力以丧其親，孝感當時，名光後來者，世不乏人。此可謂丧則致其哀矣。","sortOrder":77},
  {"id":"s_work_gp_6_78","chapterId":"ch_work_gp_6","text":"【譯述】左庶子李涵擔任河北宣慰使的時候，母親去世，可他这時正被任命為宣慰使在外地出行。他每到一个州縣，除公事之外，没有再說過話。","sortOrder":78},
  {"id":"s_work_gp_6_79","chapterId":"ch_work_gp_6","text":"每天只吃些粗飯，喝口白开水，併睡在地上。完成出使任務返回去後，他便請求罢官，准備回去為母親守丧。代宗因為他過度悲哀而損傷了身體，所以恩准了他。能够盡哀竭力為父母親守丧，併以孝感動當時，名留後代的人，每朝每代都很多。这可以說是居丧就能竭力表示自己的哀痛。","sortOrder":79},
  {"id":"s_work_gp_6_80","chapterId":"ch_work_gp_6","text":"祭祀應當嚴肅","sortOrder":80},
  {"id":"s_work_gp_6_81","chapterId":"ch_work_gp_6","text":"【原文】古之祭禮詳矣，不可遍舉。孔子曰：“祭如在。”君子事死如事生，事亡如事存。斋三日，乃見其所為斋者。祭之日，樂與哀半，饗之必樂，已至必哀。外盡物，內盡志；入室，僾然必有見乎其位；周還出戶，肅然必有聞乎其容聲；也戶而聽，愾然必有聞乎其叹息之聲。是故先王之孝也，色不忘乎目，聲不絕乎耳，心志嗜欲不忘乎心。致愛則存，致悫則著，著存不忘乎心，夫安得不敬乎！齊齊乎其敬也，愉愉乎其忠也，勿勿乎其欲其饗之也。《詩》曰：“神之格思，不可度思，矧可思。”","sortOrder":81},
  {"id":"s_work_gp_6_82","chapterId":"ch_work_gp_6","text":"此其大略也。","sortOrder":82},
  {"id":"s_work_gp_6_83","chapterId":"ch_work_gp_6","text":"【譯述】古代的祭禮非常詳細，不可遍舉。孔子說：“祭祀就像死人复活一樣。”君子祭祀死者就像侍奉活人一樣，斋戒三天，然後去拜見所要斋戒祭祀的亡靈。祭祀亡靈的日子，歡樂與哀傷各占一半，給亡靈貢飯必須高興，而自己內心又務必哀傷。在外要盡力祭祀，在內須真心誠意；進入安置靈位的廟中，仿佛看見先人坐在那里；禮拜過後，走出門去，又如同聽到他们說話的聲音；出門之後，又好像聽到他们的叹息之聲。","sortOrder":83},
  {"id":"s_work_gp_6_84","chapterId":"ch_work_gp_6","text":"因此先王孝敬親人，親人的形象永不離开眼前，親人的聲音永不離开耳畔，親人的嗜欲和愛好，也永遠存乎心間。由於敬愛，所以親人永遠活在他的心里；由於很真挚，所以耳目中能清晰地顯現出親人的音容笑貌。對於这樣的活在自己心里、浮現於眼前的親人，怎能不去尊敬呢？恭敬表現為莊重的動作，虔誠表現為和顏悅色的姿態，殷勤周到，只希望所祭祀的亡靈能享受到自己的这點心意。《詩經》說：“神靈無處不在，不可测度，如果玩忽不敬就會遭到懲罰。”这就是它的大意。","sortOrder":84},
  {"id":"s_work_gp_6_85","chapterId":"ch_work_gp_6","text":"【原文】孟蜀太子賓客李鄲，年七十餘，享祖考，猶親涤器。人或代之，不從，以為無以達追慕之意。此可謂祭則致其嚴矣。","sortOrder":85},
  {"id":"s_work_gp_6_86","chapterId":"ch_work_gp_6","text":"【譯述】孟蜀太子賓客李鄲，年紀已七十多歲了，祭祀祖父時，還親自洗涤祭器。有人想代替他去洗刷，他不許，認為那樣無法寄托自己的思念之情。这就是說的祭祀時就要表現得莊嚴肅穆。","sortOrder":86},
  {"id":"s_work_gp_6_87","chapterId":"ch_work_gp_6","text":"一舉足一出言，皆不敢忘父母","sortOrder":87},
  {"id":"s_work_gp_6_88","chapterId":"ch_work_gp_6","text":"【原文】《經》曰：身體發膚，受之父母，不敢毀傷，孝之始也。","sortOrder":88},
  {"id":"s_work_gp_6_89","chapterId":"ch_work_gp_6","text":"【譯述】《孝經》說：人的身體、毛發、肌膚，都是父母所給，子女不敢隨意毀坏，这是孝順父母的开端。","sortOrder":89},
  {"id":"s_work_gp_6_90","chapterId":"ch_work_gp_6","text":"【原文】曾子有疾，召門弟子曰：“啟予足，啟予手。《詩》雲：‘戰戰兢兢，如臨深淵，如履薄冰。’而今而後吾知免夫小子。”","sortOrder":90},
  {"id":"s_work_gp_6_91","chapterId":"ch_work_gp_6","text":"【譯述】曾子有病，把他的門人弟子都召集來，說：“身體受之於父母，不敢隨便毀傷，你们揭开我的被，我要看看我的手和足。《詩經》說：‘戰戰兢兢，如臨深淵，如履薄冰。’從今之後我懂得在这个問題上教育你们了。”","sortOrder":91},
  {"id":"s_work_gp_6_92","chapterId":"ch_work_gp_6","text":"【原文】樂正子春下堂而傷足，數月不出，猶有忧色。門弟子曰：“夫子之足瘳矣，數月不出，猶有忧色，何也？”樂正子春曰：“善，如爾之問也！善，如爾之問也！吾聞諸曾子，曾子聞諸夫子曰：‘天之所生，地之所養，惟人為大。父母全而生之，子全而歸之，可謂孝矣；不虧其體，不辱其身，可謂全矣。故君子頃步而弗敢忘孝也，今予忘孝之道，予是以有忧色也。一舉足而不敢忘父母，一出言而不敢忘父母。一舉足而不敢忘父母，是故道而不径，舟而不遊，不敢以先父母之遺體行殆；一出言而不敢忘父母，是故惡言不出於口，忿言不反於身。不辱其身，不羞其親，可謂孝矣。”","sortOrder":92},
  {"id":"s_work_gp_6_93","chapterId":"ch_work_gp_6","text":"【譯述】樂正子春下堂的時候弄傷了腳，他幾个月没有出門，脸上還帶有忧色。他的門人弟子们說：“老師您的腳早就痊愈了，您幾个月都不出門，怎么脸上還有忧色？樂正子春說：“你们問的好！你们問的好！我曾聽曾子說，曾子聽孔夫子說：‘天地之間，數人最為尊貴。父母親把你完整地生了下來，你也要愛惜自己，把自己完整地保護好，这就是孝；不要隨便侮辱、損傷自己的身體，这就是全。所以君子即使只邁半步，也不敢忘記孝道。現在我没有註意孝道，弄傷了腳，我所以有忧色啊！”","sortOrder":93},
  {"id":"s_work_gp_6_94","chapterId":"ch_work_gp_6","text":"人一舉足一行動都不敢忘記身體是父母所給，只要开口講話就不敢忘記自己與父母的聯系。正因為一舉足就不敢忘記身體受之於父母，所以走路不歪斜亂跑，臨水要乘船，而不去遊泳，这就是不敢以父母受之於自己的身體涉险履危；一开口而不敢忘父母，所以不好聽的話不說，疾忿傷害的話也不用在自己身上。既不侮辱父母所給的身體，又不因此而使自己的父母遭到羞辱，这就可以說是做到孝了。","sortOrder":94},
  {"id":"s_work_gp_6_95","chapterId":"ch_work_gp_6","text":"救父母於危難，赴湯蹈火而不辭","sortOrder":95},
  {"id":"s_work_gp_6_96","chapterId":"ch_work_gp_6","text":"【原文】或曰：親有危難則如之何？亦忧身而不救乎？曰：非謂其然也。孝子奉父母之遺體，平居一毫不敢傷也；及其徇仁蹈義，雖赴湯火無所辭，况救親於危難乎！古以死徇其親者多矣。","sortOrder":96},
  {"id":"s_work_gp_6_97","chapterId":"ch_work_gp_6","text":"【譯述】有人問：如果父母親人有危難，怎么辦？子女也擔心自己的身體受到傷害而不去救吗？回答說：併不能这樣理解。孝子對待父母給予的身體，平時連一絲一毫都不敢傷害；到了舍身為仁、殺身取義的時候，即便是赴湯蹈火也在所不辭，何况是在危難之時救父母親人呢！自古以來為父母親人獻身的人很多很多。","sortOrder":97},
  {"id":"s_work_gp_6_98","chapterId":"ch_work_gp_6","text":"【原文】晉末乌程人潘綜遭孫恩亂，攻破村邑。綜與父驃共走避賊，驃年老行遲，賊轉逼。驃語綜：“我不能去，汝走可脱，幸勿俱死。”驃困乏坐地，綜迎賊叩頭曰：“父年老，乞賜生命。”賊至，驃亦請賊曰：“兒少自能走，今為老子不去。孝子不惜死，可活此兒。”賊因斫驃，綜乃抱父於腹下。賊斫綜頭面，凡四創，綜當時悶絕。有一賊從傍來會曰：“卿舉大事，此兒以死救父，雲何可殺？殺孝子不祥。”賊乃止，父子併得免。","sortOrder":98},
  {"id":"s_work_gp_6_99","chapterId":"ch_work_gp_6","text":"【譯述】晉末乌程人潘綜正趕上孫恩作亂，攻打進村镇里來。潘綜和父親潘驃一起逃跑躲避賊寇，但是由於潘驃年老行動遲缓，所以賊寇就向潘驃追去。潘驃對兒子潘綜說：“我走不脱了，你趕快跑可以脱身，我们不能都在这里等死。”这時潘驃已因困乏而跑不動了，只好坐在地上，潘綜拦在前邊向那些冲過來的賊叩頭求道：“我父親已經年紀大了，請饒他一命。”等賊寇到了跟前，潘驃也向賊寇求道：“我的兒子正年輕，他本來能跑得了，可是他為了我这个父親才没有走，他是个以死救父的孝子，請你们饒了他吧。”賊寇用刀去砍潘驃，潘綜就將父親抱在自己的身下。賊寇於是砍潘綜的頭部，潘綜一連中了四刀，當時就昏厥過去。这時有一个賊人從旁邊跑了過來，說：“閣下是在舉大事，这个人以死救他的父親，怎么可以殺他呢？殺孝子不吉利。”於是賊寇不再砍潘綜，这父子二人一併幸免於難。","sortOrder":99},
  {"id":"s_work_gp_6_100","chapterId":"ch_work_gp_6","text":"【原文】齊射聲校尉庾道愍所生母漂流交州，道愍尚在襁褓。及長，知之，求為廣州綏寧府佐。至府，而去交州尚遠，乃自負擔，冒崄自達。及至州，尋求母，經年不獲，日夜悲泣。嘗入村，日暮雨骤，乃寄止一家。","sortOrder":100},
  {"id":"s_work_gp_6_101","chapterId":"ch_work_gp_6","text":"有嫗負薪自外還，道愍心動，因訪之，乃其母也。於是俯伏號泣。遠近赴之，莫不揮淚。","sortOrder":101},
  {"id":"s_work_gp_6_102","chapterId":"ch_work_gp_6","text":"【譯述】齊射聲校尉庾道愍的親生母親漂流到交州的時候，庾道愍還是个襁褓中的婴兒。等到他長大，知道了这件事，於是他就請求擔任廣州綏寧府佐。他上任後，府佐離交州還很遠，他就自己背著行囊，冒险去交州。等到了交州，便尋找母親，但整整一年也没有找到，他日夜悲泣。有一次他進入一个村莊，天已經黑了，但雨下得很急，他便住宿在一家人的家里。一會兒，有一个老婆婆背著一些柴草從外邊回來，道愍似乎心里有感應，他上前詢問，这个老婆婆果然就是他的生身母親。於是母子重逢，抱頭痛哭。遠近前來觀看的人，没有不為之感動而流淚的。","sortOrder":102},
  {"id":"s_work_gp_6_103","chapterId":"ch_work_gp_6","text":"【原文】梁湘州主簿吉翂，父天監初為原乡令，為吏所誣，逮詣廷尉。翂年十五，號泣衢路，祈請公卿。行人見者，皆為陨涕。其父理雖清白，而恥為吏訊，乃虛自引咎，罪當大辟。翂乃挝登聞鼓，乞代父命。武帝嘉異之，尚以其童稚，疑受教於人，敕廷尉蔡法度嚴加胁誘，取其款實。","sortOrder":103},
  {"id":"s_work_gp_6_104","chapterId":"ch_work_gp_6","text":"法度乃還寺，盛陳徽纆，厲色問曰：“爾求代父死，敕已相許，便應伏法。然刀鋸至剧，審能死不。且爾童孺，志不及此，必人所教，姓名是誰？若有悔異，亦相聽許。”對曰：“囚雖蒙弱，豈不知死可畏憚？顧諸弟幼藐，唯囚為長，不忍見父極刑，自延视息。所以內斷胸臆，上幹萬乘。今欲殉身不测，委骨泉壤。此非細故，奈何受人教耶？”法度知不可屈撓，乃更和顏誘，語之曰：“主上知尊侯無罪行，當釋。亮觀君神儀明秀，足稱佳童。今若轉辭，幸父子同濟。奚以此妙年，苦求湯镬？”曰：“凡鯤鲕蝼蚁，尚惜其生，况在人！斯豈願齏粉。但父掛深劾，必正刑書。故思殒仆，冀延父命。”翂初見囚，獄掾依法備加桎梏。法度矜之，命脱其二械，更令著一小者。翂弗聽，曰：“翂求代父死，死囚豈可减乎？”竟不脱械。法度以聞，帝乃宥其父子。丹陽尹王志求其在廷尉故事併諸乡居，欲於歲首，舉充純孝。曰：“異哉王尹！何量翂之薄也。夫父辱子死，斯道固然，若有面目當其此舉，則是因父買名，一何甚辱！”拒之而止。此其章章尤著者也。","sortOrder":104},
  {"id":"s_work_gp_6_105","chapterId":"ch_work_gp_6","text":"【譯述】梁代的湘州主簿吉翂，他的父親天監刚开始擔任原乡令時，被人誣陷，抓起來在廷尉那里接受審訊。吉翂这時才十五歲，他在大街上嚎啕哭泣，在一些當官的面前為父親說情。路上的行人看見了都為之落淚。","sortOrder":105},
  {"id":"s_work_gp_6_106","chapterId":"ch_work_gp_6","text":"他的父親本來没有什么罪，但他恥於為獄吏審訊，就故意承認有罪，而且罪當斬首。吉翂獨自去击打登聞鼓，請求代父親去受死。當時梁武帝頗為这个少年稱奇，但是又認為他只是个孩子，大概是有人在教他，於是命令廷尉蔡法度嚴加審問，弄清實际情况。法度回到衙署，故意多放了一些捆綁罪人的繩索，然後大聲喝問：“你請求代替你的父親去死，皇上已經同意了，你这就要受刑伏法。但是刀斧無情，為了慎重，再核實一下你究竟够著死没有。而且你是个孩子，還不懂得代父去死，一定是有人在教你，这人姓甚名誰？你如果有所後悔，我们也可以重新來考慮。”吉翂回答說：“我雖然是个孩子，但是能不知道殺頭是十分可怕的吗？只是我環顧家里幾个弟弟都還幼小，只有我最大，我不忍心坐视父親受極刑，而自己獨自活在世上。所以我獨自做主，來幹預皇家的法律。我現在確實是想代父而死，这難道不是實情，還怎么要讓別人來教呢？”蔡法度知道用威吓的辦法不能使他屈服，便換了一副溫和的面孔，對他說：“皇上其實已經知道你父親是無罪的，應當釋放，我看你神采奕奕，聰明俊秀，真是一个好孩子，你現在如果要改变代父而死的說法，或許你们父子俩都没有事。為什么要用如此好的年華，去白白送死呢？”吉翂回答說：“連虫子都懂得珍惜自己的生命，而况人呢？我哪里是願意去送死，不過父親被彈劾，必然要受到刑律的處罰，所以我才想著犧牲自己，來救父親一命。”吉翂刚被拘留時，獄吏按規定給他上了所有應該上的枷鎖。蔡法度有些怜悯他，就下令給他摘去兩个刑具，還讓人給他換一个较輕的刑具。吉翂竟不肯，說：“我請求代替父親去死，就是死囚，死囚怎么可以减去刑具呢？”他竟没有减下那些刑具。蔡法度把这些事告訴了皇上，皇帝赦免了他们父子。後來，丹陽尹王志搜集吉翂被廷尉收執時候的事跡，以及他平時在乡里的善舉，想在歲首的時候推舉他為孝順父母的典范。吉翂說：“奇怪啊，王尹！怎么把我看得这么不值錢啊，父親有難，兒子去以死相救，这是很一般的道理，如果我有脸面當此孝的典范，那么就是用父親來為自己換名聲，那是多么的恥辱啊！”他不同意这樣做，这件事才停下來。这些都是孝子以死殉親的例子。","sortOrder":106},
  {"id":"s_work_gp_7_1","chapterId":"ch_work_gp_7","text":"家范卷五子下","sortOrder":1},
  {"id":"s_work_gp_7_2","chapterId":"ch_work_gp_7","text":"勿陷父母於不義","sortOrder":2},
  {"id":"s_work_gp_7_3","chapterId":"ch_work_gp_7","text":"【原文】《書》稱舜“烝烝乂，不格奸”，何謂也？曰：言能以至孝，和顽嚚昏傲，使進進以善自治，不至於大惡也。","sortOrder":3},
  {"id":"s_work_gp_7_4","chapterId":"ch_work_gp_7","text":"【譯述】《尚書》稱舜“烝烝乂，不格奸”，这是什么意思呢？这是說：舜非常孝順，能與心術不正的父親、不忠誠的母親、傲慢的弟弟和睦相處，他以孝行美德感化他们，又加強自身的修養，所以没有流於邪惡。","sortOrder":4},
  {"id":"s_work_gp_7_5","chapterId":"ch_work_gp_7","text":"【原文】曾子耘瓜，誤斬其根。皙怒，建大杖以击其臂。曾子仆地而不知人。","sortOrder":5},
  {"id":"s_work_gp_7_6","chapterId":"ch_work_gp_7","text":"久之乃蘇，欣然而起，進於曾皙曰：“响也！參得罪於大人，用力教參，得無疾乎？”退而就房，援琴而歌，欲令曾皙聞之，知其體康也。孔子聞之而怒，告門弟子曰：“參來，勿內。”曾參自以為無罪，使人請於孔子。孔子曰：“汝不聞乎，昔舜之事瞽瞍，欲使之，未嘗不在於侧；索而殺之，未嘗可得。小捶則待過，大杖則逃走，故瞽瞍不犯不父之罪，而舜不失烝烝之孝。今參事父，委身以待暴怒，殪而不避，身既死而陷父於不義，其不孝孰大焉？汝非天子之民乎？殺天子之民，其罪奚若？”曾參聞之，曰：“參，罪大矣！”遂造孔子而謝過，此之謂也。","sortOrder":6},
  {"id":"s_work_gp_7_7","chapterId":"ch_work_gp_7","text":"【譯述】曾子鋤瓜，不小心斬斷了瓜的根。父親曾皙非常生氣，舉起一根大棍就向曾子的臂膀打過來。曾子摔倒在地，不省人事。過了很久才蘇醒過來，曾子高興地站起來，走近曾皙問候道：“刚才我得罪了父親大人，您為教导我而用力打我，您有没有受傷？”退下去回到房里，曾子邊彈琴邊唱歌，想讓父親聽見，知道他的身體早已恢复了健康。孔子聽說了这些情况就發怒，告訴弟子们說：“如果曾參來了，不要讓他進門。”","sortOrder":7},
  {"id":"s_work_gp_7_8","chapterId":"ch_work_gp_7","text":"曾參自認為無罪，托人向孔子請教。孔子對來人說：“你没聽說過吗？","sortOrder":8},
  {"id":"s_work_gp_7_9","chapterId":"ch_work_gp_7","text":"昔日舜侍奉父親，父親使唤他，他總在父親身邊；父親要殺他，却找不到他。父親輕輕地打他，他就站在那里忍受，父親用大棍打他，他就逃跑，因此他的父親没有背上不義之父的罪名，而他自己也没有失去為人之子的孝心。如今曾參侍奉父親，把身體交給暴怒的父親，父親要打死他，他也不回避。他如果真的死了就會陷父於不義，相比之下，哪个更為不孝？另外，你不是天子的臣民吗？殺了天子的臣民，又會犯多大的罪？”曾參聽後，說：“我的罪過很大呀！”於是造訪孔子而向他謝罪。这件事說的就是这个道理。","sortOrder":9},
  {"id":"s_work_gp_7_10","chapterId":"ch_work_gp_7","text":"父母有错，耐心規勸","sortOrder":10},
  {"id":"s_work_gp_7_11","chapterId":"ch_work_gp_7","text":"【原文】或曰：孔子稱色難。色難者，觀父母之志趣，不待發言而後順之者也。然則《經》何以貴於諫爭乎？曰：諫者，為救過也。親之命可從而不從，是悖戾也；不可從機時從之，則陷親於大惡。然而不諫是路人，故當不義則不可不爭也。或曰：然則爭之能無咈親之意乎？曰：所謂爭者，順而止之，志在必於從也。孔子曰：“事父母幾諫。見志不從，又敬不违，勞而不怨。”《禮》：父母有過，下氣怡色，柔聲以諫。諫若不入，起敬起孝。說則复諫。不說，則與其得罪於乡党州闾，寧熟諫。","sortOrder":11},
  {"id":"s_work_gp_7_12","chapterId":"ch_work_gp_7","text":"父母怒，不說而撻之流血，不敢疾怨，起敬起孝。又曰：事親有隱而無犯。又曰：父母有過，諫而不逆。又曰：三諫而不聽則號泣而隨之，言窮無所之也。或曰：諫則彰親之過，奈何？曰：諫諸內，隱諸外者也，諫諸內則親過不遠，隱諸外故人莫得而聞也。且孝子善則稱親，過則歸己。《凯風》曰：“母氏聖善，我無令人。”其心如是，夫又何過之彰乎？","sortOrder":12},
  {"id":"s_work_gp_7_13","chapterId":"ch_work_gp_7","text":"【譯述】有人說：孔子認為察言觀色最難。察言觀色之所以難，指的是子女善觀父母的興趣愛好，不等他们發話就滿足他们的需要。既然这樣，《孝經》又為何以諫諍為貴呢？回答說：諫爭，為的是挽救父母的過失。父母的命令正確而可以遵從，子女却不遵從，这樣子女就犯了错誤。父母的命令有誤，子女不能服從却去服從，这就會导致父母犯罪。如果子女不勸諫父母那就如同陌路之人，所以當父母言行不義之時，子女必須犯顏直諫。有人說：勸諫父母豈不违背父母的意願吗？回答說：所謂諫爭，是在順乎父母的意願的前提下去阻止他们的一些不對的做法。而且一定要做到讓他们聽從自己的意見。孔子說：“侍奉父母，他们有什么過失，只能委婉地規勸；如果意見没有被采納，仍然要恭敬而不能有抵觸情緒，為父母操勞而無怨恨。”《禮記》說：父母有错，子女要和顏悅色，柔聲下氣地勸諫。若是父母聽不進勸諫，子女就要更加恭敬，以孝心來感化他们，父母高興，子女就要再次進諫；父母不高興，那么與其讓父母得罪於乡里朋友，不如顽強地多次進行勸諫。父母假如生氣了，不高興，把子女打得流血，子女也不能怨恨，仍然要孝敬父母。又說：子女侍奉父母親，可以為他们遮掩過错，却不违忤他们。又說：父母有错，勸諫他们却不违忤他们。又說：子女多次勸諫，父母還不接受，子女就要大聲哭泣，跟在他们的左右，这指的是已經到了毫無辦法的時候了。有人說：勸諫父母就會彰顯他们的過错，怎么辦？回答說：在家勸諫，當著外人就要替父母隱瞞。在家勸諫，父母的過错就能被製止；在外隱瞞，別人就不會知道父母的過错。而且孝子總是把善行歸功於父母，而把過错歸咎於自己。《凯風》說：“母親聖善賢良，我自己是个品德不好的人。”子女的孝心如果能这樣，又怎會彰顯父母的過错呢？","sortOrder":13},
  {"id":"s_work_gp_7_14","chapterId":"ch_work_gp_7","text":"子孝而父母不愛，孝名更彰","sortOrder":14},
  {"id":"s_work_gp_7_15","chapterId":"ch_work_gp_7","text":"【原文】或曰：子孝矣而父母不愛，如之何？曰：责己而已。昔舜父顽、母嚚、象傲，日以殺舜為事。舜往於田，日號泣於旻天。於父母負罪引慝，只載見瞽瞍，夔夔斋栗，瞽瞍亦允。若誠之至也，如瞽瞍者猶信而順之，况不至是者乎？","sortOrder":15},
  {"id":"s_work_gp_7_16","chapterId":"ch_work_gp_7","text":"【譯述】有人說：子女很孝順父母，但父母不慈愛，怎么辦？回答是：從自己那里找原因。從前舜的父親凶狠而心術不正，母親不忠誠，弟弟象非常傲慢，他们每天都想把舜殺死。舜初耕於歷山之時，為父母所嫉恨、困扰，每天號泣於旻天。但他對待父母，仍然克己自责，負罪引惡，非常恭敬地侍奉父母。他每次見父親的時候，都是恭敬而畏懼的樣子，最後父親終於能和他和睦相處。如果子女出於至誠的孝心，像舜的凶悍的父親都能够相信他，與他和睦相處，而况那些本來就不错的父母呢？","sortOrder":16},
  {"id":"s_work_gp_7_17","chapterId":"ch_work_gp_7","text":"【原文】曾子曰：“父母愛之，喜而不忘；父母惡之，懼而弗怨。”","sortOrder":17},
  {"id":"s_work_gp_7_18","chapterId":"ch_work_gp_7","text":"漢侍中薛包，好學篤行。丧母，以至孝聞。及父娶後妻而憎包，分出之。包日夜號泣，不能去。至被殴杖，不得已，庐於舍外，旦入而洒埽。父怒，又逐之。乃庐於里門，晨昏不废。積歲餘，父母慚而還之。","sortOrder":18},
  {"id":"s_work_gp_7_19","chapterId":"ch_work_gp_7","text":"【譯述】曾子說：“父母喜愛子女，子女高興而不忘記；父母讨厭子女，子女畏懼却不怨恨。”","sortOrder":19},
  {"id":"s_work_gp_7_20","chapterId":"ch_work_gp_7","text":"漢代的侍中薛包，勤奋好學，品德高尚。母親去世的時候，他就以孝順而遠近聞名。後來，父親娶了一个後妻，就开始有些厭惡薛包，於是將他分出去居住。薛包日夜號哭，不離去。父母用木棍打他，不得已，他就在父母住的房舍外邊結庐而居。他每天早晨都早早起來給父母洒扫庭院。父親很憤怒，又往外趕他。他於是又結庐於里門，晨省昏定從來不废。過了一年多，父母終於感到有些慚愧，將他叫回了家。","sortOrder":20},
  {"id":"s_work_gp_7_21","chapterId":"ch_work_gp_7","text":"【原文】晉太保王祥至孝，早丧親，繼母朱氏不慈，數谮之，由是失愛於父，每使扫除牛下，祥愈恭敬。父母有疾，衣不解帶，湯藥必親嘗。有丹柰結實，母命守之，每風雨，祥辄抱树而泣。其篤孝純至如此。母終，居丧毀悴，杖而後起。","sortOrder":21},
  {"id":"s_work_gp_7_22","chapterId":"ch_work_gp_7","text":"【譯述】晉代太保王祥非常孝順，他自幼丧母，繼母朱氏不慈祥，幾次在父親面前誣陷他，因此父親也不再疼愛他，父母經常讓他打扫牛棚，可他對父母越來越恭謹。父母有病，他就不脱衣服，小心侍候。給父母喂湯喂藥，他必親口嘗。他家有棵柰树結了果實，繼母叫他看守，每次刮風下雨，王祥就抱著柰树哭泣。他誠實、孝順、純厚如此。繼母死後，他在家守丧，因過度哀傷而損毀身體，要拄著拐杖才能站起來。","sortOrder":22},
  {"id":"s_work_gp_7_23","chapterId":"ch_work_gp_7","text":"【原文】西河人王延，九歲丧母，泣血三年，幾至滅性。每至忌月，則悲泣三旬。繼母卜氏，遇之無道，恒以蒲穰及败麻頭與延貯衣。其姑聞而問之，延知而不言，事母弥謹。卜氏嘗盛冬思生魚，敕延求而不獲，杖之流血。延尋汾淩而哭，忽有一魚長五尺，踴出冰上，延取以進母。卜氏心悟，撫延如己生。","sortOrder":23},
  {"id":"s_work_gp_7_24","chapterId":"ch_work_gp_7","text":"【譯述】西河人王延，九歲時母親去世，他整整哀哭三年，幾乎要死去。此後，每一年的忌月，他還要天天悲哭。他的繼母卜氏，待他不好，經常用亂草和破麻給王延做綿衣。王延的姑姑聽說後，就去問王延，王延不把这些事告訴姑姑，侍奉母親却更加謹慎。後母卜氏有一次大冬天想吃活魚，讓王延去弄魚，王延没有弄來，後母就用木棒打他，以致流血。","sortOrder":24},
  {"id":"s_work_gp_7_25","chapterId":"ch_work_gp_7","text":"王延沿著汾河邊走邊哭，忽然有一條魚五尺多長，跳到冰面上來，王延趕快拿去進獻給母親。卜氏心里有所悔悟，從此之後，撫養王延就像自己的孩子一樣。","sortOrder":25},
  {"id":"s_work_gp_7_26","chapterId":"ch_work_gp_7","text":"【原文】齊始安王谘議劉沨父紹仕宋，位中書郎。沨母早亡，紹被敕納路太後兄女為繼室。沨年數歲，路氏不以為子，奴婢辈捶打之無期度。沨母亡日，辄悲啼不食，弥為婢辈所苦。路氏生溓，沨怜愛之，不忍舍，常在床帳侧。辄被驅捶，終不肯去。路氏病，經年，沨晝夜不離左右。每有增加，辄流涕不食。路氏病瘥，感其意，慈愛遂隆。路氏富盛，一旦為沨立斋宇，筵席不减侯王。","sortOrder":26},
  {"id":"s_work_gp_7_27","chapterId":"ch_work_gp_7","text":"【譯述】齊始安王谘議劉沨的父親劉紹在宋做官，位至中書郎。他的母親早亡，劉紹被皇上敕令納路太後哥哥的女兒為繼室。这時劉沨仅幾歲，後母路氏不把他看作自己的孩子，連那些奴婢们都時不時没深没淺地打他。劉沨每到生身母親的忌日，就悲哀哭泣而不進食，这時就更加為那些奴婢们所欺侮。後來，路氏生下一个孩子叫，劉沨非常地怜愛他，不能割舍，經常守在床帳的旁邊，常常被驅趕捶打，還是不肯離开。再後來，路氏患了病，大概有一年的時間，劉沨認真侍候，晝夜不離左右。路氏的病情每一加重，他就痛哭流涕，不吃飯。路氏病好之後，被他的一片孝心所感動，於是對他变得非常慈愛。路氏很有錢，到了給劉沨成家的時候，為他設宴席招待賓朋，其規模可以比得上王侯。","sortOrder":27},
  {"id":"s_work_gp_7_28","chapterId":"ch_work_gp_7","text":"【原文】唐宣歙觀察使崔衍父倫為左丞，繼母李氏不慈於衍。衍時為富平尉，倫使於吐蕃，久方歸。李氏衣敝衣以見倫，倫問其故，李氏稱倫使於蕃中，衍不給衣食。倫大怒，召衍责詬，命仆隸拉於地，袒其背，將鞭之。衍泣涕終不自陳。倫弟殷聞之，趨往以身蔽衍，杖不得下，因大言曰：“衍每月俸錢皆送嫂處，殷所具知，何忍乃言衍不給衣食？”倫怒乃解。由是倫遂不聽李氏之谮。及倫卒，衍事李氏益謹。李氏所生次子，每多取母錢，使其主以書契征負於衍，衍歲為偿之。故衍官至江州刺史而妻子衣食無所餘。子誠孝而父母不愛，則孝益彰矣，何患乎？","sortOrder":28},
  {"id":"s_work_gp_7_29","chapterId":"ch_work_gp_7","text":"【譯述】唐代宣歙觀察使崔衍的父親崔倫擔任左丞，繼母李氏對崔衍不好。","sortOrder":29},
  {"id":"s_work_gp_7_30","chapterId":"ch_work_gp_7","text":"崔衍其時擔任富平尉，父親出使到了吐蕃，很長時間後才回來。李氏故意穿著破衣服去見崔倫，崔倫問她為什么穿这么破烂的衣服，李氏就谎稱丈夫出使吐蕃期間，兒子崔衍不供給她衣食。崔倫聽後大怒，把崔衍叫來责骂，併命令仆人將崔衍摁翻在地，揭开後背，要鞭打他。崔衍只是哭泣，但不自己說明原委。崔倫的弟弟崔殷獲悉後，趕快跑去用身體遮蔽住崔衍，使得鞭杖不能打住崔衍。崔殷大聲說：“崔衍每月的俸錢全部都送到了嫂子那里，我都知道，怎么忍心說崔衍不給衣食呢？”崔倫的怒氣这才消解。從此之後，崔倫不再聽李氏的誣告。等到崔倫死後，崔衍侍奉李氏更加謹慎。李氏所生的次子，經常向別人借錢，然後與债主订立契約，讓崔衍來付债，崔衍每年都為他偿還债務。因此，崔衍官至江州刺史，薪俸非常優厚，但他的妻子兒女仍然生活困難。子女非常孝順而父母不慈愛，那么他的孝順的美名就更加遠扬，这又有什么可怕的呢？","sortOrder":30},
  {"id":"s_work_gp_7_31","chapterId":"ch_work_gp_7","text":"媳婦不孝兒之過","sortOrder":31},
  {"id":"s_work_gp_7_32","chapterId":"ch_work_gp_7","text":"【原文】或曰：妻子失親之意則如之何？曰：《禮》：“子甚宜其妻父母不說，出。子不宜其妻，父母曰：‘是善事我，’子行夫婦之禮焉，没身不衰。”","sortOrder":32},
  {"id":"s_work_gp_7_33","chapterId":"ch_work_gp_7","text":"【譯述】有的人說：兒媳婦如果不孝順公婆，那該怎么辦呢？《禮記》對这个問題作了回答：“兒子非常喜歡他的妻子，但父母親不喜歡，只能休掉。兒子不喜歡他的妻子，但父母親說：‘她很會侍奉我。’那么兒子就得和他的妻子過下去，白頭到老。”","sortOrder":33},
  {"id":"s_work_gp_7_34","chapterId":"ch_work_gp_7","text":"【原文】漢司隸校尉鮑永，事後母至孝。妻嘗於母前叱狗，永去之。","sortOrder":34},
  {"id":"s_work_gp_7_35","chapterId":"ch_work_gp_7","text":"【譯述】漢代的司隸校尉鮑永，對後母非常孝順。他的妻子有一次當著母親的面呵斥狗，鮑永就把她休掉了。","sortOrder":35},
  {"id":"s_work_gp_7_36","chapterId":"ch_work_gp_7","text":"【原文】齊征北司徒記室劉，母孔氏，甚嚴明。年四十餘未有婚對，建元中，高帝與司徒褚彦回為娶王氏女。王氏穿壁掛履，土落孔氏床上，孔氏不悅，　即出其妻。","sortOrder":36},
  {"id":"s_work_gp_7_37","chapterId":"ch_work_gp_7","text":"【譯文】齊征北司徒記室劉，母親孔氏，治家非常嚴明。劉四十多歲的時候還没有娶上媳婦，建元年間，高帝和司徒褚彦回為他娶王氏女為妻。一次王氏在牆上釘釘子掛鞋，尘土掉在孔氏的床上，孔氏有些不高興，劉就此修掉了自己的妻子。","sortOrder":37},
  {"id":"s_work_gp_7_38","chapterId":"ch_work_gp_7","text":"【原文】唐鳳閣舍人李迥秀，母氏庶賤，其妻崔氏嘗叱媵婢，母聞之不悅，迥秀即時出妻。或止之曰：“賢室雖不避嫌疑，然過非出状，何遽如此？”迥秀曰：“娶妻本以養親，今违忤顏色，何敢留也！”竟不從。","sortOrder":38},
  {"id":"s_work_gp_7_39","chapterId":"ch_work_gp_7","text":"【譯述】唐代鳳閣舍人李迥秀，他的母親出身很低賤，妻子有一次呵斥奴婢，母親聽後很不高興，秀立刻就休掉了妻子。有人勸他說：“你妻子雖然不避嫌疑，傷害了你母親，但她的過失還不致於如此，為什么这么急噪呢？”李迥秀回答說：“我娶妻子就是為了贍養母親，如今妻子竟給母親脸色看，我怎么敢再留她呢？”最終還是没有聽從勸告。","sortOrder":39},
  {"id":"s_work_gp_7_40","chapterId":"ch_work_gp_7","text":"【原文】後漢郭巨家貧，養老母，妻生一子三歲，母常减食與之。巨謂妻曰：“貧乏不能供給，共汝埋子。子可再有，母不可再得。”妻不敢违，巨遂掘坑二尺餘，得黃金一釜。或曰：“郭巨非中道。”曰：然以此教民，民猶厚於慈而薄於孝。","sortOrder":40},
  {"id":"s_work_gp_7_41","chapterId":"ch_work_gp_7","text":"【譯述】東漢郭巨家里很窮，奉養著老母親。妻子生下一个孩子已經三歲，郭巨的母親常常自己少吃一點東西，省下來給小孫子吃。郭巨對妻子說：“咱家貧窮而不能讓全家人都吃飽，你與我一起把孩子埋掉吧。孩子我们還可以再生，但母親不可再有。”妻子不敢不同意，於是掘了一个二尺深的坑，却意外地發現里邊有一鍋黃金。有人議論說：“郭巨雖然是个孝子，但他的做法不仁道。”我们說：盡管用这樣極端的事例來教化民眾，而民風仍然是厚於慈愛，薄於孝。","sortOrder":41},
  {"id":"s_work_gp_7_42","chapterId":"ch_work_gp_7","text":"後母如母【","sortOrder":42},
  {"id":"s_work_gp_7_43","chapterId":"ch_work_gp_7","text":"原文】或曰：五母在禮，律皆同服。凡人事嫡、繼、慈、養之情，乌能比於所生。或者疑於伪與。曰：是何言之悖也？在《禮》：為人後者，斬衰三年。傳曰：何以三年也？受重者必以尊服服之。何如而可為之後？","sortOrder":43},
  {"id":"s_work_gp_7_44","chapterId":"ch_work_gp_7","text":"同宗則可為之後。如何而可以為人後？支子可也。為所後者之祖、父母、妻、妻之父母、崑弟、崑弟之子若子。繼母如母。傳曰：繼母何以如母？繼母之配父與因母同。故孝子不敢殊也。慈母如母。傳曰：慈母者，何也？妾之無子者、妾子之無母者，父命妾曰：“以為子。”命子曰：“女以為母。”若是，則生養之，終其身如母，死則丧之三年如母，貴父之命也。况嫡母，子之君也，其尊至矣。梁中軍田曹行參軍庾沙弥嫡母劉氏寢疾。沙弥晨昏侍侧，衣不解帶。或應針炙，辄以身先试。及母亡，水漿不入口累日。初進大麥薄飲，經十旬，方為薄粥，終丧不食鹽醬。","sortOrder":44},
  {"id":"s_work_gp_7_45","chapterId":"ch_work_gp_7","text":"冬日不衣綿纩，夏日不解衰绖，不出庐戶，晝夜號恸，鄰人不忍聞。所坐荐淚沾為烂。墓在新林，忽有旅松百許株枝葉鬱茂，有異常松。劉好啖甘蔗，沙弥遂不复食之。漢丞相翟方進，既富貴，後母猶在，進供養甚篤。太尉胡廣年八十，繼母在堂，朝夕贍省，旁無幾杖，言不稱老。","sortOrder":45},
  {"id":"s_work_gp_7_46","chapterId":"ch_work_gp_7","text":"漢顯宗命馬皇後母養肅宗，肅宗孝性純篤，母子慈愛，始終無纖介之間。帝既专以馬氏為外家，故所生贾貴人不登極位。贾氏親宗，無受寵榮者。及太後崩，乃策書加貴人玉赤綬而已。古人有丁蘭者，母早亡，不及養，乃刻木而事之。彼賢者，孝愛之心發於天性，失其親而無所施，至於刻木，猶可事也，况嫡繼慈養之存乎？聖人順賢者之心而為之禮，豈有聖人而教人為伪者乎？","sortOrder":46},
  {"id":"s_work_gp_7_47","chapterId":"ch_work_gp_7","text":"【譯述】有人說：對於親生母親、嫡母（妾生的子女稱父親的正妻）、繼母、慈母（撫養自己成長的庶母）和養母，為她们服丧時都要穿同一規格的丧服。也有人認為，人對嫡母、繼母、慈母和養母的恩情，都無法與生身母親相比，所以為嫡、繼、慈、養四母服丧，那都是一种伪善行為。","sortOrder":47},
  {"id":"s_work_gp_7_48","chapterId":"ch_work_gp_7","text":"我们說：这話說得太违背常禮了吧？《禮記》說：做為人的後代，服丧時應該穿斬衰服（最重的一种丧服）三年。“傳”解釋說：為什么要服斬衰服三年呢？这是因為服重孝者必須穿尊服（斬衰三年）來服丧。怎樣才算是家族的後代呢？只要是同宗就可以做為後代。怎樣才算是某一个人的後代呢？支子（嫡妻次子以下及妾子）就可以。為所後者的祖父、父母、妻子、妻子的父母、崑弟、崑弟的兒子和親子一樣。繼母和親生母親一樣。“傳”解釋說：繼母為什么和親生母親一樣？因為繼母和生母是同一个丈夫。所以孝子不敢區別對待。慈母和親生母親一樣。“傳”解釋說：慈母是什么人？没有子女的妾和妾生的孩子而又失去生母的，父親命令妾說：“你把他當作你的親生子。”又對孩子說：“你把她當作你的親生母親。”这樣，慈母撫養你，你一生都要像親生母親一樣對待慈母，慈母死後，要像生母一樣為她服丧三年。这是因為尊重父命。","sortOrder":48},
  {"id":"s_work_gp_7_49","chapterId":"ch_work_gp_7","text":"至於嫡母，她是父親的正妻，其尊貴是達到顶點了的。","sortOrder":49},
  {"id":"s_work_gp_7_50","chapterId":"ch_work_gp_7","text":"梁代中軍田曹行的參軍庾沙弥的嫡母劉氏患病臥床，沙弥每天從早到晚在她身邊侍候，睡覺連衣服都不脱。有時要針灸，沙弥就用自己的身體先试。等到嫡母去世，沙弥好幾天水漿不入口。开始只吃點大麥面糊，一百天之後，他才吃些稀飯，服丧期間他不吃鹽醬。他冬天不穿棉衣服，夏天不脱丧服，從不出家们，日夜痛哭，鄰居都不忍心聽到他的哭聲。他坐的草墊被淚水浸濕腐烂。嫡母的墓葬在新林，那里忽然長出旅松一百多株，枝繁葉茂，不同於一般的松树。嫡母生前喜歡吃甘蔗，沙弥此後就不再吃甘蔗。","sortOrder":50},
  {"id":"s_work_gp_7_51","chapterId":"ch_work_gp_7","text":"漢代臣相翟方進發達之後，他的後母仍建在，他奉養後母很孝順。","sortOrder":51},
  {"id":"s_work_gp_7_52","chapterId":"ch_work_gp_7","text":"太尉胡廣八十歲的時候，繼母建在，他朝夕侍奉，昏定晨省，繼母面前他從不用拐杖，也不敢說自己年紀大。","sortOrder":52},
  {"id":"s_work_gp_7_53","chapterId":"ch_work_gp_7","text":"漢顯宗令馬皇後像生母一樣撫養肅宗，肅宗也非常孝順，他们母子慈愛，始終都没有一點隔閡。肅宗把馬氏一家當做自己的外戚，所以生他的贾貴人没有被立為太後，贾氏宗族的人，也没有一个得寵沾光的。","sortOrder":53},
  {"id":"s_work_gp_7_54","chapterId":"ch_work_gp_7","text":"等到太後馬氏去世後，肅宗才下詔給了生母贾貴人一个玉赤綬，如此而已。","sortOrder":54},
  {"id":"s_work_gp_7_55","chapterId":"ch_work_gp_7","text":"古代有一个叫丁蘭的人，他母親死得早，他没有來得及奉養，他成人之後就用木頭給母親刻了一个牌位來供奉。那些有德行的人，孝敬父母之心出自本性，父母去世之後不能侍奉，還要刻牌位來供奉，况且嫡母、繼母、慈母、養母在世呢？古代的聖人依據那些有德行的人的想法製定了禮，哪里有聖人教人去做假的呢？","sortOrder":55},
  {"id":"s_work_gp_7_56","chapterId":"ch_work_gp_7","text":"養老送終，人之大事","sortOrder":56},
  {"id":"s_work_gp_7_57","chapterId":"ch_work_gp_7","text":"【原文】葬者，人子之大事。死者以窀穸為安宅，兆而未葬，猶行而未有歸也。是以孝子雖愛親，留之不敢久也。古者天子七月，諸侯五月，大夫三月，士逾月。誠由禮物有厚薄，奔赴有遠近，不如是不能集也。國家諸今，王公以下皆三月而葬，蓋以待同位外姻之會葬者適時之宜，更為中製也，《禮》：未葬不变服，啜粥，居倚庐，寢苫枕塊，既虞而後有所变，蓋孝子之心，以為親未獲所安，已不敢即安也。","sortOrder":57},
  {"id":"s_work_gp_7_58","chapterId":"ch_work_gp_7","text":"【譯述】父母去世後安葬，是為人子女的一件大事。死亡的人把墓穴當作房屋，為死者選好墓地却未埋葬，就像活人出行而没有歸家一樣。因此孝子雖然很愛戴他的父母，但是留下他们的遺體也不敢太久。古代規定皇帝死後七个月下葬，諸侯五个月，大夫三个月，一般士民則是一个多月。由於送葬的禮物有厚薄，來參加葬禮的親戚有路程遠近之別，所以不这樣分別規定期限，那些參加葬禮的人和禮物就不能聚齊。國家法令規定，王公以下的人死後三个月都要安葬，大概是要等待親戚朋友都能會齊，这樣更合適。《禮記》說：亡父亡母没有安葬，子女不能更換丧服，只能吃點稀飯，住在臨時搭蓋的簡陋的棚子里，睡在草席上面，以土塊為枕頭。等到亡父亡母埋葬拜祭以後，穿戴居處才能有所改变。这大概是因為孝子的內心覺得父母没有安葬，自己也不敢安居。","sortOrder":58},
  {"id":"s_work_gp_7_59","chapterId":"ch_work_gp_7","text":"【原文】漢蜀郡太守廉范，王莽大司徒丹之孫也。父遭丧亂，客死於蜀漢，范遂流寓西州。西州平，歸乡里。年五十，辭母西迎父丧。蜀都太守張穆，丹之故吏，重資送范。范無所受，與客步負丧歸葭萌。載船觸石破没，范抱持棺柩，遂俱沉溺。眾傷其義，鉤求得之，療救仅免於死，卒得歸葬。","sortOrder":59},
  {"id":"s_work_gp_7_60","chapterId":"ch_work_gp_7","text":"【譯述】東漢蜀郡太守廉范，是王莽的大司徒廉丹的孫子。父親遭遇戰亂，客死於蜀漢，廉范就寄居在西州。西州平定之後，他回到家乡。五十多歲的時候，他辭別母親到西蜀去遷葬亡父。蜀都太守張穆是廉丹的部下，送給廉范很多錢财，廉范一點也不接受，與別人一起帶著亡父的棺柩步行回到葭萌縣。他们乘坐的船只觸石破裂沉没，廉范抱著父親的棺柩一起沉入水中，眾人為他的孝心所感動，將他和棺柩一起救起。經過搶救治療，他没有死，終於回去安葬了父親的棺柩。","sortOrder":60},
  {"id":"s_work_gp_7_61","chapterId":"ch_work_gp_7","text":"【原文】宋會稽贾恩，母亡未葬，為鄰火所逼，恩及妻栢氏號泣奔救。鄰近赴助，棺榇得免，恩及栢氏俱燒死。有司奏，改其里為“孝義里”，蠲租布三世，追赠恩顯親左尉。","sortOrder":61},
  {"id":"s_work_gp_7_62","chapterId":"ch_work_gp_7","text":"【譯述】宋代會稽的贾恩，母親去世還未來得及安葬，正碰上鄰居失了火，燒到了自己家的院子里。贾恩和妻子栢氏一邊哭泣，一邊救火。鄰近的人都趕來帮助救火，母親的棺柩終於保住了，但贾恩和他的妻子却都被燒死了。地方官奏請皇上，因此而將贾恩居住的这條里弄改名為“孝義里”，免除这里的人三代的租稅，併追封贾恩為顯親左尉。","sortOrder":62},
  {"id":"s_work_gp_7_63","chapterId":"ch_work_gp_7","text":"【原文】會稽郭原平，父亡，為塋圹凶功不欲假人，己雖巧而不解作墓，乃訪邑中有塋墓者，助之運力，經時展勤，久乃閒練。又自賣丁夫以供眾費。窀穸之事，俭而當禮，性無術學，因心自然。葬畢，詣所買主，執役無懈，與諸奴分務，讓逸取勞，主人不忍使，每遣之。原平服勤，未嘗暫替。佣賃養母，有餘聚以自贖。","sortOrder":63},
  {"id":"s_work_gp_7_64","chapterId":"ch_work_gp_7","text":"【譯述】會稽的郭原平，父親去世，修造墓室不願意用別人，但他自己雖然心靈手巧，却不會修造墓室，於是他尋找镇上专門營建墓室的匠人，帮人家幹活，經過一段時間的勤學苦練，他終於學會了。他又出賣相當與十个勞動力的徭役，來解决為父親下葬所需的費用。營造墓穴，應當既簡单又符合禮儀，本來也没有什么學問，只要心誠合乎禮法就可以。郭原平安葬父親後，就去那些買他勞動力的買主家，非常勤恳地幹活。他與那些和他一起幹活的佣人奴仆分工的時候，總是把輕松的活讓給別人，自己選擇累活。主人不忍心使用他，常常讓他回去，但原平服役毫不懈怠，從没有讓別人替代過。他靠為別人做佣人來養活母親，如果生活有餘，就贖回那些出賣的勞役。","sortOrder":64},
  {"id":"s_work_gp_7_65","chapterId":"ch_work_gp_7","text":"【原文】海虞令何子平，母丧去官，哀毀逾禮，每至哭踴，頓絕方蘇。屬大明末，東土飢荒，繼以師旅，八年不得營葬。晝夜號哭，常如袒括之日，冬不衣絮，暑不就清涼，一日以數合米為粥，不進鹽菜。所居屋败，不蔽風日，兄子伯與欲為葺理，子平不肯，曰：“我情事未伸，天地一罪人耳，屋何宜覆？”蔡興宗為會稽太守，甚加矜賞，為營冢圹。","sortOrder":65},
  {"id":"s_work_gp_7_66","chapterId":"ch_work_gp_7","text":"【譯述】海虞令何子平，母親去世後，辭官居丧，他哀悼母親都超過了常禮，每次哭丧的時候，他都昏死過去，好半天才能蘇醒過來。这時正是大明末，東部地區鬧飢荒，接著又是戰亂，他八年都無法安葬母親。这期間，他晝夜號哭，就好象在袒括期間一樣。他冬天不穿棉衣，暑天不乘涼，每天仅吃很少的一點粥，不吃鹹鹽和蔬菜。他所住的房屋破败不堪，不能遮蔽風雨，他的侄兒伯與想為他修房，何子平不讓修，說：“我安葬母親的事未完成，等於是一个有罪的人，怎么能住好房子呢？”这時蔡興宗擔任會稽太守，對他大加表彰和奖賞，併為他的母親修建了墓室。","sortOrder":66},
  {"id":"s_work_gp_7_67","chapterId":"ch_work_gp_7","text":"【原文】新野庾震丧父母，居貧無以葬，賃書以營事，至手掌穿，然後成葬事。賢者於葬，何如其汲汲也。今世俗信術者妄言，以為葬不擇地及歲月日時，則子孫不利，禍殃總至，乃至終丧除服，或十年，或二十年，或終身，或累世，猶不葬，至為水火所漂焚，他人所投弃，失亡尸柩，不知所之者，豈不哀哉！人所貴有子孫者，為死而形體有所付也。而既不葬，則與無子孫而死道路者奚以異乎？《詩》雲：“行有死人，尚或之。”况為人子孫，乃忍弃其親而不葬哉！","sortOrder":67},
  {"id":"s_work_gp_7_68","chapterId":"ch_work_gp_7","text":"【譯述】新野的庾震父母親去世，家里貧窮無法安葬，他就靠為別人寫字挣錢安葬父母，他寫得手掌都烂了，才凑够錢安葬了父母。那些賢達之人安葬去世的父母，竟是如此的心情急切，現在的那些信奉巫術的人胡說八道，認為安葬亡父亡母如果不占卜選擇風水寶地和吉利的年、月、日與時辰，就對子孫不利，各种禍事都會一起來。这些人以致於三年服丧結束，除去孝服之後，有的十年，有的二十年，有的甚至終身、好幾代，仍不去安葬死去的父母。搞得父母的遺體被水毀火焚，或者被別人抛弃，連尸首都找不著。豈不悲哀！人有子孫的好處就是為了在去世之後有人來安葬自己。既然不去安葬，那么與無子孫而死在野外無人收尸有啥區別呢？《詩經》說：“路上如果碰到死去的人，還有人來掩埋他。”何况是做子孫的，怎么能抛弃自己的父母不去安葬呢？","sortOrder":68},
  {"id":"s_work_gp_7_69","chapterId":"ch_work_gp_7","text":"【原文】唐太常博士呂才叙《葬書》曰：《孝經》雲，“卜其宅兆而安厝之”。","sortOrder":69},
  {"id":"s_work_gp_7_70","chapterId":"ch_work_gp_7","text":"蓋以窀穸既終，永安體魄，而朝市遷变，泉石交侵，不可前知，故謀之龟筮。近代或選年月，或相墓田，以為一事失所，禍及死生。按《禮》，天子、諸侯、大夫葬，皆有月數，則是古人不擇年月也。《春秋》：九月丁巳葬寧公，雨，不克葬；戊午日中，乃克葬。是不擇日也。鄭簡公司墓之室，當道，毀之則朝而窆，不毀則日中而窆，子產不毀。是不擇時也。古之葬者，皆於國都之北，域有常處，是不擇地也。今葬者，以為子孫富貴貧賤夭寿，皆因卜所致。夫子文為令尹而三已，柳下惠為士師而三黜，讨其邱垅，未嘗改移。而野俗無識，妖巫妄言，遂於躄踴之际，擇葬地而希官爵；荼毒之秋，選葬時而規财利。斯言至矣。夫死生有命，富貴在天，固非葬所能移。就使能移，孝子何忍委其親不葬而求利己哉？世又有用羌胡法，自焚其柩收燼骨而葬之者，人習為常，恬莫之怪。呜呼！訛俗悖戾，乃至此乎？或曰：旅宦遠方，貧不能致其柩，不焚之何以致其就葬？曰：如廉范辈，豈其家富也？延陵季子有言：“骨肉歸复於土，命也，魂氣則無不之也。”舜為天子，巡狩至蒼梧而殂，葬於其野。彼天子猶然，况士民乎！必也無力不能歸其柩，即所亡之地而葬之，不猶愈於毀焚乎？或曰：生事之以禮，死葬之以禮，祭之以禮，具此數者，可以為大孝乎？曰：未也。天子以德教加於百姓，刑於四海為孝；諸侯以保社稷為孝；卿大夫以守其宗廟為孝；士以保其祿位為孝。皆謂能成其先人之志，不墜其業者也。","sortOrder":70},
  {"id":"s_work_gp_7_71","chapterId":"ch_work_gp_7","text":"【譯述】唐朝的太常博士呂才叙《葬書》說：《孝經》里講，“占卜葬地來安葬死者”。这大概是因為墓穴是終老之地，死者永遠在这里安息，而人世上的事常有变遷，引水動土經常毀坏墓地，人们在初選墓地時又無法預知这些，所以才借助占卜來確定墓地。現在的人有的挑選年月，有的占卜墓地，以為这件事如果搞不好，就會帶來生死禍事。按照《禮》的規定，天子、諸侯和大夫下葬，都有固定的月數，这說明古人是不選擇下葬的年月的。《春秋》記載：九月丁巳安葬寧公，正好下雨，不能安葬；戊午日中的時候，得以安葬。这說明古人也不挑選日子。鄭簡公將墓室正好修在了路上，毀之則早晨落葬，不毀則中午落葬。子產不毀。这說明古人下葬是不挑選時間的。古代埋葬死者，都是在國都的北邊，其地方是固定的，这說明古人下葬是不選擇地方的。現在的人安葬死者，以為子孫的富貴、貧賤和長寿、短命都是因為占卜墓地的好坏。子文擔任令尹的時候，三次被解職，柳下惠擔任士師官的時候，三次被罢免，但他们併没有去改換自家的墓地。而那些野俗無知之人，聽信妖巫胡說八道，便在重丧之時，挑選墓地而觊觎高官厚祿；哀痛之际，挑選下葬的吉日良辰來窥视财利。这話說得太對了。这个世界上，死生有命，富貴在天，本來就不是丧葬之事所能左右的。即使能左右，作為孝子又怎么能忍心放下父母不去安葬，而以此來謀划對自己有利的事呢？當世又有用羌、胡等少數民族安葬死人的方法的，把父母親人的靈柩焚燒之後收其骨灰來埋葬。人们已習以為常，對此舉安然無所怪。乌呼！有悖於禮法的行為竟到了如此的地步！有人說：如果在外地做官旅行，而又貧窮，不能將靈柩運回故乡，像这种情况不燒成骨灰，怎么能運回故乡安葬呢？我们說：像廉范那些人，難道他们的家很富有吗？延陵季子曾說過：人死之後身體歸葬於大地，这表明他没有生命了，但他的靈魂還能够到處飄荡。舜帝在位時，出巡狩獵到達蒼梧而崩殂，舜便葬在了那里。人家貴為天子，還如此，而况我们一般人呢？如果確實没有能力將先人的靈柩運回故乡，那么就在所亡之地安葬，这不比焚燒掉好吗？有人問：父母親活著的時候，按禮法來侍奉，死後再按禮來安葬，然後按禮數來祭祀，这幾件事如果做好了，就可以算作是大孝子了吧？回答說：還不算。天子將仁德教化布於百姓，達於四海為孝；諸侯以能够保有祖宗傳下來的江山社稷為孝；卿大夫以能够守住宗廟光宗耀祖為孝；士官以能够保住自己的俸祿地位為孝。这都是說，能够繼承先人的遺志，不使祖宗开創的事業毀於自己之手，这才是大孝。","sortOrder":71},
  {"id":"s_work_gp_7_72","chapterId":"ch_work_gp_7","text":"養老送終不算孝，光宗耀祖方為孝","sortOrder":72},
  {"id":"s_work_gp_7_73","chapterId":"ch_work_gp_7","text":"【原文】晉庾袞父戒袞以酒，袞嘗醉，自责曰：“餘废先人之戒，其何以訓人？”乃於父墓前自杖三十。可謂能不忘訓辭矣。","sortOrder":73},
  {"id":"s_work_gp_7_74","chapterId":"ch_work_gp_7","text":"【譯述】晉代的庾袞，父親讓他戒掉酗酒的習慣，可是有一次庾袞飲酒大醉，他非常自责地說：“我违反了父親的戒規，還怎么去訓导別人呢？”於是他到父親的墳墓前，自己打了自己三十棍。他可以說是不忘父親的遺訓了。","sortOrder":74},
  {"id":"s_work_gp_7_75","chapterId":"ch_work_gp_7","text":"【原文】《詩》雲：“題彼脊令，載飛載鳴，我日斯邁，而月斯征。夙興夜寐，無忝爾所生。”","sortOrder":75},
  {"id":"s_work_gp_7_76","chapterId":"ch_work_gp_7","text":"【譯述】《詩經》說：“那脊令鳥啊，又飛又叫。我已經漸漸地老了，可你的歲月還很長。要早起晚睡辛勤勞作，不要有愧於你的一生。”","sortOrder":76},
  {"id":"s_work_gp_7_77","chapterId":"ch_work_gp_7","text":"【原文】《經》曰：立身行道，扬名於後世，以顯父母，孝之終也。又曰：事親者，居上不驕，為下不亂，在丑不爭。居上而驕則亡，為下而亂則刑，在丑而爭則兵。三者不除，雖日用三牲之養，猶為不孝也。","sortOrder":77},
  {"id":"s_work_gp_7_78","chapterId":"ch_work_gp_7","text":"【譯述】《孝經》說：子女立身守志，遵守道德，扬名於後代，光宗耀祖，这才是孝順父母的最高表現。又說：子女孝順父母，表現在身居高位而不驕傲，處於下民的地位却不作亂，在逆境之中却不爭斗。如果身居高位而驕傲就會自取滅亡，為下民而去作亂，就會受到懲處，身處逆境却要爭斗，就會受到傷害。这三者不消除，即便你每天用牛、羊、猪肉等供養父母，還是屬於不孝順父母。","sortOrder":78},
  {"id":"s_work_gp_7_79","chapterId":"ch_work_gp_7","text":"【原文】《內則》曰：“父母雖没，將為善，思貽父母令名，必果；將為不善，思貽父母羞辱，必不果。”","sortOrder":79},
  {"id":"s_work_gp_7_80","chapterId":"ch_work_gp_7","text":"【譯述】《內則》說：“父母雖然去世，子女要做一件好事，想到这樣會帶給父母美名，就一定能做成；子女要做坏事的時候，想到这樣會使父母蒙受羞辱，就會停下來不去做。”","sortOrder":80},
  {"id":"s_work_gp_7_81","chapterId":"ch_work_gp_7","text":"【原文】公明儀問於曾子曰：“夫子可以為孝乎？”曾子曰：“是何言欤！","sortOrder":81},
  {"id":"s_work_gp_7_82","chapterId":"ch_work_gp_7","text":"是何言欤！君子之所謂孝者，先意承志，諭父母於道。參直養者也，安能為孝乎。”","sortOrder":82},
  {"id":"s_work_gp_7_83","chapterId":"ch_work_gp_7","text":"【譯述】公明儀問曾子說：“您算得上是孝子吗？”曾子說：“这是什么話啊！这是什么話啊！古代的君子所說的孝子，父母没有發話就能知道父母的意思，而且能用道來引导父母，使父母明白更多的道理。我對父母，只是養老送終而已，怎么能稱得上是孝子呢？”","sortOrder":83},
  {"id":"s_work_gp_7_84","chapterId":"ch_work_gp_7","text":"【原文】曾子曰：“身也者，父母之遺體也。行父母之遺體，敢不敬乎？居處不莊非孝也，事君不忠非孝也，莅官不敬非孝也，朋友不信非孝也，戰陳無勇非孝也。五者不備，灾及其親，敢不敬乎？亨熟膻芗，嘗而荐之，非孝也。君子之所謂孝也，國人稱願，然曰：幸哉，有子如此！所謂孝也已。”為人子能如是，可謂之孝有終矣。","sortOrder":84},
  {"id":"s_work_gp_7_85","chapterId":"ch_work_gp_7","text":"【譯述】曾子說：“身體，是父母所給的。對於父母遺留下來的身體，子女敢不恭敬對待吗？所以子女居家處事不莊重，就是不孝順；侍奉君主不忠誠，就是不孝順；做官不奉公守法就是不孝順；交友而不講信運就是不孝順；在戰場上不勇敢就是不孝順。不具備以上五种孝順，灾禍將殃及父母，能不恭敬從事吗？亨熟膻芗，食物飲品，嘗過之後獻給父母，这算不上孝順。君子所說的孝順，指的是國人對父母稱贊說：幸福啊，你有这樣的子女！这才是所說的孝順。”做為人的子女，能够做到这些，就可以稱得上是為孝而能盡善盡美，善始善終。","sortOrder":85},
  {"id":"s_work_gp_8_1","chapterId":"ch_work_gp_8","text":"家范卷六女/孫/伯叔父/侄","sortOrder":1},
  {"id":"s_work_gp_8_2","chapterId":"ch_work_gp_8","text":"女子也應學詩書","sortOrder":2},
  {"id":"s_work_gp_8_3","chapterId":"ch_work_gp_8","text":"【原文】《禮》：女子十年不出，姆教婉娩聽從，執麻枲，治絲茧，織纴組紃，學女事以共衣服。觀於祭祀，納酒漿笾豆菹醢，禮相助奠。十有五年而笄，二十而嫁。古者婦人先嫁三月，祖廟未毀，教於公宮；祖廟既毀，教於宗室。教以婦德、婦言、婦容、婦功，教成祭之牲用魚，芼之以　藻，所以成婦順也。","sortOrder":3},
  {"id":"s_work_gp_8_4","chapterId":"ch_work_gp_8","text":"【譯述】《禮記》說：女子十歲不出閨門，學習婦道：向女師學習柔順，聽從長者的教誨，學習織麻紡繩紡紗織布，學習女紅、縫纫。觀察學習祭祀之禮，學習祭祀中獻酒摆設祭器等各种禮數。女子十五歲舉行插簪之禮，已進入成人。二十歲出嫁。古時候，女子出嫁前三个月，如果祖廟未毀，就在公宮接受教育；祖廟毀掉之後，就在宗室接受教育。主要學習婦德、婦言、婦容、婦功等，學成之後再用魚祭祀，用　藻芼，这樣才能成為一个符合婦德的的女子。","sortOrder":4},
  {"id":"s_work_gp_8_5","chapterId":"ch_work_gp_8","text":"【原文】曹大家《女戒》曰：今之君子徒知訓其男，檢其書傳，殊不知夫主之不可不事，禮義之不可不存。但教男而不教女，不亦蔽於彼此之教乎？《禮》：八歲始教之書，十五而志於學矣！獨不可依此以為教哉。夫雲婦德，不必才明絕異也；婦言，不必辯口利辭也；婦容，不必顏色美麗也；婦功，不必工巧過人也。清閒、貞靜、守節、整齊，行已有恥，動靜有法，是謂婦德。擇辭而說，不道惡語，時然後言，不厭於人，是謂婦言。盥浣尘秽，服飾鮮絜，沐浴以時，身不垢辱，是謂婦容。专心紡績，不好戲笑，絜斋酒食，以奉賓客，是謂婦功。此四者，女之大德，而不可乏者也。然為之甚易，唯在存心耳。凡人，不學則不知禮義。不知禮義，則善惡是非之所在皆莫之識也。於是乎有身為暴亂而不自知其非也，禍辱將及而不知其危也。然則為人，皆不可以不學，豈男女之有異哉？是故女子在家，不可以不讀《孝經》、《論語》及《詩》、《禮》，略通大義。其女功，則不過桑麻織績、製衣裳、為酒食而已。至於刺繡華巧，管絃歌詩，皆非女子所宜習也。古之賢女無不好學，左圖右史，以自儆戒。","sortOrder":5},
  {"id":"s_work_gp_8_6","chapterId":"ch_work_gp_8","text":"【譯述】曹大家的《女戒》說：如今的君子只知道教育他们的兒子，讓兒子讀書學習，却不知道對於女子來說，丈夫不能不侍奉，禮義也不能丢弃。只教育兒子却不教育女兒，不也忽视了男女之間的禮義教育吗？《禮記》說：八歲开始教孩子讀書，十五歲就要立志學習。但不能以此作為女子的教育方法，所謂有婦德，不必才華絕代；婦人應有的言談應對，也不必辯口利辭；婦容，不必化妆得多么美麗；婦功，也不必工巧過人。清閒、貞靜、守節、整齊，舉止知廉恥，動靜有章法，这就是婦德。說話懂得挑選詞句，不說坏話，適時而言，不讓他人讨厭自己，这就是婦言的修養。洗刷衣物尘垢，做到服飾整絜，按時沐浴，幹净衛生，这就是婦容。专心於紡織，不隨便嬉笑戲鬧，製備酒食佳肴，招待賓客，这就是婦功。以上四者，是女子最大的婦德，不能没有。这些做起來非常容易，關鍵是要時時銘記在心。做為一个人，不學習就不知道禮義法則；不知道禮義法則，就不能辨別善惡是非。於是自己违法作亂却不知道自己的错誤，禍辱臨身却不知道其危险。这樣看來，為人都不能不學習，怎么能因為男女的差別而不去學習呢？因此女子在家，不可以不讀《孝經》、《論語》以及《詩經》、《禮記》，最起碼要略通其大意。至於女功，不過是桑麻織布、做衣裳、辦酒食等等，至於刺繡華巧、管絃歌詩，都不適合女子學習。縱觀古代的賢能女子没有不好學的，左圖右史，廣泛涉獵，以此來提高自身的修養。","sortOrder":6},
  {"id":"s_work_gp_8_7","chapterId":"ch_work_gp_8","text":"【原文】漢和熹邓皇後，六歲能史書，十二通《詩》、《論語》。諸兄每讀經傳，辄下意難問，志在典籍，不問居家之事。母常非之，曰：“汝不習女工，以供衣服，乃更務學，寧當舉博士耶？”後重违母言，晝修婦業，暮誦經典，家人號曰“諸生”。其餘班婕妤、曹大家之徒，以學顯當時，名垂後來者多矣。","sortOrder":7},
  {"id":"s_work_gp_8_8","chapterId":"ch_work_gp_8","text":"【譯述】漢代和熹邓皇後，六歲就能讀史書，十二歲通晓《詩經》、《論語》。","sortOrder":8},
  {"id":"s_work_gp_8_9","chapterId":"ch_work_gp_8","text":"她的幾个哥哥每次誦讀經傳的時候，她就虛心請教，她的志向愛好全在學習典籍，不喜歡過問居家生活等事。母親經常责難她說：“你不學習女工，以備將來製作衣服，却去讀書學習，難道要考博士吗？”邓皇後仍舊愛學習，於是她白天學習婦業，晚上就誦讀經書，家里人稱她為“諸生”。其他的像班婕妤、曹大家等人，以學問文章顯扬當時，名垂後來的女子很多。","sortOrder":9},
  {"id":"s_work_gp_8_10","chapterId":"ch_work_gp_8","text":"【原文】漢珠崖令女名初，年十三。珠崖多珠，繼母連大珠以為系臂。及令死，當還葬。法，珠入於關者，死。繼母弃其系臂珠，其男年九歲，好而取之，置母鏡奁中，皆莫之知。遂與家室奉丧歸，至海關。海關候吏搜索，得珠十枚於鏡奁中。吏曰：“嘻！此值法，無可奈何，誰當坐者？”初在左右，心恐繼母去置奁中，乃曰：“初坐之。”吏曰：“其状如何？”初對曰：“君子不幸，夫人解系臂去之。初心惜之，取置夫人鏡奁中，夫人不知也。”吏將初劾之。繼母意以為實，然怜之。因謂吏曰：“願且待，幸無劾兒。兒誠不知也。兒珠，妾系臂也。君不幸，妾解去之，心不忍弃，且置鏡奁中。迫奉丧，忽然忘之。妾當坐之。”初固曰：“實初取之。”繼母又曰：“兒但讓耳，實妾取之。”因涕泣不能自禁。女亦曰：“夫人哀初之孤，強名之以活，初身，夫人實不知也。”又因哭泣，泣下交頸。送丧者盡哭哀恸，傍人莫不為酸鼻揮涕。關吏執筆劾，不能就一字。關候垂泣，終日不忍决，乃曰：“母子有義如此，吾寧生之，不忍加文。母子相讓，安知孰是？”遂弃珠而遣之。既去，乃知男獨取之。","sortOrder":10},
  {"id":"s_work_gp_8_11","chapterId":"ch_work_gp_8","text":"【譯述】漢代珠崖令有个女兒名字叫初，十三歲。珠崖这个地方寶珠很多，初的繼母將一些大的寶珠串起來，系在手臂上作妆飾。後來珠崖令去世，家里人要將他的靈柩運回家乡安葬。當時的法令規定，有携帶珠寶進入關內的，判死刑。初的繼母只好丢弃了他系在胳臂上的那串珠子，初的弟弟年方九歲，因為喜愛就把那串珠子捡起來，放在了母親的化妆盒里，誰也没有看見这一切。全家人扶柩來到海關，海關守吏檢查的時候，從化妆盒里找出十枚珠子。守吏說：“啊！这正好觸犯了法令，我们也没有辦法，你们家誰出來承擔这个罪责接受懲罰呢？”初在旁邊，她心想，恐怕是繼母摘下來放在化妆盒里的，就說：“由我來承擔。”守吏問：“你是怎么放進去的？”初回答說：“我父親不幸去世，我繼母將系在胳臂上的珠子解下來扔掉，我覺得很可惜，就捡起來放在了繼母的化妆盒里，繼母併不知道这件事。”於是守門的官吏就要給初記錄犯罪事實。初的繼母以為真是这么回事，然而，她有些怜悯初，就對那守門的官吏說：“請等一下，千萬不要錄我女兒的罪過，其實她根本就不知道。是她的珠子，我系在了臂上。因夫君去世，需歸家安葬，我便將珠子解下來，但不忍心丢弃，就暫且放在了化妆盒里。後來由於辦理丧事很急迫，就忘了这件事。所以我應當承擔责任。”初還在堅持說：“確實是我捡起來放進去的。”繼母又說：“你別再爭執了，这失誤確實是我造成的。”於是她流淚哭泣，不能自禁。初也說：“夫人是看見我是个没有父母的孩子，可怜我，所以她才冒名顶替要救我，其實就是我親身犯法，夫人確實不知道这件事。”她也哭起來，淚流滿面。那些送丧的人也都非常悲痛地哭起來，旁邊的人没有不掉淚的。守門的官吏用筆記錄，竟因哭泣而不能寫一个字。守關的人流著淚，始終不忍心做出有罪的决定，便說：“这母子俩如此有情義，我寧願來承擔责任，也不忍心記錄和上報她们的過失。而且，她们母子相互爭執，怎么能知道誰是誰非呢？”於是便將那些珠子扔掉，把她们母子放走了。初和繼母離去之後才知道珠子是初的弟弟放進去的。","sortOrder":11},
  {"id":"s_work_gp_8_12","chapterId":"ch_work_gp_8","text":"誰說女子不如男","sortOrder":12},
  {"id":"s_work_gp_8_13","chapterId":"ch_work_gp_8","text":"【原文】宋會稽寒人陳氏，有女無男。祖父母年八九十，老無所知。父篤癃疾，母不安其室。遇歲飢，三女相率於西湖采菱莼，更日至市货賣，未嘗虧怠，乡里稱為義門，多欲娶為婦。長女自傷茕獨，誓不肯行。祖父母尋相繼卒，三女自營殯葬，為庵舍居墓侧。","sortOrder":13},
  {"id":"s_work_gp_8_14","chapterId":"ch_work_gp_8","text":"【譯述】宋會稽寒人陳氏，有女兒没有兒子。祖父和祖母年紀都在八九十歲，老得有些糊涂了，什么事情都不知道。父親身患重病，母親弃家而去。","sortOrder":14},
  {"id":"s_work_gp_8_15","chapterId":"ch_work_gp_8","text":"家里如此艱難，遇到飢荒年月，三个女兒就一起到西湖去采菱角，第二天到集市上去賣，她们竟然能够很好地養活年老的祖父、祖母和重病的父親，乡里稱贊她们家為“義門”，周围的許多男子都想娶她们姊妹三人做媳婦。長女想到父親膝下無子，非常孤獨，便不願出嫁。祖父祖母不久相繼去世，三姐妹靠自己將他们安葬，併在墳墓旁邊結庐守墓。","sortOrder":15},
  {"id":"s_work_gp_8_16","chapterId":"ch_work_gp_8","text":"【原文】又諸暨東洿里屠氏女，父失明，母痼疾，親戚相弃，乡里不容。女移父母，遠住纻舍，晝采樵，夜紡績，以供養。父母俱卒，親營殯葬，負土成墳。乡里多欲娶之，女以無兄弟，誓守墳墓不嫁。","sortOrder":16},
  {"id":"s_work_gp_8_17","chapterId":"ch_work_gp_8","text":"【譯述】還有諸暨東洿里屠氏家的女兒，她的父親是个瞎子，母親有很重的病，她家的親戚和本乡近鄰没有人肯帮助他们。屠氏的女兒將父母親搬遷到遠處的纻舍，她白天砍柴，晚上織布，來供養父母。父母先後去世，她親自安葬他们，一个人靠擔土為父母親做成墳丘。乡里的人知道她很賢惠，很多人家都想娶她做媳婦，可她想到自己家里没有兄弟，便决定自己為父母守墳，不肯出嫁。","sortOrder":17},
  {"id":"s_work_gp_8_18","chapterId":"ch_work_gp_8","text":"【原文】唐孝女王和子者，徐州人，其父及兄為防狄卒，戍涇州。元和中，吐蕃寇邊，父兄戰死，無子，母先亡。和子年十七，聞父兄殁於邊，披發徒跣缞裳，獨往涇州，行丐，取父兄之丧歸徐營葬，植松柏，剪發坏形，庐於墓所。節度使王智興以状奏之，詔旌表門闾。此數女者，皆以单茕事其父母，生則能養，死則能葬，亦女子之英秀也。","sortOrder":18},
  {"id":"s_work_gp_8_19","chapterId":"ch_work_gp_8","text":"【譯述】唐代的孝女王和子，是徐州人，她的父親和哥哥從軍戍邊，駐扎在涇州。元和年間，吐蕃侵犯邊疆，和子的父親和哥哥戰死在戰場上，家里再没有兒子了，而且母親早年就去世了。这時和子年仅十七歲，她聽說父親、哥哥死於邊疆，就披麻戴孝，赤足步行，獨自前往涇州。她沿途乞讨，終於來到涇州，找到父兄的遺體，併帶回徐州安葬。她在墓地旁邊种植松柏，剪掉頭發，毀坏自己的容貌，在墓地旁邊結庐而居。節度使王智興將和子的这些情况奏聞皇上，皇上下詔表彰和子。以上这幾个女子，都是以自己一个人的力量來侍奉父母，父母活著的時候，她们能够贍養；父母死後，她们能够安葬，也可以稱得上是女中英杰了。","sortOrder":19},
  {"id":"s_work_gp_8_20","chapterId":"ch_work_gp_8","text":"【原文】唐奉天窦氏二女，雖生長草野，幼有志操。永泰中，群盜數千人剽掠其村落。二女皆有容色，長者年十九，幼者年十六，匿巖穴間。盜曳出之，騎逼以前。臨壑穀，深數百尺，其姊先曰：“吾寧就死，義不受辱！”即投崖下而死。盜方驚駭，其妹從之自投，折足败面，血流被體。盜乃舍之而去。京兆尹第五琦嘉其貞烈，奏之，詔旌表門闾，永蠲其家丁役。二女遇亂，守節不渝，视死如歸，又難能也。","sortOrder":20},
  {"id":"s_work_gp_8_21","chapterId":"ch_work_gp_8","text":"【譯述】唐代奉天有窦氏姐妹俩，雖然出生在尋常人家，但很小的時候就頗有志氣節操。永泰年間，數千強盜來她们居住的村落劫掠，她们姐妹俩長得都很漂亮，姐姐十九歲，妹妹十六歲，藏匿在洞穴里。強盜搜出她们，將她俩拉出來，然後騎著馬逼她俩往前走。走到一處數百尺深的懸崖旁邊，姐姐先說：“我寧可去死也不受侮辱！”說罢，跳崖而死。強盜们正在驚駭之中，妹妹也跟著跳了下去，摔斷了腳，毀坏了容顏，血流滿身。於是这群強盜不再去理會她们，離开了这里。京兆尹第五琦嘉其嚴守貞操，於是奏聞皇上。皇上下詔表彰她们，併永遠免除她们家的丁役。这兩个女子遭遇匪亂，尚能嚴守貞節，视死如歸，實在是難能可貴啊！","sortOrder":21},
  {"id":"s_work_gp_8_22","chapterId":"ch_work_gp_8","text":"【原文】漢文帝時，有人上書，齊太仓令淳於意有罪，當刑，詔獄逮系長安。","sortOrder":22},
  {"id":"s_work_gp_8_23","chapterId":"ch_work_gp_8","text":"意有五女，隨而泣。意怒，骂曰：“生女不生男，缓急無可使者。”於是少女緹萦傷父之言，乃隨父西，上書曰：“妾父為吏，齊中稱其廉平，今坐法當刑。妾切痛死者不可复生，而刑者不可复屬，雖欲改過自新，其道莫由，終不可得。妾願入身為官婢，以贖父刑罪，便得改行自新也。”書聞，上悲其意。此歲中亦除肉刑法。緹萦一言而善，天下蒙其泽，後世賴其福，所及遠哉。","sortOrder":23},
  {"id":"s_work_gp_8_24","chapterId":"ch_work_gp_8","text":"【譯述】漢文帝時，有人上書說齊太仓令淳於意犯了罪，應當受到懲處。文帝下詔將淳於意逮捕，關進長安的監獄。淳於意有五个女兒，她们跟在父親後邊哭泣。淳於意發怒，骂道：“我只生了女兒，没生兒子，有了事情，没有人能够出來帮忙。”他的小女兒緹萦感傷於父親的話語，便跟隨父親西行至長安，上書文帝說：“我父親當官，齊地人都稱贊他廉絜、公正。他如今犯罪，理當受刑，但我悲痛的是死者不能复生，受刑的人不能再肢體完好，即便他想改過自新，也没有途径，最終還是不可能了。我願自己進官府做奴婢，以贖免父親的罪行，使他能够改過自新。”漢文帝看過她的上書，悲悯她的孝心，就免了她父親的罪。这一年，朝廷還废除了肉刑法。只因為緹萦一句話說得好，普天下的百姓都享受恩泽，後人也受益於她的恩惠，她的恩泽所及太遠了。","sortOrder":24},
  {"id":"s_work_gp_8_25","chapterId":"ch_work_gp_8","text":"【原文】後魏孝女王舜者，趙邹人也。父子春與從兄長忻不协。齊亡之际，長忻與其妻同謀，殺子春。舜時年七歲。又二妹，粲年五歲，璠年二歲，併孤苦，寄食親戚。舜撫育二妹，恩義甚篤。而舜陰有复仇之心，長忻殊不備。姊妹俱長，親戚欲嫁，辄拒不從。乃密謂二妹曰：“我無兄弟，致使父仇不复，吾辈雖女子，何用生為？我欲共汝報复，何如？”二妹皆垂涕曰：“唯姊所命。”夜中，姊妹各持刀逾牆入，手殺長忻夫婦，以告父墓。因詣縣請罪，姊妹爭為謀首，州縣不能决。文帝聞而嘉叹，原罪。《禮》：“父母之仇，不與共戴天。”舜以幼女，蘊志發憤，卒袖白刃以揕仇人之胸，豈可以壮男子反不如哉！","sortOrder":25},
  {"id":"s_work_gp_8_26","chapterId":"ch_work_gp_8","text":"【譯述】後魏有一个孝女叫王舜，趙邹人。她的父親子春和從兄長忻不和，齊國滅亡的時候，長忻與他的妻子同謀，殺死了子春。这時王舜才七歲，還有兩个妹妹，王粲五歲，王璠年仅兩歲。她们姐妹三人孤苦無依，寄居在親戚家里。王舜照顧兩个妹妹，姊妹三人感情非常好。王舜心里一直有為父親复仇的打算，長忻却没有一點防備。她们姐妹幾个逐漸長大了，親戚家張羅著為王舜尋婆家，但王舜總是不肯出嫁。她悄悄對兩个妹妹說：“我没有兄弟，所以殺父之仇一直未報，我们雖然是女子，但活著難道就没有用？我想和你们俩一起為父報仇，怎么樣？”兩个妹妹都流淚說：“我们聽你的。”晚上，姐妹三人每人都手持一把刀，翻牆進了長忻的宅院，親手殺死了長忻夫婦，併到父親的墓前告慰父親的靈魂。然後她们到縣衙自首，請求治罪，姐妹三人爭著承認自己是首犯，州官和縣官都不能判决。孝文帝聽說了这件事，併頗為姐妹三人的舉動所感動，於是竟原谅了她们的罪。《禮記》說：“父母之仇，不共戴天。”王舜仅仅是个小女孩子，而能蓄志發憤，親手殺死殺父仇人，為父報仇，那么作為男子，怎么能够連一个女子都不如呢？","sortOrder":26},
  {"id":"s_work_gp_8_27","chapterId":"ch_work_gp_8","text":"孫後代子孫莫败家","sortOrder":27},
  {"id":"s_work_gp_8_28","chapterId":"ch_work_gp_8","text":"【原文】《書》曰：“辟不辟，忝厥祖。”《詩》雲：“無忘爾祖，聿修厥德。”然則為人而怠於德，是忘其祖也，豈不重哉！","sortOrder":28},
  {"id":"s_work_gp_8_29","chapterId":"ch_work_gp_8","text":"【譯述】《尚書》說：“人如果有罪過就會使他的祖上蒙羞。”《詩經·大雅·文王》說：“不要忘記你的祖先，要繼承發扬先人的德業。”这樣說來，做人如果不修德行，是忘記了他的祖宗。这難道不重要吗？","sortOrder":29},
  {"id":"s_work_gp_8_30","chapterId":"ch_work_gp_8","text":"【原文】晉李密，犍為人，父早亡，母何氏改醮。","sortOrder":30},
  {"id":"s_work_gp_8_31","chapterId":"ch_work_gp_8","text":"密時年數歲，感恋弥至，烝烝之性，遂以成疾。祖母劉氏躬自撫養。","sortOrder":31},
  {"id":"s_work_gp_8_32","chapterId":"ch_work_gp_8","text":"密奉事以孝謹聞，劉氏有疾則泣，侧息，未嘗解衣。飲膳湯藥，必先嘗後進。仕蜀為郎，蜀平，泰始詔征為太子洗馬。密以祖母年高，無人奉養，遂不應命。上疏曰：“臣無祖母，無以至今日。祖母無臣，無以終餘年。母孫二人更相為命，是以私情區區，不敢弃遠。臣密今年四十有四，祖母劉氏今年九十有六，是臣盡節於陛下之日長，而報養劉氏之日短也。乌鳥私情，乞願終養。”武帝矜而許之。","sortOrder":32},
  {"id":"s_work_gp_8_33","chapterId":"ch_work_gp_8","text":"【譯述】西晉的李密，犍為人，父親早死，母親何氏改嫁。这時李密只有幾歲，他性情淳厚，恋母情深，思念成疾。祖母劉氏親自撫養他。李密侍奉祖母以孝順和恭敬聞名當時，祖母劉氏一有病，他就哭泣，侍候祖母，夜里未曾脱衣。為祖母端飯菜、端湯藥，他總要嘗過之後才讓祖母用。","sortOrder":33},
  {"id":"s_work_gp_8_34","chapterId":"ch_work_gp_8","text":"他後來在蜀漢做郎官。蜀中平定後，泰始初年，晉武帝委任他為太子洗馬。他因為祖母年高，無人奉養，没有接受官職。他上書武帝說：“我如果没有祖母，也就不能活到今天。祖母如果没有我，就不能安度晚年。我们祖孫二人相依為命，因為我的區區私情，我不敢離开祖母而遠行。","sortOrder":34},
  {"id":"s_work_gp_8_35","chapterId":"ch_work_gp_8","text":"我今年四十四歲，祖母今年九十六歲，我為陛下效勞的時日還很長，可是我報恩於祖母的日子却很短。因奉養老人的私情，我請求皇上准許我為祖母養老送終。”武帝同情他，併同意了他的請求。","sortOrder":35},
  {"id":"s_work_gp_8_36","chapterId":"ch_work_gp_8","text":"【原文】齊彭城郡丞劉，有至性，祖母病疽經年，手持膏藥，潰指為烂。","sortOrder":36},
  {"id":"s_work_gp_8_37","chapterId":"ch_work_gp_8","text":"【譯述】齊彭城郡丞劉，性情至孝，祖母身患毒瘡，經年不愈，他就手拿膏藥，親自為祖母敷藥治瘡，以致於手指都潰烂了。","sortOrder":37},
  {"id":"s_work_gp_8_38","chapterId":"ch_work_gp_8","text":"【原文】後魏張元，芮城人，世以純至為乡里所推。元年六歲，其祖以其夏中熱甚，欲將元就井浴，元固不肯。祖謂其貪戲，乃以杖击其頭曰：“汝何為不肯浴？”元對曰：“衣以蓋形，為覆其亵。元不能亵露其體於白日之下。”祖異而舍之。年十六，其祖丧明三年，元恒忧泣，晝夜讀佛經禮拜，以祈福佑。每言“天人師乎？元為孫不孝，使祖丧明，今願祖目見明，元求代暗。”夜夢見一老翁，以金鎞療其祖目，元於夢中喜躍，遂即驚覺，乃遍告家人。三日，祖目果明。其後，祖臥疾再周，元恒隨祖所食多少，衣冠不解，旦夕扶侍。及祖没，號踴，絕而复蘇。复丧其父，水漿不入口三日。乡里鹹叹異之。縣博士楊辄等二百餘人上其状，有詔表其門闾。此皆為孫能養者也。","sortOrder":38},
  {"id":"s_work_gp_8_39","chapterId":"ch_work_gp_8","text":"【譯述】後魏時候的張元，芮城人，以性格純厚為乡里所推崇。張元六歲的時候，他的祖父認為夏天的中午非常炎熱，想把他帶到水池邊洗澡，可是張元堅决不肯。祖父以為他貪玩，就用手杖打他的頭，問他：“你為什么不願意洗澡？”他回答說：“穿衣服是為了遮體避羞。我不能在大天白日袒露自己的身體。”祖父聽了他的話覺得驚異，就放過了他。到他十六歲的時候，祖父已失明三年，張元為此忧愁、哭泣，日夜誦經拜佛，祈求神靈保佑。他常常这樣說：“是天人師如來吗？我為孫而不孝，使祖父失明，現在我願意讓祖父重見光明，讓我來代替他失明。”这天夜晚，他夢見有个老頭，用金鎞治療祖父的眼睛，張元在夢中高興得跳起來，於是驚醒。他將这个夢告訴了家里的每一个人。過了三天，祖父的眼睛果然重見光明。此後，祖父臥病在床，持續了兩周，張元一直侍候著祖父的飲食，而且衣不解帶，晝夜不離。等祖父病死，他哭得死去活來。接著又丧父，他三天水米未進，乡里的人们都為之贊叹稱奇。縣博士楊辄等二百多人上書皇帝，陳述張元的孝行，皇帝便下詔表彰。这些事例都是為人之孫能够贍養祖父的典范。","sortOrder":39},
  {"id":"s_work_gp_8_40","chapterId":"ch_work_gp_8","text":"【原文】唐仆射李公，有居第在長安修行里，其密鄰即故日南楊相也。丞相早歲與之有舊，及登庸，權傾天下。相君選妓數辈，以宰府不可外馆，棟宇無便事者，獨書閣東鄰乃李公冗舍也，意欲吞之。垂涎少俟，且遲遲於發言。忽一日，謹致一函，以為必遂。及复札，大失所望。又逾月，召李公之吏得言者，欲以厚价購之。或曰：水竹別墅交质。李公复不許。又逾月，乃授公之子弟官，冀其稍動初意，竟亡回命。有王處士者，知書善棋，加之敏辯，李公寅夕與之同處，丞相密召，以誠告之，托其諷諭。王生忭奉其旨，勇於展效。然以李公褊直，伺良便者久之。一日，公遘病，生獨侍前，公謂曰：“筋衰骨虛，風氣因得乘間而入，所謂空穴來風，枳枸來巢也。”生對曰：“然，向聆西院，枭集树杪，某心忧之，果致微恙。空院之來妖禽，猶枳枸來巢矣。且知赍器換缗，未如鬻之，以贍医藥。”李公卞急，揣知其意，怒發上植，厲聲曰：“男子寒死，餒死，鵩窥而死，亦其命也。先人之敝庐，不忍為權貴優笑之地。”揮手而別。自是，王生及門，不复接矣。","sortOrder":40},
  {"id":"s_work_gp_8_41","chapterId":"ch_work_gp_8","text":"【譯述】唐代仆射李公，有一所居住的宅第在長安修行里，紧挨著他们的鄰居就過去的南楊相。丞相先前與李公就有來往，等到他一朝成為宰相，權傾天下。丞相從各地挑選來了許多歌妓舞女，他認為宰相的府第不適合讓这些歌女居住，而且一時也找不到合適的房舍，惟獨東鄰李公家有多餘的房舍，他很想奪過來。丞相對李公的房子垂涎欲滴，現在只不過是在等待機會，而且遲遲没敢張嘴。一天，丞相很客氣地給李公寫了一封書信，而且自認為肯定一錘定音。等到李公回信後，令他大失所望。","sortOrder":41},
  {"id":"s_work_gp_8_42","chapterId":"ch_work_gp_8","text":"過了一个多月，丞相派人對李公說，丞相想出大价錢購買李公的房子。","sortOrder":42},
  {"id":"s_work_gp_8_43","chapterId":"ch_work_gp_8","text":"還說，用丞相的水竹別墅作為抵押也可以。李公再次拒絕。又過了一个多月，丞相提拔李公的子弟做官，希望李公能改变初衷。然而，竟没有回音。當地有一个王處士，知書善棋，而且能說會道，李公與他經常在一起。丞相悄悄將王處士叫去，把事情告訴他，讓他給想辦法成全此事。王處士很痛快地接受了請托，而且立刻去積極地張羅此事。然而，他知道李公这个人不好說話，他尋找機會已經很長時間了。有一天，李公病了，王處士獨自陪伴李公。李公對他說：“我筋衰骨虛，冷風寒氣於是能够乘虛而入。这就像是人们所說的，空穴容易來風，有枳枸就會有鳥來筑巢。”王處士答道：“對呀，先前我聽到你的西院里，有枭鳥齊集树梢的聲音，我當時就很為此忧心，不想你果真就病了。我分析，空著的院落容易招來这些怪鳥，就好象枳枸會招來鳥筑巢一樣。而且你現在拿家里的東西去換錢，倒不如將西院的房舍賣掉，用來為你治病。”不料，李公一下子急了眼，他揣摩王處士可能是為丞相做說客，因此大怒，以致頭發都竖了起來。他厲聲說：“男子漢即便是受冻受饿而死，那也聽天由命去吧！祖先留下的房舍，我怎么忍心讓它变成權貴的歌妓舞女調笑的地方呢？”於是他揮手與王處士作別。從此之後，王處士再來做客，他不去接待。","sortOrder":43},
  {"id":"s_work_gp_8_44","chapterId":"ch_work_gp_8","text":"【原文】平庐節度使楊損，初為殿中侍御史，家新昌里，與路巖第接。巖方為相，欲易其廄以廣第。損宗族仕者十餘人議曰：“家世盛衰，系權者喜怒，不可拒也。”損曰：“今尺寸土，皆先人舊物，非吾等所有，安可奉權臣邪！窮達，命也。”卒不與。巖不悅，使損按獄黔中。年餘還。彼室宅，尚以家世舊物，不忍弃失，况諸侯之於社稷，大夫之於宗廟乎？為人孫者，可不念哉！","sortOrder":44},
  {"id":"s_work_gp_8_45","chapterId":"ch_work_gp_8","text":"【譯述】平庐節度使楊損，起先擔任殿中侍御史時，家住在新昌里，與路巖的住宅相鄰。路巖當時刚擔任宰相，想買楊損家的馬圈來扩大庭院。楊損家族的十多个當官的子弟商議說：“家世的盛衰，都决定於當權者的喜怒好樂，我们不能拒絕这件事。”楊損說：“我们家的尺土寸地，都是祖先留給我们的遺產，併不是我们自己的，怎么能將它奉送給權臣呢？窮困與發達，那都是命。”最終還是没有把馬圈賣給路巖。路巖不高興，就派楊損到貴州去巡视監獄。一年之後楊損才得以回來。就連房屋住宅，他们都因為是祖傳的資產，不忍舍弃，更何况諸侯對於社稷、大夫對於宗廟呢？為人子孫後辈，能不念及祖宗吗？","sortOrder":45},
  {"id":"s_work_gp_8_46","chapterId":"ch_work_gp_8","text":"伯叔父舍子救侄，感人肺腑","sortOrder":46},
  {"id":"s_work_gp_8_47","chapterId":"ch_work_gp_8","text":"【原文】《禮》：“服，兄弟之子，猶子也。”蓋聖人緣情製禮，非引而進之也。","sortOrder":47},
  {"id":"s_work_gp_8_48","chapterId":"ch_work_gp_8","text":"【譯述】《禮記》說：“從血統上講，兄弟的子女，就像是自己的子女一樣。”","sortOrder":48},
  {"id":"s_work_gp_8_49","chapterId":"ch_work_gp_8","text":"大概聖人也是根據人情來製定禮的，併不是要強行規定什么。","sortOrder":49},
  {"id":"s_work_gp_8_50","chapterId":"ch_work_gp_8","text":"【原文】漢弟五倫性至公。或問倫曰：“公有私乎？”對曰：“吾兄子嘗病，一夜十往，退而安寢。吾子有病，雖不省视，而竟夕不眠。若是者，豈可謂無私乎？”伯魚賢者，豈肯厚其兄子不如其子哉？直以數往视之，故心安；終夕不视，故心不安耳。而伯魚更以此語人，益所以見其公也。","sortOrder":50},
  {"id":"s_work_gp_8_51","chapterId":"ch_work_gp_8","text":"【譯述】漢第五倫為人很公正。有人問他說：“你有私心吗？”他回答說：“我哥哥的孩子有一次生了病，我一晚上去看了十次，但回來後就能睡著覺；我的孩子有病，我雖然不怎么去看，但却因為擔心而整夜睡不著覺。像这樣，怎么能說是没有私心呢？”他是个有德行的人，怎么可能待他兄長的孩子不如自己的孩子呢？只是因為他一晚上好幾次去看望侄子，所以能心安；自己的兒子一夜不去看视，所以心有所不安。而他又將这些細節告訴別人，更能看出他為人、治家的公平。","sortOrder":51},
  {"id":"s_work_gp_8_52","chapterId":"ch_work_gp_8","text":"【原文】宗正劉平，更始時天下亂，平弟仲為賊所殺。其後賊复忽然而至，平扶侍其母奔走逃難。仲遺腹女始一歲，平抱仲女而弃其子。母欲還取，平不聽，曰：“力不能兩活，仲不可以絕類。”遂去而不顧。","sortOrder":52},
  {"id":"s_work_gp_8_53","chapterId":"ch_work_gp_8","text":"【譯述】宗正劉平，正趕上改朝換代時的天下大亂，劉平的弟弟仲為賊所殺。","sortOrder":53},
  {"id":"s_work_gp_8_54","chapterId":"ch_work_gp_8","text":"之後，賊人又忽然來到，劉平攙扶他的母親逃跑躲避。弟弟仲死時留下一个女孩，才一歲，劉平抱起弟弟的女孩逃難，而將自己的兒子丢弃在家。他的母親讓他返回去抱那孩子，劉平不聽，說：“我们没有能力將兩个都救活，但必須救弟弟的孩子，他不能没有後人。”說完逃跑而去，竟没有去救自己的孩子。","sortOrder":54},
  {"id":"s_work_gp_8_55","chapterId":"ch_work_gp_8","text":"【原文】侍中淳於恭兄崇卒，恭養孤幼，教誨學問，有不如法，辄反用杖自箠以感悟之。兒漸而改過。","sortOrder":55},
  {"id":"s_work_gp_8_56","chapterId":"ch_work_gp_8","text":"【譯述】東漢侍中淳於恭的哥哥淳於崇死後，淳於恭親自撫養哥哥留下的兒子，他教侄兒讀書學習，侄兒如果做错了事，淳於恭就用棍子打自己以感化侄兒。侄兒看了非常慚愧，併且改正自己的错誤。","sortOrder":56},
  {"id":"s_work_gp_8_57","chapterId":"ch_work_gp_8","text":"【原文】侍中薛包，弟子求分财異居，包不能止，乃中分其财。奴婢引其老者，曰：“與我共事久，若不能使也。”田庐取其荒頓者，曰：“吾少時所理，意所恋也。”器物取其朽败者，曰：“我素所服食，身口所安也。”弟子數破其產，辄复赈給。","sortOrder":57},
  {"id":"s_work_gp_8_58","chapterId":"ch_work_gp_8","text":"【譯述】侍中薛包，他弟弟的兒子提出要和他分清财產另過，他不能勸止，於是就與侄兒平分财產。分奴婢的時候，他總是領一些老的，併說：“这些老的和我共事很長時間了，你不會使用他们。”分田地房舍時，他總是要那些荒芜頹败的，又說：“这些地和房子都是我小時候耕种過的、住過的，我和它们有感情。”分其他東西的時候，他總是要那些朽败的，說：“这些都是我平素常用的，我已經用習慣了。”他的这个侄兒後來幾次鬧到破產，他每次都要再給他一些東西，來赈濟他。","sortOrder":58},
  {"id":"s_work_gp_8_59","chapterId":"ch_work_gp_8","text":"【原文】晉右仆射邓攸，永嘉末，石勒過泗水，攸以牛馬負妻子而逃。又遇賊，掠其牛馬。步走，擔其兒及其弟子綏。度不能兩个都救活，乃謂其妻曰：“吾弟早亡，唯有一息，理不可絕，止應自弃我兒耳。幸而得存，我後當有子。”妻泣而從之。乃弃其子而去，卒以無嗣。時人義而哀之，為之語曰：“天道無知，使邓伯道無兒。”弟子綏服攸丧三年。","sortOrder":59},
  {"id":"s_work_gp_8_60","chapterId":"ch_work_gp_8","text":"【譯述】西晉永嘉末年，天下大亂，石勒的部队經過泗水時，西晉右仆射邓攸用牛、馬載著妻子、兒子和侄子逃難，又遇見強盜，牛、馬被搶走。","sortOrder":60},
  {"id":"s_work_gp_8_61","chapterId":"ch_work_gp_8","text":"他们只好步走，邓攸挑著兒子和弟弟的孩子綏。後考慮到兒子和侄子實在不能兩个都救活，他就對妻子說：“我弟弟早死，只留下这一个兒子，按理不能讓弟弟絕了後，我们只能丢掉自己的兒子。如果能存活下來，我们以後還可以有孩子。”妻子哭泣著聽了他的話。於是邓攸就丢下親生兒子走了。邓攸最終没有能够再有兒子。當時的人感叹他的仁義，對他說：“天道無知，讓邓伯道没有兒子。”後來，他的侄子綏為伯父服丧三年。","sortOrder":61},
  {"id":"s_work_gp_8_62","chapterId":"ch_work_gp_8","text":"【原文】太尉郄鑒，少值永嘉亂，在乡里，甚窮餒。乡人以鑒名德，傳共飯之。時兄子邁、外甥周翼併小，常携之就食。乡人曰：“各自飢困，以君賢，欲共相濟耳！恐不能兼有所存。”鑒於是獨往，食訖，以飯著兩頰邊還，吐與二兒。後併得存，同過江。邁位至護軍，翼為剡縣令。鑒之薨也，翼追撫育之恩，解職而歸，席苫心丧三年。世有殺其孤規财利者，獨何心哉！","sortOrder":62},
  {"id":"s_work_gp_8_63","chapterId":"ch_work_gp_8","text":"【譯述】東晉太尉郄鑒，小的時候正好趕上了西晉的永嘉之亂，他家窮得一無所有，連飯都吃不开。本乡的人因為郄鑒是个有德行的人，所以輪流著供養他吃飯。这時，他哥的孩子邁與他的外甥周翼都非常小，他到別人家吃飯的時候，就常領著这兩个孩子。乡人對此很有意見，說：“大家都很窮困，只因為你是个賢德之人，所以大家想一起來帮助你！但是恐怕不能將你的兩个孩子也一起救活。”郄鑒於是就一个人去吃飯。但每次吃完飯，他又在嘴里含一些飯回家，吐出來給兩个孩子吃。用这种辦法竟然將兩个孩子都救活了，併和他一起過了長江。後來，侄兒官至護軍，外甥任剡縣縣令。郄鑒去世後，周翼不忘舅舅對他的撫育之恩，辭官回家，為舅舅誠心誠意服丧三年。世上有殺別人的遺孤而觊觎人家的錢财的，與上面这些事例相比，那是一种什么居心啊！","sortOrder":63},
  {"id":"s_work_gp_8_64","chapterId":"ch_work_gp_8","text":"侄叔父如父","sortOrder":64},
  {"id":"s_work_gp_8_65","chapterId":"ch_work_gp_8","text":"【原文】宋義興人許昭先，叔父肇之坐事系獄，七年不判。子侄二十許人，昭先家最貧薄，专獨申訴，無日在家。餉饋肇之，莫非珍新。資產既盡，賣宅以充之。肇之諸子倦怠，惟昭先無有懈息，如是七載。尚書沈演之嘉其操行，肇之事由此得釋。","sortOrder":65},
  {"id":"s_work_gp_8_66","chapterId":"ch_work_gp_8","text":"【譯述】南宋義興人許昭先的叔父許肇之因犯事被關進了監獄，在獄中關了七年仍未判决。肇之家子侄共二十多人，昭先家最為貧窮，但昭先獨自為叔父申訴，没有一天休息在家。他給叔父送的吃的東西，都是上等的好東西。家中資產耗費完，他就賣掉自己家的住宅來解决所需費用。肇之的幾个兒子都有些厭倦了，唯獨昭先没有懈怠，这樣一直持續了七年。尚書沈演之嘉奖他的操守品行，併帮他的忙，肇之的事情終於得到了解决。","sortOrder":66},
  {"id":"s_work_gp_8_67","chapterId":"ch_work_gp_8","text":"【原文】唐柳泌叙其父天平節度使仲郢行事雲，事季父太保如事元公，非甚疾，見太保未嘗不束帶。任大京兆鹽鐵使，通衢遇太保，必下馬端笏，候太保馬過方登車。每暮束帶迎太保馬首，候起居。太保屢以為言，終不以官達稍改。太保常言於公卿同雲：“元公之子，事某如事嚴父。”","sortOrder":67},
  {"id":"s_work_gp_8_68","chapterId":"ch_work_gp_8","text":"古之賢者，事諸父如父，禮也。","sortOrder":68},
  {"id":"s_work_gp_8_69","chapterId":"ch_work_gp_8","text":"【譯述】唐代柳泌叙述他的父親天平節度使柳仲郢的事跡時說：仲郢侍奉季父太保就像侍奉他的父親柳公綽一樣，只要不是特別匆忙，他見季父時總要整裝束帶。他擔任大京兆鹽鐵使時，在大街上碰見季父，必定要下馬端笏恭立，等到季父的車馬過去方才上車。他每天傍晚都要穿戴整齊迎接季父的馬車，問候侍奉季父的起居生活。季父多次讓他免去那些禮儀，但他從不因為自己位居高官就改变對季父的恭敬態度。季父經常在官員中間說：“元公的兒子侍奉我就像侍奉他父親一樣。”古代的賢德之人，侍奉他的伯叔父就像侍奉他的父親一樣，这是天禮人倫所應當有的表現。","sortOrder":69},
  {"id":"s_work_gp_9_1","chapterId":"ch_work_gp_9","text":"家范卷七兄/弟/姑姊妹/夫","sortOrder":1},
  {"id":"s_work_gp_9_2","chapterId":"ch_work_gp_9","text":"兄弟如同手足","sortOrder":2},
  {"id":"s_work_gp_9_3","chapterId":"ch_work_gp_9","text":"【原文】凡為人兄不友其弟者，必曰：弟不恭於我。自古為弟而不恭者孰若象？萬章問於孟子，曰：“父母使舜完廪，捐階，瞽瞍焚廪；使浚井，出，從而掩之。象曰：‘謨蓋都君鹹我績。牛羊父母，仓廪父母。幹戈朕、琴朕、弤朕、二嫂使治朕栖。’象往入舜宮，舜在床琴。象曰：‘鬱陶思君爾！’忸怩。舜曰：‘惟茲臣庶，汝其於予治。’不識舜不知象之將殺己與？”曰：“奚而不知也？象忧亦忧，象喜亦喜。”曰：“然則舜伪喜者與！”曰：“否！昔者有饋生魚於鄭子產。子產使校人畜之池。校人烹之，反命曰：‘始舍之，圉圉焉，少則洋洋焉，攸然而逝。’子產曰：‘得其所哉！得其所哉！’故君子可欺以其方，難罔以非其道。彼以愛兄之道來，故誠信而喜之，奚伪焉！”萬章問曰：“象日以殺舜為事，立為天子，則放之，何也？”孟子曰：“封之也。或曰放焉”。","sortOrder":3},
  {"id":"s_work_gp_9_4","chapterId":"ch_work_gp_9","text":"萬章曰：“舜流共工於幽州，放歡兜於崇山，殺三苗於三危，殛鯀於羽山，四罪而天下鹹服，誅不仁也。象至不仁，封之有庳。有庳之人奚罪焉？仁人固如是乎？在他人則誅之，在弟則封之。”曰：“仁人之於弟也，不藏怒焉，不宿怨焉，親愛之而已矣。親之欲其貴也，愛之欲其富也。封之有庳，富貴之也。身為天子，弟為匹夫，可謂親愛之乎？”“敢問，或曰放者何謂也？”曰：“象不得有為於其國，天子使吏治其國，而納其貢賦焉，故謂之放，豈得暴彼民哉！雖然，欲常常而見之，故源源而來。不及貢，以政接於有庳。”","sortOrder":4},
  {"id":"s_work_gp_9_5","chapterId":"ch_work_gp_9","text":"【譯述】大凡為人之兄長，不友愛他的弟弟的，必定要說：弟弟對我不恭敬。","sortOrder":5},
  {"id":"s_work_gp_9_6","chapterId":"ch_work_gp_9","text":"可從古到今，作為弟弟而對兄長不恭敬的，誰能比得上舜的弟弟象呢？","sortOrder":6},
  {"id":"s_work_gp_9_7","chapterId":"ch_work_gp_9","text":"萬章問孟子說：“舜的父母打發舜去修繕穀仓，等舜上了屋顶，他们便抽去梯子，他父親瞽瞍還放火焚燒那穀仓，幸而舜設法逃下來了。於是又打發舜去淘井，他不知道舜從旁邊的洞穴出來了，便用土填塞井眼。","sortOrder":7},
  {"id":"s_work_gp_9_8","chapterId":"ch_work_gp_9","text":"舜的兄弟象說：‘謀害舜都是我的功勞，牛羊分給父母，仓廪分給父母，幹戈歸我，琴歸我，弤弓歸我，兩位嫂嫂要她们替我鋪床又叠被。’象於是向舜的住房走去，舜却坐在床邊彈琴，象說：‘哎呀！我好想念您呀！’但神情之間是很不好意思的。舜說：‘我想念著这些臣下和百姓，你替我管理管理吧！’我不晓得舜不知象要殺他吗？”","sortOrder":8},
  {"id":"s_work_gp_9_9","chapterId":"ch_work_gp_9","text":"孟子答道：“為什么不知道呢？象忧愁，他也忧愁；象高興，他也高興。”","sortOrder":9},
  {"id":"s_work_gp_9_10","chapterId":"ch_work_gp_9","text":"萬章說：“那么，舜的高興是假裝的吗？”","sortOrder":10},
  {"id":"s_work_gp_9_11","chapterId":"ch_work_gp_9","text":"孟子說：“不！從前有一个人送條活魚給鄭國的子產，子產使主管池塘的人畜養起來，那人却煮著吃了，回報說：‘刚放在池塘里，它還要死不活的；一會兒，它搖摆著尾巴活動起來了，突然間遠遠地不知去向。’子產說：‘它得到了好地方呀！得到了好地方呀！’那人出來了，說道：‘誰說子產聰明，我已經把那條魚煮著吃了，他還說：‘得到了好地方呀，得到了好地方呀！’所以對於君子，可以用合乎人情的方法來欺骗他，不能用违反道理的诡诈欺罔他。象既然假裝著敬愛兄長的樣子來，舜因此真誠地相信而高興起來，為什么是假裝的呢？”","sortOrder":11},
  {"id":"s_work_gp_9_12","chapterId":"ch_work_gp_9","text":"萬章問道：“象每天把謀殺舜的事情作為他的工作，等舜做了天子，却仅仅流放他，这是什么道理呢？”","sortOrder":12},
  {"id":"s_work_gp_9_13","chapterId":"ch_work_gp_9","text":"孟子答道：‘其實是舜封象為諸侯，不過有人說是流放他罢了。”","sortOrder":13},
  {"id":"s_work_gp_9_14","chapterId":"ch_work_gp_9","text":"萬章說：“舜把共工流放到幽州，把歡兜發配到崇山，把三苗之君驅逐到三危，把鯀充軍到羽山，懲處了这四个大罪犯，天下便都歸服了，就是因為讨伐了不仁的人的緣故。象是最不仁的人，却以有庳之國來封他。有庳國的百姓又有什么罪過呢？對別人，就加以懲處；對弟弟，就封以國土，難道仁人的作法竟是这樣的吗？”","sortOrder":14},
  {"id":"s_work_gp_9_15","chapterId":"ch_work_gp_9","text":"孟子說：“仁人對於弟弟，有所忿怒，不藏於心中；有所怨恨，不留在胸內，只是親他愛他罢了。親他，便要使他貴；愛他，便要使他富。把有庳國土封給他，正是使他又富又貴；本人做了天子，弟弟却是一个老百姓，可以說是親愛吗？”","sortOrder":15},
  {"id":"s_work_gp_9_16","chapterId":"ch_work_gp_9","text":"萬章說：“我請問，為什么有人說是流放呢？”","sortOrder":16},
  {"id":"s_work_gp_9_17","chapterId":"ch_work_gp_9","text":"孟子說：“象不能在他國土上為所欲為，天子派遣了官吏來給他治理國家，繳納貢稅，所以有人說是流放。象難道能够暴虐地對待他的百姓吗？自然不能。縱是如此，舜還是想常常看到象，象也不斷地來和舜相見。古書上說：‘不必等到規定的朝貢的時候，平常也假借政治上的需要來相接待。’”","sortOrder":17},
  {"id":"s_work_gp_9_18","chapterId":"ch_work_gp_9","text":"【原文】漢丞相陳平，少時家貧，好讀書，有田三十畝，獨與兄伯居。伯常耕田，縱平使遊學。平為人長美色。人或謂陳平：“貧何食而肥若是？”其嫂嫉平之不视家產，曰：“亦食糠核耳。有叔如此，不如無有。”伯聞之，逐其婦而弃之。","sortOrder":18},
  {"id":"s_work_gp_9_19","chapterId":"ch_work_gp_9","text":"【譯述】西漢的丞相陳平，小時候家里貧窮，但他愛好讀書。家里有田地三十畝，他单獨與哥哥陳伯住在一起。哥哥經常一个人耕田，讓他出去遊學。陳平長得身高貌美。有人問他：“你家里很窮，可你為什么吃得这么胖？”他的嫂子恨他不事生產，白吃飯，就說：“也只能吃糠秕呗。","sortOrder":19},
  {"id":"s_work_gp_9_20","chapterId":"ch_work_gp_9","text":"有这樣的小叔子，還不如没有呢！”陳平的哥哥聽了妻子的話，就將妻子趕出了家門。","sortOrder":20},
  {"id":"s_work_gp_9_21","chapterId":"ch_work_gp_9","text":"【原文】御史大夫卜式，本以田畜為事，有少弟。弟壮，式脱身出，獨取畜羊百餘，田宅财物盡與弟。式入山牧，十餘年，羊致千餘頭，買田宅。","sortOrder":21},
  {"id":"s_work_gp_9_22","chapterId":"ch_work_gp_9","text":"而弟盡破其產，式辄复分與弟者數矣。","sortOrder":22},
  {"id":"s_work_gp_9_23","chapterId":"ch_work_gp_9","text":"【譯述】御史大夫卜式，一直靠种田、放牧為生。他有个小弟弟，弟弟長大後，卜式與弟弟分家另過，然而他只帶走一百多只羊，家里的田地、房屋等财產他都給了弟弟。卜式獨自進山放羊，十多年後，他的羊發展到千餘只，他又買了田地、房院。可是弟弟却將家產揮霍一空，卜式又好幾次分給弟弟田宅家產。","sortOrder":23},
  {"id":"s_work_gp_9_24","chapterId":"ch_work_gp_9","text":"【原文】隋吏部尚書牛弘弟弼，好酒，酗。嘗醉，射殺弘駕車牛。弘還宅，其妻迎謂曰：“叔射殺牛。”弘聞，無所怪問，直答曰：“作脯。”坐定，其妻又曰：“叔忽射殺牛，大是異事！”弘曰：“已知。”顏色自若，讀書不輟。","sortOrder":24},
  {"id":"s_work_gp_9_25","chapterId":"ch_work_gp_9","text":"【譯述】隋朝吏部尚書牛弘的弟弟牛弼喜歡喝酒，而且常撒酒瘋。有一次喝醉酒，將牛弘駕車的牛用箭射死了。牛弘回家後，妻子迎上前對他說：“小叔子射死了咱家的牛。”牛弘聽了，併没有责怪的話，只回答說：“拿去作幹牛肉。”牛弘坐定後，妻子又說：“小叔子平白無故射死了牛，这不能算是件平常的事吧！”牛弘說：“我知道了。”他面不改色，繼續讀他的書。","sortOrder":25},
  {"id":"s_work_gp_9_26","chapterId":"ch_work_gp_9","text":"【原文】唐朔方節度使李光進，弟河東節度使光顏先娶婦，母委以家事。及光進娶婦，母已亡。光顏妻籍家财，納管鑰於光進妻。光進妻不受，曰：“娣婦逮事先姑，且受先姑之命，不可改也。”因相持而泣，卒令光顏妻主之矣。","sortOrder":26},
  {"id":"s_work_gp_9_27","chapterId":"ch_work_gp_9","text":"【譯述】唐朔方節度使李光進，他的弟弟河東節度使李光顏先娶了媳婦，母親就讓光顏的妻子來管理家事。等到李光進娶媳婦的時候，母親已經去世了。光進結婚後，光顏的妻子就登記家里的财產，然後將家里的鑰匙交給嫂嫂。光進妻不接受，說：“你侍奉過婆婆，你就接受咱婆婆的委托吧，这不能改变。”說到这里，她们竟哭了起來。最後還是讓光顏的妻子來管理家務。","sortOrder":27},
  {"id":"s_work_gp_9_28","chapterId":"ch_work_gp_9","text":"【原文】平章事韓滉，有幼子，夫人柳氏所生也。弟湟戲於掌上，誤墜階而死。滉禁約夫人勿悲啼，恐傷叔郎意。為兄如此，豈妻妾他人所能間哉？","sortOrder":28},
  {"id":"s_work_gp_9_29","chapterId":"ch_work_gp_9","text":"【譯述】平章事韓滉有个小兒子，是夫人柳氏所生。弟弟韓滉讓他站在自己手掌上和他玩耍，不料小孩掉到台階上摔死了。韓滉叫夫人不要傷心啼哭，以免讓弟弟傷心。做哥哥的能这樣對待弟弟，妻妾等人怎么能離間他们兄弟之間的感情吗？","sortOrder":29},
  {"id":"s_work_gp_9_30","chapterId":"ch_work_gp_9","text":"弟兄弟不可相殘","sortOrder":30},
  {"id":"s_work_gp_9_31","chapterId":"ch_work_gp_9","text":"【原文】弟之事兄，主於敬愛。齊射聲校尉劉琎，兄夜隔壁呼琎。琎不答，方下床著衣，立，然後應。怪其久。琎曰：“向束帶來竟。”","sortOrder":31},
  {"id":"s_work_gp_9_32","chapterId":"ch_work_gp_9","text":"【譯述】弟弟對兄長，主要是能敬重他、愛他。齊射聲校尉劉琎，他哥哥劉夜里在隔壁喊，他先不答應，下床穿上衣服，端端正正地站好，然後才答應。哥哥怪他為什么那么久没答應，他說：“刚才我還没有整裝束帶。”","sortOrder":32},
  {"id":"s_work_gp_9_33","chapterId":"ch_work_gp_9","text":"【原文】梁安成康王秀，於武帝布衣崑弟，及為君臣，小心畏敬，過於疏賤者。帝益以此賢之。若此，可謂能敬矣。","sortOrder":33},
  {"id":"s_work_gp_9_34","chapterId":"ch_work_gp_9","text":"【譯述】梁安成康王秀跟武帝是平民兄弟，等到武帝即位後，他们成了君臣關系，秀對武帝小心侍候，常懷敬畏之心，他對武帝的敬畏超過了那些與武帝毫無瓜葛的人。武帝也更因此看重秀。像他们这樣，可以說是兄弟之間能互相敬重了。","sortOrder":34},
  {"id":"s_work_gp_9_35","chapterId":"ch_work_gp_9","text":"【原文】後漢議郎鄭均，兄為縣吏，頗受禮遺，均數諫止，不聽，即脱身為佣。歲餘，得錢帛歸，以與兄，曰：“物盡可复得。為吏坐贓，終身捐弃。”兄感其言，遂為廉絜。均好義篤實，養寡嫂孤兒，恩禮甚至。","sortOrder":35},
  {"id":"s_work_gp_9_36","chapterId":"ch_work_gp_9","text":"【譯述】東漢議郎鄭均，哥哥當縣吏，經常接受些禮品，鄭均多次勸諫哥哥不要这樣，哥哥不聽，於是他就去當佣人。過了一年多，他挣了些錢回來送給哥哥，併說：“錢没了可以再挣，但當官如果貪贓枉法，就會受到懲處，一辈子都完了。”哥哥聽了他的話非常感動，於是為官清正廉絜。鄭均為人忠厚老實，哥哥死後，他養活寡嫂和哥哥的孤兒，恩禮備至。","sortOrder":36},
  {"id":"s_work_gp_9_37","chapterId":"ch_work_gp_9","text":"【原文】晉鹹寧中疫潁川，庾袞二兄俱亡。次兄毗复危殆。癘氣方炽，父母諸弟皆出次於外，袞獨留不去。諸父兄強之，乃曰：“袞性不畏病。”","sortOrder":37},
  {"id":"s_work_gp_9_38","chapterId":"ch_work_gp_9","text":"遂親自扶持，晝夜不眠。其間复撫柩哀臨不輟。如此十有餘旬，疫势既歇，家人乃反。毗病得差，袞亦無恙。父老鹹曰：“異哉此子！守人所不能守，行人所不能行，歲寒然後知松柏之後凋，始知疫癘之不相染也。”","sortOrder":38},
  {"id":"s_work_gp_9_39","chapterId":"ch_work_gp_9","text":"【譯述】西晉鹹寧年間潁川發生瘟疫，庾袞的兩个哥哥都死了，還有个哥哥庾毗也生命垂危。此時瘟疫正是最厲害的時候，父母及幾个弟弟都居住在外，躲避瘟疫，庾袞獨自留在家里，不肯離去。家里的人強迫他走，他說：“我不怕染病。”他在家親自侍候哥哥庾毗，晝夜不眠。期間他還為已死的兩个哥哥守靈，從未停止過祭祀。这樣過了一百多天，瘟疫漸漸没有了，家人才返回來。这時庚毗的病也好了，庾袞也安然無恙。","sortOrder":39},
  {"id":"s_work_gp_9_40","chapterId":"ch_work_gp_9","text":"乡親们都說：“这人真是不同尋常，能够堅守他人不能堅守的岗位，能做他人所不能做的事情，天氣寒冷才知道松柏比其他树耐寒，而瘟疫也似乎不能傳染給好人。”","sortOrder":40},
  {"id":"s_work_gp_9_41","chapterId":"ch_work_gp_9","text":"【原文】右光祿大夫顏含，兄畿，鹹寧中得疾，就医自療，遂死於医家。家人迎丧，旐每繞树而不可解，引丧者顛仆，稱畿言曰：“我寿命未死，但服藥太多，傷我五臟耳，今當复活，慎無葬也。”其父祝之曰：“若爾有命复生，其非骨肉所願，今但欲還家，不爾葬也。”乃解。及還，其婦夢之曰：“吾當复生，可急开棺。”婦頗說之。其夕，母及家人又夢之，即欲开棺，而父不聽。含時尚少，乃慨然曰：“非常之事，古則有之。今靈異至此，开棺之痛，孰與不开相負？”父母從之，乃共發棺，有生验以手刮棺，指抓盡傷，氣息甚微，存亡不分矣。飲哺將獲，累月猶不能語。飲食所須，托之以夢。阖家營视，頓废生業，雖在母妻，不能無倦也。含乃絕弃人事，躬親侍養，足不出戶者，十有三年。石崇重含淳行，赠以甘旨，含謝而不受。或問其故，答曰：“病者綿昧，生理未全，既不能進噉，又未識人惠，若當谬留，豈施者之意也？”畿竟不起。含二親既終，兩兄既殁，次嫂樊氏因疾失明，含課励家人，盡心奉養。日自嘗省藥饌，察問息耗，必簪屦束帶，以至病愈。","sortOrder":41},
  {"id":"s_work_gp_9_42","chapterId":"ch_work_gp_9","text":"【譯述】右光祿大夫顏含的哥哥顏畿，在鹹寧年間得了病，就医治療的時候，死在了医生的家里。家人去將他斂入棺材中，要運回去安葬。在起靈柩的時候，引魂幡纏繞在树上，怎么也解不开。在前邊引路的人突然跌倒在地上，自稱他是顏畿，說：“我的寿數還没有到，我没有死，只是因為吃藥太多，傷了五臟而导致昏厥，現在我要活過來了，你们千萬不要將我埋葬了。”他的父親祷告說：“如果你真的能活轉過來，也是我们的共同願望，現在咱们只是要回家，併不是要去安葬你。”說罢，引魂幡果然很痛快就解开了。回到家，顏畿的媳婦晚上夢見顏畿對她說：“我就要复活了，你们馬上打开棺材。”顏畿的媳婦醒來後非常高興。这天晚上，顏畿的母親和家里的其他人有夢見了同樣內容的夢，大家想馬上就开棺看看，可是父親不允許。顏含这時還很小，他大聲說：“怪異之事古代就有，現在如此異常，相比之下，开棺還是比不开要好。”父母親聽從了他的意見，於是大家一起將棺材打开，果然看見有手指抓棺材的印痕，而且顏畿的手指都抓傷了。大家一看，顏畿還有微弱的呼吸，但和死人没有什么兩樣。家里人將他抬回家，飲食侍候，但是他好幾个月還不能說話。他如果想吃什么或需要什么，就給家人托夢。全家人都在為他忙碌，因此而荒废了家里的生產和其他事業。時間長了，即使是母親和妻子也不能不感到倦殆，唯弟弟顏含放下所有的事情，親自侍奉哥哥，十三年足不出戶。當時的顯赫人物石崇很钦佩顏含的所做所為，便特地赠送他们美味佳肴。但是顏含只感謝人家的好意，却不接受食物。有人問他為什么不接受饋赠，他回答說：“現在病人臥床不起，不醒人事，而且生理機能也没有恢复，他既不能吃这些東西，又不能親領人家的好意，如果我隨便留下，那哪里是饋赠者的意思呢？”顏畿最終也没有能够恢复健康。後來，顏含的父母親双双去世，兩个哥哥也都死了，二嫂樊氏因病失明，顏含就帶領家里的人盡心奉養，他每天親自去察看嫂子吃的藥和飯，以及嫂子的身體状况，而且一定要穿戴整齊，保持禮節。一直到嫂子的病痊愈。","sortOrder":42},
  {"id":"s_work_gp_9_43","chapterId":"ch_work_gp_9","text":"【原文】後魏正平太守陆凯兄琇，坐鹹陽王禧謀反事，被收，卒於獄。凯痛兄之死，哭無時節，目幾失明，訴冤不已，備盡人事。至正始初，世宗复琇官爵。凯大喜，置酒集諸親曰：“吾所以數年之中抱病忍死者，顧門戶計爾。逝者不追，今願畢矣。”遂以其年卒。","sortOrder":43},
  {"id":"s_work_gp_9_44","chapterId":"ch_work_gp_9","text":"【譯述】後魏正平太守陆凯的哥哥陆琇，受鹹陽王禧謀反一事的牵連，被關進了監獄，併死在監獄。陆凯對哥哥的死非常痛惜，經常哭泣，眼睛也幾乎要失明。他反复為哥哥申訴冤屈，盡到了一个弟弟的责任。到正始初年，世宗恢复了陆琇的爵位，陆凯非常高興，製備酒食招待親戚们，他說：“这幾年，我之所以堅持活下來，就是為了要恢复我们陆家的榮譽，現在我的願望實現了。”他在这一年果真死去了。","sortOrder":44},
  {"id":"s_work_gp_9_45","chapterId":"ch_work_gp_9","text":"【原文】唐英公李勣，貴為仆射，其姊病，必親為燃火煮粥，火焚其須鬢。","sortOrder":45},
  {"id":"s_work_gp_9_46","chapterId":"ch_work_gp_9","text":"姊曰：“仆射妾多矣，何為自苦如是？”曰：“豈為無人耶？顧今姊年老，勣亦老，雖欲久為姊煮粥，复可得乎？”若此，可謂能愛矣！","sortOrder":46},
  {"id":"s_work_gp_9_47","chapterId":"ch_work_gp_9","text":"【譯述】唐英公李勣，身為仆射，他的姐姐病了，他還親自為她燒火煮粥，以致火苗燒了他的胡須和頭發。姐姐勸他說：“你的妾那么多，你自己為何要这樣辛苦？”李勣回答說：“難道真的没有人吗？我是想姐姐現在年紀大了，我自己也老了，即使想長久地為姐姐燒火煮粥，又怎么可能呢？”像这樣的弟弟，就可以說是能够敬愛姐姐了。","sortOrder":47},
  {"id":"s_work_gp_9_48","chapterId":"ch_work_gp_9","text":"【原文】夫兄弟至親，一體而分，同氣異息。《詩》雲：“凡今之人，莫如兄弟。”又雲：“兄弟阋於牆，外御其侮。”言兄弟同休戚，不可與他人議之也。若己之兄弟且不能愛，何况他人？己不愛人，人誰愛己？人皆莫之愛，而患難不至者，未之有也。《詩》雲“毋獨斯畏”，此之謂也。兄弟，手足也。今有人斷其左足，以益右手，庸何利乎？虺一身兩口，爭食相龁，遂相殺也。爭利而害，何異於虺乎？","sortOrder":48},
  {"id":"s_work_gp_9_49","chapterId":"ch_work_gp_9","text":"【譯述】兄弟之間可以說是至親至愛的，就好象同出一體，同氣異息。《詩經》說：“現在的人，都不如兄弟那樣親密。”又說：“兄弟在家里雖然有矛盾，但在外邊却能共同抵御敵人。”这說的是兄弟能够同歡樂、共患難，不能和他人相提併論。如果連自己的兄弟都不能去愛，又怎么能去愛他人呢？自己不愛他人，他人又怎么會愛你呢？人人都不喜愛你，你想没有禍患和灾難是不可能的。《詩經》說“怕的就是只有你一个人”，指的就是这个意思。兄弟如同手足。如果有人砍斷他的左腳，來延長他的右手，这有什么好處呢？虺有一个身子兩張嘴，爭食相咬，於是自相殘殺。如果兄弟之間為了各自的利益互相殘害，这跟虺有什么差別呢？","sortOrder":49},
  {"id":"s_work_gp_9_50","chapterId":"ch_work_gp_9","text":"【原文】《顏氏家訓》論兄弟曰：“方其幼也，父母左提右挈，前襟後裾，食則同案，衣則傳服，學則連業，遊則共方，雖有悖亂之人，不能不相愛也。及其壮也，各妻其妻，各子其子，雖有篤厚之人，不能不少衰也。娣姒之比兄弟，則疏薄矣。今使疏薄之人而節量親厚之恩，猶方底而圓蓋，必不合也。唯友悌深至，不為旁人之所移者，可免夫。兄弟之际，異於他人，望深雖易怨，比他親則易弭。譬猶居室，一穴則塞之，一隙則涂之，無頹毀之慮。如雀鼠之不恤，風雨之不防，壁陷楹淪，無可救矣。仆妾之為雀鼠，妻子之為風雨，甚哉！兄弟不睦，則子侄不愛。子侄不愛，則群從疏薄。群從疏薄，則童仆為仇敵矣。如此，則行路皆踖其面而蹈其心，誰救之哉？人或交天下之士，皆有歡愛，而失敬於兄者，何其能多而不能少也？人或將數萬之師，得其死力，而失恩於弟者，何其能疏而不能親也？娣姒者，多爭之地也。所以然者，以其當公務而就私情，處重责而懷薄義也。若能恕己而行，換子而撫，則此患不生矣。","sortOrder":50},
  {"id":"s_work_gp_9_51","chapterId":"ch_work_gp_9","text":"人之事兄不同於事父，何怨愛弟不如愛子乎？是反照而不明矣。","sortOrder":51},
  {"id":"s_work_gp_9_52","chapterId":"ch_work_gp_9","text":"【譯述】《顏氏家訓》在論述兄弟關系的時候說：“當他们年紀還小的時候，總是一起在父母的前後左右，吃飯在同一張桌子上，衣服也是同一件衣服，哥哥穿了再給弟弟穿。讀書也是这樣，哥哥讀過的書再給弟弟讀，玩也是一起玩。这樣一來，雖然是不懂禮法的人，但對兄弟也是不能不愛的。等到成人之後，兄弟们各有了自己的家庭、子女，这時雖是誠實忠厚的人，兄弟之間的情愛也總是要稍為减退一些的。妯娌之間的關系，是比不上兄弟關系那樣親密的。如果使各自關系较疏薄的妯娌來製約兄弟之間的親情，这正好比方的容器配个圓的蓋子，必然不能嚴密無間了。只有兄弟親情特別深厚、不受妻子影响的人家，才能免去这种情形。兄弟之間的關系不同於常人，相互之間求全责備就容易產生怨恨，但因手足情親所以这种怨恨也容易消弭。拿住的房子來作比喻，發現一个洞穴一條裂縫就堵住它，这房子就没有倒塌的危险，如果鳥雀、老鼠、風雨的破坏都不去防治，那么牆壁門窗的毀坏倒塌就是不可避免的了，一个家庭里的仆人妻妾對於兄弟情感的破坏作用，是可以和最歷害的雀鼠風雨相比的。兄弟之間不和睦，將导致各家的子女不相愛，而这种情形又會导致同族別的小辈都互相疏遠淡薄，导致各家的僮仆互相敵视。这樣，陌生人都會來欺負他们，還有誰來救助呢？有的人結交天下之士都很融洽，而對自己的哥哥反而不去敬重；有的人可以統帥幾萬士兵，得到他们的擁戴，可是對自己的弟弟反而缺少恩愛，这种人為什么这樣的不會處理兄弟關系呢？妯娌關系，是一种容易起矛盾起爭斗的關系。之所以會造成这种情形，是因為她们相處時各懷私心，擔當重任而心懷薄義。","sortOrder":52},
  {"id":"s_work_gp_9_53","chapterId":"ch_work_gp_9","text":"如果能够實行己所不欲勿施於人的原則，把妯娌的兒子當自己的兒子來疼愛，那么这种矛盾磨擦就不會出現了。一个人尊敬兄長，不同於尊敬父親，那又怎能怨恨哥哥對自己的愛及不上對兒子的愛呢？这樣埋怨就是只苛责別人而不要求自己。","sortOrder":53},
  {"id":"s_work_gp_9_54","chapterId":"ch_work_gp_9","text":"【原文】吳太伯及弟仲雍，皆周太王之子，而王季歷之兄也。季歷賢，而有聖子昌，太王欲立季歷以及昌。於是太伯、仲雍二人乃奔荆蠻，文身斷發，示不可用，以避季歷。季歷果立，是為王季，而昌為文王。太伯之奔荆蠻，自號句吳。荆蠻義之，從而歸之千餘家，立為吳太伯。子曰：“太伯，其可謂至德也已矣，三以天下讓，民無得而稱焉。”","sortOrder":54},
  {"id":"s_work_gp_9_55","chapterId":"ch_work_gp_9","text":"【譯述】吳太伯和弟弟仲雍，都是周太王的兒子，王季歷的哥哥。季歷很賢能，而且有聖子姬昌，周太王想立季歷與姬昌為王。因此太伯和仲雍兄弟俩就奔赴荆蠻，文身截發，表示他们不能够再為王了，用这樣的方法來躲避弟弟季歷。季歷果然被立為王，稱為王季，而姬昌就是周文王。","sortOrder":55},
  {"id":"s_work_gp_9_56","chapterId":"ch_work_gp_9","text":"太伯到了荆蠻之後，自稱句吳。荆蠻百姓認為他很講仁義道德，於是紛紛歸附他，跟隨他的人有一千多家，立他為吳太伯。孔子說：“太伯，可以說是很有道德，多次讓位給季歷，百姓無不稱贊他的美德。”","sortOrder":56},
  {"id":"s_work_gp_9_57","chapterId":"ch_work_gp_9","text":"【原文】伯夷、叔齊，孤竹君之二子也。父欲立叔齊。及父卒，叔齊讓伯夷。","sortOrder":57},
  {"id":"s_work_gp_9_58","chapterId":"ch_work_gp_9","text":"伯夷曰：“父命也。”遂逃去。叔齊亦不肯立而逃之。國人立其中子。","sortOrder":58},
  {"id":"s_work_gp_9_59","chapterId":"ch_work_gp_9","text":"【譯述】伯夷、叔齊，是商代孤竹君的兩个兒子。父親孤竹君打算立叔齊來繼承王位。等到父親死後，叔齊主動讓位給伯夷，伯夷說：“立你為繼承人是父親的命令，怎么能隨便更改呢？”於是他逃亡而去。叔齊也不願當繼承人，逃跑了。於是國人就擁立孤竹君的第二个兒子為王。","sortOrder":59},
  {"id":"s_work_gp_9_60","chapterId":"ch_work_gp_9","text":"【原文】宋宣公舍其子與夷而立穆公。穆公疾，复舍其子冯而立與夷。君子曰：“宣公可謂知人矣！主穆公，其子饗之，命以義夫！”","sortOrder":60},
  {"id":"s_work_gp_9_61","chapterId":"ch_work_gp_9","text":"【譯述】宋宣公没有立他的兒子為繼承人，而是立了穆公。穆公在有病的時候，也没有立自己的兒子冯，而是立與夷為繼承者。君子評論这件事時說：“宣公可以稱得上是知人了！他雖然立了穆公，但在宗廟里祭祀他的仍然是他的兒子與夷，併且將他尊稱為義夫！”","sortOrder":61},
  {"id":"s_work_gp_9_62","chapterId":"ch_work_gp_9","text":"【原文】吳王寿夢卒，有子四人，長曰諸樊，次曰餘祭，次曰夷昧，次曰季札。季札賢，而寿夢欲立之。季札讓，不可，於是乃立長子諸樊。諸樊卒，有命授弟餘祭，欲傳以次，必致國於季札而止。季札終逃去，不受。【譯述】吳王寿夢有四个兒子，長子叫諸樊，次子叫餘祭，老三叫夷昧，老四叫季札。其中季札最有才德，吳王臨死時想立季禮為王。可是季札謙讓而不接受，於是就立了長子諸樊。諸樊死的時候留下遺嘱，要將王位傳給二弟餘祭，而且今後也傳弟不傳子，一定要把國家交到四弟季札手里，才能終止。可季札最終還是逃走了，不接受王位。","sortOrder":62},
  {"id":"s_work_gp_9_63","chapterId":"ch_work_gp_9","text":"【原文】漢扶陽侯韦腎病篤，長子太常丞弘坐宗廟事系獄，罪未决。室家問賢當為後者。賢恚恨，不肯言。於是賢門下生博士義倩等與室家計，共矯賢令，使家丞上書言大行，以大河都尉玄成為後。賢薨，玄成在官聞丧，又言當為嗣，玄成深知其非賢雅意，即陽為病狂，臥便利中，笑語昏亂。征至長安，既葬，當袭爵，以病狂不應召。大洪臚奏状，章下丞相御史案验，遂以玄成實不病劾奏之。有詔勿劾，引拜，玄成不得已受爵。宣帝高其節，時上欲淮陽憲王為嗣，然因太子起於細微，又早失母，故不忍也。久之，上欲感風憲王，辅以禮讓之臣，乃召拜玄成為淮陽中尉。","sortOrder":63},
  {"id":"s_work_gp_9_64","chapterId":"ch_work_gp_9","text":"【譯述】漢扶陽侯韦賢病重，他的長子太常丞弘因宗廟事被捕入獄，還没有判决。家里的人詢問韦賢在他身後誰可以做繼承人。韦賢感到很氣憤，不肯回答。於是韦賢的弟子博士義倩等人和他家里的人計議，他们假裝是韦賢的命令，讓家丞給皇上上書，要求立大河都尉玄成為繼承人。韦賢死後，在外邊做官的玄成聽到了噩耗，又聽說讓他做扶陽侯的繼承人。但玄成深知这不是韦賢本人的意思，於是就假裝得了瘋病，整天躺臥在垃圾之中，胡亂說笑。韦賢家的人將他接到長安，在安葬好韦賢之後，就讓他正式承袭爵位。他仍舊假裝瘋狂，不理他们。大洪臚將这些情况報告皇上，皇上便派丞相御史下去查验。經查，玄成屬於裝病，於是就向皇上彈劾他裝病。皇上下詔不去追究他的罪责，只是讓他趕紧承袭爵位。宣帝很佩服他高尚的節操，这時宣帝正想改立淮陽憲王為太子，但因為現在的太子出身低賤，又早早地没了母親，所以不忍心废他。過了一段時間，宣帝想要教化憲王，讓那些懂得禮義謙讓的大臣來辅助訓导他，於是就將玄成拜為淮陽中尉。","sortOrder":64},
  {"id":"s_work_gp_9_65","chapterId":"ch_work_gp_9","text":"【原文】陵陽侯丁綝卒，子鸿當袭封，上書讓國於弟成，不報。既葬，掛衰绖於冢庐而逃去。鸿與九江人鮑駿相友善，及鸿亡封，與駿遇於東海，陽狂不識駿。駿乃止而讓之曰：“春秋之義，不以家事废王事；今子以兄弟私恩而絕父不滅之基，可謂智乎？”鸿感語垂涕，乃還就國。","sortOrder":65},
  {"id":"s_work_gp_9_66","chapterId":"ch_work_gp_9","text":"【譯文】陵陽侯丁綝去世，他的兒子鸿應當承袭爵位。鸿給皇上上書要求將爵位讓於弟弟成，但皇上没有批复。安葬了父親，鸿將孝服掛在墳墓上逃走了。鸿先前和九江人鮑駿關系非常好，等到鸿不接受封位而出逃的時候，恰好與鮑駿在東海相遇。但鸿假裝不認識鮑駿。鮑駿拦住鸿對他說：“春秋時代所謂的義，不能以家事荒废國事，現在你们因為兄弟之間相互謙讓而葬送父親傳下來的基業，这能算得上是聰明吗？”鸿為鮑駿的話所感動，以致於涕泗交流。最終，他回去接受了爵位。","sortOrder":66},
  {"id":"s_work_gp_9_67","chapterId":"ch_work_gp_9","text":"【原文】居巢侯劉般卒，子恺當袭爵，讓於弟憲，遁逃避封。久之，章和中，有司奏請絕恺國。肅宗美其義，特優假之，恺猶不出。積十餘歲，至永元十年，有司复奏之。侍中贾逵上書稱：“恺有伯夷之節，宜蒙矜宥，全其先公，以增聖朝尚德之美。”和帝納之，下詔曰：“王法崇善，成人之美，其聽憲嗣爵。遭事之宜，後不得以為比。”乃征恺，拜為郎。","sortOrder":67},
  {"id":"s_work_gp_9_68","chapterId":"ch_work_gp_9","text":"【譯述】居巢侯劉般去世，他的兒子劉恺應當承袭爵位。但他要求將爵位讓給弟弟劉憲，自己為此而出逃。過了很長時間，到章和年間，有關部門將这件事奏聞皇上，請求收回劉恺的封國。肅宗很欣賞他们的禮讓之義，再請劉恺就位，可劉恺還不出來。等了十多年，到了永元十年，有關部門又一次向皇上奏請此事。侍中贾逵上書說：“劉恺有伯夷的節操，皇上應該保護和宽宥他，以保全他先人的基業，这也可以彰顯陛下的聖德。”和帝聽從了贾逵的意見，下詔說：“國家的法律是懲惡扬善，成人之美的。現准許劉憲承袭爵位。仅此一回，下不為例。”而且召劉恺到朝廷，拜為郎。","sortOrder":68},
  {"id":"s_work_gp_9_69","chapterId":"ch_work_gp_9","text":"【原文】後魏高涼王孤，平文皇帝之第四子也，多才藝，有志略。烈帝元年，國有內難，昭成為质於後趙。烈帝臨崩，顧命迎立昭成。及崩，群臣鹹以新有大故，昭成來，未可果，宜立長君。次弟屈，刚猛多变，不如孤之宽和柔順。於是大人梁蓋等殺屈，共推孤為嗣。孤不肯，乃自詣鄴奉迎，請身留為质。石季龍義而從之。昭成即王位，乃分國半部以與之。","sortOrder":69},
  {"id":"s_work_gp_9_70","chapterId":"ch_work_gp_9","text":"然兄弟之际，宜相與盡誠，若徒事形跡，則外雖友愛而內實乖離矣。","sortOrder":70},
  {"id":"s_work_gp_9_71","chapterId":"ch_work_gp_9","text":"【譯述】後魏高涼王孤，是平文皇帝的第四个兒子，他多才多藝，很有志氣謀略。烈帝元年，國家發生內亂，昭成到後趙作人质。烈帝臨死的時候，遺詔迎立昭成為帝。烈帝死後，群臣都認為皇帝刚刚駕崩，迎立昭成不一定能成功，應該擁立新君。昭成的弟弟屈，刚猛多变，不像孤宽和柔順。於是大人梁蓋等殺死屈，一起擁立孤為帝。孤不同意即位，親自到鄴地去迎接哥哥昭成回來即皇帝位，他願意留作人质。石季龍深感他的大義，就答應了他的要求。昭成即皇帝位後，就分給孤一半江山。兄弟之間，就應該坦誠相待，如果光是講究些虛伪的禮儀，就會外表看上去团結友愛，實质上却是相互背離。","sortOrder":71},
  {"id":"s_work_gp_9_72","chapterId":"ch_work_gp_9","text":"【原文】宋祠部尚書蔡廓，奉兄軌如父，家事大小皆咨而後行。公祿賞賜，一皆入軌。有所資須，悉就典者請焉。從武帝在彭城，妻郄氏書求夏服。時軌為給事中，廓答書曰：“知須夏服，計給事自應相供，無容別寄。”向使廓從妻言，乃乖離之漸也。","sortOrder":72},
  {"id":"s_work_gp_9_73","chapterId":"ch_work_gp_9","text":"【譯述】宋祠部尚書蔡廓，侍奉哥哥蔡軌如同侍奉父親一樣，家里的大事小事他都要先請示兄長，然後再做。他做官的俸祿和上邊給的賞賜，都要交給哥哥。他如果需要錢物，都要到管家那里領取。有一次，他隨從武帝到了彭城，妻子郄氏給他寫信，要求換夏天的衣服。这時蔡軌為給事中，蔡廓給妻子回信說：“我已經知道你需要夏天的衣服，但我估計哥哥自有安排，你用不著再說了。”假設蔡廓聽了妻子的話，出面向哥哥索要衣服，那么他们之間就要因相互不信任而漸漸產生矛盾。","sortOrder":73},
  {"id":"s_work_gp_9_74","chapterId":"ch_work_gp_9","text":"【原文】梁安成康王秀與弟始興王憺友愛尤篤，憺久為荆州刺史，常以所得中分秀。秀稱心受之，不辭多也。若此，可謂能盡誠矣！","sortOrder":74},
  {"id":"s_work_gp_9_75","chapterId":"ch_work_gp_9","text":"【譯述】梁朝安成康王秀與弟弟始興王憺非常友愛，憺長時間擔任荆州刺史，經常把他的俸祿所得分給哥哥，秀欣然接受，也不怎么推辭。兄弟之間如果能像这樣，可謂是能够以誠相待了。","sortOrder":75},
  {"id":"s_work_gp_9_76","chapterId":"ch_work_gp_9","text":"【原文】衛宣公惡其長子急子，使諸齊，使盜待諸莘，將殺之。弟寿子告之使行，不可，曰：“弃父之命，惡用子矣！有無父之國則可也。”及行，飲以酒，寿子載其旌以先，盜殺之。急子至，曰：“我之求也，此何罪，請殺我乎！”又殺之。","sortOrder":76},
  {"id":"s_work_gp_9_77","chapterId":"ch_work_gp_9","text":"【譯述】衛宣公不喜歡他的長子急子，就讓他出使齊國，然後指使強人在莘这个地方等待他，將要殺掉他。急子的弟弟寿子將这个秘密告訴了哥哥，併讓哥哥趕快逃走。但急子認為这樣做不對，他說：“不聽從父親的命令，那還算什么兒子！如果是在一个不尊重父親的國家，那就可以这樣做。”等到急子出發的時候，弟弟寿子請他喝酒，將他灌醉，然後寿子自己打著急子的旌旗走在前邊，藏在这里的強人誤將寿子殺死。急子來到这里，說：“这是我的所求，他有什么罪？請殺我吧！”这些人又將急子殺了。","sortOrder":77},
  {"id":"s_work_gp_9_78","chapterId":"ch_work_gp_9","text":"【原文】王莽末，天下亂，人相食。沛國趙孝弟禮，為饿賊所得，孝聞之，即自縛詣賊曰：“禮久饿贏瘦，不如孝肥。”饿賊大驚，併放之，謂曰“且可歸，更持米來。”孝求不能得，复往報賊，願就烹。眾異之，遂不害。乡党服其義。","sortOrder":78},
  {"id":"s_work_gp_9_79","chapterId":"ch_work_gp_9","text":"【譯述】西漢王莽末年，天下大亂，幾乎到了人吃人的地步。沛國趙孝的弟弟趙禮，被一群饿賊抓住了，这伙人正准備將趙禮煮了吃，趙孝聽說了，就自己把自己綁起來去見那些賊寇，說：“我弟弟有很長時間吃不飽飯，瘦得很，不如我肥。”这伙饿賊聽了大驚，一去將他们兄弟俩放了，併對他们說：“你们先回去吧，但要拿些吃的來。”趙孝回去後想辦法找糧食，但無法找到，他就又去告訴那些賊：我找不到糧食，你们就煮了吃我吧。眾賊寇很是為他的行動感到驚異，於是不加害於他。乡里的人们都佩服他講義氣，守信用。","sortOrder":79},
  {"id":"s_work_gp_9_80","chapterId":"ch_work_gp_9","text":"【原文】北漢淳於恭兄崇將為盜所烹，恭請代，得俱免。又，齊國倪萌、梁郡車成二人，兄弟併見執於赤眉，將食之。萌、成叩頭，乞以身代，賊亦哀而兩釋焉。","sortOrder":80},
  {"id":"s_work_gp_9_81","chapterId":"ch_work_gp_9","text":"【譯述】北漢時候淳於恭的哥哥淳於崇被盜賊抓住，盜賊要煮他，淳於恭請求代替弟弟去死，那些盜賊便都饒了他们。還有，齊國的倪萌、梁郡的車成，他们俩都曾經是兄弟俩一起被赤眉軍抓住，而且要將他们煮了吃。倪萌和車成分別向賊人乞求以身自代，那些賊人也都為他们所感動，哀怜他们而把他们放掉了。","sortOrder":81},
  {"id":"s_work_gp_9_82","chapterId":"ch_work_gp_9","text":"【原文】宋大明五年，發三五丁，彭城孫棘弟薩應充行，坐违期不至。棘詣郡辭列：“棘為家長，令弟不行，罪應百死，也以身代薩。”薩又辭列自引。太守張岱疑其不實，以棘、薩各置一處，報雲：“聽其相代，顏色併悅，甘心赴死。”棘妻許又寄語屬棘：“君當門戶，豈可委罪小郎？且大家臨亡，以小郎屬君，竟未妻娶，家道不立，君已有二兒，死复何恨？”岱依事表上。孝武詔，特原罪，州加辟命，併賜帛二十匹。","sortOrder":82},
  {"id":"s_work_gp_9_83","chapterId":"ch_work_gp_9","text":"【譯述】宋大明五年，朝廷征發兵役，彭城孫棘的弟弟孫薩應當服兵役，但他犯了過期不去的罪。孫棘到郡守那里領罪說：“我是一家之長，却没有讓弟弟及時出發，罪該萬死，我請求代替弟弟服罪。”孫薩也自己去認罪，說这事與哥哥無關。太守張岱懷疑他们是事先串通好的，便將孫棘和孫岱分別關押，试探虛實。手下回來報告說：“他们兄弟俩聽說能够代替對方去死後，都非常高興，甘心去死。”这時，孫棘的妻子又捎話來嘱咐丈夫：“你是一家之主，责任怎么能往弟弟的身上推呢？况且父母臨死的時候，將弟弟托付給你。他還没有娶妻，没有成家立業，而你已經有兩个兒子了，死又有什么遺憾的呢？”太守將这件事表奏皇上，孝武皇帝下詔，特赦其罪，讓州府任命他们官職，併賜給帛二十匹。","sortOrder":83},
  {"id":"s_work_gp_9_84","chapterId":"ch_work_gp_9","text":"【原文】梁江陵王玄紹、孝英、子敏，兄弟三人，特相友愛，所得甘旨新異，非共聚食，必不先嘗。孜孜色貌，相見如不足者，及西台陷没，玄紹以須面魁梧，為兵所围，二弟共抱，各求代死，解不可得，遂併命雲。賢者之於兄弟，或以天下國邑讓之，或爭相為死；而愚者爭锱銖之利，一朝之忿，或斗訟不已，或幹戈相攻，至於破國滅家，為他人所有，乌在其能利也哉？正由智識褊淺，見近小而遺遠大故耳，豈不哀哉！《詩》雲：“彼令兄弟，綽綽有裕。不令兄弟，交相為癒。”其是之謂欤。子產曰：“直鈞，幼賤有罪。”然則兄弟而及於爭，雖俱有罪，弟為甚矣！世之兄弟不睦者，多由異母或前後嫡庶更相憎嫉，母既殊情，子亦異党。","sortOrder":84},
  {"id":"s_work_gp_9_85","chapterId":"ch_work_gp_9","text":"【譯述】梁江陵王玄紹、孝英、子敏，兄弟三人感情特別好，他们如果有好吃的東西，就一起來吃，决不會一个人獨自吃。他们三个人親密無間，經常在一起。後來戰亂爆發，西台失陷，因為玄紹身材魁梧，所以被敵兵所包围。他的兩个弟弟一起抱住他，都請求代他去死。敵兵不能將他们分开，於是一起放了他们。","sortOrder":85},
  {"id":"s_work_gp_9_86","chapterId":"ch_work_gp_9","text":"賢能的兄弟之間，或者以天下國家互相推讓，或者爭相代死；可是那些愚蠢的兄弟，却往往爭奪锱銖小利，因為一時的忿恨，或者爭吵不休，或者大動幹戈，以至家滅國破，為他人占有，这樣做好處何在？那正是因為他们智識短淺，貪圖小利，而导致因小失大，这難道不是很悲哀吗？《詩經》說：“兄弟之間和睦，家產就會綽綽有餘；兄弟之間不和，就會貧病交加。”說的就是这种情况。子產說：“直鈞，幼賤有罪。”如此說來，兄弟之間相互爭斗，雖然都有過，但是弟弟的责任大。世上兄弟之間不和睦的，大多是因為異母或前後嫡、庶母互相憎恨、嫉妒。","sortOrder":86},
  {"id":"s_work_gp_9_87","chapterId":"ch_work_gp_9","text":"母親對孩子的感情各有不同，孩子们自然不會团結一致。","sortOrder":87},
  {"id":"s_work_gp_9_88","chapterId":"ch_work_gp_9","text":"【原文】晉太保王祥，繼母朱氏遇祥無道。朱子覽，年數歲，見祥被楚撻，辄涕泣抱持。至於成童，每諫其母，少止凶虐。朱屢以非理使祥，覽辄與祥俱。又虐使祥妻，覽妻亦趨而共之。朱患之，乃止。祥丧父之後，漸有時譽，朱深疾之，密使鸩祥。覽知之，径起取酒。祥疑其有毒，爭而不與。朱遽奪，反之。自後，朱賜祥饌，覽先嘗。朱辄懼覽致毙，遂止。覽孝友恭恪，名亚於祥，仕至光祿大夫。","sortOrder":88},
  {"id":"s_work_gp_9_89","chapterId":"ch_work_gp_9","text":"【譯述】西晉太保王祥的繼母朱氏對待王祥不講人道。朱氏的親兒子覽年仅幾歲，看到王祥被母親殴打，每次都哭泣著抱住王祥。覽十五歲成童之後，常勸說母親，讓她停止對王祥的凶殘虐待。朱氏多次非理懲罰王祥，覽就與王祥一起去受罰。朱氏還虐待王祥的妻子，覽的妻子也跟著一起受罰。朱氏没有辦法，就停止了對王祥的虐待。王祥的父親死了之後，王祥在當地的聲譽漸高，朱氏很嫉恨，暗中派人要毒死王祥。覽知道後，連忙拿起毒酒。王祥懷疑酒中有毒藥，就跟覽爭奪酒，不讓覽喝。朱氏立刻奪過毒酒，把他還給送酒的人。從此以後，朱氏拿給王祥的飯菜，覽總要先嘗一下。朱氏害怕覽被毒死，就停止了對王祥的謀害。覽孝順父母，愛護兄弟，名聲仅次於王祥，他官至光祿大夫。","sortOrder":89},
  {"id":"s_work_gp_9_90","chapterId":"ch_work_gp_9","text":"【原文】後魏仆射李冲，兄弟六人，四母所出，頗相忿阋。及冲之貴，封祿恩賜，皆與共之，內外辑睦。父亡後，同居二十餘年，更相友愛，久無間然，皆冲之德也。","sortOrder":90},
  {"id":"s_work_gp_9_91","chapterId":"ch_work_gp_9","text":"【譯述】後魏仆射李冲，有兄弟六人，分別為四个母親所生，他们互相仇视、爭斗。等到李冲顯貴之後，他把自己的俸祿和皇上給的賞賜全部獻出來給兄弟们共用，從此兄弟们內外团結，能够和睦相處。父親死後，他们兄弟幾个在一起生活了二十多年，更加相互友愛，没有一點隔閡，他们能够这樣親密無間，都是因為李冲的品德高尚。","sortOrder":91},
  {"id":"s_work_gp_9_92","chapterId":"ch_work_gp_9","text":"【原文】北齊南汾州刺史劉丰，八子俱非嫡妻所生。每一子所生丧，諸子皆為製服三年。武平、仲所生丧，諸弟併請解官，朝廷義而不許。","sortOrder":92},
  {"id":"s_work_gp_9_93","chapterId":"ch_work_gp_9","text":"【譯述】北齊南汾州刺史劉丰，他的八个兒子都不是他的嫡妻所生。每一个兒子的生母去世，其他幾个兒子都要為她服丧三年。武平和仲的生母去世，其他幾个兄弟都請求辭職居丧，朝廷表彰他们的節義，但没有允許他们辭職。","sortOrder":93},
  {"id":"s_work_gp_9_94","chapterId":"ch_work_gp_9","text":"【原文】唐中書令韦嗣立，黃門侍郎承慶異母弟也。母王氏遇承慶甚嚴，每有杖罰，嗣立必解衣清代，母不聽，辄私自杖。母察知之，漸加恩貸。","sortOrder":94},
  {"id":"s_work_gp_9_95","chapterId":"ch_work_gp_9","text":"兄弟苟能如此，奚異母之足患哉！","sortOrder":95},
  {"id":"s_work_gp_9_96","chapterId":"ch_work_gp_9","text":"【譯文】唐代中書令韦嗣立是黃門侍郎承慶的異母弟弟，母親王氏對待承慶非常嚴酷，但是每次王氏鞭打承慶的時候，嗣立就解开自己的衣服，請求代替哥哥受罰。母親不允許，他就自己打自己一頓。母親知道後，對承慶就漸漸好了起來。如果兄弟之間能友愛如此，區區一个異母又有什么妨礙呢？","sortOrder":96},
  {"id":"s_work_gp_9_97","chapterId":"ch_work_gp_9","text":"姑姊妹村婦不以私害公，吓退敵國入侵之兵【原文】齊攻魯，至其郊，望見野婦人抱一兒、携一兒而行。軍且及之，弃其所抱，抱其所携而走於山。兒隨而啼，婦人疾行不顧。齊將問兒曰：“走者爾母耶？”曰：“是也。”“母所抱者誰也？”曰：“不知也。”齊將乃追之。軍士引弓將射之，曰：“止！不止，吾將射爾。”婦人乃還。齊將問之曰：“所抱者誰也？所弃者誰也？”婦人對曰：“所抱者，妾兄之子也；弃者，妾之子也。見軍之至，將及於追，力不能兩護，故弃妾之子。”齊將曰：“子之於母，其親愛也，痛甚於心，令釋之而反抱兄之子，何也？”婦人曰：“己之子，私愛也。兄之子，公義也。夫背公義而向私愛，亡兄子而存妾子，幸而得免，則魯君不吾畜，大夫不吾養，庶民國人不吾與也。夫如是，則胁肩無所容，而累足無所履也。","sortOrder":97},
  {"id":"s_work_gp_9_98","chapterId":"ch_work_gp_9","text":"子雖痛乎，獨謂義何？故忍弃子而行義。不能無義而视魯國。”於是齊將案兵而止，使人言於齊君曰：“魯未可伐。乃至於境，山泽之婦人耳，猶知持節行義，不以私害公，而况於朝臣士大夫乎？請還。”齊君許之。魯君聞之，賜束帛百端，號曰“義姑姊”。","sortOrder":98},
  {"id":"s_work_gp_9_99","chapterId":"ch_work_gp_9","text":"【譯述】齊國的軍队攻打魯國，到了魯國的郊外，望見原野上有个婦女懷里抱著一个小孩，手里拉著一个小孩趕路。軍队快追上去的時候，那婦女放下懷里抱著的孩子，抱起手里牵著的小孩逃到山里。那个被放下的小孩在後邊啼哭，可婦女依然飛快地行走，併不理會。齊軍將領問那个哭泣的小孩：“逃跑的婦女是你的母親吗？”小孩回答說：“是的。”“你母親抱的小孩是誰？”“不知道。”齊軍將領就去追那个婦女，士兵引弓搭箭准備射她，併喊道：“站住！不站住，就射死你。”婦女只好回轉身來。齊國的將領問她：“你抱的小孩是誰？丢下的那个小孩是誰？”婦女回答說：“懷里抱的，是我哥哥的兒子；丢下的，是我自己的兒子。看見軍队快要追趕上來，我無力同時保護兩个孩子，就舍弃了我自己的兒子。”齊國的將領說：“兒子對於母親來說，那是最疼愛不過的，你現在却丢弃親兒子，反抱著哥哥的孩子跑，这是為什么？”婦人說：“疼愛自己的孩子那是一种个人感情；救兄長的孩子，那是一种公共道德。","sortOrder":99},
  {"id":"s_work_gp_9_100","chapterId":"ch_work_gp_9","text":"如果我违背公共道德而偏私个人感情，丢弃兄長的孩子而救我自己的孩子，就算是幸免於難，但魯國的國君也因此而不願再要我这樣的臣民，魯國的大夫也不願再去養我，國內的一般百姓也以與我為伍為恥。果真这樣的話，我以後根本没有容身之所，也没有邁步之地。这樣說來，雖然很心疼兒子，但道義上怎么辦呢？所以我忍心丢下兒子來保全道義。","sortOrder":100},
  {"id":"s_work_gp_9_101","chapterId":"ch_work_gp_9","text":"關鍵是如果失去了道義就再無脸去見魯國了。”聽了这个婦人的話，齊國的將領竟按兵不動，他派人報告齊國的國君說：“現在不能征伐魯國。我们來到魯境，連一个山野婦人都懂得守節操行道義，不以私害公，而况他们的朝臣和士大夫呢？所以我们請求退兵。”齊國的國君同意了这个意見。後來，魯國的國君聽說了这件事，賜給这个婦女束帛百端，併給了她一个“義姑姊”的榮譽稱號。","sortOrder":101},
  {"id":"s_work_gp_9_102","chapterId":"ch_work_gp_9","text":"【原文】梁節姑姊之室失火，兄子與己子在室中，欲取其兄子，辄得其子，獨不得兄子。火盛，不得复入。婦人將自趣火，其友止之曰：“子本欲取兄之子，惶恐卒誤得爾子，中心謂何？何至自赴火？”婦人曰：“梁國豈可戶告人晓也，被不義之名，何面目以見兄弟國人哉？吾欲复投吾子，為失母之恩。吾势不可生。”遂赴火而死。","sortOrder":102},
  {"id":"s_work_gp_9_103","chapterId":"ch_work_gp_9","text":"【譯述】梁國有个有節操的婦女，她家里失了火，哥哥的兒子與自己的兒子都在室內，她想救出哥哥的兒子，但每次找到的都是自己的兒子，唯獨不見哥哥的兒子。火势旺盛，她不能再進去，就准備跳進火中，她的朋友阻拦她說：“你本來想救你哥哥的兒子，驚慌當中却救出了自己的兒子，你的本意是好的，為什么自己要跳進火中去死呢？”那个婦女回答說：“在梁國这么大的一个國家，怎么可能向每一戶人家都表白清我的想法呢？我蒙受没有道義的名聲，有何脸面去見兄弟和國人呢？我想把我的兒子再投進火中，又怕失去了為人母親的恩情和道義。我的確無法活下去了。”於是就跳進火中燒死。","sortOrder":103},
  {"id":"s_work_gp_9_104","chapterId":"ch_work_gp_9","text":"【原文】漢陽任延寿妻季兒，有三子。季兒兄季宗與延寿爭葬父事，延寿與其友田建陰殺季宗。建獨坐死。延寿會赦，乃以告季兒。季兒曰：“嘻！獨今乃語我乎？”遂振衣欲去，問曰：“所與共殺吾兄者，為誰？”曰：“與田建。田建已死，獨我當坐之，汝殺我而已。”季兒曰：“殺夫不義，事兄之仇亦不義。”延寿曰：“吾不敢留汝，願以車馬及家中财物盡以送汝，惟汝所之。”季兒曰：“吾當安之？兄死而仇不報，與子同枕席而使殺吾兄，內不能和夫家，外又縱兄之仇，何面目以生而戴天履地乎？”延寿慚而去，不敢見季兒。季兒乃告其大女曰：“汝父殺吾兄，義不可以留，又終不复嫁矣。吾去汝而死，汝善视汝兩弟。”遂以繦自經而死。左冯翊王讓聞之，大其義，令縣复其三子而表其墓。","sortOrder":104},
  {"id":"s_work_gp_9_105","chapterId":"ch_work_gp_9","text":"【譯述】漢代陽任延寿的妻子叫季兒，他们有三个孩子。季兒的哥哥季宗和任延寿為安葬父親的事發生爭斗，任延寿與他的朋友田建暗殺了季宗。後來只田建一人被判了死刑，延寿正巧碰上了大赦，没有死。他回去告訴季兒，季兒說：“噫，為什么現在才告訴我？”於是她一邊穿衣服准備離去，一邊問道：“你和誰一起殺的我哥哥？”回答說：“和田建。","sortOrder":105},
  {"id":"s_work_gp_9_106","chapterId":"ch_work_gp_9","text":"但田建現在已經死了，只有我來承擔责任了，你來殺我吧，”季兒說：“殺自己的丈夫是不義之舉，但是侍奉兄長的仇人也是不義之事。”延寿說：“我也不敢再留你做我的妻子了，我願意將家里的車馬和财物都送給你，你任意拿取。”季兒說：“我應當去哪里呢？兄長被殺而不能為他報仇，我和你一起生活却發生了你殺我兄長的事，我在內不能調理好丈夫與別人的矛盾，在外又放過了兄長的仇人，我還有什么脸面活在世界上呢？”延寿覺得很羞慚，不敢再去見季兒。季兒對她的大女兒說：“你的父親殺了我的哥哥，按道義我不能再留在这里了，但我也不能再改嫁他人了。我只得丢下你们去死，你一定要好好照看你的兩个弟弟。”於是她便上弔自殺了。當時的左冯翊王讓聽說了这件事後，贊賞季兒的節義，下令讓縣里免去她的三个孩子的徭役，併旌表季兒的節烈義舉。","sortOrder":106},
  {"id":"s_work_gp_9_107","chapterId":"ch_work_gp_9","text":"【原文】唐冀州女子王阿足，早孤，無兄弟，唯姊一人。阿足初適同縣李氏，未有子而亡，時年尚少，人多聘之。為姊年老孤寡，不能舍去，乃誓不嫁，以養其姊。每晝營田業，夜便紡績，衣食所須，無非阿足出者，如此二十餘年。及姊丧，葬送以禮。乡人莫不稱其節行，競令妻女求與相識。後數歲，竟終於家。","sortOrder":107},
  {"id":"s_work_gp_9_108","chapterId":"ch_work_gp_9","text":"【譯述】唐代冀州女子王阿足，早年丧父，没有兄弟，只有一个姐姐。阿足起初嫁給本縣的李氏，還没有生孩子，丈夫就死了，这時阿足還很年輕，很多人想娶她為妻。但她想到姐姐年老又孤苦伶仃，她不願離开姐姐，就發誓不再嫁人，以便來養活姐姐。她白天耕田种地，晚上紡紗織布，姐姐的衣食用品都是她提供的，如此这般，長達二十多年。等到姐姐去世，她依照禮法安葬了姐姐。乡里的百姓無不稱贊她的品行，競相讓自己的妻子、女兒與她結識，向她學習。幾年後，她老死在家中。","sortOrder":108},
  {"id":"s_work_gp_9_109","chapterId":"ch_work_gp_9","text":"夫夫妻應相敬如賓","sortOrder":109},
  {"id":"s_work_gp_9_110","chapterId":"ch_work_gp_9","text":"【原文】夫婦之道，天地之大義，風化之本原也，可不重欤！《易》：“艮下兑上，鹹。彖曰：止而說，男下女，故取女吉也。巽下震上，恒。彖曰：刚上而柔下，雷風相與。”蓋久常之道也。是故禮，婿冕而親迎，御輪三周。所以下之也。既而婿乘車先行，婦車從之，反尊卑之正也。","sortOrder":110},
  {"id":"s_work_gp_9_111","chapterId":"ch_work_gp_9","text":"《家人》：“初九，閒有家，悔亡。”正家之道，靡不在初，初而驕之，至於狼，浸不可製，非一朝一夕之所致也。昔舜為匹夫，耕漁於田泽之中，妻天子之二女，使之行婦道於翁姑，非身率以禮義，能如是乎？","sortOrder":111},
  {"id":"s_work_gp_9_112","chapterId":"ch_work_gp_9","text":"【譯述】夫婦之間的道義，是天地間的很重要的道義，也是風俗教化的本原，能不重视吗！《周易》說：“艮在下兑在上，是‘鹹’卦。彖辭說：男女交往既有節製又互相愉悅，男子謙卑地向女子求婚，这樣娶妻子就吉利。巽在下震在上，是‘恒’卦。彖辭說：男子在上，女子在下，是雷和風的結合。”这大概是永恒不变的道理。因此禮法規定：新郎戴上禮帽，迎親的時候要駕車繞行幾圈，為的是為了向新娘表示謙恭。然後新郎乘車走在前面，新娘的車跟在後面，又是為了表明男尊女卑。“家人”卦說：“處於一位的陽爻表現的是：在治理家庭時，要註意防止妻子的空閒無聊，那樣就不會產生悔恨。”因此端正家風的辦法，就是一娶回媳婦的時候就要嚴格管理。一开始就娇慣妻子，以至於妻子放荡恣肆，不可遏製。这併不是一朝一夕就會出現这樣的情况的，而是從一开始就没有管好的結果。從前虞舜身為平民的時候，親自在田泽之中种田養魚。他娶了天子的兩个女兒做妻子，但能讓她们在公婆面前履行婦道，如果不是他自己躬行禮義，妻子能做到这些吗？","sortOrder":112},
  {"id":"s_work_gp_9_113","chapterId":"ch_work_gp_9","text":"【原文】漢鮑宣妻桓氏，字少君。宣嘗就少君父學，父奇其清苦，故以女妻之，裝送資賄甚盛。宣不悅，謂妻曰：“少君生富驕，習美飾，而吾實貧賤，不敢當禮。”妻曰：“大人以先生修德守約，故使賤妾侍執巾櫛，既奉承君子，惟命是從。”宣笑曰：“能如是，是吾志也。”妻乃悉歸侍御服飾，更著短布裳，與宣共挽鹿車，歸乡里，拜姑畢，提瓮出汲，修行婦道，乡邦稱之。","sortOrder":113},
  {"id":"s_work_gp_9_114","chapterId":"ch_work_gp_9","text":"【譯述】西漢鮑宣的妻子桓氏，字少君。鮑宣曾經跟隨少君的父親讀書學習，少君的父親欣賞他刻苦好學，就把女兒許配給了他。少君出嫁時嫁妆非常丰厚，鮑宣心里不高興，就對妻子說：“你生在富貴人家，習慣穿著漂亮的衣服，可是我非常貧窮，不敢和你結婚。”妻子說：“我父親因為你品德高尚、俭朴簡約，所以讓我來侍奉你，既然做了你的妻子，我什么事情都聽你的。”鮑宣笑著說：“你真能这樣，就符合我的心意了。”少君將那些貴族服裝全都送回娘家，穿上了平民的簡短衣裳，與鮑宣一起拉著小車，回到家乡。她拜完婆母，就提著水瓮出去打水，修習為婦之道，乡里的人對她非常稱贊。","sortOrder":114},
  {"id":"s_work_gp_9_115","chapterId":"ch_work_gp_9","text":"【原文】扶風梁鸿，家貧而介絜。势家慕其高節，多欲妻之，鸿併絕不許。","sortOrder":115},
  {"id":"s_work_gp_9_116","chapterId":"ch_work_gp_9","text":"同縣孟氏有女，状肥丑而黑，力舉石臼，擇對不嫁，行年三十。父母問其故，女曰：“欲得賢如梁伯駕者。”鸿聞而聘之。女求作布衣麻履，織作筐緝績之具。及嫁，始以裝飾，入門七日，而鸿不答。妻乃跪床下請曰：“竊聞夫子高義，簡斥數婦，妾亦偃蹇數夫矣。今而見擇，敢不請罪？”鸿曰：“吾欲裘褐之人，可與俱隱深山者爾。今乃衣綺縞，傅粉墨，豈鸿所願哉！”妻曰：“以觀夫子之志爾。妾自有隱居之服。”","sortOrder":116},
  {"id":"s_work_gp_9_117","chapterId":"ch_work_gp_9","text":"乃更椎髻，著布衣，操作具而前。鸿大喜，曰：“此真梁鸿之妻也！能奉我矣！”字之曰“德曜。”遂與偕隱。是皆能正其初者也。夫婦之际，以敬為美。","sortOrder":117},
  {"id":"s_work_gp_9_118","chapterId":"ch_work_gp_9","text":"【譯述】東漢扶風人梁鸿，家里雖然十分貧窮，但他志向高絜。當地有權势的人家羨慕他的品行高尚，都願意把女兒許配給他，可是他都回絕了。","sortOrder":118},
  {"id":"s_work_gp_9_119","chapterId":"ch_work_gp_9","text":"同縣孟氏家有个女兒，長得肥胖而且又黑又丑，力氣很大，能舉起石臼。家人為她選好了對象她却不出嫁，年近三十，尚未婚配。父母問她原因，她說：“我想找个像梁鸿那樣賢能的人。”梁鸿聽說後就和她订了婚。","sortOrder":119},
  {"id":"s_work_gp_9_120","chapterId":"ch_work_gp_9","text":"她讓父母給她准備了布衣麻鞋以及筐篚、紡織用具等等。出嫁後，她每天都梳妆打扮，但進入梁家七天，梁鸿也没有答理她。她跪在床下請罪說：“我聽說你志向高絜，拒絕了好幾个求婚女子，我也不肯低就，回絕了幾个求婚男子。如今被你看中，敢問我的過错何在？”梁鸿回答說：“我想娶的是能過平民生活的女子，她能和我一起隱居深山之中。如今你却穿著綾羅綢緞，涂脂抹粉，哪里是我的願望啊！”妻子說：“我先前那樣打扮，為的就是觀察你的志向。我自有隱居的服裝。”過了一會兒，她的頭發綰成椎髻，身穿布衣短裳，手拿幹活的工具，來到梁鸿跟前。梁鸿非常高興，說：“这才像我梁鸿的妻子！你可以侍奉我了。”","sortOrder":120},
  {"id":"s_work_gp_9_121","chapterId":"ch_work_gp_9","text":"他給妻子取字叫“德曜”，然後和她一起隱居深山。像这樣的夫妻就是一开始丈夫就將妻子引上了正路。夫妻之間，以相敬如賓為美德。","sortOrder":121},
  {"id":"s_work_gp_9_122","chapterId":"ch_work_gp_9","text":"【原文】晉臼季使，過冀，見冀缺耨，其妻馌之，敬，相待如賓。與之歸，言諸文公曰：“敬，德之聚也，能敬必有德，德以治民，君請用之。”","sortOrder":122},
  {"id":"s_work_gp_9_123","chapterId":"ch_work_gp_9","text":"文公從之，卒為晉名卿。","sortOrder":123},
  {"id":"s_work_gp_9_124","chapterId":"ch_work_gp_9","text":"【譯述】晉國的臼季出使遠方，路過冀地，看見冀缺鋤田，他的妻子給他送來了飯。妻子對丈夫非常恭敬，而冀缺對妻子也相敬如賓。臼季就把冀缺一起帶回了晉國，併向晉文公推荐說：“對別人恭敬是有德行的最大的表現，一个人如果能做到恭敬，他肯定有德行。而德正是治理國家所需要的東西，陛下請重用这个人吧，不會有错。”晉文公聽從了他的話，將冀缺委以官職。而冀缺也確實很有德行，最終成為晉國很出名的好官。","sortOrder":124},
  {"id":"s_work_gp_9_125","chapterId":"ch_work_gp_9","text":"【原文】漢梁鸿避地於吳，依大家皋伯通，居庑下，為人賃舂。每歸，妻為具食，不敢於鸿前仰视，舉案齊眉。伯通察而異之，曰：“彼佣，能使其妻敬之如此，非凡人也。”方舍之於家。","sortOrder":125},
  {"id":"s_work_gp_9_126","chapterId":"ch_work_gp_9","text":"【譯述】東漢梁鸿到吳地避亂，投靠在大家世族皋伯通的門下，寄居他家廊下，靠為人舂米為生。梁鸿每次舂米回來，妻子都為他做好了飯菜，却不敢仰视丈夫一眼，將盛飯菜的托盤高高舉起來，送到丈夫面前。伯通發現後非常驚異，說：“他是一个佣人，却能讓他的妻子對他如此恭敬，他肯定不是平常人。”於是伯通就讓梁鸿住進家里。","sortOrder":126},
  {"id":"s_work_gp_9_127","chapterId":"ch_work_gp_9","text":"【原文】晉太宰何曾，閨門整肅，自少及長，無聲樂嬖幸之好。年老之後，與妻相見，皆正衣冠，相待如賓，己南向，妻北面再拜，上酒，酬酢既畢，便出。一歲如此者，不過再三焉。若此，可謂能敬矣！","sortOrder":127},
  {"id":"s_work_gp_9_128","chapterId":"ch_work_gp_9","text":"【譯述】西晉太宰何曾，他家閨門整肅有規矩。全家的人，從年輕的到成年的，没有一个人喜歡聲色。何曾在年老之後，每次與妻子會面，都要整衣束帶，與妻子相敬如賓。他自己面南而坐，妻子向北給他拜兩拜，然後端上酒來，互相敬酒之後，何曾就走了。夫婦之間这樣互相行禮，一年之中不過兩三次。像这樣的夫妻，可謂是相敬如賓。","sortOrder":128},
  {"id":"s_work_gp_9_129","chapterId":"ch_work_gp_9","text":"【原文】昔莊周妻死，鼓盆而歌。漢山陽太守薛勤，丧妻不哭，臨殯曰：“幸不為夭，夫何恨！”太尉王龚妻亡，與諸子併杖行服，時人兩譏之。晉太尉劉實丧妻，為庐杖之製，終丧不御肉，輕薄笑之，實不以為意。彼莊、薛弃義，而王、劉循禮，其得失豈不殊哉？何譏笑焉！","sortOrder":129},
  {"id":"s_work_gp_9_130","chapterId":"ch_work_gp_9","text":"【譯述】古代莊周的妻子死了，莊周敲著盆子高歌。漢代山陽太守薛勤，妻子死了他不哭，臨到殯殓的時候他說：“你已經不算是夭折了，有什么遺憾的呢？”太尉王龚的妻子去世，王龚和幾个兒子一起行丧禮，當時的人都譏諷他。晉太尉劉實的妻子去世，他為妻子按禮製服丧，在治丧期間他一點肉都不吃。當時那些輕薄的人譏笑他，很不以為然。莊周和薛勤絲毫不講禮義，而王龚和劉實遵守禮法，他们誰對誰错難道還看得不明顯吗？為什么要譏笑王龚和劉實呢？","sortOrder":130},
  {"id":"s_work_gp_9_131","chapterId":"ch_work_gp_9","text":"【原文】《易》：“恒。六五，恒其德。貞，婦人吉。夫子凶。象曰：婦人貞吉，從一而終也。夫子製義，從婦凶也。”丈夫生而有四方之志，威令所施，大者天下，小者一官，而近不行於室家，為一婦人所製，不亦可羞哉！昔晉惠帝為贾後所製，废武悼楊太後於金墉，絕膳而終。囚愍懷太子於許昌，尋殺之。唐肅宗為張後所製，遷上皇於西內，以忧崩。","sortOrder":131},
  {"id":"s_work_gp_9_132","chapterId":"ch_work_gp_9","text":"建寧王倓以忠孝受誅。彼二君者，貴為天子，製於悍妻，上不能保其親，下不能庇其子，况於臣民！自古及今，以悍妻而乖離六親、败亂其家者，可勝數哉？然則悍妻之為害大也。故凡娶妻，不可不慎擇也。既娶而防之以禮，不可不在其初也。其或驕縱悍戾，訓厲禁約而終不從，不可以不弃也。夫婦以義合，義絕則離之。今士大夫有出妻者，眾則非之，以為無行，故士大夫難之。按禮有七出，顧所以出之，用何事耳！若妻實犯禮而出之，乃義也。昔孔氏三世出其妻，其餘賢士以義出妻者眾矣，奚虧於行哉？苟室有悍妻而不出，則家道何日而寧乎？","sortOrder":132},
  {"id":"s_work_gp_9_133","chapterId":"ch_work_gp_9","text":"【譯述】《易經》里的恒卦講：“六五：恒守其德行。如果卜得婦人就吉利，丈夫則凶。象辭說：爻辭講婦人操守貞絜就會吉利，这是符合從夫以終其身的道理的。丈夫則因事製義，該行的道義也很多。如果用婦德來約束男子，則必遭凶险。”男子生來志在四方，發號施令，大則謀國，小則為官，然而其號令却不能在家里行通，為一个婦女所控製，这不是很可恥的事吗？晉惠帝受製於贾南風，废掉武悼楊太後，使她在金墉絕食而死。將憋懷太子囚禁在許昌，不久就殺死了他。唐肅宗受製於張後，把父皇遷到太極宮內，以致於玄宗忧鬱而死，建寧王倓也因為忠誠父皇而被殺。那兩个國君貴為天子，可一旦被凶悍的妻子控製，亦上不能保護他的父親，下不能庇護他的兒子，更何况一般百姓呢？從古到今，因為家里有凶悍的妻子而背離六親、败坏家庭的人多得不可勝數。由此說來，悍妻的危害很大。所以男子娶妻，不能不慎重。娶妻之後以禮進行訓导，一定要從新婚开始就施行。妻子驕縱悍戾，丈夫經過訓导禁約，却仍然不能聽從，丈夫就要考慮休掉她。夫婦之間有情義就在一起生活，没有情義就分手。現在有的士大夫休掉妻子，就會引來許多非議，以為他没有德行，所以士大夫要想休掉他的妻子是一件很難的事。按照禮法，如果妻子违背七條婦德中的一條，就應該將她休掉。根據这七條婦德來决定是否休妻，還用費什么事呢？如果妻子確實违背了禮法，休妻就是一种義舉。從前孔氏家族三代都休過妻子，其他有才德的人按禮法休掉妻子的也很多很多，但这些併没有影响他们的德行。相反，如果家里有凶悍而不講禮的妻子，你不休掉她，家里什么時候才能獲得安寧啊！","sortOrder":133},
  {"id":"s_work_gp_10_1","chapterId":"ch_work_gp_10","text":"家范卷八妻上","sortOrder":1},
  {"id":"s_work_gp_10_2","chapterId":"ch_work_gp_10","text":"女子柔順方才可愛","sortOrder":2},
  {"id":"s_work_gp_10_3","chapterId":"ch_work_gp_10","text":"【原文】太史公曰：“夏之興也以涂山，而桀之放也以妹喜；殷之興也以有娀，紂之殺也嬖妲己；周之興也以薑嫄及大任，而幽王之擒也，淫於褒姒。故《易》基乾坤，《詩》始關雎。夫婦之际，人道之大倫也。禮之用，唯婚姻為兢兢。夫樂調而四時和，陰陽之变，萬物之統也，可不慎欤？”為人妻者，其德有六：一曰柔順，二曰清絜，三曰不妒，四曰俭約，五曰恭謹，六曰勤勞。夫天也，妻地也；夫日也，妻月也；夫陽也，妻陰也。天尊而處上，地卑而處下。日無盈虧，月有圓缺。陽唱而生物，陰和而成物。故婦人专以柔順為德，不以強辯為美也。漢曹大家作《女戒》，其首章曰：“古者生女三日，臥之床下，明其卑弱，主下人也。","sortOrder":3},
  {"id":"s_work_gp_10_4","chapterId":"ch_work_gp_10","text":"謙讓恭敬，先人後己，有善莫名，有惡莫辭，忍辱含垢，常若畏懼。”","sortOrder":4},
  {"id":"s_work_gp_10_5","chapterId":"ch_work_gp_10","text":"又曰：“陰陽殊性，男女異行。陽以刚為德，陰以柔為用。男以強為貴，女以柔為美。故鄙諺有雲：‘生男如狼，猶恐其；生女如鼠，猶恐其虎。’然則修身莫若敬，避強莫若順。故曰：敬順之道，婦人之大禮也。”又曰：“婦人之得意於夫主，由舅姑之愛己也。舅姑之愛己，由叔妹之譽己也。”由此言之，我臧否譽毀，一由叔妹。叔妹之心，誠不可失也。皆知叔妹之不可失，而不能和之以求親，其蔽也哉！自非聖人，鮮能無過，雖以賢女之行、聰哲之性，其能備乎！是故室人和則謗掩，外內離則惡扬，此必然之势也。夫叔妹者，體敵而名尊，恩疏而義親，若淑媛謙順之人，則能依義以篤好，崇恩以結援，使徽美顯章，而瑕過隱塞，舅姑矜善，而夫主嘉美，聲譽曜於邑鄰，休光延於父母。若夫蠢愚之人，於叔則托名以自高，於妹則因寵以驕盈。驕盈既施，何和之有？恩義既乖，何譽之臻？是以美隱而過宣，姑忿而夫慍，毀訾布於中外，恥辱集於厥身，進增父母之羞，退益君子之累，斯乃榮辱之本，而顯否之基也，可不慎哉！然則求叔妹之心，固莫尚於謙順矣。謙則德之柄，順則婦之行；兼斯二者，足以和矣！若此，可謂能柔順矣！妻者，齊也。一與之齊，終身不改。故忠臣不事二主，貞女不事二夫。《易》曰：“柔順利貞，君子攸行。”又曰：“用六，利永貞。”晏子曰：“妻柔而正。”","sortOrder":5},
  {"id":"s_work_gp_10_6","chapterId":"ch_work_gp_10","text":"言婦人雖主於柔，而不可失正也。故後妃逾國，必乘安車辎軿；下堂，必從傅母保阿；進退則鳴玉環珮，內飾則結纫綢缪；野處則帷裳壅蔽，所以正心一意，自斂製也。《詩》雲：“自伯之東，首如飛蓬。豈無膏沭，誰適為容。”故婦人，夫不在，不為容飾，禮也。","sortOrder":6},
  {"id":"s_work_gp_10_7","chapterId":"ch_work_gp_10","text":"【譯述】司馬遷說：“夏朝的興盛，是因為有了涂山，而夏桀最終被流放，罪在妹喜；商朝的興起，功歸於有娀，商紂王殘酷殺戮朝臣，是因為他寵愛妲己；周代的興起是因為有薑嫄及大任，而幽王最終被擒，是因為有褒姒的荒淫。因此，《周易》以乾坤為基礎，《詩經》以關雎為开始。夫妻之間的道德關系，是人類社會的道德規范的重大原則。禮法用於婚姻，是因為對待婚姻要小心謹慎。樂調節，則四時和，陰陽的变化，是萬物变化的依據，能不慎重吗？”為人妻子，其品德共有六种：一是柔順，二是清絜，三是不嫉妒，四是俭約，五是恭謹，六是勤勞。丈夫如天空，妻子像大地；丈夫像太陽，妻子像月亮；丈夫陽刚，妻子陰柔。","sortOrder":7},
  {"id":"s_work_gp_10_8","chapterId":"ch_work_gp_10","text":"天位尊而居上，地卑下而處下，太陽没有盈虧变化，月亮却有圓缺。陽唱而能生物，陰和而能成物。所以妻子以溫柔順從為美德，而不以強詞奪理為美。","sortOrder":8},
  {"id":"s_work_gp_10_9","chapterId":"ch_work_gp_10","text":"漢代的曹大家作《女戒》，在第一章里說：“古代生了女孩子，三天之後就將他放在床下，意思是說女孩子天生卑微體弱，屬於下賤者。","sortOrder":9},
  {"id":"s_work_gp_10_10","chapterId":"ch_work_gp_10","text":"女孩子長大後，應該處處謙讓恭敬，先人後己，做了好事不要去張扬，做了错事不要推卸责任。女人要忍受屈辱，經常表現出戰戰兢兢的樣子來。”","sortOrder":10},
  {"id":"s_work_gp_10_11","chapterId":"ch_work_gp_10","text":"《女戒》又說：“陰陽性质不同，男女行為上有區別。陽以刚強為德，陰以柔順為用。男子以強健為貴，女子以柔順為美。因此有句諺語說：‘生个男孩像豺狼，還害怕他软弱如蛇；生个女孩像老鼠，仍害怕她成為老虎。’修養自身莫如恭敬，躲避強暴莫若溫順。所以說：恭敬柔順之道，是為人妻子的最重要的禮義。”又說：“妻子受到丈夫的寵愛，是因為得到了公婆的喜愛。公婆喜歡自己，又是因為小叔小姑稱贊自己。”由此可以看出，妻子的榮辱譽毀，完全在於小叔小姑對你怎么評价。對小叔小姑的愛心，確實不能失去。每个妻子都知道不能失去小叔小姑的愛心，但又不能溫和地對待他们，豈不是大错特错吗？妻子併不是聖人，怎么能没有過错呢？即使有賢女的品行和聰慧，也難以成為没有缺點的完人。因此妻子只要得到家人的愛護，她的缺點過错就不會外傳。倘若得不到家人的喜愛，她的過错就會傳扬出去，这是必然的。","sortOrder":11},
  {"id":"s_work_gp_10_12","chapterId":"ch_work_gp_10","text":"小叔小姑對嫂子來說，本來就不好相處，但他们的名份又很尊貴；互相之間本來就没有什么恩情，但道義上必須表現為和睦相處。若是賢淑、謙順的妻子，和小叔小姑和睦相處，崇恩結援，使自己的美德得以遠扬，错誤得以遮掩，以致於公婆夸奖自己，丈夫贊扬自己，賢婦的聲譽傳播乡鄰，近而為父母帶來榮耀。若是愚蠢的妻子，在小叔面前自高自大；在小姑面前因寵而驕悍。既然如此，又怎能談得上和平相處呢？既然背恩弃義，又怎能獲取小姑小叔的贊譽？結果自己的美德被遮掩，過错被遠扬，最後公婆憤恨，丈夫惱怒，惡名傳遍內外，而恥辱都集於一身，留在夫家就會增添父母的恥辱，回到娘家又會增加丈夫的忧慮。對待小叔小姑的態度是為人之妻榮辱的關鍵，能不慎重對待吗？要博得小叔小姑的好感，最好的辦法就是謙恭溫順。謙恭，是美好品德的根本，溫順是妻子應有的品行，二者兼備，就能和小叔小姑和睦相處。妻子像这樣，才能稱之為柔順。妻子要對丈夫恭敬，一旦與丈夫結婚，就要終身不再改嫁。因此忠誠的大臣不能侍奉兩个君主，貞節的女子不能侍奉兩个丈夫。《周易》說：“妻子柔順，有利於貞守婦道，丈夫才能遠行。”又說：“用六：有利於永遠恪守婦道。”晏婴說：“妻子如果性情柔順，作風就會正派。”說的是妻子以溫柔為主，此外還要作風正派。因此皇帝的後妃要出行，必須乘坐有帷幕的安車；走到堂下，要聽從傅母和保姆的意見，進門出門都要佩帶鳴玉，在家梳妆打扮，就要自結綢缪組紐；在野外居住要穿著帷裳，為的是能够一心一意，做到自我約束。《詩經》說：“自從君子遠征東邊，我在家里披頭散發。難道是没有润發油吗？","sortOrder":12},
  {"id":"s_work_gp_10_13","chapterId":"ch_work_gp_10","text":"不是，可我又為誰打扮呢？”所以妻子在丈夫外出的時候不打扮自己，这是合乎禮法的。","sortOrder":13},
  {"id":"s_work_gp_10_14","chapterId":"ch_work_gp_10","text":"【原文】衛世子共伯早死，其妻薑氏守義。父母欲奪而嫁之，誓而不許，作《柏舟》之詩以見志。","sortOrder":14},
  {"id":"s_work_gp_10_15","chapterId":"ch_work_gp_10","text":"【譯述】衛國太子共伯死得早，他的妻子薑氏堅守為人妻子的禮義。薑氏的父母想讓她改嫁，她發誓不再嫁人，還寫了一首詩《柏舟》，以此來表達自己堅強的意志。","sortOrder":15},
  {"id":"s_work_gp_10_16","chapterId":"ch_work_gp_10","text":"【原文】宋共公夫人伯姬，魯人也。寡居三十五年。至景公時，伯姬之宮夜失火，左右曰：“夫人少避火。”伯姬曰：“婦人之義，保傅不具，夜不下堂。待保傅之來也。”保母至矣，傅母未至也。左右又曰：“夫人少避火。”","sortOrder":16},
  {"id":"s_work_gp_10_17","chapterId":"ch_work_gp_10","text":"伯姬不從，遂逮於火而死。","sortOrder":17},
  {"id":"s_work_gp_10_18","chapterId":"ch_work_gp_10","text":"【譯述】宋共公的夫人伯姬是魯國人，他一直守寡長達三十五年。到景公的時候，伯姬住的宮中在夜里失了火，她跟前的人對她說：“夫人趕快出來避火。”伯姬說：“婦人應該遵守的禮義是，如果保母和傅母不在跟前，晚上就不能下堂。我要等待保、傅來了才出去。”一會兒，保姆來了，但傅母還没來，跟前的人又勸：“夫人趕快出來避火。”伯姬不從，於是被火燒死了。","sortOrder":18},
  {"id":"s_work_gp_10_19","chapterId":"ch_work_gp_10","text":"【原文】楚昭夫人貞薑，齊女也。王出遊，留夫人漸台之上而去。王聞江水大至，使使者迎夫人，忘持其符。使者至，請夫人出。夫人曰：“王與宮人約令，召宮人必持符。今使者不持符，妾不敢從。”使曰：“今水方大至，還而取符，則恐後矣！”夫人不從。於是使者反取符，未還，則水大至，台崩，夫人流而死。","sortOrder":19},
  {"id":"s_work_gp_10_20","chapterId":"ch_work_gp_10","text":"【譯述】楚昭王的夫人貞薑，是齊國的女子。一次，楚昭王出遊，將貞薑夫人留在了漸台之上。走在半道，楚昭王突然聽說江水暴涨，便立即派使者去漸台上接夫人。可是使者在匆忙之中忘了拿符。使者到了夫人那里，請夫人趕快走。夫人說：“大王與宮中的人有約令，召宮人一定要拿大王的符。現在使者不拿符，我不敢離开。”使者說：“可眼下洪水馬上就要到來，等我回去取了符，恐怕就遲了！”夫人仍然不走。於是，使者只好返回去取符。他還没有返回來，洪水就涌來了，漸台坍塌，貞薑夫人被洪水淹没而死。","sortOrder":20},
  {"id":"s_work_gp_10_21","chapterId":"ch_work_gp_10","text":"【原文】蔡人妻，宋人之女也。既嫁，而夫有惡疾，其母將再嫁之。女曰：“夫人之不幸也，奈何去之？適人之道，一與之醮，終身不改，不幸遇惡疾，彼無大故，又不遣妾，何以得去？”終不聽。","sortOrder":21},
  {"id":"s_work_gp_10_22","chapterId":"ch_work_gp_10","text":"【譯述】有一个蔡人娶了宋人的女兒作妻子。宋女出嫁不久，丈夫便患了重病，她的母親想讓她改嫁。宋女說：“丈夫遭遇了不幸，我怎能離开他？嫁給他人就要堅守道義，一旦與他結婚，就得厮守終身，不再改嫁。丈夫雖然不幸得了重病，但他併没有大的变故，而且他又没有趕我走，我為什么要離开他呢？”她最終没有聽從母親的話。","sortOrder":22},
  {"id":"s_work_gp_10_23","chapterId":"ch_work_gp_10","text":"【原文】梁寡婦高行，榮於色而美於行。早寡不嫁，梁貴人多爭欲娶之者，不能得。梁王聞之，使相聘焉。高行曰：“妾夫不幸早死，妾守養其幼孤，貴人多求妾者，幸而得免。今王又重之。妾聞婦人之義，一往而不改，以全貞信之節。今慕貴而忘賤，弃義而從利，無以為人。”乃援鏡持刀以割其鼻，曰：“妾已刑矣，所以不死者，不忍幼弱之重孤也。王之求妾，以其色也，今刑餘之人，殆可釋矣！”於是相以報王。王大其義而高其行，乃复其身，尊其號曰：“高行。”","sortOrder":23},
  {"id":"s_work_gp_10_24","chapterId":"ch_work_gp_10","text":"【譯述】梁國有一个寡婦叫高行，她容貌漂亮，又有好名聲，年輕守寡，没有改嫁。梁國的達官顯貴都爭著想娶她為妻，但不能得到她。梁國國王聽說後，便派丞相去禮聘。高行說：“我的夫君不幸早死，我撫育他的孩子，有許多達官顯貴來娶我，我都拒絕了。不想現在大王又來禮聘。","sortOrder":24},
  {"id":"s_work_gp_10_25","chapterId":"ch_work_gp_10","text":"我聽說婦人應該遵守的禮義是從一而終，以成全貞絜和守信用的節操。","sortOrder":25},
  {"id":"s_work_gp_10_26","chapterId":"ch_work_gp_10","text":"如果我現在羨慕富貴，忘掉貧賤之先夫，丢弃信義而去追逐利益，那我還怎么做人呢？”於是他照著鏡子，用刀割下了自己的鼻子，然後說：“我已經毀了容，我之所以没有去死，是因為丢不下幼弱的孩子。大王想要得到我，無非是為了我的美色，現在我已經是个毀了容的人了，大概可以放過我了吧！”丞相將这一情况報告給梁王，梁王嘉奖她的品行德義，於是聽其自便，併賜給她一个封號叫“高行”。","sortOrder":26},
  {"id":"s_work_gp_10_27","chapterId":"ch_work_gp_10","text":"【原文】漢陳孝婦，年十六而嫁，未有子。其夫當行戍，夫且行時，屬孝婦曰：“我生死來可知，幸有老母，無他兄弟備養，吾不還，汝肯養吾母乎？”婦應曰：“诺。”夫果死不還。婦乃養姑不衰，慈愛愈固，紡績織纴以為家業，終無嫁意。居丧三年，父母哀其年少無子而早寡也，將取而嫁之。孝婦曰：“夫行時屬妾以其老母，妾既許诺之，夫養人老母而不能卒，許人以诺而不能信，將何以立於世？”欲自殺。其父母懼而不敢嫁也，遂使養其姑二十八年。姑八十餘，以天年終，盡賣其田宅财物以葬之，終奉祭祀。淮陽太守以聞，孝文皇帝使使者賜黃金四十斤，复之終身無所與，號曰“孝婦”。","sortOrder":27},
  {"id":"s_work_gp_10_28","chapterId":"ch_work_gp_10","text":"【譯述】漢代陳孝婦，年仅十六歲就出嫁了，没生孩子。她的丈夫要去戍守邊疆，臨走的時候，嘱咐她說：“我这一走，生死未卜，家里還有老母親，又没有其他弟兄能够贍養，如果我回不來，你願意贍養我的母親吗？”孝婦回答說：“願意。”丈夫果然死在戰場上没有回來。孝婦就贍養婆婆，婆媳相依為命，互相疼愛，孝婦靠紡紗織布來維持生活，始終没有改嫁的想法。她為丈夫居丧三年後，父母可怜她年輕守寡又没有孩子，就想讓她改嫁。她說：“丈夫走的時候把他的老母托付給我，我既然許下诺言就應該守信用，贍養他人老母却不能堅持到最後，許诺於人却不能守信運，我還怎么活在世界上呢？”她想用自殺來反抗父母，她的父母害怕她尋死就不敢強迫她改嫁，讓她繼續贍養婆婆。二十八年後，婆婆八十多歲，寿終正寢。孝婦將房屋、田地等家產全部賣掉來安葬婆婆。而且為婆婆守丧、祭祀。淮陽太守將她的事跡禀報皇帝，孝文皇帝派遣使者賜給她黃金四十斤，免除她終身的賦役，併尊稱她為“孝婦”。","sortOrder":28},
  {"id":"s_work_gp_10_29","chapterId":"ch_work_gp_10","text":"【原文】吳許升妻呂榮，郡遭寇賊，榮逾垣走。賊持刀追之。賊曰：“從我則生，不從我則死。”榮曰：“義不以身受辱寇虜也。”遂殺之。是日疾風暴雨，雷電晦冥，賊惶恐，叩頭謝罪，乃殯葬之。","sortOrder":29},
  {"id":"s_work_gp_10_30","chapterId":"ch_work_gp_10","text":"【譯述】吳許升的妻子呂榮，為躲避賊寇追趕，跳牆而逃。那些賊寇持刀追她。賊喊：“跟我们走你就可以活命，不跟我们走就殺死你。”呂榮回答說：“我决不受辱於賊寇！”於是自殺而死。这天疾風暴雨，電閃雷鳴，賊寇為自己傷天害理感到恐懼，便叩頭謝罪，併安葬了呂榮。","sortOrder":30},
  {"id":"s_work_gp_10_31","chapterId":"ch_work_gp_10","text":"【原文】沛劉長卿妻，五更桓榮之孫也。生男五歲而長卿率。妻防遠嫌疑，不肯歸寧。兒年十五，晚又夭殁。妻慮不免，乃豫刑其耳以自誓。宗婦相與愍之，共謂曰：“若家殊無他意，假令有之，猶可因姑姊妹以表其誠，何貴義輕身之甚哉！”對曰：“昔我先君五更，學為儒宗，尊為帝師。五更以來，歷代不替。男以忠孝顯，女以貞順稱。《詩》雲：‘無忝爾祖，聿修厥德。’是以豫自刑剪，以明我情。”沛相王吉上奏高行，顯其門闾，號曰“行義桓嫠”。縣邑有祀必膰焉。","sortOrder":31},
  {"id":"s_work_gp_10_32","chapterId":"ch_work_gp_10","text":"【譯述】沛劉長卿的妻子是五更桓榮的孫女。他们結婚後生了一个男孩，但孩子五歲時劉長卿就死了。妻子怕娘家讓她改嫁，便不回娘家。她的兒子長到十五歲的時候，又不幸死掉。劉妻考慮娘家早晚要讓她改嫁，便預先割掉自己的耳朵，發誓不嫁。同宗族的女人们很怜悯她，一起對她說：“其實你娘家併没有讓你改嫁的意思，即便有，我们還可以替你說情，表白你的誠意，為什么貴義輕身竟到如此的地步呢？”她回答說：“從前我先夫活著的時候，學問上乘，被尊為帝師。打他之後，没有能超過他的。男人就應該以忠誠和孝順來求得顯達，女人就應該以貞絜和溫順來贏得好名聲。《詩經》說：‘不要羞辱你的祖先，應當修養你的德行。’因此我預先自己毀容，以向世人表明我的心志。”沛相王吉向皇上奏明她的高行義舉，對她進行表彰，併稱她為“行義桓嫠”。她死之後，縣里只要有祭祀活動，就肯定要祭拜她。","sortOrder":32},
  {"id":"s_work_gp_10_33","chapterId":"ch_work_gp_10","text":"【原文】度遼將軍皇甫規卒時，妻年猶盛而容色美。後董卓為相國，聞其名，聘以軿辎百乘，馬四十匹，奴婢錢帛充路。妻乃輕服詣卓門，跪自陳請，辭甚酸怆。卓使傅奴侍者，悉拔刀围之，而謂曰：“孤之威教，欲令四海風靡，何有不行於一婦人乎？”妻知不免，乃立骂卓曰：“君羌胡之种，毒害天下猶未足邪！妾之先人，清德奕世。皇甫氏文武上才，為漢忠臣，君親非其趣使走吏乎！敢欲行非禮於爾君夫人耶？”卓乃引車庭中，以其頭懸軛，鞭扑交下。妻謂持杖者曰：“何不重乎？速盡為惠！”遂死車下。後人圖畫，號曰“禮宗”雲。","sortOrder":33},
  {"id":"s_work_gp_10_34","chapterId":"ch_work_gp_10","text":"【譯述】度遼將軍皇甫規死的時候，他的妻子還正值盛年，姿色猶存。後來，董卓當了相國，聽說她很美麗，就以豪華的車子百輛、四十匹馬和許多奴婢錢帛為聘禮，想娶她。皇甫規的妻子得知後，就親自到董卓的門上，跪地陳說自己不願再嫁，言辭誠恳動人。董卓命令手下手執利刃將她围住，併對她說：“我以我的威势，想讓天下的人都聽我的號令，我怎么能容忍一个婦人竟不聽的話！”皇甫妻心知不能免禍，便幹脆站起來大骂董卓：“你本來就是个羌人和胡人的野种，你禍害天下還没有够啊！","sortOrder":34},
  {"id":"s_work_gp_10_35","chapterId":"ch_work_gp_10","text":"我夫君家，清明廉正的德行代代相傳。我的先夫皇甫規文武全才，是漢室的忠臣，你那時只不過是他驅使下的一个小小走卒，你敢對你的上司的夫人行非禮吗？”董卓命人將一輛車拉進庭院中，將她的頭套進軛里，然後鞭打她。皇甫妻對那些打她的人說：“為什么不打得重一點呢？我只願快點死。”她最終被打死在車下。後人為她畫像，稱她為“禮宗”。","sortOrder":35},
  {"id":"s_work_gp_10_36","chapterId":"ch_work_gp_10","text":"【原文】魏大將軍曹爽從弟文叔妻，谯郡夏侯文寧之女，名令女。文叔早死，服阕，自以年少無子，恐家必嫁己，乃斷發以為信。其後家果欲嫁之。","sortOrder":36},
  {"id":"s_work_gp_10_37","chapterId":"ch_work_gp_10","text":"令女聞，即复以刀截兩耳。居止嘗依爽。及爽被誅，曹氏盡死，令女叔父上書，與曹氏絕婚，強迎令女歸。時文寧為梁相，怜其少執義，又曹氏無遺類，冀其意沮，乃微使人諷之。令女叹且泣曰：“吾亦悔之，許之是也。”家以為信，防之少懈。令女於是竊入寢室，以刀斷鼻，蒙被而臥。其母呼與語，不應。發被视之，流血滿床席。舉家驚惶，奔往视之，莫不酸鼻。或謂之曰：“人生世間，如輕尘栖弱草耳，何至辛苦乃爾！且夫家夷滅已盡，守此欲誰為哉？”令女曰：“聞仁者不以盛衰改節，義者不以存亡易心。曹氏前盛之時，尚欲保終，况今衰亡，何忍弃之？禽獸之行，吾豈為乎？”司馬宣王聞而嘉之，聽使乞子，養為曹氏後。","sortOrder":37},
  {"id":"s_work_gp_10_38","chapterId":"ch_work_gp_10","text":"【譯述】魏大將軍曹爽從弟文叔的妻子，是谯郡夏侯文寧的女兒，她的名字叫令女。文叔很早就死了，令女服丧期滿後，自料自己年輕而且没有孩子，娘家肯定要讓他改嫁，於是她剪斷自己的頭發，以示自己不再改嫁。後來，娘家果然想讓她再嫁，令女聽說後，又用刀子剪下了自己的兩个耳朵，併住在曹爽家里。等到曹爽被殺，曹氏家族被滅族，令女的叔父上書朝廷，聲明他家與曹家斷絕婚姻關系，而且硬將令女接回娘家。此時令女的父親文寧擔任梁相，可怜女兒還年輕，却固執於婦道，而且曹家已經没有後人了，因此他希望女兒能改变初衷。於是他派人去勸說女兒。令女假裝叹氣而且哭著說：“我也很後悔，我答應便是了。”家人信以為真，便不再防范她。令女於是偷偷進入寢室，用刀子割斷了自己的鼻子，然後用被子蒙住頭睡在床上。她母親叫她，與她說話，她不答應。揭开被子一看，血流滿床。全家人都很驚慌，跑去看她，都為之掉淚。有人對她說：“人活在世上，就好象一點灰尘落在了小草上，為何要这么認真呢？况且你丈夫家已被滅族，你即使守著，又為了誰呢？”","sortOrder":38},
  {"id":"s_work_gp_10_39","chapterId":"ch_work_gp_10","text":"令女回答說：“我聽說仁德的人不因為盛衰窮富而改变自己的節操；有義氣的人不因為存亡而变心。曹家在興盛的時候，我還想保持名節，而况他家現在已經衰亡，我怎么忍心背弃他们呢？像禽獸一樣無情無義的事，我怎么能够做出來呢？”司馬宣王聽說了这件事，便贊扬她的德行，任凭她去要一个孩子來撫養，作為曹氏的後代。","sortOrder":39},
  {"id":"s_work_gp_10_40","chapterId":"ch_work_gp_10","text":"【原文】後魏鉅鹿魏溥妻房氏者，慕容垂貴乡太守常山房湛女也。幼有烈操，年十六，而溥遇疾且卒，顧謂之曰：“死不足恨，但痛母老家貧，赤子蒙眇，抱怨於黃壚耳。”房垂泣而對曰：“幸承先人餘訓，出事君子，義在偕老。有志不從，蓋其命也。今夫人在堂，弱子襁褓，顧當以身少相衛，永釋長往之恨。”俄而溥卒。及將大斂，房氏操刀割左耳，投之棺中，仍曰：“鬼神有知，相期泉壤。”流血滂然，丧者哀懼。姑劉氏輟哭而謂曰：“新婦何至於此？”對曰：“新婦少年，不幸早寡，實慮父母未量至情，觊持此自誓耳。”聞知者莫不感怆。時子緝生未十旬，鞠育於後房之內，未曾出門。遂終身不聽絲竹，不預坐席。緝年十二，房父母仍存，於是歸寧。父兄尚有異議，緝竊聞之，以啟其母。房命駕，绐雲他行，因而遂歸，其家弗知之也。行數十里方覺，兄弟來追，房哀叹而不反。其執意如此。","sortOrder":40},
  {"id":"s_work_gp_10_41","chapterId":"ch_work_gp_10","text":"【譯述】後魏鉅鹿人魏溥的妻子房氏，是慕容垂貴乡太守常山房湛的女兒。","sortOrder":41},
  {"id":"s_work_gp_10_42","chapterId":"ch_work_gp_10","text":"房氏雖然年紀不大，但頗有操守。她十六歲的時候，丈夫魏溥得病而死。臨死時丈夫對她說：“我死倒無所謂，只是我母親已上年紀，家里貧窮，而且孩子又小，这些讓我死不瞑目啊！”房氏哭著對他說：“我接受父母的指教，有幸來侍奉你，本來打算與你白頭到老。現在不能實現这个願望，这大概也是天意。你死之後，上有高堂老母，下有襁褓幼子，只有我年輕力壮，我自當照料他们，請你放心好了。”夫妻俩說完这些話，魏溥就死了。入殓的時候，房氏用刀子將自己的左耳朵割下來，扔進棺材里，併說：“如果鬼神有知的話，請你在地下等我。”她血流如註，參加丧禮的人看了，都既可怜她，又感到驚懼。婆婆劉氏哭著說：“媳婦你為什么要这樣呢？”房氏回答說：“我年紀還小，不幸早寡，我擔心我的父母親不考慮我们的夫妻感情，令我改嫁，所以我割耳發誓，不再改嫁。”聽到这話的人無不感叹而悲怆。这時他们的孩子緝出生還不到一百天，房氏在家里撫養孩子，從不出門。她終身不聽音樂，不和外邊的人同坐。緝十二歲的時候，房氏的父母仍然健在，於是他回家去看望父母。此時她的父親和哥哥還有讓她改嫁的意思，緝偷偷地聽見了这些議論，便告給了她的母親。房氏於是讓備車，谎稱要到別的地方，却踏上了歸家的路，而她的娘家還不知道。走了數十里，娘家方才發覺，她的兄弟们追上來，房氏只是哀叹，却不再回娘家去。他嚴守貞絜，竟是这般固執。","sortOrder":42},
  {"id":"s_work_gp_10_43","chapterId":"ch_work_gp_10","text":"【原文】滎陽張洪祁妻劉氏者，年十七夫亡。遺腹生一子，二歲又没。其舅姑年老，朝夕養奉，率禮無违。兄矜其少寡，欲奪嫁之。劉自誓不許，以終其身。","sortOrder":43},
  {"id":"s_work_gp_10_44","chapterId":"ch_work_gp_10","text":"【譯述】滎陽張洪祁的妻子劉氏，十七歲的時候丈夫就死了。生了一个孩子二歲又夭折了。她的公婆年紀很大，她就朝夕侍奉，她一切按照禮法行事，從不违忤公婆。哥哥可怜她年輕守寡，想讓她改嫁，可她發誓不再嫁人，以此而終老其身。","sortOrder":44},
  {"id":"s_work_gp_10_45","chapterId":"ch_work_gp_10","text":"【原文】陳留董景起妻張氏者，景起早亡，張時年十六，痛夫少丧，哀傷過禮，蔬食長斋。又無兒息，獨守貞操，期以阖棺。乡曲高之，終見標異。","sortOrder":45},
  {"id":"s_work_gp_10_46","chapterId":"ch_work_gp_10","text":"【譯述】陳留董景起的妻子張氏，丈夫死的時候，張氏才十六歲。她哀痛丈夫早死，悲傷過度，長時間只吃素食蔬菜。她又没有兒子，只自己獨守貞操，等待著死的那一天。乡里的人都稱贊她，她終於成全了自己的好名聲。","sortOrder":46},
  {"id":"s_work_gp_10_47","chapterId":"ch_work_gp_10","text":"【原文】隋大理卿鄭善果母崔氏，周末，善果父誠讨尉遲迥，力戰死於陣。","sortOrder":47},
  {"id":"s_work_gp_10_48","chapterId":"ch_work_gp_10","text":"母年二十而寡，父彦睦欲奪其志。母抱善果曰“婦人無再適男子之義。","sortOrder":48},
  {"id":"s_work_gp_10_49","chapterId":"ch_work_gp_10","text":"且鄭君雖死，幸有此兒。弃兒為不慈，背夫為無禮，寧當割耳剪發，以明素心。违禮滅慈，非敢聞命。”遂不嫁，教養善果，至於成名。自初寡，便不御脂粉，常服大練，性又節俭，非祭祀賓客之事，酒肉不妄陳其前。靜室端居，未嘗辄出門闾。內外姻戚有吉凶事，但厚加赠遺，皆不請其家。","sortOrder":49},
  {"id":"s_work_gp_10_50","chapterId":"ch_work_gp_10","text":"【譯述】隋朝大理卿鄭善果的母親崔氏。周代末年，善果的父親誠征讨尉遲迥戰死。她的母親崔氏年仅二十歲就守了寡，父親彦睦想讓女兒改嫁，崔氏懷抱善果說：“婦人没有嫁兩次的道理，况且我丈夫雖然死了，但還有这个孩子，丢弃兒子是不慈愛，背叛丈夫是不講禮義，我本來應當割耳剪發，以表明我誓死不再改嫁的决心。违背禮義，滅絕慈愛，这些事我不敢做。”於是他不再改嫁，一心教育撫養兒子善果，終於使他長大成人。自從守寡，她便不施脂粉，穿家常衣服，她性情又節俭，如果不是祭祀和招待賓客，吃飯從不摆放酒肉。她每天在家靜靜地坐著，從没有出過門。娘家婆家的親戚有紅白喜事，她都多饋赠禮物，但從不親自登門。","sortOrder":50},
  {"id":"s_work_gp_10_51","chapterId":"ch_work_gp_10","text":"【原文】韓觊妻於氏，父實，周大左辅。於氏年十四適於觊，雖生長膏腴，家門鼎貴，而動遵禮度，躬自俭約，宗党敬之。年十八，觊從軍没，於氏哀毀骨立，恸感動路。每朝夕奠祭，皆手自捧持。及免丧，其父以其幼少無子，欲嫁之，誓不許。遂以夫孽子世隆為嗣，身自撫育，愛同己生，訓导有方，卒能成立。自孀居以後，唯時或歸寧。至於親族之家，絕不往來。有尊親就省謁者，送迎皆不出戶庭。蔬食布衣，不聽聲樂，以此終身。隋文帝聞而嘉叹，下詔褒美，表其門闾，長安中號為“節婦闾”。","sortOrder":51},
  {"id":"s_work_gp_10_52","chapterId":"ch_work_gp_10","text":"【譯述】韓觊的妻子於氏，她的父親於實是周大左辅。於氏十四歲的時候就嫁給了韓觊，她雖然生長在富貴人家，但却知禮識節，懂得約束自己的行為，宗族和乡里的人都很敬重她。她十八歲的時候，韓觊當兵而死，於氏悲傷過度，骨瘦如柴，她的哀痛足以讓路人感動。朝夕祭奠丈夫的時候，她都是親自用手捧著供品。服丧期滿後，她父親可怜她年輕又没有孩子，想讓她改嫁，但她堅决不答應。她將丈夫的庶子世隆當作自己的孩子來撫養，慈愛如同自己所生一樣，而且教育有方，最終將这个孩子培養成人。自從守寡之後，每逢過時過節，她才回娘家看看父母，至於其他親戚，她一概不與他们往來。有長辈和親戚來看望她，她送迎都不出大門。吃粗茶淡飯，穿粗布衣服，從不聽聲樂，一直到死。隋文帝聽說後，贊叹一番，併下詔褒奖她，旌表她所居住的里巷。在長安城中，这里被稱為“節婦闾”。","sortOrder":52},
  {"id":"s_work_gp_10_53","chapterId":"ch_work_gp_10","text":"【原文】周虢州司戶王凝妻李氏，家青齊之間。凝卒於官，家素貧，一子尚幼。李氏携其子，負其遺骸以歸。東過开封，止旅舍，主人見其婦人獨携一子而疑之，不許其宿。李氏顧天已暮，不肯去。主人牵其臂而出之。李氏仰天恸曰：“我為婦人，不能守節，而此手為人執耶！不可以一手併污吾身。”即引斧自斷其臂。路人見者，環聚而嗟之，或為之泣下。","sortOrder":53},
  {"id":"s_work_gp_10_54","chapterId":"ch_work_gp_10","text":"开封尹聞之，白其事於朝官，為賜藥封瘡，恤李氏而笞其主人。若此，可謂能清絜矣。","sortOrder":54},
  {"id":"s_work_gp_10_55","chapterId":"ch_work_gp_10","text":"【譯述】周虢州司戶王凝的妻子李氏，家住在青齊之間。王凝死在官署，家里很貧窮，有一个孩子還很小。李氏帶著孩子，去收拾丈夫的遺骨回家。路過开封的時候，她想找一个旅馆住下。主人看見她獨自一人領著一个孩子，就有些懷疑她，不讓她住宿。李氏看看天已經黑了，就不肯離去。主人抓住她的手臂將她拉了出去。李氏仰天痛哭道：“我作為婦人，却不能保守節操，这只手竟被別人抓過了，但我不能再讓这只手來玷污我的全身。”於是她用斧子砍斷了自己的手臂。過路的人都围過來看，而且為之嗟叹，有的還流下了淚。开封府尹聽說了这件事，便禀報了朝廷，併給李氏拿來藥，為她包扎傷口。安撫李氏，鞭打旅馆的主人。像她这樣，可以說是能够保持清白和貞絜了。","sortOrder":55},
  {"id":"s_work_gp_11_1","chapterId":"ch_work_gp_11","text":"家范卷九妻下","sortOrder":1},
  {"id":"s_work_gp_11_2","chapterId":"ch_work_gp_11","text":"女人不妒品自高","sortOrder":2},
  {"id":"s_work_gp_11_3","chapterId":"ch_work_gp_11","text":"【原文】《禮》，自天子至於命士，媵妾皆有數，惟庶人無之，謂之匹夫匹婦。是故《關雎》美後妃，樂得淑女以配君子，慕窈窕，思賢才，而無傷淫之心。至於《樛木》、《螽斯》、《桃夭》、《芣莒》、《小星》，皆美其無妒忌之行。文母十子，眾妾百斯男，此周之所以興也。詩人美之。然則婦人之美，無如不妒矣。","sortOrder":3},
  {"id":"s_work_gp_11_4","chapterId":"ch_work_gp_11","text":"【譯述】在《禮記》里，從天子到有官位和爵位的人，納妾的多少都是有規定的，惟獨平民百姓没有規定，稱為匹夫、匹婦。所以《詩經·關雎》贊美後妃，歌頌淑女許配君子。愛慕窈窕女子，思念有才德的男子，而没有諷刺淫荡的意思。至於《樛木》、《螽斯》、《桃夭》、《芣莒》、《小星》等篇，都是贊美没有嫉妒的行為。周文王的母親生了十个兒子，至於眾妾所生的兒子大概有上百人之多，这正是周所以興旺發達的原因，所以詩人來贊美这件事。这樣說來，婦人最大的美德就是不去嫉妒。","sortOrder":4},
  {"id":"s_work_gp_11_5","chapterId":"ch_work_gp_11","text":"【原文】晉趙衰從晉文公在狄，取狄女叔隗，生盾。文公返國，以女趙姬妻衰，生原同、屏括、樓婴。趙姬請逆盾與其母。衰辭而不敢。姬曰：“不可。得寵而忘舊，不義；好新而慢故，無恩；與人勤於隘阨，富貴而不顧，無禮。弃此三者，何以使人？必逆叔隗！”及盾來，姬以盾為才，固請於公，以為嫡子，而使其三子下之；以叔隗為內子，而己下之。","sortOrder":5},
  {"id":"s_work_gp_11_6","chapterId":"ch_work_gp_11","text":"【譯述】晉國的趙衰跟隨晉文公逃亡到狄國，娶了狄國的女子叔隗為妻。等到晉文公返回晉國後，就把自己的女兒趙姬嫁給了趙衰，併生了原同、屏括和樓婴。趙姬讓趙衰把趙盾和他的母親迎接到晉國來。趙衰没敢答應。趙姬說：“不迎是错誤的。得新寵而忘舊人，不是仁義之舉；喜新而厭舊，没有恩情；與人共度艱難歲月，自己富貴之後就不去理她，不合禮法。丢了这三點，你還怎么去說服別人呢？所以你一定要將叔隗接來。”等到趙盾來了，趙姬認為趙盾很有才華，就堅决要求趙衰將趙盾立為嫡子，而將自己的三个兒子排在趙盾的後面。併以叔隗為趙衰的正妻，自己排在她的後邊。","sortOrder":6},
  {"id":"s_work_gp_11_7","chapterId":"ch_work_gp_11","text":"【原文】楚莊王夫人樊姬曰：“妾幸得備扫除，十有一年矣，未嘗不捐衣食，遣人之鄭衛求美人而進之於王也。妾所進者九人，今賢於妾者二人，與妾同列者七人。妾知妨妾之愛、奪妾之貴也。妾豈不欲擅王之愛、奪王之寵哉？不敢以私蔽公也！”","sortOrder":7},
  {"id":"s_work_gp_11_8","chapterId":"ch_work_gp_11","text":"【譯述】楚莊王夫人樊姬說：“我有幸侍奉大王，已經十一年了，这期間，我經常花費錢财派人到鄭國和衛國搜求美人，進獻給大王。我所進獻的九人，其中比我賢惠的有二人，與我不相上下的有七人。我也知道这樣做會妨礙大王對我的愛，會奪去我的尊貴。我難道不想讓大王只寵愛我一个人吗？我只不過是不敢以私废公罢了。","sortOrder":8},
  {"id":"s_work_gp_11_9","chapterId":"ch_work_gp_11","text":"【原文】宋女宗者，鮑蘇之妻也。既入，養姑甚謹。鮑蘇去而仕於衛，三年而娶外妻焉。女宗之養姑愈謹，因往來者請問鮑蘇不輟，賂遺外妻甚厚。女宗之姒謂女宗曰：“可以去矣。”女宗曰：“何故？”姒曰：“夫人既有所好，子何留乎？”女宗曰：“婦人之所寶，豈以专夫室之愛為善哉？若抗夫室之好，苟以自榮，則吾未知其善也。夫《禮》，天子妻妾十二，諸侯九，大夫三，士二。今吾夫固士也，其有二，不亦宜乎！且婦人有七去，七去之道，妒正為首。姒不教吾以居室之禮，而反使吾為見弃之行，將安用此？”遂不聽，事姑愈謹。宋公聞而美之，表其闾，號曰“女宗”。","sortOrder":9},
  {"id":"s_work_gp_11_10","chapterId":"ch_work_gp_11","text":"【譯述】宋國的女宗是鮑蘇的妻子。結婚後，女宗侍奉婆婆非常謙恭謹慎。","sortOrder":10},
  {"id":"s_work_gp_11_11","chapterId":"ch_work_gp_11","text":"後來，鮑蘇離开家到衛國去做官，三年之後他又在衛國娶了妻子。女宗得知後，不但没有嫉妒，反而贍養婆婆更加小心，只要有順路的人，女宗就委托向鮑蘇問好，而且還給鮑蘇在衛國的妻子帶去非常丰厚的禮品。鮑蘇的一个妾對女宗說：“你應該離开鮑家了。”女宗問：“為什么？”妾說：“夫君既然另有新歡，你還留下幹什么呢？”女宗說：“對於一个婦人來說，她所最寶貴的難道就是獨自擁有丈夫的愛吗？如果只知道獨霸丈夫，反對丈夫另添房室，從而求取自己的榮耀，我是没有看出这其中的高尚來。《禮記》規定，天子可以有十二个妻妾，諸侯可以有九个，大夫可以有三个，士兩个。我的丈夫本來就是士，他有兩个妻子，不也是應該的吗？而且，婦人有七种被休掉的情况，在这七种被休掉的错誤中，嫉妒丈夫的正妻是最大的。你不教給我為人之妻所應遵守的禮義，反讓我做那些有可能被丈夫休掉的事情。我怎么能聽你的話呢？”","sortOrder":11},
  {"id":"s_work_gp_11_12","chapterId":"ch_work_gp_11","text":"於是她不聽这些，對待婆婆更加謹慎小心。宋公聽到这件事後，夸贊她的品行，旌表其門第，尊稱她為“女宗”。","sortOrder":12},
  {"id":"s_work_gp_11_13","chapterId":"ch_work_gp_11","text":"【原文】漢明德馬皇後，伏波將軍援之女也。年十三選入太子宮，接待同列，先人後己，由此見寵。及帝即位，常以皇嗣未廣，每懷忧叹，荐達左右，若恐不及。後宮有進見者，每加慰納。若數所寵引，辄增隆遇，未幾立為皇後。是知婦人不妒，則益為君子所賢。欲专寵自私，則愈疏矣！由其識慮有遠近故也。","sortOrder":13},
  {"id":"s_work_gp_11_14","chapterId":"ch_work_gp_11","text":"【譯述】漢代明德馬皇後是伏波將軍馬援的女兒，她十三歲的時候就被選入太子宮，對待其他嫔妃，能够先人後己，因此她得到了太子的寵愛。太子即位後，她為皇家子弟不多而常常發愁，於是他為皇帝引荐嫔妃，惟恐皇帝不喜歡她们。如果後宮嫔妃有要求主動進見皇上的，她都為之引見。如果有誰被皇帝數次寵幸，待遇馬上就提高了。正因為这樣，她不久就被立為皇後。由此知道女人如果没有妒忌心，就容易博得君子的好感。相反，越想獨霸男人，越是容易被疏遠。做得好坏，这與她们有没有見識有關。","sortOrder":14},
  {"id":"s_work_gp_11_15","chapterId":"ch_work_gp_11","text":"【原文】後唐太祖正室劉氏，代北人也。其次妃曹氏，太原人也。太祖封晉王，劉氏封秦國夫人，無子，性賢，不妒忌，常為太祖言：“曹氏相，當生貴子，宜善待之。”而曹氏亦自謙退，因相得甚歡。曹氏封晉國夫人，後生子，是謂莊宗。太祖奇之。及莊宗即位，册尊曹氏為皇太後，而以嫡母劉氏為皇太妃。太妃往謝太後，太後有慚色。太妃曰：“願吾兒享國無窮，使吾曹獲没於地，以從先君，幸矣！他复何言？”莊宗滅梁入洛，使人迎太後歸洛，居長寿宮。太妃恋陵廟，獨留晉陽。太妃與太後甚相愛，其送太後往洛，涕泣而別，歸而相思慕，遂成疾。太後聞之，欲馳至晉陽视疾；及其卒也，又欲自往葬之。莊宗泣諫，群臣交章請留，乃止。而太後自太妃卒，悲哀不飲食，逾月亦崩。莊宗以妾母加於嫡母，劉後猶不慍，况以妾事女君如禮者乎！若此，可謂能不妒矣。","sortOrder":15},
  {"id":"s_work_gp_11_16","chapterId":"ch_work_gp_11","text":"【譯述】後唐太祖的正室劉氏，是代北人。太祖的次妃曹氏是太原人。太祖被封為晉王的時候，劉氏被封為秦國夫人，她没有生孩子，但很賢惠，不嫉妒，併經常對太祖說：“我給曹氏相面，她一定會生下貴子的，應該善待她。”然而，曹氏也常常謙讓退避，所以她们俩相處得非常好。","sortOrder":16},
  {"id":"s_work_gp_11_17","chapterId":"ch_work_gp_11","text":"曹氏被封為晉國夫人，後來生了兒子，正是莊宗。太祖想起先前劉氏所說的話，感到这件事很神奇。等到莊宗即位的時候，册封曹氏為皇太後，而封嫡母劉氏為皇太妃。太妃去向太後道謝，太後覺得很慚愧。太妃說：“願我们的孩子永保江山，能够讓我们平安地活到老，然後在地下與先君相會，这才是最大的幸運，我们還有什么可說的呢？”後來莊宗滅了梁，進入洛，便派人迎接太後歸洛，居住在長寿宮。太妃由於留恋皇陵宗廟，獨自留在了晉陽。太妃和太後感情非常好，太妃送太後赴洛的時候，洒淚而別。回去後仍思念太後，竟鬱悶成疾。太後得知後，很想親自到晉陽去看她；太妃去世，太後又想親自去安葬太妃。因為莊宗哭著勸諫，大臣们也一再挽留，太後才只好作罢。然而，自從太妃去世，太後也因悲痛而不吃飯，只過了一个多月，也去世了。莊宗將妾母排在嫡母的前面，劉後仍然不惱怒，而况妾侍奉正妻本來就是合乎禮法的呢！","sortOrder":17},
  {"id":"s_work_gp_11_18","chapterId":"ch_work_gp_11","text":"向劉氏这樣的，可以稱得上没有嫉妒之心。","sortOrder":18},
  {"id":"s_work_gp_11_19","chapterId":"ch_work_gp_11","text":"【原文】《葛覃》美後妃恭俭節用，服浣濯之衣。然則婦人固以俭約為美，不以侈麗為美也。","sortOrder":19},
  {"id":"s_work_gp_11_20","chapterId":"ch_work_gp_11","text":"【譯述】《葛覃》贊扬後妃勤俭節約，說她们穿著已經洗過幾次的衣服。这樣說來，作為婦人應以勤俭節約為美德，而不能以奢侈華麗為美。","sortOrder":20},
  {"id":"s_work_gp_11_21","chapterId":"ch_work_gp_11","text":"【原文】漢明德馬皇後，常衣大練，裙不加緣。朔望，諸姬主朝請，望見後袍衣疏粗，反以為綺，就视乃笑。後辭曰：“此繒特宜染色，故用之耳。”六宮莫不叹息。性不喜出入遊觀，未嘗臨御窗牖，又不好音樂。上時幸苑囿離宮，希嘗從行。彼天子之後猶如是，况臣民之妻乎？","sortOrder":21},
  {"id":"s_work_gp_11_22","chapterId":"ch_work_gp_11","text":"【譯述】東漢明德馬皇後經常穿著粗帛衣服，裙子也不加邊飾。每月初一和十五，舉行朝謁之禮，有一次妃嫔们看見馬皇後的衣服粗疏，還以為是上等的絲織品，她们來到跟前一看，不禁相视而笑。馬皇後遮掩道：“这种繒特別容易染色，所以我才穿它。”妃嫔们看見她如此朴素，無不感叹。馬皇後不喜歡外出遊玩觀光，從來不到窗前觀望外面，也不喜好音樂。皇上經常巡幸行宮苑囿，皇後很少隨行。她身為皇後，還如此俭朴簡約，而况一般平民百姓的妻子呢？","sortOrder":22},
  {"id":"s_work_gp_11_23","chapterId":"ch_work_gp_11","text":"【原文】漢鮑宣妻桓氏，歸侍御服飾，著短布裳，挽鹿車。","sortOrder":23},
  {"id":"s_work_gp_11_24","chapterId":"ch_work_gp_11","text":"梁鸿妻屏綺縞，著布衣、麻履，操緝績之具。","sortOrder":24},
  {"id":"s_work_gp_11_25","chapterId":"ch_work_gp_11","text":"【譯述】漢代鮑宣的妻子桓氏，將侍御婦人的服飾放起來，改穿布衣短服，親自拉小車幹活。","sortOrder":25},
  {"id":"s_work_gp_11_26","chapterId":"ch_work_gp_11","text":"梁鸿的妻子把絲綢衣服藏起來，穿布衣麻鞋，親自紡紗織布。","sortOrder":26},
  {"id":"s_work_gp_11_27","chapterId":"ch_work_gp_11","text":"【原文】唐岐陽公主適殿中少監杜悰，謀曰：“上所賜奴婢，卒不肯窮屈。”","sortOrder":27},
  {"id":"s_work_gp_11_28","chapterId":"ch_work_gp_11","text":"奏請納之。上嘉叹，許可。因錫其直，悉自市寒賤可製指者。自是閉門，落然不聞人聲。悰為澧州刺史，主後悰行。郡縣聞主且至，殺牛羊犬馬，數百人供具。主至，從者不過二十人、六七婢，乘驢阘茸，約所至不得肉食。驿吏立門外，舁飯食以返。不數日間，聞於京師，眾哗，說以為異事。悰在澧州三年，主自始入後三年間，不識刺史廳屏。彼天子之女猶如是，况寒族乎？若此，可謂能節俭矣。","sortOrder":28},
  {"id":"s_work_gp_11_29","chapterId":"ch_work_gp_11","text":"【譯述】唐代岐陽公主嫁給殿中少監杜悰為妻，公主和丈夫商量說：“皇上賜給我们的奴婢，最終還是過不慣貧窮的生活。”於是他们奏請皇上不要奴婢。皇上大為贊叹，同意了公主的意見，賞賜給她一些銀錢，公主用这些銀錢買了些出身卑賤又易於指使的人做佣人。從此以後公主閉門不出，家里和和睦睦，安安靜靜。杜驚擔任澧州刺史，公主跟隨前往。","sortOrder":29},
  {"id":"s_work_gp_11_30","chapterId":"ch_work_gp_11","text":"郡、縣官吏聽說公主要來，殺牛、羊、狗、馬，有數百人忙碌，准備招待公主。但公主到後，隨從的人不過二十个，奴婢只有六七个，乘坐的驢子很瘦弱，公主還規定所到地方不得摆設酒宴肉食。只見驿站官吏站在門外，抬來一些簡单的飯菜就回去了。没過幾天，她的事跡傳到京城，議論紛紛，人们都把这件事當作一件少有的奇事來傳扬。杜悰在澧州任職三年，公主在这三年間從未到過他的官府，始終没見過刺史衙門里邊是什么樣子的。她是皇帝的女兒尚且能如此俭朴簡約，而况一般的百姓呢？像这樣的妻子，可以算得上節俭了。","sortOrder":30},
  {"id":"s_work_gp_11_31","chapterId":"ch_work_gp_11","text":"【原文】古之賢婦未有不恭其夫者也，曹大家《女戒》曰：“得意一人，是謂永畢；失意一人，是謂永訖。”由斯言之，夫不可不求其心。然所求者，亦非謂佞媚苟親也。固莫若专心正色，禮義貞絜耳。耳無途聽，目無邪视，出無冶容，入無废飾，無聚群辈，無看视門戶，此則謂专心正色矣。若夫動靜輕脱，视聽陝输，入則亂發坏形，出則窈窕作態，說所不當道，觀所不當视，此謂不能专心正色矣。是以冀缺之妻馌其夫，相待如賓；梁鸿之妻饋其夫，舉案齊眉。若此，可謂能恭謹矣。","sortOrder":31},
  {"id":"s_work_gp_11_32","chapterId":"ch_work_gp_11","text":"【譯述】古代的賢婦對待丈夫無不恭恭敬敬。曹大家的《女戒》說：“得到丈夫的喜愛，妻子就可以終生有靠，失去丈夫的歡愛，妻子就一切都完了。”由此可見，為人妻子一定要得到丈夫的真心疼愛。然而要想得到丈夫的歡心，併不是去諂媚奉承，而是要专心正色嚴肅認真，堅守禮義貞絜。即不道聽途說，目不邪视，外出不妖艳打扮，在家不懶於妆飾，不三五成群聚會閒聊，不到門口去張望，能做到这些，就稱得上是专心正色嚴肅認真了。如果是舉止輕佻、视聽不定，在家披頭散發，出門賣弄風骚，說些不該說的話，看些不該看的事，这就是不能专心正色嚴肅認真。所以冀缺的妻子到田間給丈夫送飯，能够相敬如賓；梁鸿的妻子給丈夫端上飯菜，能够舉案齊眉。像这樣的妻子，就算得上恭敬謹慎了。","sortOrder":32},
  {"id":"s_work_gp_11_33","chapterId":"ch_work_gp_11","text":"【原文】《易》：“家人，六二，無攸遂，在中饋。”《詩·葛覃》美後妃，在父母家，志在女功，為絺绤，服勞辱之事。《采苹》、《采蘩》，美夫人能奉祭祀。彼後夫人猶如是，况臣民之妻，可以端居終日，自安逸乎？","sortOrder":33},
  {"id":"s_work_gp_11_34","chapterId":"ch_work_gp_11","text":"【譯述】《周易》說：“‘家人’卦，處於二位的陰爻表現的是，妻子在家雖没有专斷的權力，但是要管理好家務。”《詩經·葛覃》贊扬後妃，說她们在父母家里從事女工，紡紗織布，還參加體力勞動。《采苹》、《采蘩》稱贊夫人能進行祭祀活動。那些後妃、夫人尚且能如此勤勞，何况一般百姓的妻子呢？難道可以端坐終日、享受安逸吗？","sortOrder":34},
  {"id":"s_work_gp_11_35","chapterId":"ch_work_gp_11","text":"【原文】魯大夫公父文伯退朝，朝其母。其母方績，文伯曰：“以歜之家而主猶績乎？懼幹季孫之怒也，其以歜為不能事主乎！”母叹曰“魯其亡乎！使僮子備官而未之聞耶？王後親織玄紞，公侯之夫人加之以紘綖。","sortOrder":35},
  {"id":"s_work_gp_11_36","chapterId":"ch_work_gp_11","text":"卿之內子為大帶，命婦成祭服，列士之妻加之以朝衣，自庶士以下皆衣其夫。社而賦事，烝而獻功，男女效績，愆則有辟，古之製也。今我寡也，爾又在下位，朝夕處事，猶恐忘先人之業，况有怠惰，其何以避辟！吾冀而朝夕修我曰：‘必無废先人。’爾今曰：‘胡不自安？’以是承君之官，餘懼穆伯之絕嗣也。”","sortOrder":36},
  {"id":"s_work_gp_11_37","chapterId":"ch_work_gp_11","text":"【譯述】魯國的大夫公父文伯退朝後，去拜見母親。母親正在織布，文伯說：“像我们这樣富有的人家，其主人還用得著親自紡織吗？您这樣做會讓季孫不高興的，人家會說我们这樣富有還不能安心侍奉國君？”母親聽了他的話，叹了口氣說：“魯國難道要滅亡了吗？但你難道不知道魯國使僮子備官吗？王後要親自做帽子上的裝飾物玄紞，公侯的夫人再為它加上紘綖，卿的妻子要製做緇帶，大夫的妻子要做祭服，元士的妻子要製做朝服，從下士到一般百姓，都要做衣服給丈夫穿。春天秋天祭祀土神的時候，人人都要忙碌，冬天祭祀的時候，也要有所貢獻。不論男女，都要為國效勞，延誤時間或做错事，都要受到處罰，这是古代就有的製度。現在我守了寡，你又仅是个大夫，我们兢兢業業，還怕不能承繼先人之志，如果再懈怠懶惰，怎能辭其咎？我希望把一切都做好，併且時時警戒自己說：‘一定要對得起先人。’你現在却說：‘為什么要这么辛苦？’你以这樣的認識和態度繼承你父親的官爵，我擔心你父親穆伯没有好的繼承人了。”","sortOrder":37},
  {"id":"s_work_gp_11_38","chapterId":"ch_work_gp_11","text":"【原文】漢明德馬皇後，自為衣袿，手皆裂。皇後猶爾，况他人乎？曹大家《女戒》曰：“晚寢早作，勿憚夙夜，執務私事，不辭剧易。所作必成，手跡整理，是謂勤也。”若此，可謂能勤勞矣。","sortOrder":38},
  {"id":"s_work_gp_11_39","chapterId":"ch_work_gp_11","text":"【譯述】漢代明德馬皇後，自己製做衣服，手都冻裂了。皇後都能这樣勤勞，何况一般人呢？曹大家《女戒》說：“做為人的妻子，晚睡早起，不分晝夜，處理家事，不挑揀難易。所作必成，親手來整理，这就為勤勞。”像这樣，可以說是能勤勞了。","sortOrder":39},
  {"id":"s_work_gp_11_40","chapterId":"ch_work_gp_11","text":"【原文】為人妻者，非徒備此六德而已。又當辅佐君子，成其令名。是以《卷耳》求賢審官，《殷其雷》勸以義，《汝墳》勉之以正，《雞鳴》警戒相成，此皆內助之功也，自涂山至於太姒，其徽風著於經典，無以尚之。周宣王薑後，齊女也。宣王嘗晏起，後脱簪珥，待罪永巷，使其傅母通言於王曰：“妾之淫心見矣，至使君王失禮而晏朝，以見君王樂色而忘德也，敢請婢子之罪。”王曰：“寡人不德，實自生過，非後之罪也。”遂复薑後而勤於政事，早朝晏退，卒成中興之名。故《雞鳴》樂击鼓以告旦，後夫人必鳴珮而去君所，禮也。","sortOrder":40},
  {"id":"s_work_gp_11_41","chapterId":"ch_work_gp_11","text":"【譯述】不過，為人之妻，併非只需要具備以上六种品德就可以了，妻子還應當辅佐丈夫，讓他功成名就。所以《卷耳》求賢審官，《殷其雷》用義來勸戒丈夫，《汝墳》勉励丈夫做人要正直，《雞鳴》警戒相成，这些都是賢內助的功勞。從涂山到太姒，她们的功績載入史籍，無人能比。周宣王薑後是个齊國女子，宣王有一次起床晚了，薑後就取下金簪珥環，待罪於後宮，派她的保姆傳話給宣王說：“因為我顯露淫心，使得君王失禮晚朝，出現了好色忘德的過失，請求君王懲罰我吧。”宣王說：“寡人無德，確是自己有错，併非皇後的過错。”宣王不治薑後的罪，自己從此勤於政事，早上朝晚退朝，終於成就了中興國家的美名。所以《雞鳴》很高興宣示天亮的鼓聲。皇後、夫人必須帶著鳴珮去國君的住所，这是古禮。","sortOrder":41},
  {"id":"s_work_gp_11_42","chapterId":"ch_work_gp_11","text":"【原文】齊桓公好淫樂，衛姬為之不聽。","sortOrder":42},
  {"id":"s_work_gp_11_43","chapterId":"ch_work_gp_11","text":"楚莊王初即位，狩獵畢戈，樊姬諫，不止，乃不食鳥獸之肉。三年，王勤於政事不倦。","sortOrder":43},
  {"id":"s_work_gp_11_44","chapterId":"ch_work_gp_11","text":"【譯述】齊桓公喜好淫樂，衛姬堅持按禮法辦事。","sortOrder":44},
  {"id":"s_work_gp_11_45","chapterId":"ch_work_gp_11","text":"楚莊王刚即位的時候，非常喜歡打獵，樊姬勸諫，他不聽，於是樊姬就不再吃鳥獸的肉，用这种方法來勸諫。三年之後，楚莊王終於能够勤於政事，而且不知疲倦。","sortOrder":45},
  {"id":"s_work_gp_11_46","chapterId":"ch_work_gp_11","text":"【原文】晉文公避驪姬之難，適齊。齊桓公妻之，有馬二十乘，公子安之。","sortOrder":46},
  {"id":"s_work_gp_11_47","chapterId":"ch_work_gp_11","text":"從者以為不可，將行，謀於桑下，蠶妾在其上，以告薑氏。薑氏殺之，而謂公子曰：“子有四方之志？其聞之者，吾殺之矣！”公子曰：“無之。”薑曰：“行也，懷與安，實败名。公子不可。”善與子犯謀，醉而遣之，卒成霸功。","sortOrder":47},
  {"id":"s_work_gp_11_48","chapterId":"ch_work_gp_11","text":"【譯述】晉文公避驪姬之難，到了齊國。齊桓公把薑氏嫁給他為妻，併給他二十乘車馬作為嫁妆。晉文公居然安享富貴，不打算复國了。但跟隨他的那些人認為不能就这樣消沉下去，暗暗打算要離开这里，他们謀於桑下，蠶妾在旁邊聽到了，就告給了薑氏。薑氏殺掉蠶妾，然後對晉文公說：“你们有遠大的志向，將要離开这里？竊聽到你们的機密的人我已經把她殺死了。”晉文公說：“没有这回事。”薑氏說：“你们還是趕快走吧，不舍兒女私情，貪圖安逸，會毀掉你的大事的。”晉文公還是不願放弃安逸的生活，薑氏便與子犯合謀，用酒將他灌醉，然後把他扶上車子拉走。就这樣晉文公最後終於得以回國即位，併且成就了一代霸主的功業。","sortOrder":48},
  {"id":"s_work_gp_11_49","chapterId":"ch_work_gp_11","text":"【原文】陶大夫答子治陶，名譽不興，家富三倍。妻數諫之，答子不用。居五年，從車百乘歸休，宗人击牛而贺之，其妻獨抱兒而泣。姑怒而數之曰：“吾子治陶五年，從車百乘歸休，宗人击牛而贺之。婦獨抱兒而泣，何其不祥也！”婦曰：“夫人能薄而官大，是謂婴害；無功而家昌，是謂積殃。昔令尹子文之治國也，家貧而國富，君敬之，民戴之，故福結於子孫，名垂於後世。今夫子則不然，貪富務大，不顧後害，逢禍必矣！願與少子俱脱。”姑怒，遂弃之。處期年，答子之家果以盜誅，唯其母以老免，婦乃與少子歸，養始終卒天年。","sortOrder":49},
  {"id":"s_work_gp_11_50","chapterId":"ch_work_gp_11","text":"【譯述】陶大夫答子治理陶地的時候，没有好的名聲，家里却非常富裕。妻子幾次勸諫他，他不聽。過了五年，他帶著車馬百乘回家休息，本宗族的人殺牛為他慶贺。唯獨他的妻子抱著孩兒在一邊哭泣。婆婆憤怒地责備她說：“我兒治理陶地五年，帶著車馬百乘歸來休息，族中人殺牛為他慶贺，你却抱著孩子哭泣，多么不吉祥呀！”兒媳婦說：“一个人没有能力却做了大官，就會招來灾禍；做官没有政績而家里富裕，可以說是在積累禍患。先前令尹子文治理國家，家中貧窮，而國家富裕，皇帝敬重他，百姓愛戴他，因此福遺子孫，名留後世。如今我的丈夫却不是这樣，貪求富貴喜好虛名，而不顧後患，必定要招來禍患。我願與孩子一起離去。”婆婆大怒，將兒媳趕出家門。一年之後，果然因為答子貪污财物，全家人被殺，唯獨答子的母親因為年老免於一死。这時，答子的妻子帶著小孩回家贍養婆婆，為婆婆養老送終。","sortOrder":50},
  {"id":"s_work_gp_11_51","chapterId":"ch_work_gp_11","text":"【原文】楚王聞於陵子終賢，欲以為相。使使者持金百镒，往聘迎之。於陵子終入謂其妻曰：“楚王欲以我為相，我今日為相，明日結驷連騎，食方丈於前，子意可乎？”妻曰“夫子織屦以為食，業本辱而無忧者，何也？非與物無治乎，左琴右書，樂在其中矣！夫結驷連騎，所安不過容膝；食方丈於前，所飽不過一肉。以容膝之安、一肉之味而懷楚國之忧，其可乎？亂世多害，吾恐先生之不保命也。”於是，子終出謝使者而不許也。遂相與逃而為人灌園。","sortOrder":51},
  {"id":"s_work_gp_11_52","chapterId":"ch_work_gp_11","text":"【譯述】楚王聽說於陵子終很有才德，就想委任他為宰相。楚王派使者帶著百镒黃金去聘請於陵子終。於陵子終回家對妻子說：“楚王想讓我擔任宰相，我今天當了宰相，明天就坐著豪華的車子，前呼後擁，頓頓吃丰盛的宴席，你認為这樣可以吗？”妻子說：“你現在以編織鞋為生，職業雖然不怎么樣，但是無忧無慮，这是為什么呢？就是因為你遠離是非财货，讀書彈琴，自得其樂。一个人，即便擁有再多的車馬，容身也只不過需要很小的一塊地方；宴席再丰盛，也只不過吃一點肉就飽了。你為得到一點安身之地和一頓飯的好處，竟要負擔整个楚國的忧患和煩惱，值得吗？而且亂世多禍，你如果要接受任命，我害怕你連命都保不住。”於是，於陵子終出來謝絕了楚王的使者，没有接受聘任。他们一起出逃，以為別人种菜園為生。","sortOrder":52},
  {"id":"s_work_gp_11_53","chapterId":"ch_work_gp_11","text":"【原文】漢明德馬皇後，數規諫明帝，辭意款備。時楚獄連年不斷，囚相證引，坐系者甚眾。後慮其多濫，乘間言及，帝惻然感悟，夜起彷徨，為思所納，卒多有降宥。時諸將奏事及公卿较議難平者，帝數以试後。後辄分解趣理，各得其情。每於侍執之际，辄言及政事，多所毗補，而未嘗以家私幹。","sortOrder":53},
  {"id":"s_work_gp_11_54","chapterId":"ch_work_gp_11","text":"【譯述】漢代明德馬皇後，屢次規諫明帝，言辭恳切，思考周到。當時，冤獄連年不斷，囚犯们相互牵連，受到法律懲罰的人非常多。馬皇後擔心用刑過多過濫，便找機會向明帝提起这件事，皇上也感到这件事很重要，併對那些遭受冤獄的人動了惻隱之心。他晚上睡不著覺，起來散步，思考馬皇後的建議併加以采納，最終有許多被冤枉或犯罪较輕的人得到了赦免。當時，將領们所奏的事和公卿们的一些議論有難以决斷的，明帝就每每讓馬皇後來决斷，以此來考察她處理事情的能力。馬皇後每次都能合情合理地分析和處理，她常常利用侍奉明帝的機會，來談她對國家大事的看法，對國事處理提出許多有用的意見。然而她從來没有因為家里的私事來幹預皇上。","sortOrder":54},
  {"id":"s_work_gp_11_55","chapterId":"ch_work_gp_11","text":"【原文】河南樂羊子嘗行路，得遺金一餅，還，以與妻。妻曰：“妾聞志士不飲盜泉之水，廉者不受嗟來之食，况拾遺求利，不污其行乎？”羊子大慚，乃捐金於野，而遠尋師學。一年來歸，妻跑問其故。羊子曰：“久行懷思，無它異也。”妻乃引刀趁機而言曰：“此織生自蠶茧，成於機杼，一絲而累，以至於寸，累寸不已，遂成丈匹。今若斷斯織也，則絹失成功，稽废時月。夫子積學，當日知其所亡，以就懿德。若中道而歸，何異斷斯織乎？”羊子感其言，复還終業，遂七年不反。妻常躬勤養姑，又遠饋羊子。","sortOrder":55},
  {"id":"s_work_gp_11_56","chapterId":"ch_work_gp_11","text":"【譯述】河南樂羊子有一次在路上行走拾到一餅金子，回家將金子交給妻子。","sortOrder":56},
  {"id":"s_work_gp_11_57","chapterId":"ch_work_gp_11","text":"妻子說：“我聽說有志氣的人不喝盜泉之水，有骨氣的人不吃嗟來之食，何况你靠揀東西求利，難道不怕玷污了你的品行吗？”羊子非常慚愧，就把金子扔到了野外，然後到很遠的地方去拜師求學。一年之後羊子回來，妻子跪著問他為何要回來。羊子說：“我出去久了，有些想家，併没有別的原因。”妻子就拿了把刀走到織機前，對羊子說：“蠶茧抽絲，機抒織布，一根根絲線織成一寸一寸的布，慢慢積累，就成了一丈布、一匹布。如果現在將它砍斷，不但这匹絹織不成功，而且還荒废了時間。你去求學，也是在積累知識，應當每天了解你所不懂的新的知識，以修成懿德美行。如果中途輟學回家，其結果與砍斷这匹布有何不同？”羊子聽了妻子的話非常感動，又回去繼續學習，此後七年没有再回家。妻子在家辛勤勞動，贍養婆婆，還要供給羊子求學所需的錢物。","sortOrder":57},
  {"id":"s_work_gp_11_58","chapterId":"ch_work_gp_11","text":"【原文】吳許升少為博徒，不治操行。妻呂榮嘗躬勤家業，以奉養其姑。數勸升修學，每有不善，辄流涕進規。榮父積忿疾升，乃呼榮，欲改嫁之。榮叹曰：“命之所遭，義無離二。”終不肯歸。升感激自励，乃尋師遠學，遂以成名。","sortOrder":58},
  {"id":"s_work_gp_11_59","chapterId":"ch_work_gp_11","text":"【譯述】吳國許升年輕的時候是个赌徒，不註意節操品行。他的妻子呂榮辛勤操持家業，侍奉婆婆。妻子多次勸告許升讀書學習，每當許升有不好的行為時，她就淚流滿面地規勸。呂榮的父親非常痛恨許升，他要將呂榮叫回家，想讓她改嫁。呂榮叹息道：“命中既然給我安排了这樣的丈夫，我必須忠貞如一，不再改嫁。”呂榮始終不肯回家。許升非常感激，從此奋發向上，外出拜師求學，後來一舉成名。","sortOrder":59},
  {"id":"s_work_gp_11_60","chapterId":"ch_work_gp_11","text":"【原文】唐文德長孫皇後崩，太宗謂近臣曰：“後在宮中，每能規諫，今不复聞善言，內失一良佐，以此令人哀耳！”此皆以道辅佐君子者也。","sortOrder":60},
  {"id":"s_work_gp_11_61","chapterId":"ch_work_gp_11","text":"【譯述】唐朝文德長孫皇後去世，太宗對近臣說：“皇後在宮中的時候，常常規勸我，現在我再聽不到她的良言，在內失去了一个很好的助手，这讓我很覺悲哀。”以上这些事例都是為人之妻能够用道義來辅佐丈夫成就事業的典范。","sortOrder":61},
  {"id":"s_work_gp_11_62","chapterId":"ch_work_gp_11","text":"【原文】漢長安大昌里人妻，其夫有仇人，欲報其夫而無道径。聞其妻之孝有義，乃劫其妻之父，使要其女為中，譎父呼其女告之。女計念，不聽之，則殺父，不孝；聽之，則殺夫，不義。不孝不義，雖生不可以行於世。欲以身當之，乃且許诺曰：“旦日在樓新沭，東首臥則是矣！妾請开牖戶待之。”還其家，乃譎其夫，使臥他所。因自沭，居樓上東首，开牖戶而臥。夜半，仇家果至，斷頭持去，明而视之，乃其妻首也。他人哀痛之，以為有義，遂釋，不殺其夫。","sortOrder":62},
  {"id":"s_work_gp_11_63","chapterId":"ch_work_gp_11","text":"【譯述】漢朝長安大昌里某人的妻子，她的丈夫有个仇人，那个仇人想報复她的丈夫却没有辦法。仇人聽說她非常孝敬父母，就劫持了她的父親，以此來要挟她共同害她丈夫，併且假托她父親，要她說出丈夫在哪里。","sortOrder":63},
  {"id":"s_work_gp_11_64","chapterId":"ch_work_gp_11","text":"她想，不聽仇人的話，父親就要被殺，这是不孝順；如果順從仇人，丈夫就會被殺，这是没有仁義。既不孝順又不仁義，雖然活著也没脸見他人了。最後她决定自己替丈夫去死，於是就許诺那个仇人說：“明天我们在樓上沐浴，頭朝東而睡的就是我丈夫，我打开窗戶等你。”回到家，她就骗她丈夫，讓他睡到別的地方。她自己洗了澡，在樓上頭朝東而睡，而且打开了窗戶。半夜，仇人果然來了，砍下她的頭拿走，等到天亮一看，原來是仇人的妻子的頭。仇人非常哀痛，認為这个女人很講禮義，就放過了她的丈夫。","sortOrder":64},
  {"id":"s_work_gp_11_65","chapterId":"ch_work_gp_11","text":"【原文】光啟中，楊行密围秦彦、畢師鋒，扬州城中食盡，人相食，軍士掠人而賣其肉。有洪州商人周迪，夫婦同在城中，迪餒且死，其妻曰：“今飢窮势不兩全，君有老母，不可以不歸，願鬻妾於屠肆，以濟君行道之資。”遂詣屠肆自鬻，得白金十兩以授迪，號泣而別。迪至城門，以其半賂守者，求去。守者詰之，迪以實對。守者不之信，與共詣屠肆验之，見其首已在案上。眾聚觀，莫不叹息，競以金帛遺之。迪收其餘骸，負之而歸。古之節婦，有以死徇其夫者，况敢庸奴其夫乎？","sortOrder":65},
  {"id":"s_work_gp_11_66","chapterId":"ch_work_gp_11","text":"【譯述】唐代光啟年間，楊行密围攻秦彦和畢師铎，扬州城內没有一點糧食，到了人吃人的地步，士兵紛紛搶掠人口，販賣人肉。洪州商人周迪和妻子都住在城中。周迪十分飢饿，快要死了，妻子說：“現在我们因飢饿而處於窮途末路，咱俩不可能同時保全性命，你家中還有老母親，你不能不回去，我願意把自己賣給肉鋪，帮助你筹集路費。”於是她就到肉鋪將自己賣掉，得到十兩白金，將其交給丈夫，與他哭泣告別。周迪來到城門，用五兩白金賄賂守門人，請求放他出去。守門人盤問他，他如實回答。守門人不相信他的話，與他一起來肉鋪查验，果然看見他妻子的頭顱已經在案上了。於是眾人围觀，無不叹息，紛紛送給他錢财。周迪將妻子殘留下來的骸骨收集起來，背回家乡。古代的節烈婦女，能够以死殉夫，又哪里會役使其丈夫呢？","sortOrder":66},
  {"id":"s_work_gp_12_1","chapterId":"ch_work_gp_12","text":"家范卷十舅甥/舅姑/婦妾/乳母","sortOrder":1},
  {"id":"s_work_gp_12_2","chapterId":"ch_work_gp_12","text":"嘴里含飯，救活外甥","sortOrder":2},
  {"id":"s_work_gp_12_3","chapterId":"ch_work_gp_12","text":"【原文】秦康公之母，晉獻公之女。文公遭驪姬之難，未反而秦姬卒。穆公納文公。康公時為太子，赠送文公於渭之陽，念母之不見也，曰：“我見舅氏，如母存焉！”故作渭陽之詩。","sortOrder":3},
  {"id":"s_work_gp_12_4","chapterId":"ch_work_gp_12","text":"【譯述】秦康公的母親是晉獻公的女兒。文公遭遇驪姬之難，尚未回國，秦姬就死了。穆公收留了文公。當時康公為太子，把舅舅文公送到渭陽，他想到母親已死，就說：“我見到了舅舅，就好象看見了我的母親一樣。”因此還寫了渭陽之詩。","sortOrder":4},
  {"id":"s_work_gp_12_5","chapterId":"ch_work_gp_12","text":"【原文】漢魏郡霍谞，有人誣谞舅宋光於大將軍梁商者，以為妄刊文章，坐系洛陽詔獄，掠考困極。谞時年十五，奏記於商，為光訟冤，辭理明切。商高谞才志，即為奏，原先罪，由是顯名。","sortOrder":5},
  {"id":"s_work_gp_12_6","chapterId":"ch_work_gp_12","text":"【譯述】東漢魏郡有个人叫霍谞。有人在大將軍梁商那里誣告霍谞的舅舅宋光。宋光以亂寫文章罪，被關進洛陽監獄，在嚴刑拷打之下，困苦不堪。當時霍谞年仅十五歲，就上書梁商，為舅舅喊冤，言辭意思明白恳切。","sortOrder":6},
  {"id":"s_work_gp_12_7","chapterId":"ch_work_gp_12","text":"梁商器重霍谞有才能、有志氣，便為宋光向上邊說好話，宽恕了他的罪過。霍谞因此而出了名。","sortOrder":7},
  {"id":"s_work_gp_12_8","chapterId":"ch_work_gp_12","text":"【原文】晉司空郄鑒，頰邊貯飯以活外甥周翼。鑒夢，翼為剡令，解職而歸，席苫心丧三年。此皆舅甥之有恩者也。","sortOrder":8},
  {"id":"s_work_gp_12_9","chapterId":"ch_work_gp_12","text":"【譯述】晉司空郄鑒在飢荒年月靠嘴里含一口飯救活了外甥周翼。郄鑒去世後，周翼正擔任剡縣縣令，他辭職回家，為舅舅服丧三年。以上这些都是舅甥之間有恩情的典范。","sortOrder":9},
  {"id":"s_work_gp_12_10","chapterId":"ch_work_gp_12","text":"舅姑孝順公婆如父母","sortOrder":10},
  {"id":"s_work_gp_12_11","chapterId":"ch_work_gp_12","text":"【原文】晏子稱：“姑慈而從，婦聽而婉，禮之善物也。”","sortOrder":11},
  {"id":"s_work_gp_12_12","chapterId":"ch_work_gp_12","text":"【譯述】晏子說：“婆婆慈祥而有威信，媳婦聽話而又溫婉，是禮法中最好的表現。”","sortOrder":12},
  {"id":"s_work_gp_12_13","chapterId":"ch_work_gp_12","text":"【原文】《禮》：“子婦有勤勞之事，雖甚愛之，姑縱之而寧數休之。子婦未孝未敬，勿庸疾怨，姑教之。若不可教，而後怒之；不可怒，子放婦出而不表禮焉。”","sortOrder":13},
  {"id":"s_work_gp_12_14","chapterId":"ch_work_gp_12","text":"【譯述】《禮記》說：“婆婆雖然疼愛兒媳，但還是要讓她去辛勤勞作，不能舍不得讓她幹活，實在不得已，可以讓她在幹活時多休息幾次，不要累坏了身體就可以了。兒媳婦不孝敬公婆，公婆不要生氣，也不要怨恨，先教育她。如果教育不聽，然後再訓斥她。訓斥也不起作用，就讓兒子休掉她，但不表明她的失禮之罪。","sortOrder":14},
  {"id":"s_work_gp_12_15","chapterId":"ch_work_gp_12","text":"【原文】季康子問於公父文伯之母曰：“主亦有以語肥也？”對曰：“吾聞之先姑曰：‘君子能勞，後世有繼。’子夏聞之，曰：‘善哉！’商聞之曰：‘古之嫁者，不及舅姑，謂之不幸。’夫婦，學於舅姑者，禮也。”","sortOrder":15},
  {"id":"s_work_gp_12_16","chapterId":"ch_work_gp_12","text":"【譯述】季康子問公父文伯的母親：“您有話要告訴我吗？”回答說：“我聽我婆婆說：‘君子如果能任勞任怨，子孫後代就會興旺發達。’子夏聽後說：‘對啊！’商曾聽說：‘古代女子出嫁，如果没有公婆，就是不幸。’所以，兒媳婦必須向公婆學習做人的道理，这是禮法所規定的。”","sortOrder":16},
  {"id":"s_work_gp_12_17","chapterId":"ch_work_gp_12","text":"【原文】唐禮部尚書王珪子敬直，尚南平公主。禮有婦見舅姑之儀，自近代，公主出降，此禮皆废。珪曰：“今主上钦明，動循法製，吾受公主謁見，豈為身榮，所以成國家之美耳！”遂與其妻就席而坐，令公主親執笲，行盥饋之道，禮成而退。是後，公主下降，有舅姑者，皆備婦禮，自珪始也。","sortOrder":17},
  {"id":"s_work_gp_12_18","chapterId":"ch_work_gp_12","text":"【譯述】唐代禮部尚書王珪的兒子王敬直娶南平公主為妻。從前禮法中本有媳婦拜見公婆的儀式，可是到了後來，公主出嫁後拜見公婆的禮節就废止了。王敬直與南平公主結婚時，王珪說：“如今皇上英明，所有的事都依據法律，我接受公主的拜謁，併不是為了自己的虛榮，而是要成全國家的美德。”於是王珪就與妻子坐在首席上，讓公主親自拿著笲，履行盥洗和獻飯等拜見公婆的儀式，公主行禮完畢後才退下。此後，公主出嫁，只要公婆健在，就要行拜見公婆的禮儀，这个禮儀的施行始於王珪。","sortOrder":18},
  {"id":"s_work_gp_12_19","chapterId":"ch_work_gp_12","text":"婦不與公婆辯曲直","sortOrder":19},
  {"id":"s_work_gp_12_20","chapterId":"ch_work_gp_12","text":"【原文】《內則》：婦事舅姑，與子事父母略同。","sortOrder":20},
  {"id":"s_work_gp_12_21","chapterId":"ch_work_gp_12","text":"舅没則姑老，冢婦所祭祀賓客，每事必請於姑，介婦請於冢婦。舅姑使冢婦，毋怠、不友、無禮於介婦。舅姑若使介婦，無敢敵耦於冢婦，不敢併行，不敢併命，不敢併坐。","sortOrder":21},
  {"id":"s_work_gp_12_22","chapterId":"ch_work_gp_12","text":"凡婦不命運私室，不敢退。婦將有事，大小必請於舅姑。子婦無私货，無私蓄，無私器，不敢私假，不敢私與。婦或賜之飲食、衣服、布帛、佩帨、芷蘭，則受而獻諸舅姑。舅姑受之則喜，如新受賜。若反賜之，則辭。不得命，如更受賜，藏以待乏。婦若有私親兄弟，將與之，則必复請其故，賜而後與之。","sortOrder":22},
  {"id":"s_work_gp_12_23","chapterId":"ch_work_gp_12","text":"【譯述】《內則》說：媳婦侍奉公婆，跟兒子侍奉父母基本相同。公公死後，婆婆老了之後，婆婆不再管理家事。接管家政的長子媳婦，不論是舉行祭祀，還是招待賓客，大小事情都要向婆婆請示，介婦又要向長子媳婦請示。公婆教育長子媳婦不能怠慢介婦，不能對介婦無禮、不友好。公婆指使介婦，介婦更不能驕傲，不可跟長子媳婦相比，不敢和她一樣向別人發號施令，也不能和她坐在一起。","sortOrder":23},
  {"id":"s_work_gp_12_24","chapterId":"ch_work_gp_12","text":"婆婆未叫媳婦回房，媳婦就不敢回房休息。媳婦若有私事，不論事情大小，都要報告公婆。媳婦不能有自己的錢财、積蓄、器物，不能向他人借東西，也不能私自送給別人東西。有人送給媳婦飲食、衣服、布帛、佩帨、芷蘭等東西，媳婦接受後就要交給公婆。公婆得到後很高興，如同自己得到了饋赠一樣。如果公婆將那些東西再送給媳婦，媳婦就要拒絕接受。實在推辭不掉，就要像重新接受公婆賜物一樣，將它收藏起來，留待缺乏時再拿出來用。媳婦如果有親戚、兄弟，想把这些禮物送給親戚、兄弟，一定要重新請示公婆，公婆再次賞賜自己之後，才能去送。","sortOrder":24},
  {"id":"s_work_gp_12_25","chapterId":"ch_work_gp_12","text":"【原文】曹大家《女戒》曰：舅姑之意豈可失哉？固莫尚於曲從矣！姑雲不爾而是，固宜從命；姑雲爾而非，猶宜順命。勿得违戾是非，爭分曲直，此則所謂曲從矣。故《女憲》曰：“婦如影响，焉不可賞？”","sortOrder":25},
  {"id":"s_work_gp_12_26","chapterId":"ch_work_gp_12","text":"【譯述】曹大家《女戒》說：“公婆的意願怎么能够违拗呢？所以最好的辦法就是去曲從！婆婆說不要这樣，說對了，本當聽從；婆婆說这樣，但說错了，也應當聽從。不要和公婆爭辯是非曲直，只能一味地順從，这就是所謂的“曲從”。所以《女憲》說：“媳婦如果能够順從公婆，怎么不可以奖賞她呢？”","sortOrder":26},
  {"id":"s_work_gp_12_27","chapterId":"ch_work_gp_12","text":"【原文】漢廣漢薑詩妻，同郡庞盛之女也。詩事母至孝，妻奉順尤篤，母好飲江水，去舍六七里，妻常沂流而汲。後值風，不時得還，母渴，詩责而遣之。妻乃寄止鄰舍，晝夜紡績，市珍羞，使鄰母以意自遺其姑。如是者久之。姑怪問鄰母，鄰母具對。姑感慚呼還，恩養愈謹。其子後因遠汲溺死，妻恐姑哀傷，不敢言，而托以行學不在。","sortOrder":27},
  {"id":"s_work_gp_12_28","chapterId":"ch_work_gp_12","text":"【譯述】東漢時廣漢人薑詩的妻子，是同郡庞盛的女兒。薑詩侍奉母親非常孝順，妻子侍奉婆婆尤其溫順。薑母喜歡喝江水，但那條江離家有六七里遠，薑詩妻子常常去打江水。有一次薑妻去打水，遇到大風，没有按時回來。薑母口渴，薑詩责備妻子併將她趕出家門。薑妻便寄居附近的一戶人家家里，晝夜紡紗織布，用挣來的錢購買珍貴的食物，讓鄰居老太太以自己的名義送給婆婆。这樣持續了很長時間，婆婆感到奇怪，就詢問鄰居老太太到底怎么回事，鄰居老太太如實相告。婆婆聽後非常感動，而且覺得有些對不住她，就將薑妻接回了家。薑妻贍養婆婆更加恭謹。她的兒子因為到遠處打水被水淹死，薑妻擔心婆婆為此哀傷，就不敢說出真情，谎稱他到外邊求學去了。","sortOrder":28},
  {"id":"s_work_gp_12_29","chapterId":"ch_work_gp_12","text":"【原文】河南樂羊子，從學七年不反，妻常躬勤養姑。嘗有它舍雞谬入園中，姑盜殺而食之。妻對雞不餐而泣。姑怪，問其故。妻曰：“自傷居貧，使食它肉。”姑竟弃之。然則舅姑有過，婦亦可幾諫也。","sortOrder":29},
  {"id":"s_work_gp_12_30","chapterId":"ch_work_gp_12","text":"【譯述】河南的樂羊子，到外邊求學，七年不回家，妻子在家辛勤地贍養婆婆。有一次別人家的一只雞誤入她家的園中，婆婆悄悄將它殺掉燉了吃。樂羊子的妻子不吃雞肉，反而哭泣。婆婆感到奇怪，問她為什么。她說：“我自慚家里貧窮，讓您吃他人的雞肉。”婆婆聽後就將雞丢弃了。如此說來，公婆如果有過错，媳婦也可以勸諫。","sortOrder":30},
  {"id":"s_work_gp_12_31","chapterId":"ch_work_gp_12","text":"【原文】後魏樂部郎胡長命妻張氏，事姑王氏甚謹。太安中，京師禁酒，張以姑老且患，私為醞之，為有司所糾。王氏詣曹，自首由己私酿。張氏曰：“姑老抱患，張主家事，姑不知酿。”主司不知所處。平原王陆麗以状奏，文成義而赦之。","sortOrder":31},
  {"id":"s_work_gp_12_32","chapterId":"ch_work_gp_12","text":"【譯述】後魏樂部郎胡長命的妻子張氏，侍奉婆婆王氏非常恭謹。太安年間，京師規定不准賣酒。張氏因為婆婆上年紀了，而且有病，就悄悄在家里為婆婆酿酒，結果被官府抓獲。婆婆王氏親自到官府，說酒是她自己酿的，與媳婦没關系。可媳婦張氏却說：“我婆婆年老有病，是我主持家事，婆婆根本就不知道这件事。”斷案的人竟不知該怎么處置。平原王陆麗將这件事寫成奏章上奏，文成為她们婆媳之間的恩義之舉所感動，就赦免了她们。","sortOrder":32},
  {"id":"s_work_gp_12_33","chapterId":"ch_work_gp_12","text":"【原文】唐鄭義宗妻庐氏，略涉書史，事舅姑甚得婦道。嘗夜有強盜數十人，持杖鼓噪，逾垣而入。家人悉奔竄，唯有姑獨在堂。庐冒白刃，往至姑侧，為賊捶击，幾至於死。賊去後，家人問，何獨不懼？庐氏曰：“人所以異禽獸者，以其有仁義也。鄰里有急，尚相赴救，况在於姑而可委弃？若萬一危禍，豈宜獨生！”其姑每雲：“古人稱，歲寒然後知松柏之後凋也，吾今乃知庐新婦之心矣！”若庐氏者，可謂能知義矣。","sortOrder":33},
  {"id":"s_work_gp_12_34","chapterId":"ch_work_gp_12","text":"【譯述】唐代鄭義宗的妻子庐氏，略通書史，她侍奉公婆，很符合婦道。有一天黑夜，幾十名強盜手持棍棒，喊叫著翻牆而入。家里人都逃走了，只有婆婆一人在廳堂。庐氏冒著強盜的刀劍，跑到婆婆身邊，差點被賊寇打死。強盜退走，家人問庐氏為什么不怕？庐氏回答說：“人之所以不同於禽獸，是因為人懂得仁義道德。鄰居家如果有危急情况，尚且能相救，况且是自己的婆婆，怎么能丢下不管呢？如果她遭了什么禍患，我有何脸面活下去呢？”她的婆婆常稱贊說：“古人說歲寒然後知松柏後凋，我現在知道媳婦庐氏對我的孝心了！”像庐氏这樣的媳婦，可以稱得上是知道禮義了。","sortOrder":34},
  {"id":"s_work_gp_12_35","chapterId":"ch_work_gp_12","text":"【原文】《詩》：“何彼秾矣，美王姬也。雖則王姬，亦下嫁於諸侯，車服不系其夫，下王後一等，猶執婦道，以成肅雍之德。”","sortOrder":35},
  {"id":"s_work_gp_12_36","chapterId":"ch_work_gp_12","text":"【譯述】《毛詩》說：“《何彼秾矣》这首詩，是贊美周王的女兒王姬的品德的。她雖然是王姬，却下嫁給諸侯。她的車子和衣服都不以尊貴來壓她的夫家，而是比王後低一个等級。她是周王的女兒，仍嚴守婦道，成全恭敬和順的美德。","sortOrder":36},
  {"id":"s_work_gp_12_37","chapterId":"ch_work_gp_12","text":"【原文】舜妻，尧之二女。行婦道於虞氏。","sortOrder":37},
  {"id":"s_work_gp_12_38","chapterId":"ch_work_gp_12","text":"【譯述】舜的妻子是尧的兩个女兒。她们侍奉舜的家人，嚴格遵守婦道。","sortOrder":38},
  {"id":"s_work_gp_12_39","chapterId":"ch_work_gp_12","text":"【原文】唐岐陽公主，憲宗之嫡女，穆宗之母妹，母懿安郭皇後，尚父子儀之孫也。適工部尚書杜悰，逮事舅姑。杜氏大族，其他宜為婦禮者，不翅數千人。主卑委怡煩，奉上撫下，終日惕惕，屏息拜起，一同家人禮度。二十餘年，人未嘗以絲發間指為貴驕。承奉大族，時歲獻饋，吉凶赙助，必經親手。姑涼國太夫人寢疾，比丧及葬，主奉養，蚤夜不解帶，親自嘗藥，粥飯不經心手，一不以進。既而哭泣哀號，感動它人。彼天子之女，猶不敢失婦道，奈何臣民之女，乃敢恃其貴富以驕其舅姑？為婦若此，為夫者宜弃之，為有司者治其罪可也。","sortOrder":39},
  {"id":"s_work_gp_12_40","chapterId":"ch_work_gp_12","text":"【譯述】唐代岐陽公主是唐憲宗的嫡女，唐穆宗的同母妹妹。她的母親懿安郭皇後，是郭子儀的孫女。岐陽公主嫁給工部尚書杜悰，开始侍奉公婆。杜家是个大家族，除了公婆，媳婦應該對其行婦禮的人還有幾千人。公主謙卑怡順，侍奉公婆，愛撫後代，整天忙忙碌碌，行施各种禮儀，一律與家里其他成員一樣。她在杜家二十多年，人们没有指责過她一絲一毫的驕貴。她侍奉大家族，無論祭祀，還是操辦紅白喜事，都要親自動手。婆婆涼國夫人從臥病在床到死，公主親自侍奉，晝夜衣不解帶，親自為婆婆端湯送藥。等到婆婆死後，她哭泣哀號，感動他人。公主是皇帝的女兒，尚且不敢不守為婦之道，而平民的女兒，怎么敢凭借富貴而怠慢公婆呢？為人媳婦如果这樣不懂禮，丈夫應該將她抛弃，讓有關部門治她的罪。","sortOrder":40},
  {"id":"s_work_gp_12_41","chapterId":"ch_work_gp_12","text":"妾妾之地位與奴婢同","sortOrder":41},
  {"id":"s_work_gp_12_42","chapterId":"ch_work_gp_12","text":"【原文】《內則》：“雖婢妾，衣服飲食必後長者。”","sortOrder":42},
  {"id":"s_work_gp_12_43","chapterId":"ch_work_gp_12","text":"【譯述】《內則》說：“即便是奴婢和妾，也要遵守禮法，飲食起居都要先禮讓長辈和年紀大的人，自己排在後面。”","sortOrder":43},
  {"id":"s_work_gp_12_44","chapterId":"ch_work_gp_12","text":"【原文】妾事女君，猶臣事君也。尊卑殊絕，禮節宜明。是以“绿衣黃裳”，詩人所刺；慎夫人與窦後同席，袁盎引而却之；董宏請尊丁傅，師丹劾奏其罪。皆所以防微杜漸，抑禍亂之原也。或者主母屈己以下之，猶當貶抑退避，謹守其分，况敢挟其主父與子之势，陵慢其女君乎？","sortOrder":44},
  {"id":"s_work_gp_12_45","chapterId":"ch_work_gp_12","text":"【譯述】妾侍奉嫡妻，和臣下侍奉君主是一个道理。她们的尊貴和卑下不同，禮節也要區別分明。所以“黃衣绿裳”是詩人所諷刺的；慎夫人與窦後同席而坐，袁盎就回避；董宏請尊丁傅，師丹就向皇上彈劾他的罪。这都是為了防微杜漸，不讓禍亂在微小的地方开始萌生。即便有的嫡妻主母主動降低自己的身份，也應當謙虛退讓，謹守自己的本分。更怎么能依仗主父和兒子的势力，欺凌和慢待正室呢？","sortOrder":45},
  {"id":"s_work_gp_12_46","chapterId":"ch_work_gp_12","text":"【原文】衛宗二順者，衛宗室靈王之夫人及其傅妾也。秦滅衛君，乃封靈王世家，使奉其祀。靈王死，夫人無子而守寡，傅妾有子代後。傅妾事夫人，八年不衰，供養愈謹。夫人謂傅妾曰：“孺子養我甚謹，子奉祀而妾事我，我不願也。且吾聞，主君之母不妾事人，今我無子，於禮斥絀之人也，而得留以盡節，是我幸也。今又煩孺子不改故節，我甚內慚！","sortOrder":46},
  {"id":"s_work_gp_12_47","chapterId":"ch_work_gp_12","text":"吾願出居外，以時相見，我甚便之。”傅妾泣而對曰：“夫人欲使靈氏受三不祥耶？公不幸早終，是一不祥也；夫人無子而婢妾有子，是二不祥也；夫人欲居外，使婢妾居內，是三不祥也。妾聞忠臣事君，無時懈倦；孝子養親，患無日也。妾豈敢以少貴之故，变妾之節哉？供養，固妾之職也，夫人又何勤乎？”夫人曰：“無子之人，而辱主君之母，雖子歇爾，眾人謂我不知禮也。吾終願居外而已。”傅妾退而謂其子曰：“吾聞君子處順，奉上下之儀，修先古之禮，此順道也。今夫人難我，將欲居外，使我處內，逆也。處逆而生，豈若守順而死哉？”遂欲自殺。其子泣而守之，不聽。夫人聞之，懼，遂許傅妾留，終年供養不衰。","sortOrder":47},
  {"id":"s_work_gp_12_48","chapterId":"ch_work_gp_12","text":"【譯述】衛宗二順是衛國宗室靈王的夫人和他的傅妾。秦國滅掉衛國國君後，封衛國宗室的靈王，讓他繼承衛君宗族的香火。靈王去世後，他的夫人守寡又没有兒子，但他的傅妾有兒子，為靈王傳宗接代。傅妾侍奉夫人整整八年毫不懈怠，而且供養更加謹慎。夫人對傅妾說：“你贍養我非常恭謹，你為靈王延續了香火，還要以妾的身份來侍奉我，我不願意这樣。現在你的兒子是咱家的主君，我聽說主君的母親不能以妾的身份去侍奉人，我没有給靈王留下子嗣，按照禮法是應當被冷落废黜的人，然而還能够留在衛家，已經是我的幸運了。現在又得讓你遵守過去的禮節，我的心里很感慚愧！我願意到外邊去另外居住，我们時間長了互相見个面，我覺得这樣對我很便當。”傅妾聽後哭著說：“夫人你莫非想讓靈王家貪上三件不好的事情吗？靈王不幸早死，这是第一件不好的事；夫人没有子嗣而奴婢傅妾却有兒子，这是第二件不好的事；夫人想住在外邊，反讓奴婢傅妾住在家里，这是第三件不好的事。我聽說忠臣侍奉君主没有懈怠和厭倦的時候；孝順的子女供養父母親，生怕父母親早離开人世。我又怎么敢因為身份稍微有點变化就改变節操呢？供養夫人本來就是我的職责，夫人又哪里用得著多心呢？”夫人說：“我是个没有子嗣的人，而有辱主君的母親，雖然你一片好意，願意这樣侍奉我，但世人還以為我不懂得禮呢。我還是决定要到外邊去居住。”傅妾出來對他的兒子說：“我聽說君子應當處順，行為都要符合禮義，这就叫做順。","sortOrder":48},
  {"id":"s_work_gp_12_49","chapterId":"ch_work_gp_12","text":"現在夫人給我出了一道難題，她要到外邊去居住，讓我住在家里，这是大逆不道。與其顶著大逆不道的罪名活著，還不如遵守禮法去死！”於是她想自殺。她的兒子哭泣著看守在她身邊，併勸說她，可她不聽。夫人聽說後，很害怕，於是答應傅妾留下來。而傅妾還像以往那樣，長年供養夫人，毫不懈怠。","sortOrder":49},
  {"id":"s_work_gp_12_50","chapterId":"ch_work_gp_12","text":"【原文】後唐莊宗不知禮，尊其所生為太後，而以嫡母為太妃。太妃不以慍，太後不敢自尊，二人相好，終始不衰，是亦近世所難。","sortOrder":50},
  {"id":"s_work_gp_12_51","chapterId":"ch_work_gp_12","text":"【譯述】後唐的莊宗不懂得禮法，將他的生母尊為太後，而封嫡母為太妃。","sortOrder":51},
  {"id":"s_work_gp_12_52","chapterId":"ch_work_gp_12","text":"但是太妃併没有因此而懷恨，太後也不敢自尊自大。兩个人自始自終和睦相處，这也是現在一件難能可貴的事。","sortOrder":52},
  {"id":"s_work_gp_12_53","chapterId":"ch_work_gp_12","text":"乳母保母義重如山","sortOrder":53},
  {"id":"s_work_gp_12_54","chapterId":"ch_work_gp_12","text":"【原文】《內則》：“異為孺子室於宮中，擇於諸母與可者，必求其宽裕、慈惠、溫良、恭敬、慎而寡言者，使為子師，其次為慈母，其次為保母。皆居於室，他人無事不往。”","sortOrder":54},
  {"id":"s_work_gp_12_55","chapterId":"ch_work_gp_12","text":"【譯述】《內則》說：“應當為嫡子在宮中另辟一室居住，挑選性情宽厚、仁慈賢惠、溫順賢良、謙恭禮敬、謹慎寡言的人來做嫡子的教師、慈母和保姆，他们和嫡子住在一起，負责嫡子的教育，照顧他的生活，其他人没有事情不能隨意進出嫡子的房間。”","sortOrder":55},
  {"id":"s_work_gp_12_56","chapterId":"ch_work_gp_12","text":"【原文】魯孝公義保臧氏。初，孝公父武公與其二子——長子括、中子戲——朝周宣王。宣王立戲為魯太子。武公薨，戲立，是為懿公。孝公時號公子稱，最少。義保與其子俱入宮養公子稱。括之子曰伯御，與魯人作亂，攻殺懿公而自立，求公子稱於宮中，入殺之。義保聞伯御將殺稱，衣其子以稱之衣，臥於稱之處，伯御殺之。義保遂抱稱以出，遇稱之舅魯大夫於外。舅問：“稱死乎？”義保曰：“不死，在此。”舅曰：“何以得免？”義保曰：“以吾子代之。”義保遂抱以逃。十一年，魯大夫皆知稱之在保，於是請周天子殺伯御，立稱，為孝公。","sortOrder":56},
  {"id":"s_work_gp_12_57","chapterId":"ch_work_gp_12","text":"【譯述】魯孝公的義保臧氏。最初，孝公的父親武公與他的兩个兒子——長子括、中子戲——朝見周宣王，周宣王立戲為魯太子。武公死後，戲繼位，这就是懿公。其時孝公號公子稱，年齡最小。義保帶著兒子進入宮中撫養公子稱。括的兒子名叫伯御，與魯人發動叛亂，殺死懿公而自立，又到宮中尋找公子稱，想殺死他。義保聽說伯御要殺公子稱，就把稱的衣服穿在自己兒子的身上，讓兒子睡在公子稱的床上，結果被伯御殺死。義保抱起稱出宮，在宮外遇到稱的舅舅魯大夫，舅舅問：“稱死了吗？”義保說：“没有死，在这里。”舅舅問：“稱怎么免於一死的？”義保回答說：“用我的兒子代替了稱。”於是義保抱著稱逃了出去。十一年，魯大夫都知道稱在義保那里，就請求周天子殺掉伯御，立稱為諸侯，是為孝公。","sortOrder":57},
  {"id":"s_work_gp_12_58","chapterId":"ch_work_gp_12","text":"【原文】秦攻魏，破之，殺魏王，誅諸公子，而一公子不得。令魏國曰：“得公子者，賜金千镒；匿之者，罪至夷。”公子乳母與公子俱逃。魏之故臣見乳母，識之，曰：“乳母固無恙乎？”乳母曰：“嗟乎！吾奈公子何。”故臣曰：“今公子安在？吾聞秦令曰，有能得公子者，賜金千镒；匿之者，罪至夷！乳母傥知其處乎？而言之，則可以得千金；知而不言，則崑弟無類矣！”乳母曰：“吁！我不知公子之處。”故臣曰：“我聞公子與乳母俱逃。”曰：“吾雖知之，亦終不可以言。”故臣曰：“今魏國已破亡，族已滅矣！子匿之，尚誰為乎？”母曰：“吁！夫見利而反上者逆，畏死而弃義者，亂也。今持逆亂而以求利，吾不為也。且夫凡為人養子者，務生之，非為殺之也，豈可以利賞畏誅之故，废正義而行逆節哉？妾不能生而令公子禽矣！”乳母遂抱公子逃於深泽之中。故臣以告秦軍，追見，爭射之。乳母以身為公子蔽矢，矢著身者數十，與公子俱死。秦君聞之，貴其能守忠死義，乃以卿禮葬之，祠以太牢，寵其兄為五大夫，賜金百镒。","sortOrder":58},
  {"id":"s_work_gp_12_59","chapterId":"ch_work_gp_12","text":"【譯述】秦國攻破魏國，殺掉魏王，還殺掉了魏王的幾个公子，但是有一个公子没有找到，於是秦國就在魏國傳令：“找到公子的，賞賜千镒金子；有隱藏公子的，就要殺掉他的全族。”这个公子的乳母與公子一起逃亡。魏國的一个舊臣看到乳母，認出了她，就說：“乳母別來無恙？”乳母說：“唉呀，我不知公子怎么辦。”舊臣說：“公子現在在哪里？我聽說秦國下了令，誰找到公子，賞賜千镒金子；誰隱藏公子，就誅滅全家。乳母知道公子的住處吗？如果說出來，可以得到千镒金子；如果你知道不說出來，你的兄弟就活不成了！”乳母說：“吁！我不知道公子在哪兒。”老臣說：“我聽說公子是和你一起逃走的。”乳母說：“我即便知道，也不說出來。”舊臣說：“現在魏國已經滅亡，魏王宗族也被消滅，你隱藏公子，為的是誰呢？”乳母說：“唉！見利就上的人大逆不道，怕死而弃義的人就是亂臣賊子。現在持逆作亂以圖利，是我所不願意的，况且為人撫養孩子，為的是讓他生存下去，併非是為了殺死他，我怎么能因為求利、怕死而去抛弃正義、為非作亂呢？我不能為了自己活命就讓公子被人捉去！”乳母就抱著公子逃到深山里面。舊臣將公子的行蹤報告給秦軍，秦軍追上去，爭著用箭射他们。乳母用身體為公子擋箭，射到身上的箭多達幾十支，最後她與公子一起被射死。秦國國王聽說了这件事，非常欣賞乳母能够竭忠盡義，就下令按照卿的規格埋葬了她，而且用太牢祭祀她，還封她的哥哥為五大夫，併賞賜百镒金子。","sortOrder":59},
  {"id":"s_work_gp_12_60","chapterId":"ch_work_gp_12","text":"【原文】唐初，王世充之臣獨孤武都謀叛歸唐，事覺誅死。子師仁始三歲，世充怜其幼，不殺，命禁掌之。其乳母王蘭英求自髡鉗，入保養師仁，世充許之。蘭英鞠育備至。時丧亂凶飢，人多饿死，蘭英乞丐捃拾，每有所得，辄歸哺師仁，自惟啖土飲水而已。久之，诈為捃拾，竊抱師仁奔長安。高祖嘉其義，下詔曰：“師仁乳母王氏，慈惠有聞，撫育無倦，提携遺幼，背逆歸朝，宜有褒隆，以錫其號，可封寿永郡君。”","sortOrder":60},
  {"id":"s_work_gp_12_61","chapterId":"ch_work_gp_12","text":"【譯述】唐朝初年，王世充的大臣獨孤武都密謀叛变王世充，歸順唐朝，事情败露而被殺。他的兒子師仁仅三歲，世充可怜他幼小，没有殺，命令放在宮中撫養。師仁的乳母王蘭英自願受髡鉗，入宮撫養師仁，王世充答應了她。蘭英撫養師仁，無微不至。这時由於戰亂和飢荒，很多人饿死了，蘭英到處乞讨，捡拾，只要得到一點吃的，就拿回去喂師仁，而她自己只是吃點土、喝點水而已。過了很長時間，她谎稱捡拾穀子，悄悄地抱著師仁跑到長安。唐高祖嘉奖她的仁義，下詔說：“師仁的乳母王氏，以慈惠而聞名，撫育別人的遺孤，不知疲倦，而且背逆歸朝，應該給以褒奖，以宣扬她的名聲，可以封她為寿永郡君。”","sortOrder":61},
  {"id":"s_work_gp_12_62","chapterId":"ch_work_gp_12","text":"【原文】五代漢鳳翔節度使侯益入朝，右衛大將軍王景崇叛於鳳翔，有怨於益，盡殺其家屬七十餘人。益孫延廣尚襁褓，乳母劉氏以己子易之，拖延廣而逃，乞食於路，以達大梁，歸於益家。呜呼！人無貴賤，顧其為善何如耳！觀此乳保，忘身殉義，字人之孤，名流後世，雖古烈士，何以過哉！","sortOrder":62},
  {"id":"s_work_gp_12_63","chapterId":"ch_work_gp_12","text":"【譯述】五代後漢鳳翔節度使侯益入朝謁見皇上，右衛大將軍王景崇在鳳翔反叛，他跟侯益有仇，就殺死侯益的家屬七十多人。侯益的孫子延廣還在襁褓之中，乳母劉氏用自己的兒子換了延廣，抱著延廣逃跑，沿路乞讨，終於到了大梁，回到侯益的家中。呜呼，人没有貴賤之分，關鍵是看他做没做好事。看这些乳母，舍身取義，替別人撫養孤兒，名傳後世，即便是古代那此堅貞不屈的刚強之士，也未必超過她们。","sortOrder":63},
  {"id":"s_work_gp_13_1","chapterId":"ch_work_gp_13","text":"附一：司馬光傳(選自《宋史》)","sortOrder":1},
  {"id":"s_work_gp_13_2","chapterId":"ch_work_gp_13","text":"司馬光字君實，陝州夏縣人也。父池，天章閣待製。光生七歲，凛然如成人，聞講左氏春秋，愛之，退為家人講，即了其大指。自是手不釋書，至不知飢渴寒暑。群兒戲於庭，一兒登瓮，足跌没水中，眾皆弃去，光持石击瓮破之，水迸，兒得活。其後京、洛間畫以為圖。仁宗寶元初，中進士甲科。年甫冠，性不喜華靡，聞喜宴獨不戴花，同列語之曰：“君賜不可违。”乃簪一枝。","sortOrder":2},
  {"id":"s_work_gp_13_3","chapterId":"ch_work_gp_13","text":"除奉禮郎，時池在杭，求签蘇州判官事以便親，許之。丁內外艱，執丧累年，毀瘠如禮。服除，签書武成軍判官事，改大理評事，補國子直講。枢密副使庞籍荐為馆閣校勘，同知禮院。","sortOrder":3},
  {"id":"s_work_gp_13_4","chapterId":"ch_work_gp_13","text":"中官麥允言死，給滷簿。光言：“繁纓以朝，孔子且猶不可。允言近習之臣，非有元勋大勞，而赠以三公官，給一品滷簿，其视繁纓，不亦大乎？”夏竦賜謚文正，光言：“此謚之至美者，竦何人，可以當之？”改文莊。加集賢校理。","sortOrder":4},
  {"id":"s_work_gp_13_5","chapterId":"ch_work_gp_13","text":"從庞籍辟，通判併州。麟州屈野河西多良田，夏人蠶食其地，為河東患。籍命光按视，光建：“筑二堡以製夏人，募民耕之，耕者從則籴賤，亦可漸纾河東貴籴遠输之忧。”籍從其策；而麟將郭恩勇且狂，引兵夜渡河，不設備，没於敵，籍得罪去。光三上書自引咎，不報。籍没，光升堂拜其妻如母，撫其子如崑弟，時人賢之。","sortOrder":5},
  {"id":"s_work_gp_13_6","chapterId":"ch_work_gp_13","text":"改直秘閣、开封府推官。交趾貢異獸，謂之麟，光言：“真伪不可知，使其真，非自至不足為瑞，願還其獻。”又奏賦以風。修起居註，判禮部。有司奏日當食，故事食不滿分，或京師不見，皆表贺。光言：“四方見，京師不見，此人君為陰邪所蔽；天下皆知而朝廷獨不知，其為灾當益甚，不當贺。”從之。","sortOrder":6},
  {"id":"s_work_gp_13_7","chapterId":"ch_work_gp_13","text":"同知諫院。蘇轍答製策切直，考官胡宿將黜之，光言：“轍有愛君忧國之心，不宜黜。”詔置末級。","sortOrder":7},
  {"id":"s_work_gp_13_8","chapterId":"ch_work_gp_13","text":"仁宗始不豫，國嗣未立，天下寒心而莫敢言。諫官范镇首發其議，光在併州聞而繼之，且貽書勸镇以死爭。至是，复面言：“臣昔通判併州，所上三章，願陛下果斷力行。”帝沉思久之，曰：“得非欲選宗室為繼嗣者乎？此忠臣之言，但人不敢及耳。”光曰：“臣言此，自謂必死，不意陛下开納。”帝曰：“此何害，古今皆有之。”光退未聞命，复上疏曰：“臣向者進說，意謂即行，今寂無所聞，此必有小人言陛下春秋鼎盛，何遽為不祥之事。小人無遠慮，特欲仓卒之际，援立其所厚善者耳。‘定策國老’、‘門生天子’之禍，可勝言哉？”帝大感動曰：“送中書。”光見韓琦等曰：“諸公不及今定議，異日禁中夜半出寸紙，以某人為嗣，則天下莫敢违。”琦等拱手曰：“敢不盡力。”未幾，詔英宗判宗正，辭不就，遂立為皇子，又稱疾不入。光言：“皇子辭不赀之富，至於旬月，其賢於人遠矣。然父召無诺，君命召不俟駕，願以臣子大義责皇子，宜必入。”英宗遂受命。","sortOrder":8},
  {"id":"s_work_gp_13_9","chapterId":"ch_work_gp_13","text":"兖國公主嫁李玮，不相能，詔出玮衛州，母楊歸其兄璋，主入居禁中。光言：“陛下追念章懿太後，故使玮尚主。今乃母子離析，家事流落，獨無雨露之感乎？玮既黜，主安得無罪？”帝悟，降主沂國，待李氏恩不衰。","sortOrder":9},
  {"id":"s_work_gp_13_10","chapterId":"ch_work_gp_13","text":"進知製誥，固辭，改天章閣待製兼侍講、知諫院。時朝政頗姑息，胥吏喧哗則逐中執法，輦官悖慢則退宰相，衛士凶逆而獄不窮治，軍卒詈三司使而以為非犯階級。光言皆陵遲之漸，不可以不正。","sortOrder":10},
  {"id":"s_work_gp_13_11","chapterId":"ch_work_gp_13","text":"充媛董氏薨，赠淑妃，輟朝成服，百官奉慰，定謚，行册禮，葬給滷簿。光言：“董氏秩本微，病革方拜充媛。古者婦人無謚，近製惟皇後有之。滷簿本以賞軍功，未嘗施於婦人。唐平陽公主有舉兵佐高祖定天下功，乃得給。至韦庶人始令妃主葬日皆給鼓吹，非令典，不足法。”時有司定後宮封赠法，後與妃俱赠三代，光論：“妃不當與後同，袁盎引却慎夫人席，正為此耳。天聖親郊，太妃止赠二代，而况妃乎？”","sortOrder":11},
  {"id":"s_work_gp_13_12","chapterId":"ch_work_gp_13","text":"英宗立，遇疾，慈聖光獻後同聽政。光上疏曰：“昔章獻明肅有保佑先帝之功，特以親用外戚小人，負謗海內。今攝政之际，大臣忠厚如王曾，清純如張知白，刚正如魯宗道，质直如薛奎者，當信用之；猥鄙如馬季良，讒諂如羅崇勋者，當疏遠之，則天下服。”","sortOrder":12},
  {"id":"s_work_gp_13_13","chapterId":"ch_work_gp_13","text":"帝疾愈，光料必有追隆本生事，即奏言：“漢宣帝為孝昭後，終不追尊衛太子、史皇孫；光武上繼元帝，亦不追尊鉅鹿、南頓君，此萬世法也。”後詔兩製集議濮王典禮，學士王珪等相视莫敢先，光獨奋筆書曰：“為人後者為之子，不得顧私親。王宜准封赠期親尊屬故事，稱為皇伯，高官大國，極其尊榮。”議成，珪即命吏以其手稿為按。既上與大臣意殊，御史六人爭之力，皆斥去。光乞留之，不可，遂請與俱貶。","sortOrder":13},
  {"id":"s_work_gp_13_14","chapterId":"ch_work_gp_13","text":"初，西夏遣使致祭，延州指使高宜押伴，傲其使者，侮其國主，使者訴於朝。光與呂誨乞加宜罪，不從。明年，夏人犯邊，殺略吏士。趙滋為雄州，专以猛悍治邊，光論其不可。至是，契丹之民捕魚界河，伐柳白溝之南，朝廷以知雄州李中祐為不材，將代之。光謂：“國家當戎夷附順時，好與之計较末節，及其桀驁，又從而姑息之。近者西禍生於高宜，北禍起於趙滋；時方賢此二人，故邊臣皆以生事為能，漸不可長。宜敕邊吏，疆場細故辄以矢刃相加者，罪之。”","sortOrder":14},
  {"id":"s_work_gp_13_15","chapterId":"ch_work_gp_13","text":"仁宗遺賜直百餘萬，光率同列三上章，謂：“國有大忧，中外窘乏，不可专用乾興故事。若遺賜不可辭，宜許侍從上進金錢佐山陵。”不許。光乃以所得珠為諫院公使錢，金以遺舅氏，義不藏於家。後還政，有司立式，凡後有所取用，當覆奏乃供。光雲：“當移所屬使立供已，乃具數白後，以防矯伪。”","sortOrder":15},
  {"id":"s_work_gp_13_16","chapterId":"ch_work_gp_13","text":"曹佾無功除使相，兩府皆遷官。光言：“陛下欲以慰母心，而遷除無名，則宿衛將帥、內侍小臣，必有觊望。”已而遷都知任守忠等官，光复爭之，因論：“守忠大奸，陛下為皇子，非守忠意，沮坏大策，離間百端，賴先帝不聽；及陛下嗣位，反覆交構，國之大賊。乞斬於都市，以謝天下。”责守忠為節度副使，蘄州安置，於下快之。","sortOrder":16},
  {"id":"s_work_gp_13_17","chapterId":"ch_work_gp_13","text":"詔刺陝西義勇二十萬，民情驚撓，而紀律疏略不可用。光抗言其非，持白韓琦。琦曰：“兵貴先聲，谅祚方桀驁，使骤聞益兵二十萬，豈不震慑？”光曰：“兵之貴先聲，為無其實也，獨可欺之於一日之間耳。","sortOrder":17},
  {"id":"s_work_gp_13_18","chapterId":"ch_work_gp_13","text":"今吾雖益兵，實不可用，不過十日，彼將知其詳，尚何懼？”琦曰：“君但見慶歷間乡兵刺為保捷，忧今复然，已降敕榜與民約，永不充軍戍邊矣。”光曰：“朝廷嘗失信，民未敢以為然，雖光亦不能不疑也。”琦曰：“吾在此，君無忧。”光曰：“公長在此地，可也；異日他人當位，因公見兵，用之運糧戍邊，反掌間事耳。”琦嘿然，而訖不為止。不十年，皆如光慮。","sortOrder":18},
  {"id":"s_work_gp_13_19","chapterId":"ch_work_gp_13","text":"王廣淵除直集賢院，光論其奸邪不可近：“昔漢景帝重衛綰，周世宗薄張美。廣淵當仁宗之世，私自結於陛下，豈忠臣哉？宜黜之以厲天下。“進龍圖閣直學士。","sortOrder":19},
  {"id":"s_work_gp_13_20","chapterId":"ch_work_gp_13","text":"神宗即位，擢為翰林學士，光力辭。帝曰：“古之君子，或學而不文，或文而不學，惟董仲舒、扬雄兼之。卿有文學，何辭為？”對曰：“臣不能為四六。”帝曰：“如兩漢製詔可也；且卿能進士取高第，而雲不能四六，何邪？”竟不獲辭。","sortOrder":20},
  {"id":"s_work_gp_13_21","chapterId":"ch_work_gp_13","text":"御史中丞王陶以論宰相不押班罢，光代之，光言：“陶由論宰相罢，則中丞不可复為。臣願俟既押班，然後就職。”許之。遂上疏論修心之要三：曰仁，曰明，曰武；治國之要三：曰官人，曰信賞，曰必罰。其說甚備。且曰：“臣獲事三朝，皆以此六言獻，平生力學所得，盡在是矣。”御樂院內臣，國朝常用供奉官以下，至內殿崇班則出；近歲暗理官資，非祖宗本意。因論高居簡奸邪，乞加遠竄。章五上，帝為出居簡，盡罢寄資者。既而复留二人，光又力爭之。張方平參知政事，光論其不葉物望，帝不從。還光翰林兼侍讀學士。","sortOrder":21},
  {"id":"s_work_gp_13_22","chapterId":"ch_work_gp_13","text":"光常患歷代史繁，人主不能遍覽，遂為通志八卷以獻。英宗悅之，命置局秘閣，續其書。至是，神宗名之曰《資治通鑒》，自製《序》授之，俾日進讀。","sortOrder":22},
  {"id":"s_work_gp_13_23","chapterId":"ch_work_gp_13","text":"詔錄潁邸直省官四人為閤門祗候，光曰：“國初草創，天步尚艱，故御極之初，必以左右舊人為腹心耳目，謂之隨龍，非平日法也。閤門祗候在文臣為馆職，豈可使厮役為之。”","sortOrder":23},
  {"id":"s_work_gp_13_24","chapterId":"ch_work_gp_13","text":"西戎部將嵬名山欲以橫山之眾，取谅祚以降，詔邊臣招納其眾。光上疏極論，以為：“名山之眾，未必能製谅祚。幸而勝之，滅一谅祚，生一谅祚，何利之有？若其不勝，必引眾歸我，不知何以待之。臣恐朝廷不獨失信谅祚，又將失信於名山矣。若名山餘眾尚多，還北不可，入南不受，窮無所歸，必將突據邊城以救其命。陛下不見侯景之事乎？”","sortOrder":24},
  {"id":"s_work_gp_13_25","chapterId":"ch_work_gp_13","text":"上不聽，遣將种諤發兵迎之，取綏州，費六十萬，西方用兵，蓋自此始矣。","sortOrder":25},
  {"id":"s_work_gp_13_26","chapterId":"ch_work_gp_13","text":"百官上尊號，光當答詔，言：“先帝親郊，不受尊號。末年有獻議者，謂國家與契丹往來通信，彼有尊號我獨無，於是复以非時奉册。昔匈奴冒頓自稱‘天地所生日月所置匈奴大单於’，不聞漢文帝复為大名以加之也。願追述先帝本意，不受此名。”帝大悅，手詔奖光，使善為答辭，以示中外。","sortOrder":26},
  {"id":"s_work_gp_13_27","chapterId":"ch_work_gp_13","text":"執政以河朔旱傷，國用不足，乞南郊勿賜金帛。詔學士議，光與王珪、王安石同見，光曰：“救灾節用，宜自貴近始，可聽也。”安石曰：“常袞辭堂饌，時以為袞自知不能，當辭位不當辭祿。且國用不足，非當世急務，所以不足者，以未得善理财者故也。”光曰：“善理财者，不過頭會箕斂爾。”安石曰：“不然，善理财者，不加賦而國用足。”","sortOrder":27},
  {"id":"s_work_gp_13_28","chapterId":"ch_work_gp_13","text":"光曰：“天下安有此理？天地所生财货百物，不在民，則在官，彼設法奪民，其害乃甚於加賦。此蓋桑羊欺武帝之言，太史公書之以見其不明耳。”爭議不已。帝曰：“朕意與光同，然姑以不允答之。”會安石草詔，引常袞事责兩府，兩府不敢复辭。","sortOrder":28},
  {"id":"s_work_gp_13_29","chapterId":"ch_work_gp_13","text":"安石得政，行新法，光逆疏其利害。邇英進讀，至曹參代萧何事，帝曰：“漢常守萧何之法不变，可乎？”對曰：“寧獨漢也，使三代之君常守禹、湯、文、武之法，雖至今存可也。漢武取高帝約束紛更，盜賊半天下；元帝改孝宣之政，漢業遂衰。由此言之，祖宗之法不可变也。”呂惠卿言：“先王之法，有一年一变者，‘正月始和，布法象魏’是也；有五年一变者，巡守考製度是也；有三十年一变者，‘刑罰世輕世重’是也。光言非是，其意以風朝廷耳。”帝問光，光曰：“布法象魏，布舊法也。諸侯变禮易樂者，王巡守則誅之，不自变也。刑新國用輕典，亂國用重典，是為世輕世重，非变也。且治天下譬如居室，敝則修之，非大坏不更造也。公卿侍從皆在此，願陛下問之。三司使掌天下财，不才而黜可也，不可使執政侵其事。今為製置三司條例司，何也？”宰相以道佐人主，安用例？苟用例，則胥吏矣。今為看詳中書條例司，何也？”惠卿不能對，則以他語詆光。帝曰：“相與論是非耳，何至是。”光曰：“平民舉錢出息，尚能蠶食下戶，况縣官督责之威乎！”惠卿曰：“青苗法，願取則與之，不願不強也。”光曰：“愚民知取债之利，不知還债之害，非獨縣官不強，富民亦不強也。昔太宗平河東，立籴法，時米斗十錢，民樂與官為市。其後物貴而和籴不解，遂為河東世世患。","sortOrder":29},
  {"id":"s_work_gp_13_30","chapterId":"ch_work_gp_13","text":"臣恐異日之青苗，亦猶是也。”帝曰：“坐仓秋米何如？”坐者皆起，光曰：“不便。”惠卿曰：“籴米百萬斛，則省東南之漕，以其錢供京師。”光曰：“東南錢荒而粒米狼戾，今不籴米而漕錢，弃其有餘，取其所無，農末皆病矣！”侍講吳申起曰：“光言，至論也。”","sortOrder":30},
  {"id":"s_work_gp_13_31","chapterId":"ch_work_gp_13","text":"它日留對，帝曰：“今天下汹汹者，孫叔敖所謂‘國之有是，眾之所惡’也。”光曰：“然。陛下當論其是非。今條例司所為，獨安石、韓絳、惠卿以為是耳，陛下豈能獨與此三人共為天下邪？”帝欲用光，訪之安石。安石曰：“光外托劘上之名，內懷附下之實。所言盡害政之事，所與盡害政之人，而欲置之左右，使與國論，此消長之大機也。光才豈能害政，但在高位，則異論之人倚以為重。韓信立漢赤幟，趙卒氣奪，今用光，是與異論者立赤幟也。”","sortOrder":31},
  {"id":"s_work_gp_13_32","chapterId":"ch_work_gp_13","text":"安石以韓琦上疏，臥家求退。帝乃拜光枢密副使，光辭之曰：“陛下所以用臣，蓋察其狂直，庶有補於國家。若徒以祿位榮之，而不取其言，是以天官私非其人也。臣徒以祿位自榮，而不能救生民之患，是盜竊名器以私其身也。陛下誠能罢製置條例司，追還提舉官，不行青苗、助役等法，雖不用臣，臣受賜多矣。今言青苗之害者，不過謂使者骚動州縣，為今日之患耳。而臣之所忧，乃在十年之外，非今日也。夫民之貧富，由勤惰不同，惰者常乏，故必資於人。今出錢貸民而斂其息，富者不願取，使者以多散為功，一切抑配。恐其逋負，必令貧富相保，貧者無可偿，則散而之四方；富者不能去，必责使代偿數家之負。春算秋計，展轉日滋，貧者既盡，富者亦貧。十年之外，百姓無复存者矣。又盡散常平錢穀，专行青苗，它日若思复之，將何所取？富室既盡，常平已废，加之以師旅，因之以飢饉，民之羸者必委死溝壑，壮者必聚而為盜賊，此事之必至者也。”抗章至七八，帝使謂曰：“枢密，兵事也，官各有職，不當以他事為辭。”對曰：“臣未受命，則猶侍從也，於事無不可言者。”安石起视事，光乃得請，遂求去。","sortOrder":32},
  {"id":"s_work_gp_13_33","chapterId":"ch_work_gp_13","text":"以端明殿學士知永興軍。宣撫使下令分義勇戍邊，選諸軍驍勇士，募市井惡少年為奇兵；調民造幹，悉修城池樓橹，關辅骚然。光極言：“公私困敝，不可舉事，而京兆一路皆內郡，繕治非急。宣撫之令，皆未敢從，若乏軍興，臣當任其责。”於是一路獨得免。徙知許州，趣入觀觐，不赴；請判西京御史台歸洛，自是絕口不論事。而求言詔下，光讀之感泣，欲嘿不忍，乃复陳六事，又移書责宰相吳充，事見《充傳》。蔡天申為察訪，妄作威福，河南尹、轉運使敬事之如上官；嘗朝謁應天院神御殿，府獨為設一班，示不敢與抗。光顧謂台吏曰：“引蔡寺丞歸本班。”吏即引天申立監竹木務官富贊善之下。天申窘沮，即日行。元丰五年，忽得語涩疾，疑且死，豫作遺表置臥內，即有缓急，當以界所善者上之。官製行，帝指御史大夫曰：“非司馬光不可。”又將以為東宮師傅。蔡確曰：“國是方定，願少遲之。”《資治通鑒》未就，帝尤重之，以為賢於荀悅《漢紀》，數促使終篇，賜以潁邸舊書二千四百卷。及書成，加資政殿學士。凡居洛陽十五年，天下以為真宰相，田夫野老皆號為司馬相公，婦人孺子亦知其為君實也。","sortOrder":33},
  {"id":"s_work_gp_13_34","chapterId":"ch_work_gp_13","text":"帝崩，赴闕臨，衛士望見，皆以手加額曰：“此司馬相公也。”所至，民遮道聚觀，馬至不得行，曰：“公無歸洛，留相天子，活百姓。”哲宗幼冲，太皇太後臨政，遣使問所當先，光謂：“开言路。”詔榜朝堂。而大臣有不悅者，設六語雲：“若陰有所懷；犯非其分；或扇搖機事之重；或迎合已行之令；上以僥幸希進；下以眩惑流俗。若此者，罰無赦。”後复命示光，光曰：“此非求諫，乃拒諫也。人臣惟不言，言則入六事矣。”乃具論其情，改詔行之，於是上封者以千數。","sortOrder":34},
  {"id":"s_work_gp_13_35","chapterId":"ch_work_gp_13","text":"起光知陳州，過闕，留為門下侍郎。蘇軾自登州召還，緣道人相聚號呼曰：“寄謝司馬相公，毋去朝廷，厚自愛以活我。”是時天下之民，引領拭目以觀新政，而議者猶謂“三年無改於父之道”，但毛舉細事，稍塞人言。光曰：“先帝之法，其善者雖百世不可变也。若安石、惠卿所建，為天下害者，改之當如救焚拯溺。况太皇太後以母改子，非子改父。”眾議甫定。遂罢保甲团教，不复置保馬；废市易法，所储物皆鬻之，不取息，除民所欠錢；京東鐵錢及茶鹽之法，皆复其舊。或謂光曰：“熙、丰舊臣，多巧小人，他日有以父子義間上，則禍作矣。”光正色曰：“天若祚宗社，必無此事。”於是天下釋然，曰：“此先帝本意也。”","sortOrder":35},
  {"id":"s_work_gp_13_36","chapterId":"ch_work_gp_13","text":"元祐元年复得疾，詔朝會再拜，勿舞蹈。時青苗、免役、將官之法猶在，而西戎之議未决。光叹曰：“四患未除，吾死不瞑目矣。”折簡與呂公著雲：“光以身付医，以家事付愚子，惟國事未有所托，今以屬公。”乃論免役五害，乞直降敕罢之。諸將兵皆隸州縣，軍政委守令通决。废提舉常平司，以其事歸之轉運、提點刑獄。邊計以和戎為便。謂監司多新進少年，務為刻急，令近臣於郡守中選舉，而於通判中舉轉運判官。又立十科荐士法。皆從之。","sortOrder":36},
  {"id":"s_work_gp_13_37","chapterId":"ch_work_gp_13","text":"拜尚書左仆射兼門下侍郎，免朝觐，許乘肩舆，三日一入省。光不敢當，曰：“不見君，不可以视事。”詔令子康扶入對，且曰：“毋拜。”遂罢青苗錢，复常平粜籴法。兩宮虛己以聽。遼、夏使至，必問光起居，敕其邊吏曰：“中國相司馬矣，毋輕生事，开邊隙。”光自見言行計從，欲以身徇社稷，躬親庶務，不舍晝夜。賓客見其體羸，舉諸葛亮食少事煩以為戒，光曰：“死生，命也。”為之益力。病革，不复自覺，諄諄如夢中語，然皆朝廷天下事也。","sortOrder":37},
  {"id":"s_work_gp_13_38","chapterId":"ch_work_gp_13","text":"是年九月薨，年六十八。太皇太後聞之恸，與帝即臨其丧，明堂禮成不贺，赠太師、溫國公，遂以一品禮服，赙銀絹七千。詔戶部侍郎趙瞻、內侍省押班冯宗道護其丧，歸葬陝州。謚曰文正，賜碑曰忠清粹德。京師人罢市往弔，鬻衣以致奠，巷哭以過車。及葬，哭者如哭其私親。","sortOrder":38},
  {"id":"s_work_gp_13_39","chapterId":"ch_work_gp_13","text":"嶺南封州父老，亦相率具祭，都中及四方皆盡像以祀，飲食必祝。","sortOrder":39},
  {"id":"s_work_gp_13_40","chapterId":"ch_work_gp_13","text":"光孝友忠信，恭俭正直，居處有法，動作有禮。在洛時，每往夏縣展墓，必過其兄旦，旦年將八十，奉之如嚴父，保之如婴兒。自少至老，語未嘗妄，自言：“吾無過人者，但平生所為，未嘗有不可對人言者耳。”誠心自然，天下敬信，陝、洛間皆化其德，有不善，曰：“君實得無知之乎？”","sortOrder":40},
  {"id":"s_work_gp_13_41","chapterId":"ch_work_gp_13","text":"光於物澹然無所好，於學無所不通，惟不喜釋、老，曰：‘其微言不能出吾書，其誕吾不信也。“洛中有田三頃，丧妻，賣田以葬，惡衣菲食以終其身。","sortOrder":41},
  {"id":"s_work_gp_13_42","chapterId":"ch_work_gp_13","text":"紹聖初，御史周秩首論光誣謗先帝，盡废其法。章惇、蔡卞請發冢斫棺，帝不許，乃令奪赠謚，仆所立碑。而惇言不已，追貶清遠軍節度副使，又貶崖州司戶參軍。徽宗立，复太子太保。蔡京擅政，复降正議大夫，京撰奸党碑，令郡國皆刻石。長安石工安民當镌字，辭曰：“民愚人，固不知立碑之意。但如司馬相公者，海內稱其正直，今謂之奸邪，民不忍刻也。”府官怒，欲加罪，泣曰：“被役不敢辭，乞免镌安民二字於石末，恐得罪於後世。”聞者愧之。","sortOrder":42},
  {"id":"s_work_gp_13_43","chapterId":"ch_work_gp_13","text":"靖康元年，還赠謚。建炎中，配饗哲宗廟庭。","sortOrder":43},
  {"id":"s_work_gp_13_44","chapterId":"ch_work_gp_13","text":"【譯文】司馬光，字君實，是陝州夏縣人。他的父親司馬池，曾任天章閣待製。司馬光七歲的時候，嚴肅如同成年人，聽別人講《左氏春秋》，他特別喜愛，回家後將所聽到的講給家人，竟能說出其中的大意。此後，他整天手不釋卷，非常愛讀書，往往不知道飢饿、口渴和寒暑季節。有一次，一群小孩在院中遊戲，其中有一个孩子爬到一口大缸上，不慎落入缸中，小孩们很害怕，都逃跑了，只有司馬光非常冷靜，他從地上拾起一塊石頭，把缸砸破，缸里的水一下子全流了出來，小孩得救了。後來京師、洛陽一帶把这件事繪成圖畫，廣為傳誦。宋仁宗寶元初年，司馬光考中進士，这年他刚二十歲。他不喜歡華麗，朝廷規定，凡是中進士的人，都要參加一次“聞喜宴”，在參加宴會時，皇帝要賜給每位新中進土一朵大紅花，大家都佩戴上大紅花，以示榮耀。唯獨司馬光不戴花，一位同中進士的人告訴他說：“君王賞賜的花，不戴不恭敬。”於是司馬光才戴上一枝。","sortOrder":44},
  {"id":"s_work_gp_13_45","chapterId":"ch_work_gp_13","text":"朝廷授予他奉禮郎，因司馬池在杭州，司馬光便請求任蘇州判官以便能侍奉父親，朝廷答應了。父母親去逝後，他守丧多年。以至容貌憔悴。他謹守禮節，守丧期滿，負责武成軍判官的事務，後改為大理評事，增補為國子監直講。枢密副使庞籍推荐他為馆閣校勘，負责禮院事務。","sortOrder":45},
  {"id":"s_work_gp_13_46","chapterId":"ch_work_gp_13","text":"中官麥允言死後，被給予帝王駕出時扈從的儀仗队。司馬光說：“戴很多纓子的帽子上朝，孔子尚且認為不可。麥允言只是皇上親近的大臣，併没有多少功勞，而被赠以三公的官位，給予一品官的儀仗队，看他帽上的纓子，这不也太多了吗？”夏竦死了之後被賜謚文正，司馬光說：“这个謚號是最美的了，夏竦是什么人，可受得起吗？”因為他的話，夏竦被改謚文莊。司馬光被任命為集賢校理。","sortOrder":46},
  {"id":"s_work_gp_13_47","chapterId":"ch_work_gp_13","text":"司馬光接受庞籍的邀請，擔任併州判官。麟州屈野河西良田頗多，西夏人蠶食这一帶土地，已成為河東的禍患。庞籍命令司馬光去巡视，司馬光建議說：“修筑兩个城堡來抵御西夏人，招募老百姓去耕种土地。耕种的人多，糧食買賣价格就低，也就可以慢慢缓和河東糧食价格昂貴而依賴遠處供給的忧慮。”庞籍聽從了他的計策。麟州將領郭恩勇敢却有點狂妄，率兵在夜間渡河，不設防備，被敵方消滅，庞籍因此獲罪，離开了麟州。司馬光三次上書陳述郭恩覆滅是自己的過失，但没有得到答复。庞籍死後，司馬光上堂拜見他的妻子，待她像母親一樣，撫養他的兒子就像自己的兄弟一樣，當時的人都很稱贊他。","sortOrder":47},
  {"id":"s_work_gp_13_48","chapterId":"ch_work_gp_13","text":"後來，司馬光改任直秘閣、开封府推官。这時，交趾貢納一种奇怪的野獸，說是麟，司馬光說：“真假不得而知，即使是真的，不是自己來的也不能說明是祥瑞之兆，希望送還他们的所獻之物。”他又寫了一篇賦進行諷諫。他又修撰起居註，供職禮部。有關部門說有日食，按慣例，日食不滿度數，或許京師看不見，就應當上表祝贺。司馬光說：“四方都看得見，京師看不見，这說明君王被陰险邪惡的小人所蒙蔽；天下的人都知道，唯獨朝廷不知道，它所帶來的灾害會更厲害，不應當慶贺。”朝廷聽從了他的意見。","sortOrder":48},
  {"id":"s_work_gp_13_49","chapterId":"ch_work_gp_13","text":"他與別人一同負责諫院的時候，蘇轍在回答科舉考试的對策中，言辭切中要害而且很直率，考官胡宿打算不錄取他，司馬光說：“蘇轍有愛君忧國之心，不應該落榜。”因為司馬光的这一建議，皇上下詔將蘇轍定為最後一等。","sortOrder":49},
  {"id":"s_work_gp_13_50","chapterId":"ch_work_gp_13","text":"仁宗身體不好，可國家的繼承人還没有確定，天下的人都很忧慮却不敢說話。諫官范镇首先發表自己的看法，司馬光在併州聽說後，也發表意見，併且赠送書信給范镇，勸他以死抗爭。到这時，司馬光又對皇上當面說：“我過去在併州作通判，所上的文書三章，希望陛下果斷篤行。”皇帝深思了好久，然後說：“莫非想要挑選宗室後代作為繼承人吗？这的確是忠臣說的話，只是別人不敢說罢了。”司馬光說：“我說这个，自己認為一定會招來死罪，没想到皇上如此开明，竟然接受了。”皇上說：“这有什么不好，古今都有这類事。”司馬光退朝後没有聽說有詔令，就又上書說：“我前面所說，心想立即就會施行，現在却没聽到什么，这中間一定有小人說陛下身強力壮，怎么立即做不吉祥的事？","sortOrder":50},
  {"id":"s_work_gp_13_51","chapterId":"ch_work_gp_13","text":"那些小人没有長遠的考慮，只是想在仓猝之間，拉拢他们所看重的和友善的。‘定策國老’、‘門生天子’之禍，能說得完吗？”皇帝大為感動，說：“將司馬光的上書送到中書省。”司馬光見到韓琦等說：“諸公没來得及商定，他日宮中半夜傳出寸紙，把某人作為繼承人，而且全國的人不敢违背。”韓琦等双手作揖說：“不敢不盡力。”不久，下詔讓英宗負责宗正事務，英宗一再推辭，不肯答應，於是被立為皇子。英宗又說自己有病，不肯入宮。司馬光說：“皇子推辭富貴，已經快一个月了，可見他比一般人賢惠得多。然而，對父親的召唤不答應，君王征召，却不肯應征，希望以臣下的道義來责備皇子，想必他一定會入宮。”皇上照他說的辦，英宗果然接受了征召。","sortOrder":51},
  {"id":"s_work_gp_13_52","chapterId":"ch_work_gp_13","text":"兖國公主嫁給李玮，李玮不能勝任宰相的職務，皇上下詔調李玮到衛州，李玮的母親就去歸附其兄李璋，公主回到宮中居住。司馬光說：“皇帝陛下想念章懿太後，所以讓李玮娶了公主。現在是母子分離，家事零落，唯獨皇上未感覺到没有恩泽吗？李玮已經被罢黜，公主怎么會没有罪呢？”皇帝明白了，下詔讓公主到沂國，對待李氏的恩惠也不变。朝廷要晉升他為負责起草皇帝詔書的官，他一再推辭，於是改授為天章閣待製兼侍講，併負责諫院的工作。當時朝廷對許多违法的事多姑息遷就，小官吏们起哄就可以驅逐執法官；負责皇帝坐車的官吏违令、傲慢，竟能撤換宰相；衛士们行凶造反，可監獄不去窮追他们的责任；兵士辱骂三司使而不被認為是冒犯長官。司馬光說这些都是犯死罪的發端，不能不將他们正法。","sortOrder":52},
  {"id":"s_work_gp_13_53","chapterId":"ch_work_gp_13","text":"充媛董氏死後，被赠淑妃稱號，大臣停止上朝，為她服丧。官員们都前去撫慰，為其議定謚號，實行册封的禮節，送葬時為其配備儀仗队。司馬光說：“董氏的位次本來低微，病危將死時才拜為充媛。古時候婦人没有謚號，近代的製度也只有皇後才有。儀仗队本來是用於奖賞有軍功的人的，從來没有用於婦人。唐朝平陽公主有率兵辅佐唐高祖平定天下的功勞，才享此殊榮。到了韦庶人才开始下令妃子下葬的日子都給予鼓吹，但这不是要讓它成為製度，不值得效法。”當時有關部門議定後宮的封赠辦法，皇後和妃子全部要封赠三代，司馬光說：“妃子不應當與皇後一樣，西漢時的袁盎引导慎夫人離开與皇後同坐的席位，也正是这个緣故。仁宗天聖年間行郊祀祭禮，太妃只赠給二代，何况是妃子呢？”英宗即皇帝位，患病，慈聖光獻皇後和他一同處理政務，司馬光上疏說：“過去章獻明肅皇後有保佑先帝的功勞，只是因為親近、任用外戚小人，遭到國內人士的非議。現在處理政務，大臣中忠誠厚道的像王曾，清廉純正的像張知白，刚正不阿的如魯宗道，正直無私的像薛奎，等等，應該相信重用他们；猥琐、卑鄙的像馬季良，讒害忠良的像羅崇勋，等等，應當疏遠他们。这樣天下的人就會心悅誠服。”","sortOrder":53},
  {"id":"s_work_gp_13_54","chapterId":"ch_work_gp_13","text":"英宗皇帝病愈，司馬光料想一定會追尊繼皇子的事，於是上書說：“漢宣帝是孝昭帝的後代，但終究不去追尊衛太子、史皇孫；光武帝繼承西漢元帝，也不追尊鉅鹿、南頓君，这是永久的法則。”後來皇上下詔讓兩製集體商議濮王的典章禮節，學士王珪等互相觀望不敢首先表態，司馬光獨自揮筆寫道：“作為一个人的後嗣，就是為人之子，不能顧及自己的親屬。大王應該准許封赠他的父親，稱為皇伯，給他高官和大的封國，以表示對他的尊敬和榮寵。”商議定了，王珪即命令屬吏將司馬光的手稿作為商議的結果。呈上去後，與大臣们的意見不一樣，六位御史力爭，都因此而遭到貶斥。司馬光請求將他们留下，没被准許，於是請求與他们一同受貶。","sortOrder":54},
  {"id":"s_work_gp_13_55","chapterId":"ch_work_gp_13","text":"起初，西夏派使者來參加祭祀，延州指揮使高宜負责護送作伴，他對西夏使者很傲慢，併出言侮辱西夏國王。使者回去之後，報告了朝廷。司馬光與呂誨請皇上對高宜治罪，皇上没有聽從。第二年，西夏人犯邊，殺掠官吏和平民。趙滋在雄州為官，只是凭他的勇猛和強悍治理邊境，司馬光先前就認為这樣很危险。此時，契丹人在界河捕魚，在白溝的南面砍伐柳树，朝廷認為雄州知州李中祐没有才能，准備派人取代他。司馬光說：“我们的國家在少數民族歸附我们的時候，我们和他们計较細枝末節；等到他们桀驁不馴的時候，又聽其所為，姑息他们。近來西邊的禍害起於高宜，北邊的禍害因為趙滋，可是時下却認為这兩个人是賢人，所以邊境的官吏都以惹是生非為本事，漸漸發展到不可阻擋。應該給邊境的官吏下令，在邊疆處理小事動辄用武的人，按犯罪論處。”","sortOrder":55},
  {"id":"s_work_gp_13_56","chapterId":"ch_work_gp_13","text":"宋仁宗用於赠送、賞賜的東西，价值竟達百餘萬。司馬光率領同僚三次上書，勸諫說：“國家還有大的忧患，內外貧乏，不可专門效仿乾興的舊事。如果必須赠送、賞賜，應准許大臣向上進獻所得賞賜金錢來帮助營建山陵。”皇上没有答應。司馬光便把皇上賞賜的珠寶作為諫院的辦公費，黃金送給舅家，堅决不肯自己留在家里。皇後歸政後，有關部門製订法律，規定皇後想要的東西，要上奏兩次才供給。司馬光說：“應該轉交給有關的部門來負责供給，併要如數告訴皇後，防止有人從中作弊。”","sortOrder":56},
  {"id":"s_work_gp_13_57","chapterId":"ch_work_gp_13","text":"曹佾没有什么功勞被任命為使相，兩府都升官。司馬光說：“皇帝陛下想要慰藉母親的心，而提拔無名之辈，这樣守衛的老將、侍奉的小臣，一定會有所希冀。”不久，又晉升都知任守忠等官員，司馬光又爭辯，他議論說：“任守忠是个大奸臣，陛下被立為皇子，也不是任守忠的意思，他阻止和破坏重大决策，破坏各种事情，幸好先帝没有聽從；等到陛下繼承皇位後，他又多次幹坏事，是國家的大賊。請將斬首於都市，以答謝天下。”由於他的这一議論，任守忠被貶為節度副使，讓他到蘄州，天下人對此都感到高興。","sortOrder":57},
  {"id":"s_work_gp_13_58","chapterId":"ch_work_gp_13","text":"皇上下詔征發陝西義勇二十萬人，百姓為此驚扰，而且这些人紀律混亂，根本就不能任用。司馬光慷慨激昂地加以評論，把情况告訴韓琦，韓琦說：“用兵貴在先聲奪人，谅祚現在正桀驁不訓，如果他聽說一下增兵二十萬，難道不會感到震驚害怕吗？”司馬光說：“用兵之所以貴在先聲奪人，是因為这畢竟不真實，仅可以欺骗一時罢了。現在我们雖然增兵，實际上这些兵不堪用，不超過十天，他们就會知道我们的實情，人家還會有什么可怕的呢？”韓琦說：“你只看到慶歷年間乡兵打了勝仗，擔心現在又會像那樣，現在已下聖旨與百姓約定，永遠不再充軍防守邊防。”司馬光說：“朝廷曾經失信於民，老百姓不會相信，即使我司馬光也不能不懷疑。”韓琦說：“我在这个位置上，你不要有忧慮。”司馬光說：“您在这里，可以这樣，他日別人處在这个位置，因為公事征兵，招兵運糧、守邊，这些都是易如反掌的事。”韓琦不再作聲，可事情也就这樣了，也併没有停止老百姓的兵役。還不到十年，就都像司馬光所忧慮的情形了。","sortOrder":58},
  {"id":"s_work_gp_13_59","chapterId":"ch_work_gp_13","text":"王廣淵被安置到集賢院，司馬光認為他奸邪不可親近，說：“過去漢景帝重用衛綰，周世宗不看重張美。王廣淵在仁宗在世時，私自結交陛下，難道可以說是忠臣吗？應該貶黜他，以嚴肅天下。”不久司馬光被提升為龍圖閣直學士。","sortOrder":59},
  {"id":"s_work_gp_13_60","chapterId":"ch_work_gp_13","text":"宋神宗即位後，司馬光又被提拔為翰林學士，司馬光極力推辭。皇帝說：“古時候的君子，有的有學問而不寫文章，有的寫文章而無學問，只有董仲舒、扬雄二者兼之。你有文章、學問，為什么要推辭呢？”司馬光回答說：“我不能作四六骈體文。”皇帝說：“就像兩漢的詔書就可以了；何况你能在進士考试中獲得很高名次，却說不能作四六骈文，这是為什么？”終究推辭不掉。","sortOrder":60},
  {"id":"s_work_gp_13_61","chapterId":"ch_work_gp_13","text":"御史中丞王陶因為議論宰相不值日而被罢官，讓司馬光代替他。司馬光說：“王陶由於議論宰相被罢免了官職，那么御史中丞我現在不能擔任。我希望等到宰相值日後，再來就職。”他的話被答應了。他又上書談論修心的三个要領：仁、明、武；治國的三个主要問題：任人、信賞、必罰。他的議論十分周詳。他還說：“我事奉三朝皇帝，都以这六句話為中心進獻忠言，我一生努力學習所獲得的，都在这里。”他任音樂院內臣，宋朝常常任用供奉官以下的官吏，調到內殿做一段時間的領班就調出去了；但近年有的官吏暗中領取國家财物，这不是祖宗的本意。因此，司馬光議論說高居簡是奸邪之人，請求疏遠和流放他。他接連上了五次奏章，皇帝終於罢黜了高居簡，併全部罢免了那些轉寄資财為自己牟取私利的人，後來留下二人，司馬光又極力抗爭。張方平擔任參知政事，司馬光說他與眾望不符，皇帝没有聽從。但繼續讓他擔任翰林兼侍讀學士。","sortOrder":61},
  {"id":"s_work_gp_13_62","chapterId":"ch_work_gp_13","text":"司馬光常常忧慮歷代史書繁浩，君主無法全部瀏覽，於是他撰寫《通志》八卷，呈獻給皇上。英宗看了十分高興，下令置局秘閣，讓他繼續寫这部書。宋神宗併賜名為《資治通鑒》，還為这部書親自撰寫《序》，讓人每天為他進讀。","sortOrder":62},
  {"id":"s_work_gp_13_63","chapterId":"ch_work_gp_13","text":"朝廷下詔錄用潁邸直省官四人為閤門祗侯，司馬光說：“朝廷在刚建立的時候，大政施展困難，所以必須使用左右舊人作為心腹耳目，把他们叫做隨龍，但这併不是平時的常法。閤門祗侯在文臣是馆職，怎么可以讓服役的仆人擔任呢？”","sortOrder":63},
  {"id":"s_work_gp_13_64","chapterId":"ch_work_gp_13","text":"西部少數民族部落將領嵬名山想凭借橫山的兵眾，挟谅祚來投降，詔令邊境的臣子招納他的人眾。司馬光上疏尖銳地指出說：“嵬名山所凭借的民眾，不一定能製服谅祚。即便僥幸戰勝，消滅了谅祚，又生出一个谅祚，这有什么利益？如果不獲勝，嵬名山一定帶領民眾來歸順我们，到那時不知道怎么處理这件事。我恐怕朝廷不仅失信於谅祚，而且又會失信於嵬名山了。如果嵬名山餘眾還多，返回北邊又不可能，進入南邊又不被接受，他到了窮困無所歸附的時候，一定會突然占據邊境城堡來以求自救。陛下難道没有聽說過侯景的事吗？”皇上没有聽從他的話，派遣將領种諤帶兵迎接，奪取綏州，花費了六十萬。對西方用兵，大概就是從这里开始的。","sortOrder":64},
  {"id":"s_work_gp_13_65","chapterId":"ch_work_gp_13","text":"百官上尊號，司馬光掌管詔書，他說：“先帝舉行祭祀大禮，不接受尊號。到先帝末年時，有人建議，說國家與契丹往來通信，他们有尊號而我们没有，因此没有到册封的時候又進行了册封。過去匈奴冒頓自稱‘天地所生日月所置匈奴大单於’，但没有聽說漢文帝又取名來加封給自己。希望揣知先帝的本意，不要接受这个名號。”皇帝很高興接受司馬光的建議，親手下詔嘉奖司馬光，併讓他寫好答謝辭，以昭示內外人士。","sortOrder":65},
  {"id":"s_work_gp_13_66","chapterId":"ch_work_gp_13","text":"掌管政務的官吏，認為河朔一帶天旱歉收，國家用度不充足，請求在南郊祭祀時不要賞賜黃金絹帛之類。皇上下詔讓學士们議論这件事。","sortOrder":66},
  {"id":"s_work_gp_13_67","chapterId":"ch_work_gp_13","text":"司馬光和王珪、王安石同時被召見，司馬光說：“救灾和節約用度，應該從貴戚和近臣开始，这件事可以这么辦。”王安石說：“常袞推辭政事堂的公膳，當時的人認為常袞没有什么能力，應當辭去職務而不應當推辭俸祿。况且國家用度不足，不是當前一時的紧急事務。國用之所以不足，是因為没有得到善於理财的人。”司馬光說：“善於理财的人，不過是按人頭收穀，用箕收取罢了。”王安石說：“不是这樣，善於理财的人，不增加賦稅而國家的财用就能够充足。”司馬光說：“天下哪里會有这樣的道理？天地所生财货和各种物資，不在老百姓那里，就在公家，他们設法掠奪百姓，其危害比增加賦稅更歷害。这大概像桑弘羊骗漢武帝一樣，太史公寫他，那是因為太史公也不明白。”對这个問題，群臣们爭論不休。皇帝說：“我的意思與司馬光一樣，然而暫時不能允許。”正巧讓王安石草擬詔書，他引用常袞的事责備兩府，兩府不敢再推辭。","sortOrder":67},
  {"id":"s_work_gp_13_68","chapterId":"ch_work_gp_13","text":"王安石开始主持政務，施行新法，司馬光堅决反對，上書陳述利害。","sortOrder":68},
  {"id":"s_work_gp_13_69","chapterId":"ch_work_gp_13","text":"邇英將上書進獻誦讀，當讀到曹參代替萧何的事時，皇帝說：“漢朝一直遵守萧何之法不变，行得通吗？”回答說：“不仅是漢朝，三代的君主也常常固守大禹、商湯、周文王、周武王的法則，这个法則即使保存到今日也没問題。漢武帝采取高祖紛紛改变成規的辦法，結果盜賊布滿了半壁天下，元帝更改孝宣帝時候的政策，漢朝的王業從此衰落。这樣說來，祖宗之法是不能变改的。”","sortOrder":69},
  {"id":"s_work_gp_13_70","chapterId":"ch_work_gp_13","text":"呂惠卿說：“先王的成法，有一年改变一次的，‘正月始和，布法象魏’說的就是这个道理；也有五年变更一次的，巡行境內的考績製度就是这樣；還有三十年变更一次的，‘刑法時輕時重’就是这个道理。","sortOrder":70},
  {"id":"s_work_gp_13_71","chapterId":"ch_work_gp_13","text":"司馬光說的不對，他的用意在於諷刺朝廷罢了。”皇帝問司馬光，司馬光說：“布法象魏，是頒布原來的法規。諸侯國改变禮節和樂器的，國君在巡行時遇到就要誅殺諸侯王，这就是說这些不是可以隨便改变的。","sortOrder":71},
  {"id":"s_work_gp_13_72","chapterId":"ch_work_gp_13","text":"關於刑法，刚建立的國家用輕法，混亂的國家用重法，这就是所謂時重時輕，但併不是变化。况且治理天下好比住房子，房子坏了就修補一下；没有倒塌就不要另造新房。公卿侍從们都在这里，希望陛下詢問他们。","sortOrder":72},
  {"id":"s_work_gp_13_73","chapterId":"ch_work_gp_13","text":"三司使掌管天下的财富，没有才能的人罢黜他们是可以的，但不能讓掌管政事的人幹預三司使的事務。現在設立三司條例司，不知為了什么？","sortOrder":73},
  {"id":"s_work_gp_13_74","chapterId":"ch_work_gp_13","text":"宰相用德行辅佐君王，怎么用規程、條例呢？如果用規程、條例，那是低級官吏的所為。現在看到的詳見於中書條例司，為什么呢？”呂惠卿不能回答，就用別的話來詆毀司馬光。皇帝說：“互相讨論事情的错對，何必这樣！”司馬光說：“百姓放债收取利息，還能够蠶食剝削下等的人家，何况政府放债呢？危害可想而知。”呂惠卿說：“青苗法，是願意借就借，不願借的也不強迫。”司馬光說：“無知識的老百姓知道借债的利益，但不知道還债的害處。不只是政府不強迫，那些富裕而放貸的百姓也不強迫。過去太宗平定河東，製定和籴法，當時一斗米十錢，百姓樂意和官府做交易。後來物价暴涨而和籴之法没有取消，終於成為河東的世代禍害。我恐怕它日的青苗法，也會像这樣。”皇帝說：“官仓籴米怎么樣？”在坐的人都站了起來，司馬光說：“也不好。”呂惠卿說：“籴米一百萬斛，就可以省去東南的漕運，然後我们用这些省下的錢供給京師。”司馬光說：“東南很窮，一粒米而能使人变得貪暴凶殘，現在不籴米而收取漕運的費用，是放弃那些有餘的，而去與那些窮的人收，對農業和商業都有害處！”侍講吳申站起來說：“司馬光所說的，切中了要害。”","sortOrder":74},
  {"id":"s_work_gp_13_75","chapterId":"ch_work_gp_13","text":"一天司馬光留下來與皇帝說話，皇帝說：“現在天下一片混亂，这大概就是孫叔敖所說的‘國家現在執行的政策，是民眾所厭惡的’。”","sortOrder":75},
  {"id":"s_work_gp_13_76","chapterId":"ch_work_gp_13","text":"司馬光說：“是的，陛下應當論證其是非。現在條例司所製订的那些條例，唯獨王安石、韓絳和呂惠卿認為是對的，陛下怎么能够就與这三个人共同治理天下呢？”皇帝想要重用司馬光，征求王安石的意見。王安石說：“司馬光外表直言勸諫皇上，內心却在讨好下臣。所說全部是危害國家政務的，和他在一起的人，也都是對國政有危害的人，如果想將司馬光安置在身邊，讓他參預讨論國家大事，这關系到國家走向繁榮還是走向削弱。司馬光的才能本來不足以對國政形成危害，但是他處在高位，那些有不同意見的人會倚附他，以他為依托。韓信树起漢的紅色旗，趙地士兵的勇氣就全没有了。現在任用司馬光，就等於是給那些持反對意見的人树紅色旗。”","sortOrder":76},
  {"id":"s_work_gp_13_77","chapterId":"ch_work_gp_13","text":"王安石因為韓琦上疏，就呆在家里請求辭職。皇帝於是任命司馬光為枢密副使，司馬光推辭說：“陛下所以任用我，大概是因為我狂妄直率，也許對國家有點好處。如果仅仅是用俸祿和職位使我榮耀，而不聽我的意見，是將官位當作私恩，而不是真正任用人。我只是拿俸祿和職位作為自己的榮耀，而不能拯救百姓於灾難之中，这等於是盜竊國家的名位和車服儀製來為自己謀利。陛下如果真能够罢掉製置條例司，追還提舉官，不施行青苗、助役等法令，雖然不任用我，我得到的恩賜也很多了。現在說青苗法害處的，不過是說使者骚動州縣，这仅仅是現在的禍患而已。可是我所忧慮的，乃是十年之後，而不是今天的事。一般說來，老百姓的貧富，與他们的勤勞和懶惰有關，懶惰的人常常貧乏，所以必定求助於別人。現在拿出錢借給百姓而指望收取他们的利息，富裕的人不願意借，而使者又以多借出去為功勞，这一切都是強行分配。國家擔心他们拖欠债務，一定要讓窮人和富人互相擔保，以後貧窮的人不能偿還债務，就會向四方逃走；富裕的人不能離开，一定倒被责令偿還其他人家所欠的债。春天开始到秋天結算，數額一天天增大，貧困的人跑光了，富裕的人也变成窮人了。十年以後，百姓没有能生存的了。現在又全部散發常平仓的錢穀，來實行青苗法，日後如果想要恢复常平仓，有那么容易吗？富裕人家也没有了，常平仓也废了，再加上軍队开銷，因而很快就會造成飢荒，这樣老百姓中那些贏弱的一定會死於溝壑，強壮的一定會聚集起來造反為盜，这是事情發展的必然結果。”他上書陳述達七、八次，皇帝派人對他說：“枢密，是負责軍事的，為官各有職责，不應該拿其他事情來推辭自己的本職工作。”司馬光回答說：“我没有接受任命，就還是侍從，對於任何事情没有不能說的。”王安石出來主持政事，司馬光於是獲得請求辭職的機會，於是離开了京城。","sortOrder":77},
  {"id":"s_work_gp_13_78","chapterId":"ch_work_gp_13","text":"司馬光以端明殿學士的身份出知永興軍。宣撫使下命令分拨義勇戍守邊疆，挑選軍队中的驍勇武士，招募市井中那些不怕死的少年為奇兵，併征調百姓製作幹糧，全部修筑城池望樓，關辅一帶因此而被骚扰，不得安寧。司馬光極力呼吁：“國家和人民都困弊疲乏，不可以再生事，京兆一路全部是內郡，修繕併不是當務之急。宣撫的命令，不敢聽從，如果說在軍事方面缺乏什么，我擔負责任。”於是一路獨免骚扰。後來，又調他到許州任知州，他急忙朝見皇帝，不想赴任；請求回洛陽西京御史台任職，從此絕口不談政事。皇上請求進諫的詔令下達以後，司馬光讀後感動得流了淚，想默不作聲又不能自禁，於是他又陳述了六件事，還寫信譴责宰相吳充，这些事情見於《吳充傳》。","sortOrder":78},
  {"id":"s_work_gp_13_79","chapterId":"ch_work_gp_13","text":"蔡天申擔任察訪官的時候，作威作福，河南尹、轉運使對他恭敬得像對待上司一樣；當朝拜謁應天院神御殿時，官府单獨為他設了一班，以示不敢與他對抗。司馬光回頭對台吏說：“把蔡寺丞帶回本班。”官吏於是帶蔡天申站到監竹木務官富贊善之後，蔡天申很感窘迫和沮丧，當天就離开了。","sortOrder":79},
  {"id":"s_work_gp_13_80","chapterId":"ch_work_gp_13","text":"元丰五年，司馬光忽然患言語不流畅的疾病，自己懷疑將離开人世，便預備了遺書，將其放在屋內臥房里，打算一旦病情加重，就將它托好友送給皇上。官製施行，皇帝指著御史大夫說：“非司馬光不可。”又打算讓他擔任東宮太子的師傅。蔡確建議說：“國家的太子刚刚定下來，希望能稍微推遲一下。”这時《資治通鑒》還没有全部完成，皇帝特別註重这本書，認為比荀悅的《漢紀》還要好，皇上多次催促他快些完稿，併把潁邸舊書二千四百卷賞賜給他。書寫完後，加授他為資政殿學士。","sortOrder":80},
  {"id":"s_work_gp_13_81","chapterId":"ch_work_gp_13","text":"他居住在洛陽的十五年，天下人將他當作真正的宰相，村夫野老都稱他為司馬相公，婦人孺子都知道他是司馬君實。","sortOrder":81},
  {"id":"s_work_gp_13_82","chapterId":"ch_work_gp_13","text":"皇帝去逝後，司馬光趕到宮殿，守衛的士兵望見他，都以手加額說：“这是司馬相公呀！”他所到之處，老百姓都拦在路上，聚集在一起围觀，以至於馬都不能通過，大家要求說：“你不要回洛陽了，就留下來作宰相，快救活百姓。”繼位的哲宗年幼，太皇太後臨朝聽政，派遣使者問司馬光當前首要的任務，司馬光說：“廣开言路。”於是下詔在朝堂公开張帖文書、告示。朝廷針對大臣有意見的，定下了六條，說：“暗中有所懷疑的人；挑拨與自己無關的事的人；或者煽動動搖重要事情；或者迎合王安石的法令；對上想僥幸希望晉升；對下想迷惑流俗。像这些人，堅决懲罰不赦。”然後把它交給司馬光，司馬光看後說：“这不是請求進諫，而是在拒諫。作臣子的只有不說話，一說話就歸入到六條里了。”於是朝廷詳細讨論其中的情况，將詔書修改後頒布施行。在當時，上書言事的人數以千計。","sortOrder":82},
  {"id":"s_work_gp_13_83","chapterId":"ch_work_gp_13","text":"朝廷准備起用司馬光作陳州知州，但過闕的時候，又將他留下任為門下侍郎。蘇軾從登州被召回朝廷，司馬光所過的路上，人们聚集在一起大聲呼喊說：“感謝司馬相公，你不要去朝廷了，好好保重身體，來救活我们吧。”當時天下的老百姓，對新政都拭目以待，可是議論的人還有人說：“先皇刚去世，現在的皇帝三年不能改变父親的製度。”只是粗略地舉出一些細小事情，稍微搪塞人们的耳目。司馬光說：“先帝的法規，好的部分即使百代也不應該改变，像王安石、呂惠卿所創製的法規，已成為天下的禍害，更改它们就像救民於水火一樣。何况太皇太後是因母親改变兒子，不是兒子改变父親。”眾議决定了，於是罢去保甲团教，不再設立保馬法，废除市易法，將所储存的物資全部賣掉，不收利息，免除老百姓所欠的錢；有關京東鐵錢及茶鹽的管理辦法，也都恢复原來的樣子。有人對司馬光說：“熙寧、鹹丰時期的舊臣，大多是奸佞小人，他日有人拿父子情義離間皇上，那么大禍就會發生了。”司馬光神色嚴厲地說：“上天如果要降福宗廟，必定不會有这類事。”於是天下的人都放心了，說：“这是先帝的本意。”","sortOrder":83},
  {"id":"s_work_gp_13_84","chapterId":"ch_work_gp_13","text":"元祐元年，司馬光又患病，皇帝下詔讓他朝會後再去拜見，不要激動。當時青苗法、免役法、將官法還存在，而對待西方少數民族的意見也没有統一。司馬光叹息說：“这四种禍患没有消除，我死也不能瞑目呀！”他寫信給呂公著說：“我把身體交給了医生，把家事交給了兒子，但國家大事没有可寄托的人，現在把它交給您吧。”於是他評論免役法的五點害處，請求朝廷下令罢黜此法。建議各位將領下屬的兵士都要隸屬州縣，軍政事務應當委托郡守、縣令一同决定。废除提舉常平司，將其事務轉交給轉運使、提點刑獄。他還認為，關於邊疆問題，以和少數民族講和為好。認為監司現在多為新近選拔的少年，大都刻薄急躁，應當命令親近的臣子從郡守中選拔舉荐，而要在通判中選拔轉運判官。又建議國家設立十科荐士法。皇上都聽從了他的意見。","sortOrder":84},
  {"id":"s_work_gp_13_85","chapterId":"ch_work_gp_13","text":"又拜授尚書左仆射兼門下侍郎，免除上朝朝拜，准許他坐肩舆，三天到一次朝廷。司馬光不敢接受，他說：“不見君主，不能够處理事務。”於是皇上下詔讓司馬光的兒子司馬康攙扶著司馬光入朝和皇帝商議事情，併且對他說：“你可以不下拜。”在司馬光的再三反對之下，朝廷終於罢去了青苗錢，恢复了常平仓的粜籴法。太皇太後都虛心地聽從他的意見。遼國和西夏的使者來了，一定詢問司馬光的起居和身體状况。","sortOrder":85},
  {"id":"s_work_gp_13_86","chapterId":"ch_work_gp_13","text":"而且他们的君主命令他们的邊境官吏說：“中國任用司馬光為宰相了，不要輕率生事，發生邊境糾紛。”这時，朝廷對司馬光言聽計從，司馬光也想要以身報國，於是他親自過問所有事務，不分晝夜地工作。賓客们見他身體羸弱，就用諸葛亮吃得少而事情多的例子，勸他引以為戒。","sortOrder":86},
  {"id":"s_work_gp_13_87","chapterId":"ch_work_gp_13","text":"司馬光說：“死和生，是命中註定的事，別去管它。”於是他工作更加努力。病危將死之時，他已不再有知覺，然而他對別人仍然恳切教导，好像是在夢中說話，但所說的還都是朝廷、國家的大事。","sortOrder":87},
  {"id":"s_work_gp_13_88","chapterId":"ch_work_gp_13","text":"这年九月，司馬光去逝，終年六十八歲。太皇太後聽到司馬光去逝的消息，非常悲痛，和皇帝立即去弔丧，以至明堂建成的大禮也没有去參加祝贺。赠封司馬光為太師、溫國公，赠給死者的衣服是一品官的禮服，赠送的銀絹多達七千。併下令讓戶部侍郎趙瞻、內侍省押班冯宗道監護丧事，歸葬到陝州。謚號文正，賜碑《忠清粹德》。京城的人们罢市前往凭弔，有的人甚至賣掉衣物去參加祭奠，街巷中的哭泣聲超過了車水馬龍的聲音。等到安葬的時候，哭的人非常真誠，仿佛是在哭自己的親人。嶺南封州的父老们，也都紛紛祭奠司馬光，京城及全國各地都畫他的像來祭祀他，吃飯前一定要先祭祀他。","sortOrder":88},
  {"id":"s_work_gp_13_89","chapterId":"ch_work_gp_13","text":"司馬光这个人可以稱得上是孝順父母、友愛兄弟、忠於君王、取信於人，又恭敬、節俭、正直，他做的每一件事都有法度，每一言行每一舉動都符合禮節。在洛陽時，他每次到夏縣去扫墓，一定要經過他的哥哥司馬旦的家。司馬旦年近八十，司馬光侍奉他仍像嚴父一樣，保護他像撫育婴兒一樣。從小到大到老，他說話從來没有隨便說過一句，他自己說：“我没有什么超過別人的地方，只是我一生的所作所為，從來没有不可告人的。”他的誠心是出自天性，天下的人都敬重他，相信他，陝西、洛陽一帶的人们都以他為榜樣，與他對照，學習他的好品德。如果人们做了不好的事，就說：“司馬君實莫非不知道吗？”","sortOrder":89},
  {"id":"s_work_gp_13_90","chapterId":"ch_work_gp_13","text":"司馬光對财物和物质享受看得很淡薄，没有什么愛好，對學問却没有不精通的。他惟獨不喜歡佛教、道教，說：“佛道的微言大義不能够超過我的書，其中的荒誕我却不相信。”他在洛陽有田地三頃，妻子死後，他賣掉土地作為丧葬的費用。他一辈子粗茶淡飯、普通衣服，一直到死。","sortOrder":90},
  {"id":"s_work_gp_13_91","chapterId":"ch_work_gp_13","text":"到了紹聖初年的時候，御史周秩首先說司馬光誣蔑、誹謗先帝，全部废除先帝新法。章惇、蔡卞請求掘其墓，砸碎他的棺材，皇帝没有允許，但下令剝奪他的赠謚，推倒為他立的碑。可是，章惇一直不停止地攻击司馬光，於是追貶司馬光為清遠軍節度副使，又追貶他為崖州司戶參軍。宋徽宗即皇帝位，恢复他為太子太保的名分。到蔡京专權的時候，又降司馬光為正議大夫，在京城撰刻《奸党碑》，併命令郡國也都刻石立碑。長安石匠安民不得不刻字，他推辭說：“我是个愚蠢之人，不知道立碑的意義。但像司馬相公这樣的人，海內外都稱贊他為人正直，現在反說他是奸邪，我安民怎么忍心刻！”長安府的官吏感到惱怒，要治安民的罪，安民哭著說：“我被征發服勞役，不敢推辭，但在碑的最後請求不要刻‘安民’二字，害怕得罪後人。”聽到此話的人都感到非常羞愧。","sortOrder":91},
  {"id":"s_work_gp_13_92","chapterId":"ch_work_gp_13","text":"至靖康元年，重又赠他原先的謚號。到建炎年間，將他供奉在哲宗的廟里，與哲宗一起享受祭祀。","sortOrder":92},
  {"id":"s_work_gp_14_1","chapterId":"ch_work_gp_14","text":"附二：司馬光與《資治通鑒》","sortOrder":1},
  {"id":"s_work_gp_14_2","chapterId":"ch_work_gp_14","text":"司馬光，生於北宋真宗天禧三年（1019年），卒於哲宗元佑元年（1086年），字君實，號迂叟，是北宋陝州夏縣涑水乡（今山西夏縣）人，世稱涑水先生，進士出身，歷任馆閣校勘、同知禮院、天章閣待製兼侍講、知諫院、御史中丞、翰林院學士兼侍讀等職。熙寧三年（1070年），他因與王安石政見不同，堅辭枢密副使，以端明殿學士出知永興軍（今陝西西安市），次年改判西京御史台，退居洛陽，专事著史15年。哲宗即位，高大後臨政，召司馬光入主國事，任命為相（尚書左仆射兼門下侍郎）。身後追赠太師，封溫國公，謚文正。","sortOrder":2},
  {"id":"s_work_gp_14_3","chapterId":"ch_work_gp_14","text":"司馬光家世代為宦，父親司馬池為宋仁宗寶元慶歷間名臣，官至兵部郎中、天章閣待製，一生以清直仁厚享有盛譽。司馬光受家庭熏陶，篤誠好學，七歲時，“凛然如成人，聞講《左氏春秋》，即能了其大旨”，從此，“手不釋書，至不知飢渴寒暑”，15歲時所寫文章，時人稱許之“文辭純浑，有西漢風”，20歲時中進士甲第，可謂功名早成。但他併不以此“矜夸滿志，崑明於物，如謂大下莫己若也”，而是豪邁地提出：“賢者居世，會當履義蹈仁，以德自顯，區區外名何足傳邪！”这些話反映了青年司馬光的胸懷與器識，立志以仁德建功立業，不求虛名。因此，步入仕途後的司馬光，繼續廣泛深入地學習，達到了博學無所不通，音樂、律歷、天文、術數皆極其妙的淵博程度，其中最用心力的是對經學與史學的研究，尤其，＿對古籍閱讀極廣，考察極細，可謂通習知晓，烂熟於胸。他隨讀隨作札記，仅26歲一年所寫讀史札記，便多達30來篇，就中萌發了删削卷帙浩繁的古史成一部編年體通史的著史想法，以方便閱讀，而更為深沉的動力，則是封建政治的需要。","sortOrder":3},
  {"id":"s_work_gp_14_4","chapterId":"ch_work_gp_14","text":"當時，北宋建國近百年，已出現种种危機，具有浓厚儒家思想的司馬光，以積極用世的態度，連連上疏，陳述自己一整套的治國主張，大致是以人才、禮治、仁政、信義作為安邦治國的根本措施，这在當時，是有積極意義的。除上疏陳述主張外，在他本人的從政活動中，亦能堅持原則，積極貫彻執行有利於國家的决策方略，尤其在荐賢斥佞的斗爭中，他犯顏直諫，面折廷爭，從不顧及个人安危，被稱為社稷之臣，神宗也感慨地說：“如光者，常在左右，自可無過。”","sortOrder":4},
  {"id":"s_work_gp_14_5","chapterId":"ch_work_gp_14","text":"在熙寧变法中，司馬光與主持变法的王安石發生嚴重分歧。就其竭誠為國來說，二人是一致的，但在具體措施上，各有偏向。王安石主要是围繞著當時财政、軍事上存在的問題，通過大刀闊斧的經濟、軍事改革措施，來解决燃眉之急。司馬光則認為在守成時期，應偏重於通過倫理綱常的整頓，來把人们的思想束縛在原有製度的製約之內，即使改革，也定要穩妥，認為“治天下譬如居室，敝則修之，非大坏不更造也”，因為“大坏而更改，非得良匠美材不成，今二者皆無，臣恐風雨之不庇也”。司馬光的主張雖然偏於保守；但實际上是一种在“守常”基礎上的改革方略。從王安石变法中所出現的偏差和用人不當來看，證明了司馬光在政治上的老練和穩健，除了魄力不及王安石外，政治上是成熟的。","sortOrder":5},
  {"id":"s_work_gp_14_6","chapterId":"ch_work_gp_14","text":"在政見不同、難於合作的情况下，司馬光退居洛陽，通過編纂史著，從歷史的成败興亡中，提取治國的借鑒，“使觀者自责善惡得失”。應該說，司馬光著史，是其從政治國的另一方式。早在宋仁宗嘉佑年間（1056——1063年），他曾與劉恕商量說：“餘欲托始於周威烈王命韓趙魏為諸侯，下訖五代，因丘明編年之體，仿荀悅簡要之文，網羅舊說，成一家之言。”这說明他30多歲時，已醞酿出《通鑒》的規模。宋英宗治平元年（1064年）首呈《歷年圖》25卷，二年後又呈《通志》八卷，說明他在政事活動之餘，已進行撰寫。他的著史得到宋英宗、宋神宗的稱贊、支持，宋英宗同意他設立書局，自擇官屬，神宗以此書“鑒於往事，有資於治道”而命名為《資治通鑒》，併親製序文，以示重视。除了允許其借閱國家所有的圖書資料外，神宗還將穎邸舊書3400卷，賞賜給司馬光參考。修書所需筆、墨、絹、帛，以及果餌金錢之費，盡由國家供給，為他提供了優厚的著書條件。","sortOrder":6},
  {"id":"s_work_gp_14_7","chapterId":"ch_work_gp_14","text":"司馬光著史，還選取了劉恕、劉（分文）、范祖禹等人做為助手，他们既是當時第一流的史學家，又與司馬光在政治、史學上觀點一致，故能在編書中各顯其才，通力合作。《通鑒》的成功，與他们的努力分不开，但最終使《通鑒》達到光辉顶點的，還决定於主編司馬光的精心著述。正如劉恕之子劉羲仲所說：“先人在書局，只類事跡，勒成長編，其是非予奪之际，一出君實筆削。”","sortOrder":7},
  {"id":"s_work_gp_14_8","chapterId":"ch_work_gp_14","text":"《通鑒》的編寫，大致分三个步骤：一、排列丛目；二、編寫長編；三、删改定稿。一二兩步，在主編指导下由助手完成，第三步則完全由主編一人完成。全書的發凡起例由主編拿出後，編寫過程中的具體方法和原則，司馬光強調了以下幾个方面：","sortOrder":8},
  {"id":"s_work_gp_14_9","chapterId":"ch_work_gp_14","text":"一、嚴格的選材。丛目、長編的取材盡量廣泛，提出“寧失於繁，毋失於略”，所選史料內容則著重在國家興亡、政策得失、君臣道德等方面，目的在提供治國借鑒，反映生民休戚的情况。这樣，所收史料除正史之外，諸如稗官野史、百家譜錄、總集別集、傳状碑志等總數不下300多种。長編長達650O多卷，3000多萬字。","sortOrder":9},
  {"id":"s_work_gp_14_10","chapterId":"ch_work_gp_14","text":"二、精心的考異。只有真實才有价值，只有有价值才能具備借鑒作用。任何史家著史都要對史料進行考異，而司馬光除將考異所選史料收入正文之外，又將各种不同的說法和鑒別理由加以逐條說明，著成《通鑒考異》30卷，與《通鑒》一起奉上。由於考異中“抉擇幽隱，校計毫厘”的嚴謹態度，大大增強了史著的可靠性、真實性，《通鑒》以信史著稱，離不开《考異》的辅翼作用。而这种著史方式，為後世史家沿用，清代以考證史實見長的乾嘉學派，正是沿著这條路子發展起來的。","sortOrder":10},
  {"id":"s_work_gp_14_11","chapterId":"ch_work_gp_14","text":"三、編製目錄。《通鑒》記載了16个朝代1362年的史實，是一部總計294卷的長篇巨著，為翻檢方便，於修史同時編寫《通鑒目錄》30卷，我國古代編年體史書因按年紀事，故没有篇目，不作目錄，只是以年檢索。司馬光突破这种舊例，分三部分將年表、帝紀、歷法、天象、目錄、舉要、索引集於一塊，开創了編年體史書多功能目錄的新體例，使《通鑒》體更臻於完善，將我國的歷史編纂學推進到了新的水平上。","sortOrder":11},
  {"id":"s_work_gp_14_12","chapterId":"ch_work_gp_14","text":"四、完善史體。編年體記事簡明扼要，但受時間限製使史事拖沓割裂，不易反映全貌。司馬光註意吸收紀傳體的優點，為交待前因後果，大量采用連載、主載、附叙、追叙、補叙等寫法，帶有以事件為線索組織材料的性质，表現出突破編年體，醞酿紀事本末體的趨势，對南宋袁枢編纂《通鑒紀事本末》一書，有啟迪先导之功。这一改造，使古老的編年體例煥發了新的生命力，後世仿作接踵以起，形成了一个從古至今的編年史書系統。这一系統中，《通鑒》以通史成書，便幹“探明变化之由，尋求演变之跡”，與唐宋以來社會上“主通明变”的思潮相吻合，也與“資治通鑒”的目的相一致。","sortOrder":12},
  {"id":"s_work_gp_14_13","chapterId":"ch_work_gp_14","text":"五、加工貫通。集體寫書，由於手筆不同，風格各異，容易產生割裂驳雜的現象，但《通鑒》的語言風格如出一人之手，浑然一體，毫無雕琢弥縫的痕跡，这正是司馬光精心改編和加工的結果。有著深厚文字功底的司馬光，尤長於叙事，款款寫來，原委了然，文字優美而质朴，格調古雅浑厚而又簡絜晓畅，真可謂別具匠心，自成一體。有許多場面和人物描寫，已成文學史上的名篇，而大型戰爭如赤壁之戰，淝水之戰的叙述，更是勝炙人口，引人入勝，超越了所有其他史書的記載，成為歷史散文的上乘。","sortOrder":13},
  {"id":"s_work_gp_14_14","chapterId":"ch_work_gp_14","text":"六、撰寫附論。我國史家借論贊以寓褒貶勸戒之意，已成傳統。司馬光在《通鑒》一書中附論，不仅數量多，而且篇幅長。全書附有180多篇，80多篇援引他人之論，其餘全為親手撰寫。所論多為治亂之因，君臣之道，是在以往所寫史論與奏疏基礎上，因史事而發揮，就時事而議論。字里行間，充滿著匡辅的誠意和情感，寓褒貶臧否於其中，體現出因事勸諫的良苦用心，無論是民族問題還是用人原則，都針對現状提出了革除弊政的歷史借鑒，具有一定的理論和現實意義。更具匠心的是，这么多的附論，與《通鑒》的內容取舍編排，竟是这樣的浑然一體而不可分割，成為貫彻“資治”这一著史目的的點睛之筆。詳實、體例精善、叙事生動、議論深刻、文風质朴的史學巨著終於完成了。主編司馬光所耗費的心血是難以估量的。在《進通鑒表》中，他說：“研精極慮，窮竭所有，目力不足，繼之以夜。”有人見其殘稿堆積有兩屋之多，皆蠅頭小字，字字端謹，無一字潦草。書成之後，66歲的司馬光，已是“骸骨癯瘁，目视昏近，齒牙無幾，神識衰耗，目前所為，旋踵遺忘”了。所以傾畢生精力於此書，還在於寄托其治國的熱望，他恳切地希望皇帝通過觀覽此書，能够“鑒前世之興衰，考古今之得失，嘉善矜惡，取是舍非，是以懋稽古之盛德，跻無前之至治，俾四海群生，鹹蒙其福”。这樣，他也就“雖委骨九泉，志願永畢了”。这不正說明了他著史是從政治國的另一方式吗？","sortOrder":14},
  {"id":"s_work_gp_14_15","chapterId":"ch_work_gp_14","text":"實际上，《通鑒》的著述意義，已遠遠超過作者的本意，它不仅為統治者提供“資治”的借鑒，也給全社會提供了借鑒，為之作註的胡三省深暗此理。他說：“《通鑒》不特記治亂之跡而已，至於禮樂、歷數、天文、地理、尤致其詳。讀者如飲河之鼠，各充其量而已。”清代王鳴盛也說：“此天地間必不可無之書，亦學者必不可不讀之書”。近千年的歷史證明：《通鑒》已與《史記》一樣，被人们併稱為史學瑰寶，廣為流傳，教益大眾。而研究者代不乏人，使其成為一門专門學問，即“通鑒學”。如今，對《通鑒》的研究正多層次、多角度地展开，它將更多地為人類的進步提供借鑒。这一發展趨势，是司馬光始料不及的，也是其卓絕貢獻的必然結果。","sortOrder":15},
  {"id":"s_work_gp_14_16","chapterId":"ch_work_gp_14","text":"司馬光一生著述甚多，在《通鑒》系列著作中，還有《通鑒舉要歷》80卷、《歷年圖》七卷、《稽古錄》20卷、《本朝百官公卿表》六卷。另外，尚有其他著作20种，200餘卷，是他對我國史學、經學、哲學乃至医學詩詞等各方面進行研究和著述的成果，主要代表作有《翰林詩草》、《註古文孝經》、《易說》、《註太玄經》、《註扬子》、《書儀》、《遊山行記》、《續詩話》、《医問》、《涑水紀聞》、《類篇》、《司馬文正公集》等。","sortOrder":16},
  {"id":"s_work_gp_14_17","chapterId":"ch_work_gp_14","text":"司馬光雖熱心於治國，但由於政見不同而未能有更多直接參與政事的機會。直到宋元丰八年（1085年）宋神宗去世後，67歲高齡的司馬光，隨著要求废除新法的浪潮被迎回宮中，擔任了相職，开始“元佑更化”，盡罢新法。他執政一年半，竭盡全力日夜操勞，耗盡了畢生心血之後與世長辭了。噩耗傳出，“京師人為之罢市往弔，鬻衣以致奠，巷哭以過車者，蓋以千萬數”，在靈柩送往夏縣時，送葬之“民哭公甚哀，如哭其私親。四方來會葬者蓋數萬人”。至於畫像祭奠的“天下皆是，家家掛象，飯食必祝”。一个封建社會中的宰相，能得到民眾这樣廣泛真誠的悼念，實屬罕見，也是歷史的必然。","sortOrder":17},
  {"id":"s_work_gp_14_18","chapterId":"ch_work_gp_14","text":"摘自《三晉歷史人物》，書目文獻出版社，1993，本文作者：崔凡芝","sortOrder":18},
];

